async function getAppRuntime() {
  if (APP_RUNTIME) return APP_RUNTIME;
  const { createAppRuntime } = await import(
    "../shared/runtime/bootstrap/createAppRuntime.js"
  );
  APP_RUNTIME = createAppRuntime({
    env: process.env,
    bullmqFactory: {
      queue: BullQueue,
      worker: BullWorker,
    },
    bullConnection: CFG.redisEnabled
      ? bullConnectionFromRedisUrl(CFG.redisUrl)
      : null,
  });
  return APP_RUNTIME;
}

async function closeServerHandle(server) {
  if (!server || typeof server.close !== "function") return;
  await new Promise((resolve) => {
    try {
      server.close(() => resolve());
    } catch {
      resolve();
    }
  });
}

async function closeBullResource(resource) {
  if (!resource || typeof resource.close !== "function") return;
  try {
    await resource.close();
  } catch {}
}

async function closeRedisClientHandle(client) {
  if (!client) return;
  if (typeof client.quit === "function") {
    try {
      await client.quit();
      return;
    } catch {}
  }
  if (typeof client.disconnect === "function") {
    try {
      await client.disconnect();
    } catch {}
  }
}

async function gracefulShutdown(signal = "shutdown") {
  if (SHUTDOWN_PROMISE) return SHUTDOWN_PROMISE;
  SHUTDOWN_PROMISE = (async () => {
    console.log(`[shutdown] starting (${signal})`);
    CRON_STATE.masterActive = false;

    try {
      FOREX_LIVE_INGESTOR?.stop?.();
      FOREX_LIVE_INGESTOR = null;
    } catch {}

    const runtime = APP_RUNTIME;
    APP_RUNTIME = null;

    const socketLayer = REALTIME_SOCKET_LAYER;
    REALTIME_SOCKET_LAYER = null;
    await closeBullResource(socketLayer);

    await closeServerHandle(REDIRECT_HTTP_SERVER);
    REDIRECT_HTTP_SERVER = null;
    await closeServerHandle(PRIMARY_HTTP_SERVER);
    PRIMARY_HTTP_SERVER = null;

    await closeBullResource(MARKET_DATA_WORKER);
    await closeBullResource(MARKET_DATA_QUEUE);
    await closeBullResource(SNAPSHOTS_CRON_WORKER);
    await closeBullResource(SNAPSHOTS_CRON_QUEUE);
    await closeBullResource(AI_ANALYSIS_CRON_WORKER);
    await closeBullResource(AI_ANALYSIS_CRON_QUEUE);
    MARKET_DATA_WORKER = null;
    MARKET_DATA_QUEUE = null;
    SNAPSHOTS_CRON_WORKER = null;
    SNAPSHOTS_CRON_QUEUE = null;
    AI_ANALYSIS_CRON_WORKER = null;
    AI_ANALYSIS_CRON_QUEUE = null;

    if (runtime && typeof runtime.close === "function") {
      try {
        await runtime.close();
      } catch {}
    }

    const redisClient = REDIS_CLIENT;
    REDIS_CLIENT = null;
    REDIS_CONNECTING = null;
    await closeRedisClientHandle(redisClient);
    await dbManagerSystem.closeAllPools().catch(() => {});

    console.log(`[shutdown] completed (${signal})`);
  })();
  return SHUTDOWN_PROMISE;
}

function loadEnvFile() {
  const envPaths = [
    path.join(__dirname, "..", ".env"),
    path.join(__dirname, ".env"),
  ];
  for (const envPath of envPaths) {
    if (!fs.existsSync(envPath)) {
      continue;
    }
    const raw = fs.readFileSync(envPath, "utf8");
    for (const line of raw.split(/\r?\n/)) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) {
        continue;
      }
      const idx = trimmed.indexOf("=");
      if (idx <= 0) {
        continue;
      }
      const key = trimmed.slice(0, idx).trim();
      const value = trimmed.slice(idx + 1).trim();
      if (process.env[key] === undefined) {
        process.env[key] = value;
      }
    }
  }
}

