function trackApiCall(apiName) {
  const name = String(apiName || "unknown").toLowerCase();
  if (GLOBAL_API_STATS.counters[name] !== undefined) {
    GLOBAL_API_STATS.counters[name]++;
  } else {
    GLOBAL_API_STATS.counters[name] = 1;
  }
  GLOBAL_API_STATS.last_updates.unshift({
    api: apiName,
    time: Date.now(),
  });
  if (GLOBAL_API_STATS.last_updates.length > 50) {
    GLOBAL_API_STATS.last_updates.pop();
  }
  // Route through NotificationManager
  if (notificationManager) {
    notificationManager.handle("REMOTE_API_CALL", "call", {
      api: apiName,
      message: name,
    });
  }
}

function asBool(value, fallback = false) {
  if (value === undefined || value === null) {
    return fallback;
  }
  const raw = String(value).trim();
  if (raw === "") {
    return fallback;
  }
  const v = raw.toLowerCase();
  return v === "1" || v === "true" || v === "yes" || v === "on";
}

function asNum(value, fallback = NaN) {
  if (value === undefined || value === null) {
    return fallback;
  }
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return asNum(value.price ?? value.value ?? value.level, fallback);
  }
  if (typeof value === "string" && value.trim() === "") {
    return fallback;
  }
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function parseKeySet(value) {
  return new Set(
    envStr(value)
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean),
  );
}

function envStr(value, fallback = "") {
  if (value === undefined || value === null) {
    return fallback;
  }
  const s = String(value).trim();
  return s === "" ? fallback : s;
}

function nullLikeEmpty(value, fallback = "") {
  if (value === undefined || value === null) return fallback;
  const text = String(value).trim();
  if (!text || text.toLowerCase() === "null") return fallback;
  return text;
}

function envFlag(value, fallback = false) {
  if (value === undefined || value === null || value === "") {
    return Boolean(fallback);
  }
  const normalized = String(value).trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(normalized)) return true;
  if (["0", "false", "no", "off"].includes(normalized)) return false;
  return Boolean(fallback);
}

function clipForLog(value, maxLen = 4000) {
  const raw = typeof value === "string" ? value : JSON.stringify(value);
  const text = String(raw || "");
  if (text.length <= maxLen) return text;
  return `${text.slice(0, Math.max(0, maxLen))} …[truncated ${text.length - maxLen} chars]`;
}

function hashForLog(value) {
  const text = String(value || "");
  return crypto.createHash("sha256").update(text).digest("hex").slice(0, 16);
}

function normalizeIsoTimestamp(value, fallback = new Date().toISOString()) {
  if (value instanceof Date) {
    const ms = value.getTime();
    return Number.isFinite(ms) ? new Date(ms).toISOString() : fallback;
  }
  const raw = String(value ?? "").trim();
  if (!raw) return fallback;
  const ms = Date.parse(raw);
  if (!Number.isFinite(ms)) return fallback;
  return new Date(ms).toISOString();
}

function trimImageBlocksFromMessages(
  messages = [],
  maxImageBlocks = Number.MAX_SAFE_INTEGER,
) {
  const safeLimit = Number.isFinite(Number(maxImageBlocks))
    ? Math.max(0, Math.floor(Number(maxImageBlocks)))
    : Number.MAX_SAFE_INTEGER;
  if (!Array.isArray(messages) || !messages.length) {
    return {
      messages,
      totalImageBlocks: 0,
      imageBlocksUsed: 0,
      imageBlocksDropped: 0,
    };
  }

  let imageSeen = 0;
  let imageUsed = 0;
  let imageDropped = 0;
  const out = [];

  for (const message of messages) {
    if (
      !message ||
      typeof message !== "object" ||
      !Array.isArray(message.content)
    ) {
      out.push(message);
      continue;
    }

    const newContent = [];
    for (const block of message.content) {
      if (block?.type === "image") {
        imageSeen += 1;
        if (imageUsed < safeLimit) {
          imageUsed += 1;
          newContent.push(block);
          continue;
        }
        imageDropped += 1;
        continue;
      }
      newContent.push(block);
    }

    out.push({
      ...message,
      content: newContent,
    });
  }

  return {
    messages: out,
    totalImageBlocks: imageSeen,
    imageBlocksUsed: imageUsed,
    imageBlocksDropped: imageDropped,
  };
}

function isOllamaRunnerStoppedError(error) {
  const msg = String(error?.message || "").toLowerCase();
  if (!msg.includes("ollama api error (500)")) return false;
  return (
    msg.includes("model runner has unexpectedly stopped") ||
    msg.includes("runner has unexpectedly stopped")
  );
}

