// --- SSE Notification Bus ---
const SSE_CLIENTS = new Map(); // userId -> Set<res>
function sseRegisterClient(userId, res) {
  if (!SSE_CLIENTS.has(userId)) SSE_CLIENTS.set(userId, new Set());
  SSE_CLIENTS.get(userId).add(res);
}
function sseRemoveClient(userId, res) {
  const set = SSE_CLIENTS.get(userId);
  if (set) {
    set.delete(res);
    if (!set.size) SSE_CLIENTS.delete(userId);
  }
}
function emitNotification(payload) {
  const data = `data: ${JSON.stringify(payload)}\n\n`;
  const targets = new Set();
  // user-specific clients
  if (payload.user_id) {
    const userClients = SSE_CLIENTS.get(payload.user_id);
    if (userClients) userClients.forEach((r) => targets.add(r));
  }
  // global clients (admin/system listeners)
  const globalClients = SSE_CLIENTS.get("*");
  if (globalClients) globalClients.forEach((r) => targets.add(r));
  // optional broadcast to all connected users (used for cross-surface events)
  if (payload && payload.broadcast_all === true) {
    for (const set of SSE_CLIENTS.values()) {
      set.forEach((r) => targets.add(r));
    }
  }
  for (const res of targets) {
    try {
      res.write(data);
    } catch (e) {
      /* client disconnected */
    }
  }

  const envelope = {
    topic: buildNotificationTopic(payload?.user_id || "*"),
    type: "notification",
    ts: Date.now(),
    version: Date.now(),
    transport: "sse",
    data: payload,
  };
  if (payload?.user_id) {
    emitRealtimeTopic(buildNotificationTopic(payload.user_id), envelope);
  }
  emitRealtimeTopic(buildNotificationTopic("*"), {
    ...envelope,
    topic: buildNotificationTopic("*"),
  });
  if (payload && payload.broadcast_all === true) {
    for (const topic of listRealtimeTopics()) {
      if (!String(topic).startsWith("notifications:")) continue;
      emitRealtimeTopic(topic, {
        ...envelope,
        topic: String(topic),
      });
    }
  }
}

function emitMt5RealtimeEvent(payload = {}) {
  const userId = String(payload?.user_id || CFG.mt5DefaultUserId || "*").trim() || "*";
  const envelope = createRealtimeEnvelope(
    buildMt5Topic(userId),
    String(payload?.event || "mt5").trim().toLowerCase() || "mt5",
    payload,
  );
  emitRealtimeTopic(buildMt5Topic(userId), envelope);
  emitRealtimeTopic(buildMt5Topic("*"), {
    ...envelope,
    topic: buildMt5Topic("*"),
  });
}

function emitBrokerSymbolMetadataRealtime(payload = {}) {
  const symbols = [
    ...new Set(
      (Array.isArray(payload.symbols) ? payload.symbols : [payload.symbol])
        .map((symbol) => String(symbol || "").trim().toUpperCase())
        .filter(Boolean),
    ),
  ];
  emitMt5RealtimeEvent({
    ...payload,
    event: "BROKER_SYMBOL_METADATA_UPDATE",
    type: "broker_symbol_metadata",
    symbols,
    symbol_count: symbols.length,
    need_refresh: true,
    comp_refresh: "market_data",
  });
}

function emitTradeRealtimeEvent(payload = {}) {
  return emitTradeRealtimeUpdate(payload, { emitRealtimeTopic });
}

function emitChartRealtimeEvent(symbol, type, payload = {}) {
  const topic = buildChartTopic(symbol);
  if (!topic) return;
  const eventType = String(type || "message").trim().toLowerCase() || "message";
  const envelope = createRealtimeEnvelope(topic, eventType, payload);
  emitRealtimeTopic(topic, envelope);
  emitRealtimeTopic(buildChartTopic("*"), {
    ...envelope,
    topic: buildChartTopic("*"),
  });
}

