function emitLogRealtimeAppendFromPath(fullPath, line, extra = {}) {
  const safePath = String(fullPath || "").trim();
  const textLine = String(line || "").trimEnd();
  if (!safePath || !textLine || !SERVER_LOG_DIR) return;
  const relativePath = path.relative(SERVER_LOG_DIR, safePath);
  if (!relativePath || relativePath.startsWith("..")) return;
  const parts = relativePath.split(path.sep).filter(Boolean);
  if (parts.length < 2) return;
  const source = String(parts[0] || "").trim().toLowerCase();
  const fileName = String(path.basename(parts[parts.length - 1]) || "").replace(
    /\.log$/i,
    "",
  );
  const objectId =
    parts.length >= 3
      ? String(parts[1] || "").trim()
      : fileName;
  const topic = buildLogTopic(source, objectId, fileName);
  if (!topic) return;
  emitRealtimeTopic(
    topic,
    createRealtimeEnvelope(topic, "log_append", {
      source,
      objectId,
      file: fileName,
      line: textLine,
      ...extra,
    }),
  );
}
// --- File-based notification persistence ---
const NOTIFICATIONS_LOG_PATH = path.join(
  SERVER_LOG_DIR,
  "system",
  "notifications.log",
);

function appendNotificationToFile(payload) {
  try {
    const dir = path.dirname(NOTIFICATIONS_LOG_PATH);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    const payloadData =
      payload?.data && typeof payload.data === "object" ? payload.data : null;
    const statusRaw =
      String(payload?.status || "").trim().toLowerCase() ||
      (String(payload?.type || "").trim().toLowerCase() === "error"
        ? "error"
        : "ok");
    const entry = {
      t: new Date().toISOString(),
      request_id:
        String(payload?.request_id || payload?.requestId || "").trim() || null,
      event: payload.event || "",
      message: payload.message || "",
      type: payload.type || "info",
      status: statusRaw,
      result:
        String(payload?.result || "").trim() ||
        (statusRaw === "error" ? "error" : "ok"),
      user_id: payload.user_id || null,
      symbol: payload.symbol || null,
      sid:
        payload.sid ||
        payload.trade_sid ||
        payloadData?.sid ||
        payloadData?.trade_sid ||
        null,
      source_type:
        payload.source_type ||
        payload.object_table ||
        payloadData?.source_type ||
        payloadData?.object_table ||
        "",
      source_id:
        payload.source_id ||
        payload.object_id ||
        payloadData?.source_id ||
        payloadData?.object_id ||
        "",
      duration_ms:
        Number(
          payload.duration_ms ||
            payload.durationMs ||
            payloadData?.duration_ms ||
            payloadData?._timing?.total_ms ||
            0,
        ) || null,
      db_duration_ms:
        Number(
          payload.db_duration_ms ||
            payload.dbDurationMs ||
            payloadData?.db_duration_ms ||
            payloadData?._timing?.db_ms ||
            0,
        ) || null,
      error: payload.error || "",
      cron_name: payload.cron_name || payloadData?.cron_name || "",
      data: payloadData || payload || {},
    };
    const line = JSON.stringify(entry) + "\n";
    // Read existing, append, trim to max 500 lines
    let lines = [];
    if (fs.existsSync(NOTIFICATIONS_LOG_PATH)) {
      lines = fs
        .readFileSync(NOTIFICATIONS_LOG_PATH, "utf8")
        .trim()
        .split("\n")
        .filter(Boolean);
    }
    lines.push(line);
    // Keep last 500 lines
    if (lines.length > 500) lines = lines.slice(-500);
    fs.writeFileSync(NOTIFICATIONS_LOG_PATH, lines.join("\n") + "\n");
  } catch (_) {}
}

const CHART_ARTIFACT_NOTIFICATION_COALESCE_MS = 15000;

function buildChartArtifactRefreshRequestId({
  symbol = "",
  timeframe = "",
  startTime = null,
  endTime = null,
  rebuildMode = "merge",
} = {}) {
  const bucket = Math.floor(Date.now() / CHART_ARTIFACT_NOTIFICATION_COALESCE_MS);
  return [
    "chart_artifacts",
    String(symbol || "").trim().toUpperCase() || "UNKNOWN",
    String(timeframe || "").trim().toLowerCase() || "na",
    Number.isFinite(Number(startTime)) ? Math.floor(Number(startTime)) : "na",
    Number.isFinite(Number(endTime)) ? Math.floor(Number(endTime)) : "na",
    String(rebuildMode || "merge").trim().toLowerCase() || "merge",
    bucket,
  ].join(":");
}

function readNotificationsFromFile(limit = 100) {
  if (!fs.existsSync(NOTIFICATIONS_LOG_PATH)) return [];
  try {
    const raw = fs.readFileSync(NOTIFICATIONS_LOG_PATH, "utf8");
    const lines = raw.trim().split("\n");
    // Return last N lines, reversed (newest first)
    const sliced = lines.slice(-Math.max(1, Math.min(limit, 500)));
    return sliced
      .map((l) => {
        try {
          return JSON.parse(l);
        } catch (_) {
          return null;
        }
      })
      .filter(Boolean)
      .reverse();
  } catch (_) {
    return [];
  }
}

function clearNotificationsFile() {
  try {
    if (fs.existsSync(NOTIFICATIONS_LOG_PATH)) {
      fs.truncateSync(NOTIFICATIONS_LOG_PATH, 0);
    }
    return true;
  } catch (_) {
    return false;
  }
}

function createRealtimeEnvelope(topic, type, data, extra = {}) {
  return {
    topic: String(topic || "").trim(),
    type: String(type || "message").trim(),
    ts: Date.now(),
    version: Number(extra.version) || Date.now(),
    transport: "sse",
    ...extra,
    data,
  };
}

function parseRealtimeStreamParams(url) {
  const topicRaw = String(url.searchParams.get("topic") || "").trim();
  const topic = parseTopic(topicRaw);
  const bars = Math.max(
    50,
    Math.min(5000, Number(url.searchParams.get("bars") || 300) || 300),
  );
  const pollMs = Math.max(
    1000,
    Math.min(30000, Number(url.searchParams.get("poll_ms") || 2500) || 2500),
  );
  const endTimeSec = Number(
    url.searchParams.get("end_time_unix") ||
      url.searchParams.get("endTimeUnix") ||
      0,
  );
  return {
    topic,
    topicRaw,
    bars,
    pollMs,
    endTimeSec: Number.isFinite(endTimeSec) && endTimeSec > 0 ? endTimeSec : null,
  };
}

const LEGACY_TRADES_TEMP_DISABLED = true;

function isLegacyTradesApiPath(pathname = "") {
  const normalized = String(pathname || "").trim();
  if (/^\/api\/trades(?:\/|$)/.test(normalized)) {
    return false;
  }
  return /^\/v2\/trades(?:\/|$)/.test(normalized);
}

function isLegacyTradesSyncPath(pathname = "") {
  const normalized = String(pathname || "").trim();
  return (
    normalized === "/mt5/ea/sync" ||
    normalized === "/mt5/ea/bulk-sync"
  );
}

function legacyTradesDisabledPayload() {
  return {
    ok: false,
    error:
      "Legacy trades is temporarily disabled. Use Trades (/api/trades) only.",
    code: "LEGACY_TRADES_DISABLED",
  };
}

function authorizeRealtimeSocket(socket) {
  const handshake = socket?.handshake || {};
  const headers = handshake.headers || {};
  const query = handshake.query || {};
  const auth = handshake.auth || {};
  const reqLike = { headers };
  const sess = getUiSessionFromReq(reqLike);
  const apiKey = String(
    auth.apiKey || query.key || headers["x-api-key"] || "",
  ).trim();
  const isAdmin = apiKey === CFG.adminKey;
  if (!sess.ok && !isAdmin) {
    return { ok: false, error: "AUTH_REQUIRED" };
  }
  return {
    ok: true,
    isAdmin,
    session: sess,
  };
}

function canAccessRealtimeChatTopic(authResult, parsedTopic) {
  if (String(parsedTopic?.kind || "").trim().toLowerCase() !== "chat") return true;
  const auth = authResult && typeof authResult === "object" ? authResult : {};
  if (auth.isAdmin) return true;
  const sessionUserId =
    String(auth?.session?.user_id || CFG.mt5DefaultUserId || "").trim();
  const topicUserId = String(parsedTopic?.userId || "").trim();
  return Boolean(sessionUserId && topicUserId && sessionUserId === topicUserId);
}

