// Discover all symbols with market_data directories
function discoverAllMarketSymbols() {
  const dir = path.join(GLOBAL_DATA_DIR, "market_data");
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir)
    .filter((d) => fs.statSync(path.join(dir, d)).isDirectory())
    .filter((d) => d === d.toUpperCase())
    .sort();
}

async function ensureUserSymbolGroups(userId) {
  const safeUserId = String(userId || CFG.mt5DefaultUserId || "default").trim();
  const existing = await settingsStore.getUserSettingData(
    safeUserId,
    "symbol_groups",
    "default",
  );
  if (
    existing &&
    Array.isArray(existing.groups) &&
    existing.groups.length > 0
  ) {
    const normalized = normalizeSymbolGroupsData(existing);
    if (JSON.stringify(normalized) !== JSON.stringify(existing)) {
      await settingsStore.upsertUserSetting(
        safeUserId,
        "symbol_groups",
        "default",
        normalized,
        "ACTIVE",
      );
    }
    return normalized;
  }

  const legacyWatchlist = await settingsStore.getUserSettingData(
    safeUserId,
    "trade",
    "WATCHLIST",
  );
  const migrated = normalizeSymbolGroupsData({
    groups: [
      {
        id: "watchlist",
        name: "Watchlist",
        symbols: Array.isArray(legacyWatchlist?.symbols)
          ? legacyWatchlist.symbols
          : [],
      },
    ],
  });
  await settingsStore.upsertUserSetting(
    safeUserId,
    "symbol_groups",
    "default",
    migrated,
    "ACTIVE",
  );
  await settingsStore
    .deleteUserSetting(safeUserId, "trade", "WATCHLIST")
    .catch(() => {});
  return migrated;
}

async function getUserWatchlistSymbols(userId) {
  const symbolGroups = await ensureUserSymbolGroups(userId);
  return resolveSymbolsGroupSymbols(symbolGroups, "system:watchlist", []);
}

async function getBrokerTrackedSymbols(userId, accountId, options = {}) {
  const uid = String(userId || CFG.mt5DefaultUserId || "").trim();
  const aid = String(accountId || "").trim();
  const cacheKey = `${uid}:${aid}`;
  const now = Date.now();
  const forceRefresh = options?.forceRefresh === true;
  const cached = BROKER_TRACKED_SYMBOLS_CACHE.get(cacheKey);
  if (
    !forceRefresh &&
    cached &&
    cached.expiresAt > now &&
    cached.value &&
    typeof cached.value === "object"
  ) {
    return cached.value;
  }

  const watchlist =
    uid ? (await getUserWatchlistSymbols(uid).catch(() => [])) || [] : [];
  const positionSymbols = [];
  if (uid && aid) {
    try {
      const b = await mt5Backend();
      const tradesRes = await b.listTradesV2({
        userId: uid,
        accountId: aid,
        pageSize: 200,
        executionStatus: ["FILLED", "PENDING"],
      });
      for (const trade of tradesRes.items || []) {
        const symbol = String(trade?.symbol || "").trim().toUpperCase();
        if (symbol && !positionSymbols.includes(symbol)) {
          positionSymbols.push(symbol);
        }
      }
    } catch {}
  }

  const watchlistSymbols = [
    ...new Set(
      watchlist
        .map((symbol) => String(symbol).trim().toUpperCase())
        .filter(Boolean),
    ),
  ];
  const value = {
    positionSymbols,
    watchlistSymbols,
    symbols: [...new Set([...positionSymbols, ...watchlistSymbols])].sort(),
  };
  BROKER_TRACKED_SYMBOLS_CACHE.set(cacheKey, {
    expiresAt: now + BROKER_TRACKED_SYMBOLS_CACHE_TTL_MS,
    value,
  });
  return value;
}

async function syncReservedSymbolGroupSymbols(
  userId,
  groupId,
  groupName,
  symbols = [],
  options = {},
) {
  const mergeIntoExisting = options?.mergeIntoExisting === true;
  const normalizedSymbols = [
    ...new Set(
      (Array.isArray(symbols) ? symbols : [])
        .map((value) =>
          String(value || "")
            .trim()
            .toUpperCase(),
        )
        .filter(Boolean),
    ),
  ];
  const current = await ensureUserSymbolGroups(userId);
  const next = normalizeSymbolGroupsData({
    ...current,
    groups: (current.groups || []).map((group) =>
      group.id === groupId
        ? {
            ...group,
            name: groupName,
            symbols: mergeIntoExisting
              ? [
                  ...(Array.isArray(group.symbols) ? group.symbols : []),
                  ...normalizedSymbols,
                ]
              : normalizedSymbols,
          }
        : group,
    ),
  });
  if (JSON.stringify(next) === JSON.stringify(current)) return next;
  await settingsStore.upsertUserSetting(
    userId,
    "symbol_groups",
    "default",
    next,
    "ACTIVE",
  );
  await StateRepo.del("USER_SETTINGS", userId).catch(() => {});
  return next;
}

async function pushDynamicSymbolsToWatchlists(symbols = []) {
  const rows = await settingsStore
    .listUserSettingsByType(null, "symbol_groups")
    .catch(() => []);
  const userIds = new Set([CFG.mt5DefaultUserId]);
  for (const row of rows || []) {
    const userId = String(row?.user_id || row?.userId || "").trim();
    if (userId) userIds.add(userId);
  }
  for (const userId of userIds) {
    await syncReservedSymbolGroupSymbols(
      userId,
      "watchlist",
      "Watchlist",
      symbols,
      { mergeIntoExisting: true },
    ).catch((error) => {
      console.warn(
        `[news] Failed to push dynamic symbols into Watchlist for ${userId}:`,
        error?.message || error,
      );
    });
  }
}

function roundNumber(value, digits = 6) {
  const num = Number(value);
  if (!Number.isFinite(num)) return null;
  const factor = 10 ** digits;
  return Math.round(num * factor) / factor;
}

function average(values = []) {
  const nums = values.map(Number).filter(Number.isFinite);
  if (!nums.length) return null;
  return nums.reduce((sum, value) => sum + value, 0) / nums.length;
}

function scoreDynamicSymbolFromBars(symbol, bars = [], timeframe = "15m") {
  const series = Array.isArray(bars) ? bars.filter(Boolean) : [];
  if (series.length < 25) return null;
  const latest = series[series.length - 1];
  const previous = series[series.length - 2];
  const history = series.slice(-21, -1);
  if (!latest || !previous || history.length < 20) return null;

  const latestRange = Math.abs(Number(latest.high) - Number(latest.low));
  const latestBody = Math.abs(Number(latest.close) - Number(latest.open));
  const prevClose = Number(previous.close);
  const latestClose = Number(latest.close);
  if (
    !Number.isFinite(latestRange) ||
    !Number.isFinite(latestBody) ||
    !Number.isFinite(prevClose) ||
    !Number.isFinite(latestClose)
  ) {
    return null;
  }

  const avgRange = average(
    history.map((bar) => Math.abs(Number(bar.high) - Number(bar.low))),
  );
  const avgBody = average(
    history.map((bar) => Math.abs(Number(bar.close) - Number(bar.open))),
  );
  const priorHigh = Math.max(...history.map((bar) => Number(bar.high)));
  const priorLow = Math.min(...history.map((bar) => Number(bar.low)));
  if (
    !Number.isFinite(avgRange) ||
    !Number.isFinite(avgBody) ||
    !Number.isFinite(priorHigh) ||
    !Number.isFinite(priorLow) ||
    avgRange <= 0
  ) {
    return null;
  }

  const moveFromPrev = Math.abs(latestClose - prevClose);
  const breakoutUp = latestClose > priorHigh;
  const breakoutDown = latestClose < priorLow;
  const nearHigh = Math.abs(priorHigh - latestClose) <= avgRange * 0.35;
  const nearLow = Math.abs(latestClose - priorLow) <= avgRange * 0.35;
  const bigMove = moveFromPrev >= avgRange * 1.25;
  const expansion =
    latestRange >= avgRange * 1.35 || latestBody >= avgBody * 1.5;

  let score = 0;
  const reasons = [];
  if (breakoutUp || breakoutDown) {
    score += 5;
    reasons.push(breakoutUp ? "breakout_up" : "breakout_down");
  }
  if (bigMove) {
    score += 3;
    reasons.push("big_move");
  }
  if (expansion) {
    score += 2;
    reasons.push("range_expansion");
  }
  if (nearHigh || nearLow) {
    score += 2;
    reasons.push(nearHigh ? "near_range_high" : "near_range_low");
  }

  if (!reasons.length) return null;
  return {
    symbol,
    timeframe,
    score,
    reasons,
    latest_close: roundNumber(latestClose),
    prior_high: roundNumber(priorHigh),
    prior_low: roundNumber(priorLow),
    avg_range: roundNumber(avgRange),
    latest_range: roundNumber(latestRange),
    moved_from_prev: roundNumber(moveFromPrev),
  };
}

function buildMarketDynamicCandidates(limit = 12) {
  const symbols = discoverAllMarketSymbols();
  const candidates = [];
  for (const symbol of symbols) {
    const bars15 = readBrokerBarsFromCsv(symbol, "15m", 40);
    const bars60 = readBrokerBarsFromCsv(symbol, "1h", 40);
    const score15 = scoreDynamicSymbolFromBars(symbol, bars15, "15m");
    const score60 = scoreDynamicSymbolFromBars(symbol, bars60, "1h");
    const best = !score15
      ? score60
      : !score60
        ? score15
        : score60.score > score15.score
          ? score60
          : score15;
    if (best) candidates.push(best);
  }

  return candidates
    .sort((a, b) => {
      if (b.score !== a.score) return b.score - a.score;
      return String(a.symbol).localeCompare(String(b.symbol));
    })
    .slice(0, Math.max(1, limit));
}

function readJsonUrlWithCurl(url) {
  const out = execFileSync(
    "curl",
    [
      "-sS",
      "-L",
      "--max-time",
      "15",
      "-H",
      "accept: application/json,text/plain,*/*",
      "-A",
      "Mozilla/5.0",
      url,
    ],
    {
      encoding: "utf8",
      maxBuffer: 10 * 1024 * 1024,
    },
  );
  return JSON.parse(out);
}

async function fetchEconomicCalendarFeed(url) {
  let lastError = null;

  try {
    const resp = await fetch(url, {
      timeout: 10000,
      headers: {
        accept: "application/json,text/plain,*/*",
        "user-agent": "Mozilla/5.0",
      },
    });
    const text = await resp.text();
    if (!resp.ok) {
      throw new Error(`status ${resp.status} ${resp.statusText}`.trim());
    }
    const parsed = JSON.parse(text);
    if (!Array.isArray(parsed)) {
      throw new Error("response was not a JSON array");
    }
    return parsed;
  } catch (error) {
    lastError = error;
  }

  try {
    return readJsonUrlWithCurl(url);
  } catch (error) {
    const curlMessage = error?.message || error;
    const fetchMessage =
      lastError?.message || lastError || "unknown fetch error";
    throw new Error(
      `fetch failed (${fetchMessage}); curl failed (${curlMessage})`,
    );
  }
}

async function refreshDynamicSymbolGroup(events = []) {
  const now = Date.now();
  const newsCandidates = (Array.isArray(events) ? events : [])
    .filter((event) => {
      const phase = getNewsEventPhase(event, now);
      const minutesUntilStart = Number(event?.minutes_until_start);
      return (
        phase === "before" ||
        phase === "during" ||
        (phase === "upcoming" &&
          Number.isFinite(minutesUntilStart) &&
          minutesUntilStart <= 48 * 60)
      );
    })
    .map((event) => ({
      source: "news",
      news_type: event.news_type,
      symbol_count: Array.isArray(event.effective_symbols)
        ? event.effective_symbols.length
        : 0,
      symbols: Array.isArray(event.effective_symbols)
        ? event.effective_symbols
        : [],
      title: event.title,
      phase: getNewsEventPhase(event, now),
      start_at: event.start_at,
      minutes_until_start: Number(event.minutes_until_start) || null,
      score: Number(event.score) || 0,
    }));

  const marketCandidates = buildMarketDynamicCandidates(12);
  const mergedSymbols = new Set();
  for (const item of newsCandidates) {
    for (const symbol of item.symbols || []) {
      const normalized = normalizeMarketDataSymbol(symbol);
      if (normalized) mergedSymbols.add(normalized);
    }
  }
  for (const item of marketCandidates) {
    const normalized = normalizeMarketDataSymbol(item.symbol);
    if (normalized) mergedSymbols.add(normalized);
  }

  const payload = {
    updated_at: new Date().toISOString(),
    sources: {
      news: newsCandidates,
      market: marketCandidates,
    },
    symbols: [...mergedSymbols].sort((a, b) => a.localeCompare(b)),
  };
  await StateRepo.set("DYNAMIC_SYMBOL_GROUP", "watchlist", payload).catch(
    () => {},
  );
  return payload;
}

function parseCronScheduleSpec(schedule) {
  const raw = String(schedule || "").trim();
  if (!raw) {
    return { mode: "none", raw: "", normalized: "", intervalSeconds: 0 };
  }

  const everyMatch = raw.match(/^every\s+(\d+)(s|m|h|d)$/i);
  if (everyMatch) {
    const value = parseInt(everyMatch[1], 10);
    const unit = everyMatch[2].toLowerCase();
    if (!Number.isFinite(value) || value <= 0) {
      return { mode: "invalid", raw, normalized: raw, intervalSeconds: 0 };
    }
    let intervalSeconds = value;
    if (unit === "m") intervalSeconds = value * 60;
    else if (unit === "h") intervalSeconds = value * 3600;
    else if (unit === "d") intervalSeconds = value * 86400;
    return {
      mode: "interval",
      raw,
      normalized: `every ${value}${unit}`,
      intervalSeconds,
    };
  }

  const atMatch = raw.match(/^at (\d{1,2}):(\d{2})\s+on\s+(.+)$/i);
  if (atMatch) {
    const hour = parseInt(atMatch[1], 10);
    const minute = parseInt(atMatch[2], 10);
    const days = atMatch[3]
      .split(",")
      .map((d) => d.trim().toLowerCase())
      .filter(Boolean);
    if (
      !Number.isFinite(hour) ||
      !Number.isFinite(minute) ||
      hour < 0 ||
      hour > 23 ||
      minute < 0 ||
      minute > 59 ||
      !days.length
    ) {
      return { mode: "invalid", raw, normalized: raw, intervalSeconds: 0 };
    }
    const normalizedDays = days
      .map((d) => d.slice(0, 1).toUpperCase() + d.slice(1, 3).toLowerCase())
      .join(",");
    return {
      mode: "event",
      raw,
      normalized: `at ${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")} on ${normalizedDays}`,
      intervalSeconds: 0,
    };
  }

  return { mode: "invalid", raw, normalized: raw, intervalSeconds: 0 };
}

const CRON_SCHEDULE_DAY_ORDER = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const CRON_SCHEDULE_DAY_INDEX = {
  Sun: 0,
  Mon: 1,
  Tue: 2,
  Wed: 3,
  Thu: 4,
  Fri: 5,
  Sat: 6,
};

function normalizeCronScheduleDay(value = "") {
  const raw = String(value || "").trim().slice(0, 3).toLowerCase();
  const match = CRON_SCHEDULE_DAY_ORDER.find(
    (day) => day.toLowerCase() === raw,
  );
  return match || "";
}

function normalizeCronScheduleTime(value = "", fallback = "00:00") {
  const match = String(value || "")
    .trim()
    .match(/^(\d{1,2}):(\d{2})$/);
  if (!match) return fallback;
  const hour = Number(match[1]);
  const minute = Number(match[2]);
  if (
    !Number.isFinite(hour) ||
    !Number.isFinite(minute) ||
    hour < 0 ||
    hour > 23 ||
    minute < 0 ||
    minute > 59
  ) {
    return fallback;
  }
  return `${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}`;
}

function cronScheduleTimeToMinutes(value = "") {
  const match = normalizeCronScheduleTime(value, "").match(/^(\d{2}):(\d{2})$/);
  if (!match) return NaN;
  return Number(match[1]) * 60 + Number(match[2]);
}

function normalizeCronScheduleExactTimes(value) {
  const raw = Array.isArray(value)
    ? value
    : String(value || "")
        .split(/[\n,;]+/)
        .map((item) => item.trim());
  return [...new Set(raw.map((item) => normalizeCronScheduleTime(item, "")).filter(Boolean))];
}

function normalizeCronScheduleWindow(
  window = {},
  fallbackIntervalSeconds = 60,
  fallbackId = "",
) {
  const mode = String(window?.mode || "interval").trim().toLowerCase();
  const exactTimes = normalizeCronScheduleExactTimes(window?.exact_times);
  const normalizedMode = mode === "exact" ? "exact" : "interval";
  const from = normalizeCronScheduleTime(
    window?.from,
    exactTimes[0] || "00:00",
  );
  const to = normalizeCronScheduleTime(
    window?.to,
    exactTimes[exactTimes.length - 1] || "23:59",
  );
  return {
    id: String(window?.id || fallbackId || "window"),
    mode: normalizedMode,
    from,
    to,
    interval_seconds: Math.max(
      15,
      Math.round(
        Number(window?.interval_seconds || fallbackIntervalSeconds) ||
          fallbackIntervalSeconds,
      ),
    ),
    exact_times: exactTimes,
  };
}

function normalizeCronScheduleRows(rows = [], fallbackIntervalSeconds = 60) {
  const byDay = new Map();
  for (const row of Array.isArray(rows) ? rows : []) {
    const day = normalizeCronScheduleDay(row?.day);
    if (!day) continue;
    const rawWindows =
      Array.isArray(row?.windows) && row.windows.length
        ? row.windows
        : [
            {
              id: `${day}-0`,
              mode: row?.mode || "interval",
              from: row?.from,
              to: row?.to,
              interval_seconds: row?.interval_seconds,
              exact_times: row?.exact_times,
            },
          ];
    const windows = rawWindows.map((window, index) =>
      normalizeCronScheduleWindow(
        window,
        fallbackIntervalSeconds,
        `${day}-${index}`,
      ),
    );
    const primaryWindow =
      windows[0] ||
      normalizeCronScheduleWindow({}, fallbackIntervalSeconds, `${day}-0`);
    byDay.set(day, {
      day,
      enabled: row?.enabled !== false,
      from: primaryWindow.from,
      to: primaryWindow.to,
      interval_seconds: primaryWindow.interval_seconds,
      mode: primaryWindow.mode,
      exact_times: primaryWindow.exact_times,
      windows,
    });
  }
  return CRON_SCHEDULE_DAY_ORDER.map((day) => {
    const existing = byDay.get(day);
    if (existing) return existing;
    const primaryWindow = normalizeCronScheduleWindow(
      {},
      fallbackIntervalSeconds,
      `${day}-0`,
    );
    return (
      {
        day,
        enabled: false,
        from: primaryWindow.from,
        to: primaryWindow.to,
        interval_seconds: primaryWindow.interval_seconds,
        mode: primaryWindow.mode,
        exact_times: primaryWindow.exact_times,
        windows: [primaryWindow],
      }
    );
  });
}

function summarizeCronScheduleRows(rows = []) {
  const enabledRows = normalizeCronScheduleRows(rows).filter((row) => row.enabled);
  return enabledRows
    .map((row) => {
      const summary = (Array.isArray(row.windows) ? row.windows : [])
        .map((window) => {
          if (window?.mode === "exact") {
            return `@ ${(window.exact_times || []).join(", ") || "--"}`;
          }
          return `${window.from}-${window.to} / ${Math.max(1, Number(window.interval_seconds || 60))}s`;
        })
        .join(" | ");
      return `${row.day} ${summary}`;
    })
    .join("; ");
}

async function shouldSkipCronForNews(data = {}, nowMs = Date.now()) {
  if (data?.avoid_news !== true) return false;
  const newsEvents = await StateRepo.get("NEWS_CALENDAR", "week").catch(
    () => [],
  );
  const activeSymbols = collectEffectiveSymbolsForPhase(newsEvents, nowMs);
  if (!activeSymbols.length) return false;
  const cronSymbols = Array.isArray(data?.symbols)
    ? data.symbols
        .map((item) => String(item || "").trim().toUpperCase())
        .filter(Boolean)
    : [];
  if (!cronSymbols.length) return true;
  return cronSymbols.some((symbol) => activeSymbols.includes(symbol));
}

function normalizeCronSettingData(data = {}, options = {}) {
  const base = data && typeof data === "object" ? { ...data } : {};
  const defaultCadenceSeconds = Math.max(
    1,
    Number(options.defaultCadenceSeconds || 60) || 60,
  );
  const spec = parseCronScheduleSpec(base.schedule);
  let cadenceSec = Number(base.cadence_seconds || 0);
  if (!Number.isFinite(cadenceSec) || cadenceSec <= 0) {
    const legacyMinutes = Number(base.cadence_minutes || 0);
    if (Number.isFinite(legacyMinutes) && legacyMinutes > 0) {
      cadenceSec = legacyMinutes * 60;
    }
  }
  if (spec.mode === "interval") {
    cadenceSec = spec.intervalSeconds;
  }
  if (!Number.isFinite(cadenceSec) || cadenceSec <= 0) {
    cadenceSec = defaultCadenceSeconds;
  }

  const out = {
    ...base,
    cadence_seconds: cadenceSec,
    timezone: normalizeCronTimezone(base.timezone),
    active_from: (() => {
      const time = new Date(base.active_from || "").getTime();
      return Number.isFinite(time) ? new Date(time).toISOString() : "";
    })(),
    active_to: (() => {
      const time = new Date(base.active_to || "").getTime();
      return Number.isFinite(time) ? new Date(time).toISOString() : "";
    })(),
    cooldown_seconds: Math.max(0, Number(base.cooldown_seconds || 0) || 0),
    avoid_news: base.avoid_news === true,
  };
  if (Array.isArray(base.schedule_rows) && base.schedule_rows.length > 0) {
    out.schedule_rows = normalizeCronScheduleRows(base.schedule_rows, cadenceSec);
    out.schedule = summarizeCronScheduleRows(out.schedule_rows);
  } else if (spec.mode === "interval" || spec.mode === "event") {
    out.schedule = spec.normalized;
  } else if (spec.mode === "none") {
    out.schedule = "";
  } else {
    out.schedule = String(base.schedule || "").trim();
  }

  const cronType = String(out.cron_type || "").trim().toUpperCase();
  const normalizeList = (value, normalize = (item) => item) => {
    const raw = Array.isArray(value)
      ? value
      : String(value || "")
          .split(/[\n,]/)
          .map((item) => item.trim())
          .filter(Boolean);
    return [...new Set(raw.map((item) => normalize(String(item || "").trim())).filter(Boolean))];
  };

  if (cronType === "TRADES_BULK_ACTION") {
    const action = String(out.bulk_action || out.action || "")
      .trim()
      .toLowerCase();
    out.bulk_action = ["close_all", "cancel_all", "delete_all"].includes(action)
      ? action
      : "";
    out.symbols = normalizeList(out.symbols, (item) => item.toUpperCase());
    out.execution_statuses = normalizeList(
      out.execution_statuses || out.statuses,
      (item) => item.toUpperCase(),
    );
    out.directions = normalizeList(
      out.directions || out.actions,
      (item) => item.toUpperCase(),
    );
    out.account_ids = normalizeList(out.account_ids);
    out.source_ids = normalizeList(out.source_ids);
    out.pnl_state = ["win", "lose"].includes(
      String(out.pnl_state || out.profit_state || "")
        .trim()
        .toLowerCase(),
    )
      ? String(out.pnl_state || out.profit_state || "")
          .trim()
          .toLowerCase()
      : "";
    out.time_range = String(out.time_range || out.time || out.range || "all")
      .trim()
      .toLowerCase();
    out.timeframes = [];
  }
  if (cronType === "DOWNLOAD_BARS_CRON") {
    out.symbols = normalizeList(out.symbols, (item) => item.toUpperCase());
    out.exclude_symbols = normalizeList(out.exclude_symbols, (item) =>
      item.toUpperCase(),
    );
    out.direction = normalizeBarsDownloadDirection(out.direction || "latest");
    out.bars_count = Math.max(
      50,
      Math.min(Number(out.bars_count) || 1000, 5000),
    );
  }
  return out;
}

function resolveTradeTimeRangeBounds(range, exactTime = "") {
  const timeToken = String(exactTime || "")
    .trim()
    .toLowerCase();
  if (timeToken) {
    if (/^\d{4}-\d{2}-\d{2}$/.test(timeToken)) {
      const start = new Date(`${timeToken}T00:00:00`);
      const end = new Date(`${timeToken}T23:59:59.999`);
      if (Number.isFinite(start.getTime()) && Number.isFinite(end.getTime())) {
        return { from: start.toISOString(), to: end.toISOString() };
      }
    }
    if (timeToken !== "all") {
      return resolveTradeTimeRangeBounds(timeToken, "");
    }
  }
  const now = new Date();
  const start = new Date(now);
  const end = new Date(now);
  switch (String(range || "all").trim().toLowerCase()) {
    case "today":
      start.setHours(0, 0, 0, 0);
      return { from: start.toISOString(), to: null };
    case "yesterday":
      start.setDate(start.getDate() - 1);
      start.setHours(0, 0, 0, 0);
      end.setDate(end.getDate() - 1);
      end.setHours(23, 59, 59, 999);
      return { from: start.toISOString(), to: end.toISOString() };
    case "week":
      start.setDate(start.getDate() - start.getDay());
      start.setHours(0, 0, 0, 0);
      return { from: start.toISOString(), to: null };
    case "month":
      start.setDate(1);
      start.setHours(0, 0, 0, 0);
      return { from: start.toISOString(), to: null };
    case "year":
      start.setMonth(0, 1);
      start.setHours(0, 0, 0, 0);
      return { from: start.toISOString(), to: null };
    case "last_week":
      start.setDate(start.getDate() - 7);
      return { from: start.toISOString(), to: null };
    case "last_month":
      start.setMonth(start.getMonth() - 1);
      return { from: start.toISOString(), to: null };
    default:
      return { from: null, to: null };
  }
}

function hasTradeBulkActionCriteria(filters = {}) {
  const hasArray = (value) =>
    Array.isArray(value) &&
    value.some((item) => String(item || "").trim().length > 0);
  return Boolean(
    hasArray(filters.sids) ||
      hasArray(filters.account_ids) ||
      hasArray(filters.source_ids) ||
      hasArray(filters.execution_statuses) ||
      hasArray(filters.symbols) ||
      hasArray(filters.directions) ||
      String(filters.account_id || "").trim() ||
      String(filters.source_id || "").trim() ||
      String(filters.execution_status || "").trim() ||
      String(filters.symbol || "").trim() ||
      String(filters.action || filters.side || "").trim() ||
      String(filters.created_from || "").trim() ||
      String(filters.created_to || "").trim() ||
      String(filters.q || "").trim() ||
      String(filters.pnl_state || filters.profit_state || "").trim(),
  );
}

function normalizeTradeBulkExecutionStatus(value = "") {
  const raw = String(value || "").trim().toUpperCase();
  if (!raw) return "";
  if (["ERROR", "FAIL", "FAILED"].includes(raw)) return "REJECTED";
  if (raw === "CANCEL" || raw === "EXPIRED") return "CANCELLED";
  if (raw === "LIVE" || raw === "OPEN" || raw === "ACTIVE") return "FILLED";
  return raw;
}

function buildTradeBulkActionFilters(payload = {}, userId = null) {
  const rangeToken = String(
    payload.time_range || payload.time || payload.range || "",
  )
    .trim()
    .toLowerCase();
  const bounds =
    !payload.created_from && !payload.created_to && rangeToken && rangeToken !== "all"
      ? resolveTradeTimeRangeBounds(rangeToken, "")
      : { from: payload.created_from || "", to: payload.created_to || "" };
  const normalizeList = (value, normalize = (item) => item) => {
    const raw = Array.isArray(value)
      ? value
      : value === undefined || value === null || value === ""
        ? []
        : [value];
    return [...new Set(raw.map((item) => normalize(String(item || "").trim())).filter(Boolean))];
  };
  const executionStatus = normalizeTradeBulkExecutionStatus(
    payload.execution_status || payload.status,
  );
  return {
    user_id: userId || payload.user_id || null,
    sids: Array.isArray(payload.sids || payload.trade_ids)
      ? payload.sids || payload.trade_ids
      : [],
    account_id: String(payload.account_id || "").trim(),
    account_ids: normalizeList(payload.account_ids),
    source_id: String(payload.source_id || "").trim(),
    source_ids: normalizeList(payload.source_ids),
    execution_status: executionStatus,
    execution_statuses: normalizeList(
      payload.execution_statuses || payload.statuses,
      normalizeTradeBulkExecutionStatus,
    ),
    created_from: String(bounds.from || "").trim(),
    created_to: String(bounds.to || "").trim(),
    q: String(payload.q || "").trim(),
    symbol: String(payload.symbol || "").trim().toUpperCase(),
    symbols: normalizeList(payload.symbols, (item) => item.toUpperCase()),
    side: String(payload.side || "").trim().toUpperCase(),
    directions: normalizeList(
      payload.directions || payload.actions,
      (item) => item.toUpperCase(),
    ),
    pnl_state: String(payload.pnl_state || payload.profit_state || "")
      .trim()
      .toLowerCase(),
    time_range: rangeToken || "all",
  };
}

// Parse cron schedule string and check if it should fire now.
// Schedule formats:
//   "every 5m" → interval-based
//   "at 11:20 on Mon,Wed,Fri" → specific days + time
function cronScheduleShouldRun(schedule, nowMs, lastRunMs, timezone) {
  const spec = parseCronScheduleSpec(schedule);
  if (spec.mode === "event") {
    const atMatch = spec.normalized.match(/^at (\d{2}):(\d{2})\s+on\s+(.+)$/i);
    if (!atMatch) return false;
    const targetHour = parseInt(atMatch[1], 10);
    const targetMin = parseInt(atMatch[2], 10);
    const targetDays = atMatch[3].split(",").map((d) => d.trim().toLowerCase());

    const wallClock = getCronWallClock(nowMs, timezone);
    const currentDay = String(wallClock.day || "").trim().toLowerCase();
    const currentHour = Number(wallClock.hour);
    const currentMin = Number(wallClock.minute);

    if (!targetDays.includes(currentDay)) return false;

    const targetTotalMins = targetHour * 60 + targetMin;
    const currentTotalMins = currentHour * 60 + currentMin;
    if (currentTotalMins < targetTotalMins) return false;
    if (currentTotalMins - targetTotalMins > 1) return false;

    if (lastRunMs && nowMs - lastRunMs < 120000) return false;

    return true;
  }

  if (spec.mode === "interval") {
    return nowMs - lastRunMs >= spec.intervalSeconds * 1000 - 5000;
  }

  return false;
}

function cronScheduleRowsShouldRun(rows = [], nowMs, lastRunMs, timezone) {
  const normalizedRows = normalizeCronScheduleRows(rows);
  const wallClock = getCronWallClock(nowMs, timezone);
  const currentDay = wallClock.day;
  const activeRow = normalizedRows.find(
    (row) => row.day === currentDay && row.enabled,
  );
  if (!activeRow) return false;
  const currentMinutes = wallClock.minutes;
  if (!Number.isFinite(currentMinutes)) return false;
  for (const window of Array.isArray(activeRow.windows) ? activeRow.windows : []) {
    if (String(window?.mode || "interval").trim().toLowerCase() === "exact") {
      const exactMatches = normalizeCronScheduleExactTimes(window?.exact_times).some(
        (exactTime) => cronScheduleTimeToMinutes(exactTime) === currentMinutes,
      );
      if (
        exactMatches &&
        (!lastRunMs || nowMs - lastRunMs >= 120000)
      ) {
        return true;
      }
      continue;
    }
    const fromMinutes = cronScheduleTimeToMinutes(window?.from);
    const toMinutes = cronScheduleTimeToMinutes(window?.to);
    if (
      !Number.isFinite(fromMinutes) ||
      !Number.isFinite(toMinutes) ||
      fromMinutes >= toMinutes
    ) {
      continue;
    }
    if (currentMinutes < fromMinutes || currentMinutes > toMinutes) continue;
    if (
      nowMs - lastRunMs >=
      Math.max(15, Number(window?.interval_seconds || activeRow.interval_seconds || 60)) *
        1000 -
        5000
    ) {
      return true;
    }
  }
  return false;
}

async function cronConfigShouldRunNow(
  data = {},
  nowMs,
  lastRunMs,
  defaultCadenceSeconds,
) {
  const normalized = normalizeCronSettingData(data, { defaultCadenceSeconds });
  const activeFromMs = normalized.active_from
    ? new Date(normalized.active_from).getTime()
    : NaN;
  const activeToMs = normalized.active_to
    ? new Date(normalized.active_to).getTime()
    : NaN;
  if (Number.isFinite(activeFromMs) && nowMs < activeFromMs) {
    return { normalized, shouldRun: false, skip_reason: "active_from" };
  }
  if (Number.isFinite(activeToMs) && nowMs > activeToMs) {
    return { normalized, shouldRun: false, skip_reason: "active_to" };
  }
  const cooldownMs = Math.max(
    0,
    Number(normalized.cooldown_seconds || 0) || 0,
  ) * 1000;
  if (cooldownMs > 0 && lastRunMs && nowMs - lastRunMs < cooldownMs - 5000) {
    return { normalized, shouldRun: false, skip_reason: "cooldown" };
  }
  if (Array.isArray(normalized.schedule_rows) && normalized.schedule_rows.length) {
    const shouldRun = cronScheduleRowsShouldRun(
      normalized.schedule_rows,
      nowMs,
      lastRunMs,
      normalized.timezone,
    );
    if (!shouldRun) {
      return { normalized, shouldRun: false };
    }
    if (await shouldSkipCronForNews(normalized, nowMs)) {
      return { normalized, shouldRun: false, skip_reason: "avoid_news" };
    }
    return { normalized, shouldRun: true };
  }
  const spec = parseCronScheduleSpec(normalized.schedule);
  if (spec.mode === "event" || spec.mode === "interval") {
    const shouldRun = cronScheduleShouldRun(
      normalized.schedule,
      nowMs,
      lastRunMs,
      normalized.timezone,
    );
    if (!shouldRun) {
      return { normalized, shouldRun: false };
    }
    if (await shouldSkipCronForNews(normalized, nowMs)) {
      return { normalized, shouldRun: false, skip_reason: "avoid_news" };
    }
    return {
      normalized,
      shouldRun: true,
    };
  }
  const shouldRun =
    nowMs - lastRunMs >=
    Number(normalized.cadence_seconds || defaultCadenceSeconds || 60) * 1000 -
      5000;
  if (!shouldRun) {
    return { normalized, shouldRun: false };
  }
  if (await shouldSkipCronForNews(normalized, nowMs)) {
    return { normalized, shouldRun: false, skip_reason: "avoid_news" };
  }
  return {
    normalized,
    shouldRun: true,
  };
}

function readCronObjectLogTimestampMs(userId, cronName, fileBaseName = "") {
  const safeUserId = String(userId || CFG.mt5DefaultUserId || "default").trim();
  const safeCronName = String(cronName || "default").trim();
  const safeFileBase = String(fileBaseName || "")
    .trim()
    .replace(/\.log$/i, "");
  if (!safeUserId || !safeCronName || !safeFileBase) return 0;
  try {
    const fullPath = path.join(
      objectLogsDir(safeUserId, "cron", safeCronName),
      `${safeFileBase}.log`,
    );
    if (!fs.existsSync(fullPath)) return 0;
    const stat = fs.statSync(fullPath);
    const ms = Number(stat?.mtimeMs || 0);
    return Number.isFinite(ms) && ms > 0 ? ms : 0;
  } catch {
    return 0;
  }
}

function extractCronAiFailureDetail(body = "") {
  const raw = String(body || "").trim();
  if (!raw) return "";
  try {
    const parsed = JSON.parse(raw);
    const detail =
      parsed?.error ||
      parsed?.message ||
      parsed?.detail ||
      parsed?.details ||
      parsed?.reason ||
      parsed?.cause ||
      parsed?.auto_save_result?.error ||
      parsed?.auto_save?.error ||
      "";
    if (detail && typeof detail === "object") {
      return JSON.stringify(detail).slice(0, 300);
    }
    const text = String(detail || "").trim();
    if (text) return text.slice(0, 300);
  } catch {}
  return raw.replace(/\s+/g, " ").slice(0, 300);
}

async function resolveCronSymbols(data = {}, userId = "default") {
  const group = normalizeCronSymbolGroupValue(data.symbols_group || "");
  const all = discoverAllMarketSymbols();
  if (group) {
    if (group === "system:all") return all;
    if (group.startsWith("system:")) {
      const preset = SYSTEM_SYMBOL_GROUP_MAP[group.slice(7)] || [];
      return preset.filter((symbol) => all.includes(symbol));
    }
    const symbolGroups = await ensureUserSymbolGroups(userId);
    return resolveSymbolsGroupSymbols(symbolGroups, group, all).filter(
      (symbol) => all.includes(symbol),
    );
  }
  // Fallback to stored symbols or auto-discover all
  const syms =
    Array.isArray(data.symbols) && data.symbols.length
      ? data.symbols
      : discoverAllMarketSymbols();
  return syms;
}

function resolveBrokerCsvPath(symbol, tf) {
  return barsStorage.resolveBrokerBarsFilePath(symbol, tf, {
    dataRoot: GLOBAL_DATA_DIR,
    duckdbPath: process.env.BARS_DUCKDB_PATH,
  });
}

// ── Metadata sidecar (replaces market_data.metadata column) ──
function resolveMetadataPath(symbol, tf) {
  const sym = String(symbol || "")
    .trim()
    .toUpperCase();
  if (!sym) return "";
  const tfKey = normalizeCsvTfKey(tf);
  const dir = path.join(GLOBAL_DATA_DIR, "market_data", sym, "metadata");
  return path.join(dir, `${tfKey}.json`);
}
function readMarketDataMetadata(symbol, tf) {
  const p = resolveMetadataPath(symbol, tf);
  let sidecar = null;
  if (p && fs.existsSync(p)) {
    try {
      sidecar = JSON.parse(fs.readFileSync(p, "utf8"));
    } catch {
      sidecar = null;
    }
  }
  const artifact = chartArtifactService.readMarketArtifacts(symbol, tf, {
    dataRoot: GLOBAL_DATA_DIR,
  });
  const legacy =
    artifact?.meta?.legacy_metadata &&
    typeof artifact.meta.legacy_metadata === "object"
      ? artifact.meta.legacy_metadata
      : null;
  if (sidecar && legacy) {
    return { ...legacy, ...sidecar };
  }
  if (sidecar) return sidecar;
  if (legacy) return legacy;
  return null;
}

function buildBrokerStorageMetadata(symbol, tf, baseMetadata = {}) {
  const provider = barsStorage.getBarsStorageProvider({
    dataRoot: GLOBAL_DATA_DIR,
    duckdbPath: process.env.BARS_DUCKDB_PATH,
  });
  const brokerFilePath = resolveBrokerCsvPath(symbol, tf);
  const fullBars = barsStorage.readBrokerBarsFromFile(symbol, tf, 0, {
    dataRoot: GLOBAL_DATA_DIR,
    duckdbPath: process.env.BARS_DUCKDB_PATH,
    fullFile: true,
  });
  const storedBars = Array.isArray(fullBars) ? fullBars.length : 0;
  const tfSec = Math.max(60, parseTfTokenToSeconds(tf));
  const computedBarStart = Number(fullBars?.[0]?.time || 0) || null;
  const computedBarEnd =
    storedBars > 0
      ? Number(fullBars?.[storedBars - 1]?.time || 0) + tfSec || null
      : null;
  const fileUpdatedAt =
    brokerFilePath && fs.existsSync(brokerFilePath)
      ? fs.statSync(brokerFilePath).mtime.toISOString()
      : null;
  try {
    return {
      ...(baseMetadata && typeof baseMetadata === "object" ? baseMetadata : {}),
      source_kind: "broker",
      file_type: provider === "parquet_duckdb" ? "parquet" : provider === "csv" ? "csv" : provider,
      stored_bars: storedBars > 0 ? storedBars : null,
      file_updated_at: fileUpdatedAt,
      bar_start:
        Number(baseMetadata?.bar_start) > 0
          ? Number(baseMetadata.bar_start)
          : computedBarStart,
      bar_end:
        Number(baseMetadata?.bar_end) > 0
          ? Number(baseMetadata.bar_end)
          : computedBarEnd,
    };
  } catch {
    return {
      ...(baseMetadata && typeof baseMetadata === "object" ? baseMetadata : {}),
      source_kind: "broker",
      file_type: provider === "parquet_duckdb" ? "parquet" : provider === "csv" ? "csv" : provider,
      stored_bars: storedBars > 0 ? storedBars : null,
      file_updated_at: fileUpdatedAt,
    };
  }
}
function writeMarketDataMetadata(symbol, tf, metadata) {
  if (!metadata || typeof metadata !== "object") return;
  const p = resolveMetadataPath(symbol, tf);
  if (!p) return;
  const dir = path.dirname(p);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  try {
    fs.writeFileSync(p, JSON.stringify(metadata));
  } catch {}
}

