function resolveLogFile(objectId, metadata, objectTable = "") {
  const ev = String(metadata.event || metadata.event_type || "").toUpperCase();

  // Extract source_id — check top-level first, then nested data (object or JSON string)
  let metaSource = metadata.source_id || metadata.provider || metadata.account;
  if (!metaSource && metadata.data) {
    const d =
      typeof metadata.data === "string"
        ? (() => {
            try {
              return JSON.parse(metadata.data);
            } catch (_) {
              return null;
            }
          })()
        : metadata.data;
    if (d && typeof d === "object") metaSource = d.source_id || d.provider;
  }

  let entry;
  if (ev.startsWith("SIGNAL_EA_SYNC_")) entry = ["accounts", "sync"];
  else if (ev.startsWith("TRADE_EA_ACK_")) entry = ["trades", "signal"];
  else if (ev.startsWith("CRON_SNAPSHOT_")) entry = ["cron"];
  else entry = EVENT_FILE_MAP[ev];
  if (!entry) return null;
  const source = entry[0];
  const idOrFile = entry[1];

  // Flat sources: filename is the 2nd element, or derived from metadata (cron)
  if (source === "CRON" || source === "cron") {
    const name = metadata.cron_name || metadata.cron || "unknown";
    const safeName = String(name)
      .trim()
      .replace(/[^A-Za-z0-9_.-]/g, "_");
    return "CRON/" + safeName + ".log";
  }
  if (
    source === "API" ||
    source === "api" ||
    source === "SYSTEM" ||
    source === "system" ||
    source === "ui"
  ) {
    const folder = source.toUpperCase();
    const safeFile = String(idOrFile || "unknown").replace(
      /[^A-Za-z0-9_.-]/g,
      "_",
    );
    return folder + "/" + safeFile + ".log";
  }
  if (source === "accounts") {
    const safeFile = String(idOrFile || "unknown").replace(
      /[^A-Za-z0-9_.-]/g,
      "_",
    );
    const accountId = String(
      metadata.account_id || metadata.object_id || objectId || "",
    ).trim();
    const targetUserId = String(
      metadata.user_id || metadata.userId || "",
    ).trim();
    if (
      (String(objectTable || "").toLowerCase() === "accounts" ||
        String(objectTable || "").toLowerCase() === "user_accounts") &&
      targetUserId &&
      accountId
    ) {
      return path.join(
        objectLogsDir(targetUserId, "user_accounts", accountId),
        safeFile + ".log",
      );
    }
    // Compatibility fallback: legacy global account logs grouped by source.
    const accSource = metaSource || "unknown";
    const safeSrc = String(accSource).replace(/[^A-Za-z0-9_.-]/g, "_");
    return "accounts/" + safeSrc + "/" + safeFile + ".log";
  }

  // Hierarchical: only trades remain (written to trade folder, not SERVER_LOG_DIR)
  if (source === "trades") {
    const tradeSid =
      metadata.trade_sid || metadata.trade_id || objectId || "unknown";
    const tradeSym = metadata.trade_symbol || metadata.symbol || "";
    const safeTradeSid = String(tradeSid || "")
      .trim()
      .replace(/[^A-Za-z0-9_.-]/g, "_");
    const tradeDir = tradeSym
      ? resolveTradeDir(tradeSid, tradeSym)
      : findExistingTradeDir(safeTradeSid);
    const safeTradeFile = String(idOrFile || "unknown").replace(
      /[^A-Za-z0-9_.-]/g,
      "_",
    );
    if (tradeDir) return path.join(tradeDir, "logs", safeTradeFile + ".log");
    return path.join("trades", safeTradeSid, safeTradeFile + ".log");
  }

  // Fallback: hierarchical subdir by ID
  const dirId = objectId || "unknown";
  const safeId = String(dirId || "unknown")
    .trim()
    .replace(/[^A-Za-z0-9_.-]/g, "_");
  return source + "/" + safeId + "/" + safeFile + ".log";
}

function fileLog(objectId, objectTable, metadata = {}, userId = null) {
  if (!SERVER_LOG_DIR) return;
  const evt = String(
    metadata.event || metadata.event_type || "INFO",
  ).toUpperCase();
  const activityResult = normalizeActivityResult(metadata || {}, {
    ok: metadata?.ok !== false,
  });
  const level = activityResult.status === "error"
    ? "ERROR"
    : activityResult.status === "warn"
      ? "WARN"
      : (metadata.level || "INFO").toUpperCase();

  if (
    String(objectTable || "")
      .trim()
      .toLowerCase() === "cron"
  ) {
    const cronName =
      String(
        metadata.cron_name || metadata.cron || objectId || "unknown",
      ).trim() || "unknown";
    const cronUserId =
      String(
        userId || metadata.user_id || metadata.userId || CFG.mt5DefaultUserId,
      ).trim() || CFG.mt5DefaultUserId;
    const line = buildObjectLogLine(cronUserId, "cron", cronName, metadata);
    const fullPath = resolveObjectLogFilePath(
      cronUserId,
      "cron",
      cronName,
      metadata,
    );
    try {
      const dir = path.dirname(fullPath);
      if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
      fs.appendFileSync(fullPath, line);
    } catch (_) {}
    emitLogRealtimeAppendFromPath(fullPath, line, {
      object_table: "cron",
      event: evt,
      level,
      user_id: cronUserId,
    });
    if (level === "ERROR") {
      try {
        const errPath = path.join(SERVER_LOG_DIR, "system", "error.log");
        const errDir = path.dirname(errPath);
        if (!fs.existsSync(errDir)) fs.mkdirSync(errDir, { recursive: true });
        fs.appendFileSync(errPath, line);
        emitLogRealtimeAppendFromPath(errPath, line, {
          object_table: "cron",
          event: evt,
          level,
          user_id: cronUserId,
        });
      } catch (_) {}
    }
    return;
  }

  const iso = new Date().toISOString();
  // Message: use explicit message, or generate from event + source + object
  const autoMsg = (() => {
    const src = metadata.source_id || metadata.provider || "";
    const srcPart = src ? ` [${src}]` : "";
    const st = metadata.status || metadata.level || "";
    const stPart = st ? ` (${st})` : "";
    return `${evt.replace(/_/g, " ").toLowerCase()}${srcPart}: ${objectId}${stPart}`;
  })();
  const msg = String(activityResult.message || metadata.message || "").trim() || autoMsg;
  // New format: [ISO] [LEVEL] [EVENT_TYPE] message, key=val, ...
  const extra = [];
  if (msg) extra.push(msg);
  extra.push("object_type=" + objectTable, "object_id=" + objectId);
  if (metadata && typeof metadata === "object") {
    for (const [k, v] of Object.entries({
      ...metadata,
      result: activityResult,
    })) {
      if (v === undefined || v === null) continue;
      if (
        k === "event" ||
        k === "event_type" ||
        k === "message" ||
        k === "level" ||
        k === "error"
      )
        continue;
      const val = typeof v === "object" ? JSON.stringify(v) : String(v);
      if (val === "" || val === "[object Object]") continue;
      extra.push(k + "=" + (val.includes(" ") ? '"' + val + '"' : val));
    }
  }
  const line =
    "[" + iso + "] [" + level + "] [" + evt + "] " + extra.join(", ") + "\n";
  const logTarget = resolveLogFile(
    objectId,
    {
      ...(metadata && typeof metadata === "object" ? metadata : {}),
      ...(userId ? { user_id: userId } : {}),
    },
    objectTable,
  );
  if (!logTarget) return;
  // Support absolute paths (trades log to trade dir) or relative paths (under SERVER_LOG_DIR)
  const isAbs = path.isAbsolute(logTarget);
  const fullPath = isAbs ? logTarget : path.join(SERVER_LOG_DIR, logTarget);
  try {
    const dir = path.dirname(fullPath);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.appendFileSync(fullPath, line);
  } catch (_) {}
  emitLogRealtimeAppendFromPath(fullPath, line, {
    object_table: objectTable,
    event: evt,
    level,
    user_id: userId || metadata?.user_id || null,
  });
  // Duplicate errors to system/error.log (skip if already writing there)
  if (level === "ERROR" && !isAbs && !logTarget.startsWith("system/error")) {
    try {
      const errPath = path.join(SERVER_LOG_DIR, "system", "error.log");
      const errDir = path.dirname(errPath);
      if (!fs.existsSync(errDir)) fs.mkdirSync(errDir, { recursive: true });
      fs.appendFileSync(errPath, line);
      emitLogRealtimeAppendFromPath(errPath, line, {
        object_table: objectTable,
        event: evt,
        level,
        user_id: userId || metadata?.user_id || null,
      });
    } catch (_) {}
  }
}

function walkLogFileLines(filePath, onLine) {
  try {
    const content = fs.readFileSync(filePath, "utf8");
    for (const line of content.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed) continue;
      onLine(trimmed, filePath);
    }
  } catch {}
}

function listObjectLogUsers() {
  if (!fs.existsSync(USER_OBJECT_DATA_ROOT)) return [];
  try {
    return fs
      .readdirSync(USER_OBJECT_DATA_ROOT, { withFileTypes: true })
      .filter((entry) => entry.isDirectory())
      .map((entry) => entry.name)
      .sort();
  } catch {
    return [];
  }
}

function listCronLogUsers() {
  return listObjectLogUsers();
}

function listProviderLogUsers() {
  return listObjectLogUsers();
}

function listCronCompatibilityLogFiles(cronName = "", requestedFile = "") {
  const safeRequestedFile = requestedFile
    ? `${safeObjectPathPart(String(requestedFile || "").replace(/\.log$/i, ""), "activity")}.log`
    : "";
  const out = [];

  for (const userId of listCronLogUsers()) {
    const cronLogsPath = objectLogsDir(userId, "cron", cronName || "default");
    if (!fs.existsSync(cronLogsPath)) continue;
    try {
      if (safeRequestedFile) {
        const candidate = path.join(cronLogsPath, safeRequestedFile);
        if (fs.existsSync(candidate)) {
          out.push({
            path: candidate,
            user_id: userId,
            file: safeRequestedFile.replace(/\.log$/i, ""),
            scope: "local",
          });
        }
        continue;
      }
      for (const entry of fs.readdirSync(cronLogsPath, {
        withFileTypes: true,
      })) {
        if (!entry.isFile() || !entry.name.endsWith(".log")) continue;
        out.push({
          path: path.join(cronLogsPath, entry.name),
          user_id: userId,
          file: entry.name.replace(/\.log$/i, ""),
          scope: "local",
        });
      }
    } catch {}
  }

  const safeCronName = safeObjectPathPart(cronName || "unknown", "unknown");
  const legacyPath = path.join(SERVER_LOG_DIR, "CRON", `${safeCronName}.log`);
  if (
    fs.existsSync(legacyPath) &&
    (!safeRequestedFile ||
      ["legacy.log", "global.log"].includes(safeRequestedFile))
  ) {
    out.push({
      path: legacyPath,
      user_id: null,
      file: "legacy",
      scope: "legacy",
    });
  }

  return out;
}

function listAllCronCompatibilityLogFiles() {
  const out = [];
  const seen = new Set();

  for (const userId of listCronLogUsers()) {
    const cronDir = objectTypeDir(userId, "cron");
    if (!fs.existsSync(cronDir)) continue;
    try {
      for (const cronEntry of fs.readdirSync(cronDir, {
        withFileTypes: true,
      })) {
        if (!cronEntry.isDirectory()) continue;
        for (const match of listCronCompatibilityLogFiles(cronEntry.name)) {
          const resolved = path.resolve(match.path);
          if (seen.has(resolved)) continue;
          seen.add(resolved);
          out.push(match);
        }
      }
    } catch {}
  }

  const legacyDir = path.join(SERVER_LOG_DIR, "CRON");
  if (fs.existsSync(legacyDir)) {
    try {
      for (const entry of fs.readdirSync(legacyDir, { withFileTypes: true })) {
        if (!entry.isFile() || !entry.name.endsWith(".log")) continue;
        const match = {
          path: path.join(legacyDir, entry.name),
          user_id: null,
          file: "legacy",
          scope: "legacy",
        };
        const resolved = path.resolve(match.path);
        if (seen.has(resolved)) continue;
        seen.add(resolved);
        out.push(match);
      }
    } catch {}
  }

  return out;
}

