async function getAiSchemaSpec() {
  try {
    const planSchema = await systemConfigStore.getSchema("trade");
    try {
      const analysisSchema = await systemConfigStore.getSchema("analysis");
      return {
        version: "3.1",
        schema: [
          {
            ...(planSchema && typeof planSchema === "object" ? planSchema : {}),
            analysis: analysisSchema,
          },
        ],
      };
    } catch {
      return {
        version: "3.1",
        schema: [planSchema && typeof planSchema === "object" ? planSchema : {}],
      };
    }
  } catch (e) {
    console.warn("[schema] system.json not found");
    return { version: "3.1", schema: [{}] };
  }
}

async function getAiResponseSchemaVersion() {
  const spec = await getAiSchemaSpec();
  return String(spec.version || "3.0");
}

async function buildAiSchemaPromptText() {
  const spec = await getAiSchemaSpec();
  const schemaVersion = String(spec.version || "3.0");
  const responseSchema = spec.schema || {};
  return `You are an expert ICT technical analyst.
Respond ONLY in valid minified JSON matching schema exactly. No prose, markdown, or trailing commas.
All fields required. Enums must match. Use null only where price data is unavailable.
Array limits: htf_context<=2, ltf_analysis<=2, pd_arrays<=6/tf, key_levels<=6, reference_zones<=6.
Trade plans must be actionable and internally consistent.
IMPORTANT: You MUST include execution_plan with entry, stop_loss, tp1/tp2/tp3 populated. Never return empty execution_plan.
schema_version=${schemaVersion}
SCHEMA=${JSON.stringify(responseSchema)}`;
}

