// Standard 9-char SID generator: [TimePart (6)] + [RandomPart (3)]
function mt5GenerateTimeSid() {
  const seconds = Math.floor(Date.now() / 1000)
    .toString(36)
    .toUpperCase();
  const rand = Math.random().toString(36).substring(2, 5).toUpperCase();
  return (seconds + rand).padEnd(9, "X").substring(0, 9);
}

// Deprecated: use mt5GenerateTimeSid
function mt5GenerateId(prefix = "ID") {
  return mt5GenerateTimeSid();
}

function mt5NormalizeSymbol(s) {
  const val = typeof s === "string" ? s : s?.symbol || s?.s || "";
  return String(val)
    .toUpperCase()
    .replace(/[\/\-\_\.]/g, "")
    .trim();
}

async function mt5Log(objectId, objectTable, metadata = {}, userId = null) {
  // Route through NotificationManager for matching event types (handles db_log + SSE)
  let eventType = null;
  if (notificationManager && metadata?.event) {
    const ev = String(metadata.event || "").toUpperCase();
    let subType = "";
    if (
      ev === "TRADE_FILLED" ||
      ev === "TRADE_SYNC_UPDATE" ||
      ev === "SL_CHANGED" ||
      ev === "PARTIAL_CLOSE"
    ) {
      eventType = "TRADE_FILLED";
      subType = ev.toLowerCase();
    } else if (ev === "TRADE_CLOSED" || ev === "TRADE_CLOSE") {
      eventType = "TRADE_CLOSED";
      subType = "closed";
    } else if (ev.startsWith("SIGNAL_")) {
      eventType = "SIGNAL_ADDED";
      subType = ev.replace("SIGNAL_", "").toLowerCase();
    } else if (ev === "PRICE_PUSH") {
      eventType = "BROKER_POLL";
      subType = "price_push";
    }
    if (eventType) {
      try {
        notificationManager.handle(eventType, subType, {
          object_id: objectId,
          object_table: objectTable,
          user_id: userId || null,
          message: metadata.event || "",
          ...metadata,
        });
      } catch (e) {
        // Log failed — still record as error
        notificationManager.handle(eventType, subType, {
          object_id: objectId,
          object_table: objectTable,
          user_id: userId || null,
          message: metadata.event || "",
          status: "ERROR",
          error: e.message || String(e),
          ...metadata,
        });
      }
    }
  }
  fileLog(objectId, objectTable, metadata, userId);
  // If this EA event is about a specific trade, also log to trade folder
  const tradeSid = metadata.trade_id || metadata.signal_id;
  if (tradeSid) fileLog(tradeSid, "ea_to_trade", metadata, userId);
}

function json(res, statusCode, data) {
  if (!res || res.destroyed || res.writableEnded) return false;
  const req = res.req || null;
  const requestStartedAt = Number(req?._requestStartedAt || 0);
  const totalMs = requestStartedAt
    ? Math.max(0, Date.now() - requestStartedAt)
    : null;
  const dbMsRaw = Number(req?._requestTiming?.dbMs || 0);
  const dbMs = Number.isFinite(dbMsRaw) && dbMsRaw > 0 ? dbMsRaw : null;
  const traceId = String(req?._traceId || "").trim() || null;
  let payload = data;
  try {
    if (payload && typeof payload === "object" && !Array.isArray(payload)) {
      payload = ensureActivityResultPayload(payload, { statusCode });
      const existingTiming =
        payload._timing && typeof payload._timing === "object"
          ? payload._timing
          : {};
      payload = {
        ...payload,
        _timing: {
          ...existingTiming,
          total_ms: totalMs,
          db_ms: dbMs,
          trace_id: traceId,
        },
      };
    }
  } catch (error) {
    const message =
      error instanceof Error ? error.stack || error.message : String(error);
    console.error(`[json] normalize failed trace=${traceId || "n/a"}: ${message}`);
  }
  let body;
  try {
    const seen = new WeakSet();
    body = JSON.stringify(payload, (key, value) => {
      if (typeof value === "bigint") return Number(value);
      if (value && typeof value === "object") {
        if (seen.has(value)) return "[Circular]";
        seen.add(value);
      }
      return value;
    });
  } catch (error) {
    const message =
      error instanceof Error ? error.stack || error.message : String(error);
    console.error(`[json] stringify failed trace=${traceId || "n/a"}: ${message}`);
    body = JSON.stringify({
      ok: statusCode < 400,
      error: statusCode >= 400 ? "response serialization failed" : undefined,
      result: {
        status: statusCode >= 400 ? "error" : "warn",
        message: "Response serialization fallback applied",
        processed: 0,
        created: 0,
        updated: 0,
        deleted: 0,
        skipped: 0,
        created_ids: [],
        updated_ids: [],
        deleted_ids: [],
        affected_ids: [],
        errors:
          statusCode >= 400
            ? [{ code: "response_serialization_failed", message }]
            : [],
      },
      _timing: {
        total_ms: totalMs,
        db_ms: dbMs,
        trace_id: traceId,
      },
    });
  }
  try {
    if (!res.headersSent) {
      const headers = {
        "Content-Type": "application/json; charset=utf-8",
        "Content-Length": Buffer.byteLength(body),
      };
      if (Number.isFinite(totalMs)) {
        headers["x-timing-total"] = String(totalMs);
      }
      if (Number.isFinite(dbMs)) {
        headers["x-timing-db"] = String(dbMs);
      }
      if (traceId) {
        headers["x-trace-id"] = traceId;
      }
      res.writeHead(statusCode, headers);
    }
    if (!res.writableEnded && !res.destroyed) {
      res.end(body);
      return true;
    }
  } catch {
    // Ignore write-after-end or socket-closed races on aborted/malformed requests.
  }
  return false;
}

async function withRequestDbTiming(req, label, work) {
  const startedAt = Date.now();
  try {
    return await work();
  } finally {
    const elapsedMs = Math.max(0, Date.now() - startedAt);
    if (!req || !req._requestTiming) return;
    req._requestTiming.dbMs = Number(req._requestTiming.dbMs || 0) + elapsedMs;
    if (!req._requestTiming.steps) req._requestTiming.steps = {};
    req._requestTiming.steps[label] = elapsedMs;
  }
}

