let REDIS_CLIENT = null;
let REDIS_CONNECTING = null;

function nowUnixSec() {
  return Math.floor(Date.now() / 1000);
}

function normalizeMarketDataSymbol(rawSymbol) {
  const base = String(rawSymbol || "")
    .trim()
    .toUpperCase();
  if (!base) return "";
  const noProvider = base.includes(":")
    ? base.split(":").slice(1).join(":").trim().toUpperCase()
    : base;
  return noProvider.replace(/[^A-Z0-9]/g, "");
}

function normalizeMarketDataTf(tfRaw) {
  const interval = String(timeframeToTwelve(tfRaw || "15m") || "15min")
    .trim()
    .toLowerCase();
  return interval || "15min";
}

function marketDataUiConfigPathForUser(userId, symbol) {
  const symbolNorm = normalizeMarketDataSymbol(symbol) || "UNKNOWN";
  const safeUserId = scopedUserId(userId);
  const baseDir =
    safeUserId === "default"
      ? path.join(USER_DATA_ROOT, "default")
      : userScopedRootDir(safeUserId);
  return path.join(baseDir, "market_data", `${symbolNorm}.json`);
}

function normalizeMarketDataUiConfig(rawConfig = {}) {
  const input =
    rawConfig && typeof rawConfig === "object" && !Array.isArray(rawConfig)
      ? rawConfig
      : {};
  const strategyIds = [
    ...new Set(
      (Array.isArray(input.strategyIds) ? input.strategyIds : [])
        .map((value) => String(value || "").trim())
        .filter(Boolean),
    ),
  ];
  const rawTimeframes =
    input.timeframes &&
    typeof input.timeframes === "object" &&
    !Array.isArray(input.timeframes)
      ? input.timeframes
      : {};
  const rawArtifactEventVisibility =
    input.artifactEventVisibility &&
    typeof input.artifactEventVisibility === "object" &&
    !Array.isArray(input.artifactEventVisibility)
      ? input.artifactEventVisibility
      : {};
  const barsCount = Number(input.barsCount);
  const gridCols = Number(input.gridCols);
  const timeframes = {};
  const artifactEventVisibility = {};
  for (const [tfRaw, tfConfigRaw] of Object.entries(rawTimeframes)) {
    const tf = String(tfRaw || "").trim().toLowerCase();
    if (!tf) continue;
    const tfConfig =
      tfConfigRaw && typeof tfConfigRaw === "object" && !Array.isArray(tfConfigRaw)
        ? tfConfigRaw
        : {};
    const visibleBars = Number(tfConfig.visibleBars);
    const priceTop = Number(tfConfig.priceTop);
    const priceBottom = Number(tfConfig.priceBottom);
    const normalized = {};
    if (Number.isFinite(visibleBars) && visibleBars > 0) {
      normalized.visibleBars = Math.max(2, Math.round(visibleBars));
    }
    if (
      Number.isFinite(priceTop) &&
      Number.isFinite(priceBottom) &&
      priceTop !== priceBottom
    ) {
      normalized.priceTop = Number(priceTop);
      normalized.priceBottom = Number(priceBottom);
    }
    if (Object.keys(normalized).length > 0) {
      timeframes[tf] = normalized;
    }
  }
  for (const [eventKeyRaw, visibleRaw] of Object.entries(rawArtifactEventVisibility)) {
    const eventKey = String(eventKeyRaw || "").trim();
    if (!eventKey || typeof visibleRaw !== "boolean") continue;
    artifactEventVisibility[eventKey] = visibleRaw;
  }
  const updatedAt = Number(input.updatedAt);
  const normalized = {
    updatedAt: Number.isFinite(updatedAt) ? Math.round(updatedAt) : Date.now(),
    strategyIds,
    timeframes,
  };
  if (Object.keys(artifactEventVisibility).length > 0) {
    normalized.artifactEventVisibility = artifactEventVisibility;
  }
  if (Number.isFinite(barsCount) && barsCount > 0) {
    normalized.barsCount = Math.max(2, Math.round(barsCount));
  }
  if (Number.isFinite(gridCols) && gridCols > 0) {
    normalized.gridCols = Math.max(1, Math.min(6, Math.round(gridCols)));
  }
  return normalized;
}

function readMarketDataUiConfig(userId, symbol) {
  const filePath = marketDataUiConfigPathForUser(userId, symbol);
  return {
    config: normalizeMarketDataUiConfig(readJsonFileSafe(filePath, {})),
    filePath,
  };
}

function writeMarketDataUiConfig(userId, symbol, config = {}) {
  const filePath = marketDataUiConfigPathForUser(userId, symbol);
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  const normalized = normalizeMarketDataUiConfig(config);
  fs.writeFileSync(filePath, JSON.stringify(normalized, null, 2));
  return { config: normalized, filePath };
}

const STRATEGY_CATALOG_CACHE_TTL_MS = 60 * 1000;

function strategyCatalogCacheKey(userId) {
  return `ui:strategies:${scopedUserId(userId || "default")}`;
}

async function listAvailableStrategiesCached(userId) {
  const cacheKey = strategyCatalogCacheKey(userId);
  const runtime = await getAppRuntime().catch(() => null);
  try {
    const cached = await runtime?.cache?.get(cacheKey);
    if (cached && Array.isArray(cached.items)) {
      return cached.items;
    }
  } catch (_) {}
  const items = await backtestService.listAvailableStrategies(userId);
  try {
    await runtime?.cache?.set(
      cacheKey,
      {
        items,
        cachedAt: Date.now(),
      },
      { ttlMs: STRATEGY_CATALOG_CACHE_TTL_MS },
    );
  } catch (_) {}
  return items;
}

async function invalidateAvailableStrategiesCache(userId) {
  const cacheKey = strategyCatalogCacheKey(userId);
  const runtime = await getAppRuntime().catch(() => null);
  try {
    await runtime?.cache?.delete(cacheKey);
  } catch (_) {}
}

function parseTfTokenToSeconds(tfToken) {
  const s = String(tfToken || "")
    .trim()
    .toLowerCase();
  if (!s) return 60;
  const m = s.match(/^(\d+)\s*(min|m|hour|h|day|d|week|w|month|mo)$/i);
  if (m) {
    const v = Math.max(1, Number(m[1]) || 1);
    const unit = m[2].toLowerCase();
    if (unit === "min" || unit === "m") return v * 60;
    if (unit === "hour" || unit === "h") return v * 3600;
    if (unit === "day" || unit === "d") return v * 86400;
    if (unit === "week" || unit === "w") return v * 86400 * 7;
    return v * 86400 * 30;
  }
  const n = Number(s.replace(/[^\d]/g, ""));
  if (Number.isFinite(n) && n > 0) return n * 60;
  return 60;
}

// --- Snapshot timeframe canonicalization ---
// Single source of truth: canonical TF token -> { seconds, label, tvInterval }
const SNAPSHOT_TF_MAP = {
  "1W": { seconds: 604800, label: "1W", tv: "W" },
  "1D": { seconds: 86400, label: "1D", tv: "D" },
  "4H": { seconds: 14400, label: "4h", tv: "240" },
  "1H": { seconds: 3600, label: "1h", tv: "60" },
  "30m": { seconds: 1800, label: "30m", tv: "30" },
  "15m": { seconds: 900, label: "15m", tv: "15" },
  "5m": { seconds: 300, label: "5m", tv: "5" },
  "1m": { seconds: 60, label: "1m", tv: "1" },
};

function normalizeSnapshotTfToken(raw) {
  const s = String(raw || "")
    .trim()
    .toUpperCase();
  if (!s) return "";
  // Direct canonical matches
  if (s === "1W" || s === "W" || s === "1WEEK" || s === "WEEK") return "1W";
  if (s === "1D" || s === "D" || s === "DAY" || s === "1DAY") return "1D";
  if (s === "4H" || s === "240" || s === "H4" || s === "4HOUR") return "4H";
  if (s === "1H" || s === "60" || s === "H1" || s === "1HOUR" || s === "HOUR")
    return "1H";
  if (s === "30M" || s === "30" || s === "M30" || s === "30MIN") return "30m";
  if (s === "15M" || s === "15" || s === "M15" || s === "15MIN") return "15m";
  if (s === "5M" || s === "5" || s === "M5" || s === "5MIN") return "5m";
  if (s === "1M" || s === "1" || s === "M1" || s === "1MIN" || s === "MIN")
    return "1m";
  // Numeric fallback: bare number = minutes
  const n = Number(s);
  if (Number.isFinite(n) && n > 0) {
    if (n >= 10080) return "1W";
    if (n >= 1440) return "1D";
    if (n >= 240) return "4H";
    if (n >= 60) return "1H";
    if (n >= 30) return "30m";
    if (n >= 15) return "15m";
    if (n >= 5) return "5m";
    return "1m";
  }
  return "";
}

function snapshotTfToSeconds(canonical) {
  return SNAPSHOT_TF_MAP[canonical]?.seconds || 60;
}
function snapshotTfToLabel(canonical) {
  return SNAPSHOT_TF_MAP[canonical]?.label || canonical;
}
function snapshotTfToTVInterval(canonical) {
  return SNAPSHOT_TF_MAP[canonical]?.tv || canonical;
}

function normalizeTvTimezone(raw, fallback = "Etc/UTC") {
  const s = String(raw || "").trim();
  if (!s) return fallback;
  const up = s.toUpperCase();
  if (up === "UTC" || up === "ETC/UTC") return "Etc/UTC";
  if (up === "NY" || up === "NEW_YORK" || up === "AMERICA/NEW_YORK")
    return "America/New_York";
  if (up === "LOCAL") return "LOCAL";
  try {
    Intl.DateTimeFormat("en-US", { timeZone: s }).format(new Date());
    return s;
  } catch {
    return fallback;
  }
}

function sessionKillerZoneLabelUTC(d = new Date()) {
  const h = Number(d.getUTCHours());
  if (h >= 0 && h < 6) return "Asia Session / Asia Range";
  if (h >= 6 && h < 8) return "London Pre-open / Frankfurt Kill Zone";
  if (h >= 8 && h < 12) return "London Session / London Kill Zone";
  if (h >= 12 && h < 17) return "New York Session / New York Kill Zone";
  if (h >= 17 && h < 22) return "NY PM Session / Reversal Zone";
  return "Late Session / Rollover Zone";
}

// Canonicalize, dedup, sort descending
function canonicalizeTfList(tfList) {
  const canonicals = tfList
    .map((t) => normalizeSnapshotTfToken(t))
    .filter(Boolean);
  return [...new Set(canonicals)].sort(
    (a, b) => snapshotTfToSeconds(b) - snapshotTfToSeconds(a),
  );
}

function estimateRequestedBarsRange({
  tfNorm,
  bars,
  nowSec = nowUnixSec(),
  endTimeSec = null,
}) {
  const sec = Math.max(60, parseTfTokenToSeconds(tfNorm));
  const count = Math.max(1, Number(bars) || 300);
  const anchorSec =
    Number.isFinite(Number(endTimeSec)) && Number(endTimeSec) > 0
      ? Number(endTimeSec)
      : nowSec;
  const alignedEnd = Math.floor(Math.max(1, anchorSec) / sec) * sec;
  const start = alignedEnd - (count - 1) * sec;
  return { start, end: alignedEnd, sec };
}

function normalizeMarketDataTimezone(rawTimezone) {
  const tz =
    String(
      rawTimezone || CFG?.marketDataDefaultTimezone || "America/New_York",
    ).trim() || "America/New_York";
  try {
    Intl.DateTimeFormat("en-US", { timeZone: tz }).format(new Date());
    return tz;
  } catch {
    return "America/New_York";
  }
}

function resolveCurrentServerTimezone() {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  } catch {
    return "UTC";
  }
}

function normalizeCronTimezone(rawTimezone) {
  const fallback = resolveCurrentServerTimezone();
  const token = String(rawTimezone || fallback).trim();
  const tz =
    !token || token.toLowerCase() === "local" ? fallback : token || fallback;
  try {
    Intl.DateTimeFormat("en-US", { timeZone: tz }).format(new Date());
    return tz;
  } catch {
    return fallback;
  }
}

function getCronWallClock(nowMs, timezone) {
  const formatter = new Intl.DateTimeFormat("en-US", {
    timeZone: normalizeCronTimezone(timezone),
    weekday: "short",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
  const parts = formatter.formatToParts(new Date(nowMs));
  const weekday = parts.find((part) => part.type === "weekday")?.value || "";
  const hour = Number(parts.find((part) => part.type === "hour")?.value || NaN);
  const minute = Number(
    parts.find((part) => part.type === "minute")?.value || NaN,
  );
  const day = CRON_SCHEDULE_DAY_ORDER.find(
    (item) => item.toLowerCase() === String(weekday).slice(0, 3).toLowerCase(),
  );
  return {
    day: day || "",
    hour,
    minute,
    minutes:
      Number.isFinite(hour) && Number.isFinite(minute) ? hour * 60 + minute : NaN,
  };
}

function normalizeMarketDataBar(rawBar) {
  if (!rawBar || typeof rawBar !== "object") return null;
  const time = Number(
    rawBar.time ?? rawBar.t ?? rawBar.bar_start ?? rawBar.bar_start_unix,
  );
  const open = Number(rawBar.open ?? rawBar.o);
  const high = Number(rawBar.high ?? rawBar.h);
  const low = Number(rawBar.low ?? rawBar.l);
  const close = Number(rawBar.close ?? rawBar.c);
  const volume = Number(rawBar.volume ?? rawBar.v);
  if (
    !Number.isFinite(time) ||
    !Number.isFinite(open) ||
    !Number.isFinite(high) ||
    !Number.isFinite(low) ||
    !Number.isFinite(close)
  )
    return null;
  if (open <= 0 || high <= 0 || low <= 0 || close <= 0) return null;
  const out = {
    time: Math.floor(time),
    open,
    high: Math.max(high, open, close),
    low: Math.min(low, open, close),
    close,
  };
  if (Number.isFinite(volume)) out.volume = volume;
  return out;
}

function normalizeMarketDataBars(rawBars = []) {
  const dedup = new Map();
  for (const raw of Array.isArray(rawBars) ? rawBars : []) {
    const bar = normalizeMarketDataBar(raw);
    if (bar) dedup.set(bar.time, bar);
  }
  return [...dedup.values()].sort((a, b) => a.time - b.time);
}

function normalizeIndicatorSeries(
  rawSeries = [],
  { min = null, max = null } = {},
) {
  return (Array.isArray(rawSeries) ? rawSeries : [])
    .map((point) => {
      const time = Number(point?.time);
      const value = Number(point?.value);
      if (!Number.isFinite(time) || !Number.isFinite(value)) return null;
      let nextValue = value;
      if (Number.isFinite(min)) nextValue = Math.max(min, nextValue);
      if (Number.isFinite(max)) nextValue = Math.min(max, nextValue);
      return { time: Math.floor(time), value: nextValue };
    })
    .filter(Boolean);
}

function buildSmaSeriesFromBars(bars, period) {
  if (!Array.isArray(bars) || bars.length < period) return [];
  const out = [];
  let sum = 0;
  for (let i = 0; i < bars.length; i += 1) {
    const close = Number(bars[i]?.close);
    if (!Number.isFinite(close)) continue;
    sum += close;
    if (i >= period) sum -= Number(bars[i - period]?.close) || 0;
    if (i >= period - 1) out.push({ time: bars[i].time, value: sum / period });
  }
  return out;
}

function buildRsiSeriesFromBarsForCache(bars, period = 14) {
  if (!Array.isArray(bars) || bars.length <= period) return [];
  let gains = 0;
  let losses = 0;
  for (let i = 1; i <= period; i += 1) {
    const change = Number(bars[i]?.close) - Number(bars[i - 1]?.close);
    if (!Number.isFinite(change)) return [];
    if (change >= 0) gains += change;
    else losses -= change;
  }
  let avgGain = gains / period;
  let avgLoss = losses / period;
  const out = [];
  const firstRs = avgLoss === 0 ? Infinity : avgGain / avgLoss;
  const firstRsi = avgLoss === 0 ? 100 : 100 - 100 / (1 + firstRs);
  out.push({ time: bars[period].time, value: firstRsi });
  for (let i = period + 1; i < bars.length; i += 1) {
    const change = Number(bars[i]?.close) - Number(bars[i - 1]?.close);
    if (!Number.isFinite(change)) continue;
    const gain = change > 0 ? change : 0;
    const loss = change < 0 ? -change : 0;
    avgGain = (avgGain * (period - 1) + gain) / period;
    avgLoss = (avgLoss * (period - 1) + loss) / period;
    const rs = avgLoss === 0 ? Infinity : avgGain / avgLoss;
    const rsi = avgLoss === 0 ? 100 : 100 - 100 / (1 + rs);
    out.push({ time: bars[i].time, value: rsi });
  }
  return normalizeIndicatorSeries(out, { min: 0, max: 100 });
}

function buildEmaSeriesFromLine(rawSeries, period = 9) {
  const series = normalizeIndicatorSeries(rawSeries);
  if (series.length < period) return [];
  const multiplier = 2 / (period + 1);
  let ema =
    series.slice(0, period).reduce((sum, point) => sum + point.value, 0) /
    period;
  const out = [{ time: series[period - 1].time, value: ema }];
  for (let i = period; i < series.length; i += 1) {
    ema = (series[i].value - ema) * multiplier + ema;
    out.push({ time: series[i].time, value: ema });
  }
  return normalizeIndicatorSeries(out, { min: 0, max: 100 });
}

function buildWmaSeriesFromLine(rawSeries, period = 45) {
  const series = normalizeIndicatorSeries(rawSeries);
  if (series.length < period) return [];
  const denominator = (period * (period + 1)) / 2;
  const out = [];
  for (let i = period - 1; i < series.length; i += 1) {
    let total = 0;
    for (let j = 0; j < period; j += 1) {
      total += Number(series[i - period + 1 + j]?.value) * (j + 1);
    }
    out.push({ time: series[i].time, value: total / denominator });
  }
  return normalizeIndicatorSeries(out, { min: 0, max: 100 });
}

function buildFallbackOscillatorSeriesForCache(
  bars,
  amplitude = 12,
  phase = 0,
) {
  if (!Array.isArray(bars) || !bars.length) return [];
  return normalizeIndicatorSeries(
    bars.map((bar, index) => ({
      time: bar.time,
      value: Math.max(
        0,
        Math.min(100, 50 + Math.sin(index / 6 + phase) * amplitude),
      ),
    })),
    { min: 0, max: 100 },
  );
}

function buildIndicatorSeriesForBars(bars = []) {
  const normalizedBars = normalizeMarketDataBars(bars);
  const rsi = buildRsiSeriesFromBarsForCache(normalizedBars, 14);
  const safeRsi = rsi.length
    ? rsi
    : buildFallbackOscillatorSeriesForCache(normalizedBars, 14, 0);
  const rsiEma9 = buildEmaSeriesFromLine(safeRsi, 9);
  const rsiWma45 = buildWmaSeriesFromLine(safeRsi, 45);
  return {
    sma20: normalizeIndicatorSeries(buildSmaSeriesFromBars(normalizedBars, 20)),
    sma50: normalizeIndicatorSeries(buildSmaSeriesFromBars(normalizedBars, 50)),
    sma200: normalizeIndicatorSeries(
      buildSmaSeriesFromBars(normalizedBars, 200),
    ),
    rsi: safeRsi,
    rsiEma9: rsiEma9.length
      ? rsiEma9
      : buildFallbackOscillatorSeriesForCache(normalizedBars, 9, 0.75),
    rsiWma45: rsiWma45.length
      ? rsiWma45
      : buildFallbackOscillatorSeriesForCache(normalizedBars, 7, 1.35),
  };
}

function attachIndicatorDataToMarketSnapshot(snapshot) {
  if (!snapshot || typeof snapshot !== "object") return snapshot;
  const bars = normalizeMarketDataBars(snapshot.bars);
  const indicators = buildIndicatorSeriesForBars(bars);
  return {
    ...snapshot,
    bars,
    indicators,
    metadata: {
      ...(snapshot.metadata && typeof snapshot.metadata === "object"
        ? snapshot.metadata
        : {}),
      indicators,
      indicator_source: "calculated_from_bars",
      indicator_updated_at: new Date().toISOString(),
    },
  };
}

function detectMarketDataGapCandidates(bars = [], tfNorm = "1min") {
  const sec = Math.max(60, parseTfTokenToSeconds(tfNorm));
  const out = [];
  for (let i = 1; i < bars.length; i++) {
    const prev = Number(bars[i - 1]?.time);
    const cur = Number(bars[i]?.time);
    if (!Number.isFinite(prev) || !Number.isFinite(cur)) continue;
    const missing = Math.round((cur - prev) / sec) - 1;
    if (missing > 0)
      out.push({ after: prev, before: cur, missing_bars: missing });
  }
  return out;
}

function medianNumber(values = []) {
  const nums = (Array.isArray(values) ? values : [])
    .map((value) => Number(value))
    .filter(Number.isFinite)
    .sort((a, b) => a - b);
  if (!nums.length) return 0;
  const mid = Math.floor(nums.length / 2);
  return nums.length % 2 ? nums[mid] : (nums[mid - 1] + nums[mid]) / 2;
}

function brokerBarsLookSynthetic(bars = [], tfNorm = "") {
  const tfKey = String(normalizeMarketDataTf(tfNorm) || "").toLowerCase();
  if (!["5", "15", "5m", "15m"].includes(tfKey)) return false;
  const sample = (Array.isArray(bars) ? bars : []).slice(-60);
  if (sample.length < 24) return false;
  const highs = sample.map((bar) => Number(bar.high));
  const lows = sample.map((bar) => Number(bar.low));
  if (highs.some((value) => !Number.isFinite(value))) return false;
  if (lows.some((value) => !Number.isFinite(value))) return false;
  const windowHigh = Math.max(...highs);
  const windowLow = Math.min(...lows);
  const windowRange = windowHigh - windowLow;
  if (!(windowRange > 0)) return false;
  const medianBarRange = medianNumber(
    sample.map((bar) => Number(bar.high) - Number(bar.low)),
  );
  const fullEnvelopeBars = sample.filter((bar) => {
    const barRange = Number(bar.high) - Number(bar.low);
    return Number.isFinite(barRange) && barRange >= windowRange * 0.82;
  }).length;
  return (
    medianBarRange >= windowRange * 0.75 &&
    fullEnvelopeBars >= Math.floor(sample.length * 0.55)
  );
}

function serializeSnapshotForDb(snapshot) {
  if (!snapshot || typeof snapshot !== "object") return "";
  const bars = normalizeMarketDataBars(snapshot.bars);
  return JSON.stringify({
    version: 2,
    timezone: "UTC",
    provider: snapshot.provider || "unknown",
    bars,
    sl: snapshot.sl ?? null,
    tp: snapshot.tp ?? null,
  });
}

function deserializeSnapshotFromDb(dbData) {
  if (!dbData) return { bars: [] };
  if (typeof dbData === "object" && Array.isArray(dbData.bars)) {
    return { ...dbData, bars: normalizeMarketDataBars(dbData.bars) };
  }
  const raw = String(dbData || "");
  try {
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === "object") {
      return { ...parsed, bars: normalizeMarketDataBars(parsed.bars) };
    }
  } catch {}
  const lines = raw.split("\n").filter((l) => l.trim().length > 0);
  return {
    timezone: "UTC",
    bars: lines
      .map((s) => {
        const parts = s.split(",");
        if (parts.length < 5) return null;
        return normalizeMarketDataBar({
          low: Number(parts[0]),
          high: Number(parts[1]),
          open: Number(parts[2]),
          time: Number(parts[3]),
          close: Number(parts[4]),
        });
      })
      .filter(Boolean),
  };
}

function chunkBarsForLastPrice(dbData) {
  try {
    const snap = deserializeSnapshotFromDb(dbData);
    const bars = Array.isArray(snap?.bars) ? snap.bars : [];
    return bars.length ? bars[bars.length - 1] : null;
  } catch {
    return null;
  }
}

function marketDataCacheKey(symbolNorm) {
  return `market_data:${symbolNorm}`;
}

function marketDataTtlSecByTf(tfNorm) {
  const sec = parseTfTokenToSeconds(tfNorm);
  if (sec <= 5 * 60) return 120;
  if (sec <= 15 * 60) return 300;
  if (sec <= 60 * 60) return 900;
  if (sec <= 4 * 60 * 60) return 3600;
  return 6 * 3600;
}

function marketDataMemoryRead(symbolNorm, tfNorm, reqStart, reqEnd) {
  const key = marketDataCacheKey(symbolNorm);
  const root = UnifiedCache.get(key, { l1Map: MARKET_DATA_MEMORY_CACHE });
  if (!root || typeof root !== "object" || !Array.isArray(root.data))
    return null;
  const tfData = root.data.find((d) => d && d.tf === tfNorm);
  if (!tfData || !Array.isArray(tfData.bars) || !tfData.bars.length)
    return null;
  const s = Number(tfData.bar_start ?? tfData.bars[0]?.time);
  const e = Number(tfData.bar_end ?? tfData.bars[tfData.bars.length - 1]?.time);
  if (!Number.isFinite(s) || !Number.isFinite(e)) return null;
  if (s <= reqStart && e >= reqEnd) return JSON.parse(JSON.stringify(tfData));
  return null;
}

function marketDataFileRead(symbolNorm, tfNorm, reqStart, reqEnd) {
  const tfSec = Math.max(60, parseTfTokenToSeconds(tfNorm));
  const requestedBars = Math.max(
    1,
    Math.ceil((Number(reqEnd || 0) - Number(reqStart || 0)) / tfSec) + 1,
  );
  const bars = readBrokerBarsFromCsv(symbolNorm, tfNorm, requestedBars, reqEnd);
  if (!bars.length) return null;
  const barStart = bars[0].time;
  const barEnd = bars[bars.length - 1].time;
  if (barStart > reqEnd || barEnd < reqStart) return null;
  const metadata = buildBrokerStorageMetadata(
    symbolNorm,
    tfNorm,
    readMarketDataMetadata(symbolNorm, tfNorm),
  );
  const chartArtifacts =
    chartArtifactService.readMarketArtifacts(symbolNorm, tfNorm, {
      dataRoot: GLOBAL_DATA_DIR,
    }) ||
    chartArtifactService.migrateLegacyMarketArtifacts(symbolNorm, tfNorm, {
      dataRoot: GLOBAL_DATA_DIR,
    });
  return {
    symbol: symbolNorm,
    timeframe: tfNorm,
    bar_start: barStart,
    bar_end: barEnd + tfSec,
    bars,
    metadata,
    indicators:
      chartArtifacts?.series?.indicators &&
      typeof chartArtifacts.series.indicators === "object"
        ? chartArtifacts.series.indicators
        : metadata?.indicators && typeof metadata.indicators === "object"
          ? metadata.indicators
        : null,
    chart_artifacts: chartArtifacts,
    last_price: bars[bars.length - 1].close,
    last_price_at: null,
  };
}

function marketDataFileWrite(symbolNorm, tfNorm, data) {
  // Merge bars into CSV (deduplicates by time)
  if (Array.isArray(data.bars) && data.bars.length) {
    mergeBarsIntoCSV(symbolNorm, tfNorm, data.bars);
  }
  // Write metadata sidecar
  if (data.metadata && typeof data.metadata === "object") {
    writeMarketDataMetadata(symbolNorm, tfNorm, data.metadata);
  }
  const bars = normalizeMarketDataBars(data?.bars);
  if (bars.length) {
    const rangeStart = Number(bars[0]?.time) || null;
    const rangeEnd = Number(bars[bars.length - 1]?.time) || null;
    const indicators =
      data?.indicators && typeof data.indicators === "object"
        ? data.indicators
        : buildIndicatorSeriesForBars(bars);
    const existing = chartArtifactService.readMarketArtifacts(symbolNorm, tfNorm, {
      dataRoot: GLOBAL_DATA_DIR,
      startTime: rangeStart,
      endTime: rangeEnd,
    });
    const envelope = chartArtifactService.mergeMarketArtifacts({
      symbol: symbolNorm,
      timeframe: tfNorm,
      bars,
      indicators,
      metadata: data?.metadata && typeof data.metadata === "object" ? data.metadata : {},
      provider: data?.provider || data?.metadata?.provider || "",
      userId: data?.user_id || CFG.mt5DefaultUserId,
      existing,
      startTime: rangeStart,
      endTime: rangeEnd,
    });
    chartArtifactService.writeMarketArtifacts(symbolNorm, tfNorm, envelope, {
      dataRoot: GLOBAL_DATA_DIR,
      startTime: rangeStart,
      endTime: rangeEnd,
    });
  }
  // Update L1 memory cache
  marketDataMemoryWrite(symbolNorm, tfNorm, data);
}

async function notifyPulse(userId, type = "general") {
  if (!CFG.redisEnabled) return;
  try {
    const client = await getRedisClient();
    if (!client) return;
    const now = Date.now();
    const key = `NOTIF_PULSE:${userId || "global"}`;
    await client.hSet(key, type, String(now));
    await client.expire(key, 3600); // 1 hour is enough for pulse
    await client.set("NOTIF_PULSE:GLOBAL", String(now), { EX: 3600 });
  } catch (err) {}
}

async function updateHealthActivity(objectType, objectId, value = {}) {
  if (!CFG.redisEnabled) return;
  try {
    const client = await getRedisClient();
    if (!client) return;
    const type = String(objectType || "")
      .trim()
      .toUpperCase();
    const id = String(objectId || "").trim();
    if (!type || !id) return;
    const field = `${type}:${id}`;
    const ts = Date.now();
    const payload = {
      object_type: type,
      object_id: id,
      key: field,
      updated_at: new Date(ts).toISOString(),
      ts,
      ...(value && typeof value === "object" ? value : { value }),
    };
    await client.hSet("HEALTH_ACTIVITY", field, JSON.stringify(payload));
    await client.zAdd("HEALTH_ACTIVITY_TS", [{ score: ts, value: field }]);
    await client.expire("HEALTH_ACTIVITY", 86400 * 14);
    await client.expire("HEALTH_ACTIVITY_TS", 86400 * 14);
  } catch {}
}

async function getHealthActivity(limit = 50, prefix = "") {
  if (!CFG.redisEnabled) return [];
  try {
    const client = await getRedisClient();
    if (!client) return [];
    const max = Math.max(1, Math.min(500, Number(limit) || 50));
    const filter = String(prefix || "")
      .trim()
      .toUpperCase();
    const members = await client.zRange("HEALTH_ACTIVITY_TS", 0, max * 5, {
      REV: true,
    });
    if (!Array.isArray(members) || !members.length) return [];
    const filtered = filter
      ? members.filter((m) =>
          String(m || "")
            .toUpperCase()
            .startsWith(filter),
        )
      : members;
    const picked = [...new Set(filtered)].slice(0, max);
    if (!picked.length) return [];
    const values = await client.hmGet("HEALTH_ACTIVITY", picked);
    return picked
      .map((k, i) => {
        const raw = values[i];
        if (!raw) return null;
        try {
          return JSON.parse(raw);
        } catch {
          return { key: k, raw };
        }
      })
      .filter(Boolean);
  } catch {
    return [];
  }
}

async function upsertSymbolActivity(symbolRaw, patch = {}) {
  if (!CFG.redisEnabled) return null;
  const symbol = normalizeMarketDataSymbol(symbolRaw);
  if (!symbol) return null;
  try {
    const client = await getRedisClient();
    if (!client) return null;
    const field = symbol;
    const existingRaw = await client.hGet("HEALTH_SYMBOL_ACTIVITY", field);
    let existing = {};
    if (existingRaw) {
      try {
        existing = JSON.parse(existingRaw) || {};
      } catch {
        existing = {};
      }
    }
    const ts = Date.now();
    const next = {
      symbol,
      updated_at: new Date(ts).toISOString(),
      ts,
      ...existing,
      ...patch,
    };
    await client.hSet("HEALTH_SYMBOL_ACTIVITY", field, JSON.stringify(next));
    await client.zAdd("HEALTH_SYMBOL_ACTIVITY_TS", [
      { score: ts, value: field },
    ]);
    await client.expire("HEALTH_SYMBOL_ACTIVITY", 86400 * 14);
    await client.expire("HEALTH_SYMBOL_ACTIVITY_TS", 86400 * 14);
    return next;
  } catch {
    return null;
  }
}

async function getSymbolActivity(limit = 200) {
  if (!CFG.redisEnabled) return [];
  try {
    const client = await getRedisClient();
    if (!client) return [];
    const max = Math.max(1, Math.min(1000, Number(limit) || 200));
    const members = await client.zRange(
      "HEALTH_SYMBOL_ACTIVITY_TS",
      0,
      max - 1,
      {
        REV: true,
      },
    );
    if (!Array.isArray(members) || !members.length) return [];
    const values = await client.hmGet("HEALTH_SYMBOL_ACTIVITY", members);
    return members
      .map((symbol, i) => {
        const raw = values[i];
        if (!raw) return null;
        try {
          return JSON.parse(raw);
        } catch {
          return { symbol, raw };
        }
      })
      .filter(Boolean);
  } catch {
    return [];
  }
}

async function getRedisClient() {
  if (!CFG.redisEnabled || !createRedisClient || !CFG.redisUrl) return null;
  if (REDIS_CLIENT?.isOpen) return REDIS_CLIENT;
  if (REDIS_CONNECTING) return REDIS_CONNECTING;
  REDIS_CONNECTING = (async () => {
    try {
      const client = createRedisClient({ url: CFG.redisUrl });
      client.on("error", (err) => {
        const msg =
          err instanceof Error ? err.message : String(err || "unknown");
        console.warn("[Redis] client error:", msg);
      });
      await client.connect();
      REDIS_CLIENT = client;
      return REDIS_CLIENT;
    } catch (error) {
      const msg =
        error instanceof Error
          ? error.message
          : String(error || "connect_failed");
      console.warn("[Redis] connect failed:", msg);
      REDIS_CLIENT = null;
      return null;
    } finally {
      REDIS_CONNECTING = null;
    }
  })();
  return REDIS_CONNECTING;
}

// ── Provider code resolver ──
function resolveProviderCode(brokerName) {
  if (!brokerName) return null;
  const name = String(brokerName).toLowerCase();
  // IC Markets
  if (name.includes("ic market") || name.includes("icmarkets"))
    return "ICMARKETS";
  // OANDA
  if (name.includes("oanda")) return "OANDA";
  // EightCap
  if (name.includes("eightcap") || name.includes("8cap")) return "EIGHTCAP";
  // Pepperstone
  if (name.includes("pepperstone")) return "PEPPERSTONE";
  // Forex.com
  if (
    name.includes("forex.com") ||
    name.includes("forexcom") ||
    name.includes("gain capital")
  )
    return "FOREXCOM";
  // FXCM
  if (name.includes("fxcm")) return "FXCM";
  // XM
  if (name.includes("xm group") || name.includes("xm.com")) return "XM";
  // Exness
  if (name.includes("exness")) return "EXNESS";
  // RoboForex
  if (name.includes("roboforex")) return "ROBOFOREX";
  // FP Markets
  if (name.includes("fp market")) return "FPMARKETS";
  // Admiral Markets
  if (name.includes("admiral")) return "ADMIRAL";
  // Vantage
  if (name.includes("vantage")) return "VANTAGE";
  // Tickmill
  if (name.includes("tickmill")) return "TICKMILL";
  // Fusion Markets
  if (name.includes("fusion")) return "FUSIONMARKETS";
  // Darwinex
  if (name.includes("darwinex")) return "DARWINEX";
  return null;
}

// ── Trade List Redis Cache (Pending / Filled) ──
const TRADE_LIST_CACHE_TTL = 300; // 5 minutes

async function invalidateTradeListCaches() {
  try {
    await StateRepo.flushBucket("TRADE_LIST").catch(() => {});
    const runtime = await getAppRuntime().catch(() => null);
    await runtime?.cache?.deletePrefix("trades:pending:");
    await runtime?.cache?.deletePrefix("trades:filled:");
    await runtime?.cache?.delete("trades:pending");
    await runtime?.cache?.delete("trades:filled");
  } catch (err) {
    console.warn("[TradeCache] invalidate failed:", err.message);
  }
}

async function getTradeListFromCache(status) {
  try {
    const runtime = await getAppRuntime().catch(() => null);
    const src = resolveMt5DbSource(currentMt5DbSourceId());
    const srcId = src?.id || "active";
    const cacheKey = `trades:${status.toLowerCase()}:${srcId}`;
    return (await runtime?.cache?.get(cacheKey)) || null;
  } catch {}
  return null;
}

async function setTradeListCache(status, items) {
  try {
    const runtime = await getAppRuntime().catch(() => null);
    const src = resolveMt5DbSource(currentMt5DbSourceId());
    const srcId = src?.id || "active";
    const cacheKey = `trades:${status.toLowerCase()}:${srcId}`;
    await runtime?.cache?.set(cacheKey, Array.isArray(items) ? items : [], {
      ttlMs: TRADE_LIST_CACHE_TTL * 1000,
    });
  } catch (err) {
    console.warn("[TradeCache] set failed:", err.message);
  }
}

async function marketDataRedisRead(symbolNorm, tfNorm, reqStart, reqEnd) {
  const runtime = await getAppRuntime().catch(() => null);
  const key = marketDataCacheKey(symbolNorm);
  const root = await runtime?.cache?.get(`market_data:${key}`);

  if (!root || !Array.isArray(root.data)) return null;

  // Find the specific timeframe in the data array
  const tfData = root.data.find((d) => d.tf === tfNorm);
  if (!tfData || !Array.isArray(tfData.bars) || !tfData.bars.length)
    return null;

  const s = Number(tfData.bar_start);
  const e = Number(tfData.bar_end);
  if (!Number.isFinite(s) || !Number.isFinite(e)) return null;

  if (s <= reqStart && e >= reqEnd) {
    return tfData;
  }
  return null;
}

function marketDataMemoryWrite(symbolNorm, tfNorm, data) {
  const key = marketDataCacheKey(symbolNorm);
  const ttl = 1800; // Unified TTL for symbol (30m)

  let root = UnifiedCache.get(key, { l1Map: MARKET_DATA_MEMORY_CACHE });
  if (!root || typeof root !== "object") {
    root = {
      symbol: symbolNorm,
      updated_time: Math.floor(Date.now() / 1000),
      data: [],
    };
  }

  // Update or Add TF
  const existingIdx = Array.isArray(root.data)
    ? root.data.findIndex((d) => d.tf === tfNorm)
    : -1;
  const tfEntry = {
    ...data,
    tf: tfNorm,
    updated_time: Math.floor(Date.now() / 1000),
  };
  if (existingIdx >= 0) {
    root.data[existingIdx] = tfEntry;
  } else {
    root.data.push(tfEntry);
  }
  root.updated_time = tfEntry.updated_time;

  UnifiedCache.set(key, root, {
    l1Map: MARKET_DATA_MEMORY_CACHE,
    l2Prefix: "market_data",
    ttlSec: ttl,
  });
}

async function marketDataRedisWrite(symbolNorm, tfNorm, snapshot) {
  const runtime = await getAppRuntime().catch(() => null);
  if (!runtime?.cache) return;
  const key = marketDataCacheKey(symbolNorm);
  const ttl = 3600; // Unified TTL for symbol (1h)

  // Atomic-ish update: Get, Merge, Set
  let root = await runtime.cache.get(`market_data:${key}`);

  if (!root || typeof root !== "object") {
    root = {
      symbol: symbolNorm,
      updated_time: Math.floor(Date.now() / 1000),
      data: [],
    };
  }

  const tfEntry = {
    ...snapshot,
    tf: tfNorm,
    updated_time: Math.floor(Date.now() / 1000),
    source: snapshot.source || "remote_api",
  };

  const existingIdx = Array.isArray(root.data)
    ? root.data.findIndex((d) => d.tf === tfNorm)
    : -1;
  if (existingIdx >= 0) {
    root.data[existingIdx] = tfEntry;
  } else {
    root.data.push(tfEntry);
  }
  root.updated_time = tfEntry.updated_time;

  await runtime.cache.set(`market_data:${key}`, root, {
    ttlMs: ttl * 1000,
  });
}

async function marketDataFileUpsert(symbolNorm, tfNorm, snapshot) {
  const bars = normalizeMarketDataBars(snapshot?.bars);
  if (!bars.length) return;
  const rangeStart = Number(bars[0]?.time) || null;
  const rangeEnd = Number(bars[bars.length - 1]?.time) || null;
  const indicators =
    snapshot?.indicators && typeof snapshot.indicators === "object"
      ? snapshot.indicators
      : buildIndicatorSeriesForBars(bars);
  const metadata = {
    ...(snapshot?.metadata && typeof snapshot.metadata === "object"
      ? snapshot.metadata
      : {}),
    indicators,
    provider: String(snapshot?.provider || "").trim() || "unknown",
    cache_source: String(snapshot?.cache_source || "").trim() || "file",
    last_price: Number.isFinite(Number(snapshot?.last_price))
      ? Number(snapshot.last_price)
      : Number(bars[bars.length - 1]?.close) || null,
    indicator_source: "calculated_from_bars",
    indicator_updated_at: new Date().toISOString(),
  };

  // Merge bars into CSV (deduplicates by time, updates L1 + Redis cache)
  mergeBarsIntoCSV(symbolNorm, tfNorm, bars);
  writeMarketDataMetadata(symbolNorm, tfNorm, metadata);

  // Skip the load -> recompute -> save cycle when nothing about the input changed (same
  // bars + same AI arrays). Pure in-memory check - no disk I/O on the hot loop.
  if (chartArtifactService.marketArtifactInputChanged(symbolNorm, tfNorm, bars, metadata)) {
    const existing = chartArtifactService.readMarketArtifacts(symbolNorm, tfNorm, {
      dataRoot: GLOBAL_DATA_DIR,
      startTime: rangeStart,
      endTime: rangeEnd,
    });
    const chartArtifacts = chartArtifactService.mergeMarketArtifacts({
      symbol: symbolNorm,
      timeframe: tfNorm,
      bars,
      indicators,
      metadata,
      provider: snapshot?.provider || metadata?.provider || "unknown",
      userId: snapshot?.user_id || CFG.mt5DefaultUserId,
      existing,
      startTime: rangeStart,
      endTime: rangeEnd,
    });
    chartArtifactService.writeMarketArtifacts(symbolNorm, tfNorm, chartArtifacts, {
      dataRoot: GLOBAL_DATA_DIR,
      startTime: rangeStart,
      endTime: rangeEnd,
    });
    marketDataMemoryWrite(symbolNorm, tfNorm, {
      ...snapshot,
      bars,
      indicators,
      metadata,
      chart_artifacts: chartArtifacts,
      bar_start: snapshot?.bar_start || bars[0]?.time || null,
      bar_end: snapshot?.bar_end || bars[bars.length - 1]?.time || null,
    });
    await marketDataRedisWrite(symbolNorm, tfNorm, {
      ...snapshot,
      bars,
      indicators,
      metadata,
      chart_artifacts: chartArtifacts,
      bar_start: snapshot?.bar_start || bars[0]?.time || null,
      bar_end: snapshot?.bar_end || bars[bars.length - 1]?.time || null,
    }).catch(() => {});
  }

  // Update cron state (keeps tracking for monitoring)
  await marketDataUpdateCronState({
    userId: snapshot.user_id || CFG.mt5DefaultUserId,
    settingName: snapshot.setting_name || "default",
    symbol: symbolNorm,
    tf: tfNorm,
    patch: {
      last_success_at: new Date().toISOString(),
      last_bar_start: bars[bars.length - 1]?.time || null,
      chunk_count: 1,
      bar_count: bars.length,
      gap_candidates: detectMarketDataGapCandidates(bars, tfNorm).slice(0, 20),
    },
  }).catch(() => {});
}

function normalizeEmail(emailRaw) {
  return String(emailRaw || "")
    .trim()
    .toLowerCase();
}

function normalizeUserRoles(rolesRaw, fallbackRoles = [UI_USER_ROLE_ID]) {
  return normalizeRoles(rolesRaw, fallbackRoles);
}

function normalizeUserPermissions(permissionsRaw) {
  return normalizePermissions(permissionsRaw);
}

function migrateLegacyRoleId(roleRaw) {
  const roleId = String(roleRaw || "").trim().toLowerCase();
  if (roleId === "system") return "admin";
  if (roleId === "guest") return UI_BUYER_ROLE_ID;
  if (roleId === "merchant") return "seller";
  if (roleId === "user") return UI_BUYER_ROLE_ID;
  return roleId;
}

function migrateLegacyRoles(roleRaw, fallbackRoles = [UI_USER_ROLE_ID]) {
  if (Array.isArray(roleRaw)) {
    return normalizeUserRoles(roleRaw.map(migrateLegacyRoleId), fallbackRoles);
  }
  const migrated = migrateLegacyRoleId(roleRaw);
  return normalizeUserRoles(migrated ? [migrated] : [], fallbackRoles);
}

function primaryUserRoleId(user = null, fallback = UI_USER_ROLE_ID) {
  return normalizeUserRoles(user?.roles, [fallback])[0] || fallback;
}

function canUseCodexForRole(roleRaw = "", isAdmin = false, user = null) {
  if (isAdmin) return true;
  if (hasPermission(user, "pages.system.users")) return true;
  const roleId = String(roleRaw || "").trim().toLowerCase();
  return roleId === "system" || roleId === "admin";
}

function normalizeUserActive(activeRaw, fallback = true) {
  if (typeof activeRaw === "boolean") return activeRaw;
  if (
    activeRaw === 1 ||
    activeRaw === "1" ||
    String(activeRaw || "").toLowerCase() === "true"
  )
    return true;
  if (
    activeRaw === 0 ||
    activeRaw === "0" ||
    String(activeRaw || "").toLowerCase() === "false"
  )
    return false;
  return Boolean(fallback);
}

function isAdminUser(user = null) {
  return hasPermission(user, "pages.system.users");
}

function isValidEmail(emailRaw) {
  const email = normalizeEmail(emailRaw);
  return Boolean(email && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email));
}

function uiPublicUserView(user) {
  const roles = normalizeUserRoles(user?.roles);
  const permissions = normalizeUserPermissions(user?.permissions);
  return {
    user_id: String(user?.user_id || ""),
    name: String(user?.name || ""),
    email: normalizeEmail(user?.email),
    roles,
    permissions,
    is_active: normalizeUserActive(user?.is_active, true),
    updated_at: String(user?.updated_at || ""),
    created_at: String(user?.created_at || ""),
  };
}

function uiPublicAccountView(row) {
  return {
    account_id: String(row?.account_id || ""),
    user_id: String(row?.user_id || ""),
    name: String(row?.name || ""),
    balance:
      row?.balance === null || row?.balance === undefined
        ? null
        : Number(row.balance),
    status: String(row?.status || ""),
    metadata:
      row?.metadata && typeof row.metadata === "object"
        ? row.metadata
        : row?.metadata
          ? row.metadata
          : null,
    created_at: String(row?.created_at || ""),
    updated_at: String(row?.updated_at || ""),
  };
}

function fallbackNameFromEmail(emailRaw) {
  const email = normalizeEmail(emailRaw);
  if (!email) return "System";
  return String(email.split("@")[0] || "System");
}

function makeSaltHex() {
  return crypto.randomBytes(16).toString("hex");
}

const UUID_V4ISH_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function makeCompactId(prefix = "ID", chars = 8) {
  const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  const size = Math.max(4, Number(chars) || 8);
  const bytes = crypto.randomBytes(size);
  let body = "";
  for (let i = 0; i < size; i += 1)
    body += alphabet[bytes[i] % alphabet.length];
  return `${String(prefix || "ID").toUpperCase()}_${body}`;
}

// --- Security & Encryption ---

const ENCRYPTION_ALGO = "aes-256-gcm";
const ENCRYPTION_KEY_SECRET = envStr(
  process.env.ENCRYPTION_KEY,
  "a_very_secret_32_byte_key_placeholder_123",
); // 32 bytes for aes-256

function getEncryptionKey() {
  // Ensure the key is exactly 32 bytes
  return crypto.createHash("sha256").update(ENCRYPTION_KEY_SECRET).digest();
}

/**
 * Encrypt sensitive data (API keys, secrets) using AES-256-GCM
 */
function encryptData(text) {
  if (!text) return null;
  const iv = crypto.randomBytes(12);
  const key = getEncryptionKey();
  const cipher = crypto.createCipheriv(ENCRYPTION_ALGO, key, iv);
  let encrypted = cipher.update(text, "utf8", "hex");
  encrypted += cipher.final("hex");
  const tag = cipher.getAuthTag().toString("hex");
  // Format: iv:tag:encrypted
  return `${iv.toString("hex")}:${tag}:${encrypted}`;
}

/**
 * Decrypt sensitive data (original plaintext)
 */
function decryptData(cipherText) {
  if (!cipherText) return null;
  const parts = cipherText.split(":");
  if (parts.length !== 3) return cipherText; // Return as is if not encrypted format (legacy support)

  try {
    const iv = Buffer.from(parts[0], "hex");
    const tag = Buffer.from(parts[1], "hex");
    const encrypted = parts[2];
    const key = getEncryptionKey();
    const decipher = crypto.createDecipheriv(ENCRYPTION_ALGO, key, iv);
    decipher.setAuthTag(tag);
    let decrypted = decipher.update(encrypted, "hex", "utf8");
    decrypted += decipher.final("utf8");
    return decrypted;
  } catch (err) {
    console.warn(
      "[security] Decryption failed, returning raw string (might be plaintext or bad key)",
      err.message,
    );
    return cipherText;
  }
}

/**
 * Encrypt/Decrypt object values (for JSONB data containing multiple keys)
 */
function encryptObject(obj) {
  if (Array.isArray(obj)) {
    return obj.map((item) => encryptObject(item));
  }
  if (!obj || typeof obj !== "object") {
    return encryptData(String(obj ?? ""));
  }
  const out = {};
  for (const [k, v] of Object.entries(obj)) {
    if (Array.isArray(v) || (v && typeof v === "object")) {
      out[k] = encryptObject(v);
    } else {
      out[k] = encryptData(String(v ?? ""));
    }
  }
  return out;
}

function decryptObject(obj) {
  if (Array.isArray(obj)) {
    return obj.map((item) => decryptObject(item));
  }
  if (!obj || typeof obj !== "object") {
    return decryptData(String(obj ?? ""));
  }
  const out = {};
  for (const [k, v] of Object.entries(obj)) {
    if (Array.isArray(v) || (v && typeof v === "object")) {
      out[k] = decryptObject(v);
    } else {
      out[k] = decryptData(String(v ?? ""));
    }
  }
  return out;
}

/**
 * Mask an API key for display: first 4 chars + **** + last 4 chars of the real decrypted key.
 * Example: sk-ant-api03-abcdef123456789 → sk-a****6789
 */
function maskApiKeyForDisplay(value) {
  const raw = String(value || "");
  if (!raw) return "";
  if (raw.length <= 8) return raw.slice(0, 1) + "****" + raw.slice(-1);
  return raw.slice(0, 4) + "****" + raw.slice(-4);
}

function maskPasswordPreview(value) {
  const raw = String(value || "");
  if (!raw) return "";
  return "****";
}

function isMaskedSecretLike(value) {
  return String(value || "").includes("****");
}

function isMaskedApiKeyLike(value) {
  const v = String(value || "").trim();
  return v.includes("****");
}

function splitApiKeyCandidates(value) {
  return String(value || "")
    .split(/[\n,]/)
    .map((item) => String(item || "").trim())
    .filter(Boolean);
}

function apiKeyFingerprint(value = "") {
  const normalized = String(value || "").trim();
  if (!normalized) return "";
  return crypto
    .createHash("sha256")
    .update(normalized)
    .digest("hex")
    .slice(0, 16);
}

function maskApiKeyEntry(entry = {}) {
  const value = String(
    entry?.api_key ?? entry?.value ?? entry?.key ?? "",
  ).trim();
  return {
    ...entry,
    api_key: value ? maskApiKeyForDisplay(value) : "",
    value: undefined,
    key: undefined,
  };
}

function normalizeApiKeyEntries(raw = {}) {
  const data = raw && typeof raw === "object" ? raw : {};
  const out = [];
  const seen = new Set();
  const push = (entry = {}, fallbackIndex = 0) => {
    const apiKey = sanitizeRuntimeApiKey(
      entry?.api_key ?? entry?.value ?? entry?.key ?? "",
    );
    if (!apiKey) return;
    const fingerprint = apiKeyFingerprint(apiKey);
    if (!fingerprint || seen.has(fingerprint)) return;
    seen.add(fingerprint);
    const statusRaw = String(
      entry?.status || (entry?.invalid === true ? "invalid" : "active"),
    )
      .trim()
      .toLowerCase();
    const status =
      statusRaw === "invalid"
        ? "invalid"
        : statusRaw === "inactive"
          ? "inactive"
          : "active";
    out.push({
      id:
        String(entry?.id || "").trim() ||
        `key_${fallbackIndex + 1}_${fingerprint.slice(0, 6)}`,
      api_key: apiKey,
      status,
      invalid: status === "invalid",
      invalid_reason: String(entry?.invalid_reason || entry?.reason || "").trim() || null,
      invalid_at: String(entry?.invalid_at || "").trim() || null,
      last_checked_at: String(entry?.last_checked_at || "").trim() || null,
      last_error: String(entry?.last_error || "").trim() || null,
      last_success_at: String(entry?.last_success_at || "").trim() || null,
      fingerprint,
    });
  };

  if (Array.isArray(data.key_entries) && data.key_entries.length) {
    data.key_entries.forEach((entry, index) => push(entry, index));
  }
  if (Array.isArray(data.api_keys) && data.api_keys.length) {
    data.api_keys.forEach((value, index) => push({ api_key: value }, out.length + index));
  }
  if (!out.length) {
    const single = sanitizeRuntimeApiKey(data.api_key || data.value || "");
    if (single) push({ api_key: single }, 0);
  }
  return out;
}

function buildApiKeySettingPayload(raw = {}, { fallbackEntries = [] } = {}) {
  const data = raw && typeof raw === "object" ? raw : {};
  let entries = normalizeApiKeyEntries(data);
  if (!entries.length && Array.isArray(fallbackEntries) && fallbackEntries.length) {
    entries = normalizeApiKeyEntries({ key_entries: fallbackEntries });
  }
  const firstActiveEntry =
    entries.find((entry) => entry.status === "active") ||
    entries.find((entry) => entry.status !== "invalid") ||
    entries[0] ||
    null;
  return {
    ...(data && typeof data === "object" ? data : {}),
    api_key: firstActiveEntry?.api_key || "",
    value: firstActiveEntry?.api_key || "",
    api_keys: entries.map((entry) => entry.api_key),
    key_entries: entries.map((entry) => ({
      id: entry.id,
      api_key: entry.api_key,
      status: entry.status,
      invalid: entry.invalid === true,
      invalid_reason: entry.invalid_reason || null,
      invalid_at: entry.invalid_at || null,
      last_checked_at: entry.last_checked_at || null,
      last_error: entry.last_error || null,
      last_success_at: entry.last_success_at || null,
      fingerprint: entry.fingerprint,
    })),
  };
}

function isLikelyInvalidProviderKeyError(errorLike = null) {
  if (!errorLike) return false;
  const status = Number(errorLike?.status || errorLike?.statusCode || 0);
  const text = String(
    errorLike?.message || errorLike?.body || errorLike?.error || errorLike || "",
  )
    .trim()
    .toLowerCase();
  if (status === 401 || status === 403) return true;
  return (
    text.includes("invalid api key") ||
    text.includes("invalid apikey") ||
    text.includes("invalid_api_key") ||
    text.includes("api key is invalid") ||
    text.includes("incorrect api key") ||
    text.includes("unauthorized") ||
    text.includes("forbidden") ||
    text.includes("authentication failed") ||
    text.includes("invalid x-api-key") ||
    text.includes("permission denied") ||
    text.includes("access denied") ||
    text.includes("key is invalid") ||
    text.includes("api_key_invalid")
  );
}

function hashPassword(passwordRaw, saltHex) {
  return crypto
    .scryptSync(String(passwordRaw || ""), saltHex, 64)
    .toString("hex");
}

const ALLOWED_AI_API_KEY_NAMES = new Set([
  "GEMINI_API_KEY",
  "OPENAI_API_KEY",
  "DEEPSEEK_API_KEY",
  "CLAUDE_API_KEY",
  "TWELVE_DATA_API_KEY",
  "OPENROUTER_API_KEY",
  "OLLAMA_API_KEY",
]);

function normalizeAiApiKeyName(rawName) {
  const name = String(rawName || "")
    .trim()
    .toUpperCase();
  if (name === "GEMINI" || name === "GOOGLE_GEMINI" || name === "GEMINI_KEY")
    return "GEMINI_API_KEY";
  if (name === "OPENAI" || name === "OPENAI_KEY") return "OPENAI_API_KEY";
  if (name === "DEEPSEEK" || name === "DEEPSEEK_KEY") return "DEEPSEEK_API_KEY";
  if (name === "OPENROUTER" || name === "OPENROUTER_KEY")
    return "OPENROUTER_API_KEY";
  if (
    name === "CLAUDE" ||
    name === "ANTHROPIC" ||
    name === "ANTHROPIC_API_KEY" ||
    name === "CLAUDE_KEY"
  )
    return "CLAUDE_API_KEY";
  if (
    name === "TWELVE" ||
    name === "TWELVEDATA" ||
    name === "TWELVE_DATA" ||
    name === "TWELVE_DATA_KEY"
  )
    return "TWELVE_DATA_API_KEY";
  if (name === "OLLAMA" || name === "OLLAMA_LOCAL" || name === "OLLAMA_API_KEY")
    return "OLLAMA_API_KEY";
  return name;
}

function resolveProviderSettingNameForLog(providerRaw, modelRaw = "") {
  const provider = String(providerRaw || "")
    .trim()
    .toLowerCase();
  const model = String(modelRaw || "")
    .trim()
    .toLowerCase();

  if (
    provider === "claude" ||
    provider === "anthropic" ||
    model.includes("claude")
  ) {
    return "CLAUDE_API_KEY";
  }
  if (provider === "openrouter" || model.includes("openrouter")) {
    return "OPENROUTER_API_KEY";
  }
  if (
    provider === "openai" ||
    provider === "gpt4o" ||
    provider === "gpt-4o" ||
    provider === "chatgpt" ||
    model.includes("gpt") ||
    model.includes("openai")
  ) {
    return "OPENAI_API_KEY";
  }
  if (provider === "deepseek" || model.includes("deepseek")) {
    return "DEEPSEEK_API_KEY";
  }
  if (
    provider === "gemini" ||
    provider === "google" ||
    provider === "google_gemini" ||
    model.includes("gemini")
  ) {
    return "GEMINI_API_KEY";
  }
  if (
    provider === "twelvedata" ||
    provider === "twelve_data" ||
    provider === "twelve" ||
    model.includes("twelve")
  ) {
    return "TWELVE_DATA_API_KEY";
  }
  if (
    provider === "ollama" ||
    provider === "local_ai" ||
    model === "local" ||
    model.startsWith("local_")
  ) {
    return "OLLAMA_API_KEY";
  }

  const normalized = normalizeAiApiKeyName(providerRaw || modelRaw || "");
  return ALLOWED_AI_API_KEY_NAMES.has(normalized) ? normalized : "";
}

function sanitizeProviderLogMessage(raw) {
  const clipped = clipForLog(raw, 600)
    .replace(/Bearer\s+[A-Za-z0-9._=-]+/gi, "Bearer [REDACTED]")
    .replace(
      /\b(sk-[A-Za-z0-9_-]{6,}|AIza[0-9A-Za-z\-_]{10,})\b/g,
      "[REDACTED]",
    )
    .replace(/\b[A-Za-z0-9+/_=-]{40,}\b/g, "[REDACTED]");
  return clipped;
}

async function logProviderActivity({
  userId,
  provider,
  model = "",
  event,
  message = "",
  level = "INFO",
  statusCode = null,
  metadata = {},
}) {
  const providerId = settingsStore.providerObjectIdFromSettingName(
    resolveProviderSettingNameForLog(provider, model),
  );
  if (!providerId || providerId === "default") return;
  const uid =
    String(userId || CFG.mt5DefaultUserId).trim() || CFG.mt5DefaultUserId;
  try {
    await writeObjectLog(uid, "providers", providerId, {
      event,
      level,
      message,
      provider: String(provider || "").trim() || providerId,
      model: String(model || "").trim() || null,
      status_code: statusCode,
      ...metadata,
    });
  } catch (err) {
    console.warn("[providers] local log write failed:", err?.message || err);
  }
}

function hashApiKey(raw) {
  return crypto
    .createHash("sha256")
    .update(String(raw || ""), "utf8")
    .digest("hex");
}

function timingSafeEqHex(aHex, bHex) {
  try {
    const a = Buffer.from(String(aHex || ""), "hex");
    const b = Buffer.from(String(bHex || ""), "hex");
    if (a.length === 0 || b.length === 0 || a.length !== b.length) return false;
    return crypto.timingSafeEqual(a, b);
  } catch {
    return false;
  }
}

function timingSafeEq(aText, bText) {
  try {
    const a = Buffer.from(String(aText || ""), "utf8");
    const b = Buffer.from(String(bText || ""), "utf8");
    if (a.length === 0 || b.length === 0 || a.length !== b.length) return false;
    return crypto.timingSafeEqual(a, b);
  } catch {
    return false;
  }
}

