function pay42Service() {
  if (PAY42_SERVICE) return PAY42_SERVICE;
  async function upsertWalletAccountFallback(account = {}) {
    const store = getUserAccountObjectStore();
    const split = store.splitLegacyUserAccount(account);
    if (!split?.accountId) return null;
    await store.upsertStaticObject(
      split.userId,
      "user_accounts",
      split.accountId,
      split.staticObject,
      {
        created_at: split.createdAt,
        updated_at: split.updatedAt,
      },
    );
    await store.upsertDynamicObject(
      split.userId,
      "user_accounts",
      split.accountId,
      split.dynamicMetadata,
      split.dynamicStatus,
      {
        created_at: split.createdAt,
        updated_at: split.updatedAt,
      },
    );
    return store.getUnifiedObject(split.userId, "user_accounts", split.accountId);
  }
  PAY42_SERVICE = create42PayService({
    projectRoot: PROJECT_ROOT,
    objectStore: {
      provider: String(CFG.mt5StorageBackend || "postgres")
        .trim()
        .toLowerCase() || "postgres",
      dataRoot: USER_DATA_ROOT,
      sqlitePath: resolveConfiguredSqlitePath(),
      postgresUrl: CFG.mt5PostgresUrl,
    },
    accounts: {
      async listUserAccounts(userId) {
        const b = await mt5Backend();
        if (b.listUserAccounts) return b.listUserAccounts(userId);
        return getUserAccountObjectStore().listUnifiedObjects(
          String(userId || "").trim(),
          "user_accounts",
        );
      },
      async ensureWalletAccount(config = {}) {
        const userId = String(config.user_id || "").trim();
        if (!userId) return null;
        const b = await mt5Backend();
        const existing = b.listUserAccounts ? await b.listUserAccounts(userId) : [];
        const current =
          (Array.isArray(existing) ? existing : []).find(
            (account) =>
              account?.metadata &&
              typeof account.metadata === "object" &&
              account.metadata.pay42_wallet === true,
          ) || null;
        if (current) return current;
        const role = String(config.role || "buyer").trim().toLowerCase();
        const suffix = role === "seller" ? "seller" : "buyer";
        const accountId = `42pay_wallet_${suffix}_${userId.replace(/[^a-zA-Z0-9_-]/g, "_")}`;
        const createPayload = {
          account_id: accountId,
          user_id: userId,
          name: String(config.name || `${userId} 42Pay Wallet`),
          status: "ACTIVE",
          balance: Number(config.default_balance || 0),
          metadata: {
            pay42_wallet: true,
            pay42_role: role,
            payment_domain: "42pay",
          },
        };
        const created = b.createAccountV2
          ? await b.createAccountV2(createPayload)
          : {
              ok: true,
              item: await upsertWalletAccountFallback(createPayload),
            };
        if (created?.item) return created.item;
        const refreshed = b.listUserAccounts ? await b.listUserAccounts(userId) : [];
        return (
          (Array.isArray(refreshed) ? refreshed : []).find(
            (account) =>
              account?.metadata &&
              typeof account.metadata === "object" &&
              account.metadata.pay42_wallet === true,
          ) || null
        );
      },
      async updateAccountBalance(accountId, patch = {}) {
        const b = await mt5Backend();
        if (b.updateAccountV2) return b.updateAccountV2(accountId, patch);
        const existing = await findUnifiedUserAccountById(accountId);
        if (!existing) return { ok: false, error: "account not found" };
        const next = await upsertWalletAccountFallback({
          ...(existing || {}),
          account_id: accountId,
          user_id: existing.user_id,
          balance: patch.balance,
          metadata:
            patch.metadata && typeof patch.metadata === "object"
              ? patch.metadata
              : existing.metadata || {},
          status: patch.status || existing.status || "ACTIVE",
        });
        return { ok: true, item: next || existing };
      },
    },
  });
  return PAY42_SERVICE;
}

