function normalizeHostHeader(hostRaw) {
  return String(hostRaw || "")
    .split(",")[0]
    .trim()
    .toLowerCase()
    .replace(/:\d+$/, "");
}

async function readJson(req) {
  const chunks = [];
  for await (const chunk of req) {
    chunks.push(chunk);
  }
  const raw = Buffer.concat(chunks).toString("utf8").trim();
  if (!raw) {
    return {};
  }
  return JSON.parse(raw);
}

function normalizeSide(sideRaw) {
  const s = String(sideRaw || "").toUpperCase();
  if (s === "BUY" || s === "LONG") return "BUY";
  if (s === "SELL" || s === "SHORT") return "SELL";
  throw new Error("Invalid side");
}

const ENTRY_MODEL_NORMALIZE_RULES = [
  { label: "ICT Turtle Soup", patterns: ["turtle soup", "turtlesoup"] },
  { label: "ICT", patterns: ["ict"] },
  { label: "SMC", patterns: ["smc", "smart money"] },
  { label: "Fibo", patterns: ["fibo", "fibonacci"] },
  { label: "Retracement", patterns: ["retracement", "pullback"] },
  { label: "Order Block", patterns: ["order block", "ob retest", "ob"] },
  { label: "FVG", patterns: ["fvg", "fair value gap"] },
  { label: "Breaker", patterns: ["breaker"] },
  { label: "Mitigation", patterns: ["mitigation"] },
  { label: "Price Action", patterns: ["price action"] },
];

function mt5CollapseWhitespace(value) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .trim();
}

function mt5EntryModelLooksVerbose(value) {
  const raw = mt5CollapseWhitespace(value);
  if (!raw) return false;
  if (raw.length > 42) return true;
  if ((raw.match(/\s+/g) || []).length >= 5) return true;
  return /[.,;:!?]/.test(raw);
}

function mt5NormalizeEntryModel(value, opts = {}) {
  const raw = mt5CollapseWhitespace(value);
  const fallbackRaw = mt5CollapseWhitespace(opts.fallback || "MANUAL");
  const normalizedFallback = fallbackRaw ? fallbackRaw.slice(0, 32) : "MANUAL";
  const source = raw || fallbackRaw;
  if (!source) return "MANUAL";
  const lower = source.toLowerCase();
  for (const rule of ENTRY_MODEL_NORMALIZE_RULES) {
    if (rule.patterns.some((p) => lower.includes(p))) return rule.label;
  }
  if (!mt5EntryModelLooksVerbose(source) && /^[a-z0-9 _/+-]+$/i.test(source)) {
    return source.slice(0, 32);
  }
  return normalizedFallback || "MANUAL";
}

function mt5MergeNote(base, addition) {
  const baseText = mt5CollapseWhitespace(base);
  const extraText = mt5CollapseWhitespace(addition);
  if (!extraText) return baseText;
  if (!baseText) return extraText;
  if (baseText.toLowerCase().includes(extraText.toLowerCase())) return baseText;
  return `${extraText} | ${baseText}`;
}

function mt5DeriveEntryModelAndNote(payload = {}, opts = {}) {
  const rawEntryModel = mt5CollapseWhitespace(
    payload.entry_model ??
      payload.entryModel ??
      payload.model ??
      payload.strategy ??
      opts.fallbackModel ??
      "",
  );
  const entryModel = mt5NormalizeEntryModel(rawEntryModel, {
    fallback: opts.fallbackModel || payload.source || "MANUAL",
  });
  const baseNote = mt5BuildNote(payload);
  const note = mt5EntryModelLooksVerbose(rawEntryModel)
    ? mt5MergeNote(baseNote, rawEntryModel)
    : baseNote;
  return { entryModel, note, entryModelRaw: rawEntryModel || null };
}

function mt5LooksLikeBrokerStrategyLabel(value = "", sid = "", comment = "") {
  const text = nullLikeEmpty(value);
  if (!text) return false;
  const sidText = String(sid || "").trim();
  const commentText = String(comment || "").trim();
  if (sidText && text === sidText) return false;
  if (commentText && text === commentText) return false;
  if (/^\d+$/.test(text)) return false;
  if (/^SID:/i.test(text)) return false;
  return true;
}

function mt5ExtractBrokerCommentSid(value = "") {
  const text = String(value || "").trim();
  if (!text) return "";
  return text.split("|")[0].trim();
}

function normalizeSignal(payload) {
  const strategy = String(
    payload.strategy || payload.source || payload.system || "UnknownStrategy",
  );
  const symbol = String(payload.symbol || payload.ticker || "").toUpperCase();
  const side = normalizeSide(payload.side || payload.action);
  const tradeIdRaw = envStr(
    payload.sid ?? payload.id ?? payload.trade_id ?? payload.tradeId,
  );
  const tradeId = normalizePublicSidBase(tradeIdRaw, "TRD");
  const timeframe = String(payload.timeframe || payload.tf || "n/a");
  const orderTypeRaw = envStr(payload.order_type ?? payload.orderType);
  const orderType = orderTypeRaw ? mt5NormalizeOrderType(payload) : "limit";
  const chartTf = envStr(
    payload.chart_tf ?? payload.chartTf ?? payload.timeframe ?? payload.tf,
  );
  const signalTf = envStr(
    payload.trade_tf ?? payload.tradeTf ?? payload.signal_tf ?? payload.signalTf,
  );
  const price = asNum(payload.price ?? payload.entry, NaN);
  const sl = asNum(payload.stop_loss ?? payload.sl, NaN);
  const tp = asNum(payload.take_profit ?? payload.tp, NaN);
  const derived = mt5DeriveEntryModelAndNote(payload, {
    fallbackModel: strategy || "UnknownStrategy",
  });
  const note = derived.note || String(payload.note || payload.comment || "");
  const signalTime =
    payload.time || payload.timestamp || new Date().toISOString();
  const quantity = asNum(payload.quantity ?? payload.qty, NaN);
  const userId = envStr(
    payload.user_id ?? payload.userId ?? payload.user ?? CFG.mt5DefaultUserId,
    CFG.mt5DefaultUserId,
  );
  const rrPlanned = asNum(payload.rr ?? payload.risk_reward, NaN);
  const riskMoneyPlanned = asNum(
    payload.risk_money ?? payload.money_risk ?? payload.riskMoney,
    NaN,
  );

  if (!symbol) throw new Error("Missing symbol");
  if (!Number.isFinite(price) || price <= 0) throw new Error("Invalid price");

  return {
    strategy,
    symbol,
    side,
    sid: tradeId || "-",
    timeframe,
    price,
    sl: Number.isFinite(sl) ? sl : null,
    tp: Number.isFinite(tp) ? tp : null,
    note,
    signalTime,
    quantity: Number.isFinite(quantity) && quantity > 0 ? quantity : null,
    order_type: orderType,
    chart_tf: chartTf || null,
    trade_tf: signalTf || null,
    user_id: userId,
    entry_model: derived.entryModel || null,
    rr_planned: Number.isFinite(rrPlanned) ? rrPlanned : null,
    risk_money_planned: Number.isFinite(riskMoneyPlanned)
      ? riskMoneyPlanned
      : null,
    risk_pct_planned: asNum(payload.risk_pct ?? payload.riskPct ?? 1.0, 1.0),
    rejection_reason: null,
    raw: payload,
  };
}

function formatSignal(signal) {
  return [
    `${signal.symbol} | ${signal.side} | ${signal.sid || "-"} | ${signal.timeframe || "n/a"}`,
    `Entry:${signal.price} SL:${signal.sl ?? "n/a"} TP:${signal.tp ?? "n/a"} | ${signal.strategy || "-"} | ${signal.note || "-"}`,
  ]
    .filter(Boolean)
    .join("\n");
}

async function sendTelegram(text) {
  if (!CFG.telegramBotToken || !CFG.telegramChatId) {
    return {
      ok: false,
      skipped: true,
      reason: "Missing TELEGRAM_BOT_TOKEN or TELEGRAM_CHAT_ID",
    };
  }
  const endpoint = `https://api.telegram.org/bot${CFG.telegramBotToken}/sendMessage`;
  const response = await fetch(endpoint, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      chat_id: CFG.telegramChatId,
      text,
      disable_web_page_preview: true,
    }),
  });

  const data = await response.json();
  if (!response.ok || !data.ok) {
    throw new Error(`Telegram API error: ${JSON.stringify(data)}`);
  }
  return data;
}

function binanceBaseUrl() {
  if (CFG.binanceProduct === "um_futures") {
    return CFG.binanceMode === "live"
      ? "https://fapi.binance.com"
      : "https://testnet.binancefuture.com";
  }
  return CFG.binanceMode === "live"
    ? "https://api.binance.com"
    : "https://testnet.binance.vision";
}

function signQuery(query, secret) {
  return crypto.createHmac("sha256", secret).update(query).digest("hex");
}

async function binanceSignedRequest(method, route, params) {
  const timestamp = Date.now();
  const allParams = {
    ...params,
    recvWindow: CFG.binanceRecvWindow,
    timestamp,
  };
  const query = new URLSearchParams(allParams).toString();
  const signature = signQuery(query, CFG.binanceApiSecret);
  const url = `${binanceBaseUrl()}${route}?${query}&signature=${signature}`;

  const res = await fetch(url, {
    method,
    headers: { "X-MBX-APIKEY": CFG.binanceApiKey },
  });

  const text = await res.text();
  let body;
  try {
    body = JSON.parse(text);
  } catch {
    body = { raw: text };
  }

  if (!res.ok) {
    throw new Error(
      `Binance ${route} failed ${res.status}: ${JSON.stringify(body)}`,
    );
  }
  return body;
}

function resolveBinanceSizing(signal) {
  if (signal.quantity && signal.quantity > 0) {
    return { quantity: String(signal.quantity) };
  }
  if (Number.isFinite(CFG.binanceDefaultQty) && CFG.binanceDefaultQty > 0) {
    return { quantity: String(CFG.binanceDefaultQty) };
  }
  if (
    CFG.binanceProduct === "spot" &&
    signal.side === "BUY" &&
    Number.isFinite(CFG.binanceDefaultQuoteQty) &&
    CFG.binanceDefaultQuoteQty > 0
  ) {
    return { quoteOrderQty: String(CFG.binanceDefaultQuoteQty) };
  }
  throw new Error(
    "No valid quantity. Provide signal.quantity or BINANCE_DEFAULT_QTY (or BINANCE_DEFAULT_QUOTE_QTY for spot BUY)",
  );
}

function buildExecSummary(execResults) {
  return execResults
    .map((r) => {
      const broker = r.broker || "broker";
      const status = r.status || "unknown";
      const detail = r.reason
        ? `(${r.reason})`
        : r.orderId
          ? `(#${r.orderId})`
          : "";
      return `${broker}:${status}${detail ? " " + detail : ""}`;
    })
    .join(" | ");
}

async function handleSignal(payload) {
  const signal = normalizeSignal(payload);

  // Store as signal in DB, no auto-execution
  const text = formatSignal(signal);
  const telegram = await sendTelegram(text);

  return {
    ok: true,
    signal,
    telegram,
  };
}

// ==================== MT5 bridge (merged routes) ====================
function mt5NowIso() {
  return new Date().toISOString();
}

async function healthCronConfigDiagnostics() {
  const empty = {
    market_data_active: 0,
    analysis_active: 0,
    strategy_scan_active: 0,
    snapshots_active: 0,
    db_error: null,
  };
  try {
    const rows = await settingsStore.listUserSettingsByType(null, "cron");
    let md = 0,
      ai = 0,
      strategy = 0,
      snap = 0;
    for (const r of rows) {
      const d = typeof r.data === "string" ? JSON.parse(r.data) : r.data || {};
      const ct = d.cron_type || "";
      if (String(r.status || "").toUpperCase() !== "ACTIVE") continue;
      if (ct === "MARKET_DATA_CRON") md++;
      else if (ct === "ANALYSIS_CRON") ai++;
      else if (ct === "STRATEGY_SCAN_CRON") strategy++;
      else if (ct === "SNAPSHOTS_CRON" || ct === "SNAPSHOT_CRON") snap++;
    }
    return {
      market_data_active: md,
      analysis_active: ai,
      strategy_scan_active: strategy,
      snapshots_active: snap,
      db_error: null,
    };
  } catch (err) {
    return {
      ...empty,
      db_error: err instanceof Error ? err.message : String(err || "error"),
    };
  }
}

async function healthCronStatusesByName() {
  try {
    const rows = await settingsStore.listUserSettingsByType(null, "cron");
    const out = {};
    for (const r of rows || []) {
      const name = String(r?.name || "").trim();
      if (!name) continue;
      const d = typeof r.data === "string" ? JSON.parse(r.data) : r.data || {};
      out[name] = {
        status: String(r?.status || "").toUpperCase() || "UNKNOWN",
        cron_type: String(d?.cron_type || ""),
      };
    }
    return out;
  } catch {
    return {};
  }
}

function mt5ParsePriceOrNull(v) {
  if (v == null) return null;
  if (v && typeof v === "object" && !Array.isArray(v)) {
    return mt5ParsePriceOrNull(v.price ?? v.value ?? v.level);
  }
  const raw = String(v).trim();
  if (!raw) return null;
  const normalized =
    raw.includes(",") && raw.includes(".")
      ? raw.replace(/,/g, "")
      : raw.includes(",")
        ? raw.replace(",", ".")
        : raw;
  const n = Number(normalized);
  return Number.isFinite(n) && n > 0 ? n : null;
}

function mt5ResolvePlannedPnlValue(rawValue, fallbackValue) {
  const direct = Number(rawValue);
  if (Number.isFinite(direct) && Math.abs(direct) > 0.000001) return direct;
  if (rawValue === 0 || rawValue === "0" || rawValue === "0.0") return 0;
  const fallback = Number(fallbackValue);
  return Number.isFinite(fallback) ? Number(fallback.toFixed(2)) : 0;
}

function mt5ResolveStoredPlannedPnlValue(rawValue, fallbackValue) {
  const direct = Number(rawValue);
  if (Number.isFinite(direct) && Math.abs(direct) > 0.000001) return direct;
  const fallback = Number(fallbackValue);
  if (Number.isFinite(fallback)) return Number(fallback.toFixed(2));
  return Number.isFinite(direct) ? direct : 0;
}

function mt5ExtractBrokerPlannedPnlOverride(rawValue) {
  const direct = Number(rawValue);
  if (!Number.isFinite(direct) || Math.abs(direct) <= 0.000001) return null;
  return Number(direct.toFixed(2));
}

function mt5ComputePlannedPnlFromMetrics(item = {}, symbolMetric = null) {
  const entry = mt5ParsePriceOrNull(
    item.entry ?? item.entry_price ?? item.target_price ?? item.price,
  );
  const side = String(item.action ?? item.side ?? "")
    .trim()
    .toUpperCase();
  const volume = Number(item.volume);
  const pipSize = Number(symbolMetric?.pip_size);
  const pipValue = Number(symbolMetric?.pip_value);
  if (
    entry == null ||
    !["BUY", "SELL"].includes(side) ||
    !Number.isFinite(volume) ||
    volume <= 0 ||
    !Number.isFinite(pipSize) ||
    pipSize <= 0 ||
    !Number.isFinite(pipValue) ||
    pipValue <= 0
  ) {
    return { tpPnl: NaN, slPnl: NaN };
  }
  const signedPnlForTarget = (targetRaw) => {
    const target = mt5ParsePriceOrNull(targetRaw);
    if (target == null) return NaN;
    let pips = (target - entry) / pipSize;
    if (side === "SELL") pips = -pips;
    return pips * pipValue * volume;
  };
  return {
    tpPnl: signedPnlForTarget(item.tp ?? item.take_profit ?? item.tp1),
    slPnl: signedPnlForTarget(item.sl ?? item.stop_loss),
  };
}

function mt5ParseAccountMetadata(rawMeta) {
  if (rawMeta && typeof rawMeta === "object") return rawMeta;
  if (typeof rawMeta !== "string" || !rawMeta.trim()) return {};
  try {
    const parsed = JSON.parse(rawMeta);
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch {
    return {};
  }
}

function mt5FindSymbolMetric(accountMeta = {}, symbol = "") {
  const want = String(symbol || "")
    .trim()
    .toUpperCase();
  if (!want) return null;
  const metrics = Array.isArray(accountMeta?.symbol_metrics)
    ? accountMeta.symbol_metrics
    : [];
  return (
    metrics.find(
      (metric) =>
        String(metric?.symbol || "")
          .trim()
          .toUpperCase() === want,
    ) || null
  );
}

function mt5NormalizeTpTargets(input = [], sideRaw = "") {
  const side = String(sideRaw || "").toUpperCase();
  const isSell = side === "SELL";
  const vals = [];
  for (const raw of Array.isArray(input) ? input : []) {
    const n = mt5ParsePriceOrNull(raw);
    if (n != null) vals.push(n);
  }
  const uniq = Array.from(new Set(vals.map((x) => Number(x.toFixed(8)))));
  uniq.sort((a, b) => (isSell ? b - a : a - b));
  return uniq.slice(0, 3);
}

function mt5NormalizeTpFields(payload = {}, sideRaw = "") {
  const cands = [
    payload.tp1,
    payload.tp2,
    payload.tp3,
    payload.tp,
    payload.take_profit,
  ];
  if (Array.isArray(payload.tp_targets)) cands.push(...payload.tp_targets);
  const targets = mt5NormalizeTpTargets(cands, sideRaw);
  return {
    tp1: targets[0] ?? null,
    tp2: targets[1] ?? null,
    tp3: targets[2] ?? null,
    tp: targets[0] ?? null,
    tp_targets: targets,
  };
}

function mt5ValidateTradeLevels({
  side = "",
  entry = NaN,
  sl = NaN,
  tp1 = NaN,
  tp2 = NaN,
  tp3 = NaN,
} = {}) {
  const normalizedSide = String(side || "")
    .trim()
    .toUpperCase();
  if (!["BUY", "SELL"].includes(normalizedSide)) {
    return "Direction must be BUY or SELL.";
  }
  const parseOptionalLevel = (value) => {
    if (value == null) return null;
    if (typeof value === "string" && !value.trim()) return null;
    return mt5ParsePriceOrNull(value);
  };
  const entryNum = mt5ParsePriceOrNull(entry);
  const slNum = mt5ParsePriceOrNull(sl);
  const tp1Num = parseOptionalLevel(tp1);
  const tp2Num = parseOptionalLevel(tp2);
  const tp3Num = parseOptionalLevel(tp3);
  if (
    !Number.isFinite(entryNum) ||
    !Number.isFinite(slNum) ||
    !Number.isFinite(tp1Num)
  ) {
    return `Entry/SL/TP1 must be numeric values. Parsed: entry=${entryNum ?? "NaN"}, sl=${slNum ?? "NaN"}, tp1=${tp1Num ?? "NaN"}.`;
  }
  const debugSuffix = () =>
    ` Parsed: side=${normalizedSide || "n/a"}, entry=${Number.isFinite(entryNum) ? entryNum : "NaN"}, sl=${Number.isFinite(slNum) ? slNum : "NaN"}, tp1=${tp1Num ?? "null"}, tp2=${tp2Num ?? "null"}, tp3=${tp3Num ?? "null"}.`;
  const targets = [tp1Num];
  if (tp2Num != null) targets.push(tp2Num);
  if (tp2Num != null && tp3Num != null) targets.push(tp3Num);
  if (normalizedSide === "BUY") {
    if (!(slNum < entryNum))
      return `For BUY, SL must be lower than Entry.${debugSuffix()}`;
    if (targets.some((value) => !(value > entryNum))) {
      return `For BUY, all TP levels must be greater than Entry.${debugSuffix()}`;
    }
    for (let index = 1; index < targets.length; index += 1) {
      if (!(targets[index] > targets[index - 1])) {
        return `For BUY, TP${index + 1} must be greater than TP${index}.${debugSuffix()}`;
      }
    }
    return "";
  }
  if (!(slNum > entryNum))
    return `For SELL, SL must be greater than Entry.${debugSuffix()}`;
  if (targets.some((value) => !(value < entryNum))) {
    return `For SELL, all TP levels must be lower than Entry.${debugSuffix()}`;
  }
  for (let index = 1; index < targets.length; index += 1) {
    if (!(targets[index] < targets[index - 1])) {
      return `For SELL, TP${index + 1} must be lower than TP${index}.${debugSuffix()}`;
    }
  }
  return "";
}

function mt5ParseNumericId(value) {
  const n = Number(value);
  return Number.isInteger(n) && n > 0 ? n : null;
}

function mt5RenewSignalIdBase(oldId = "") {
  const cleaned = String(oldId || "")
    .trim()
    .replace(/[^a-zA-Z0-9]/g, "")
    .toUpperCase();
  if (cleaned.length === 9) return cleaned;
  return mt5GenerateTimeSid();
}

function mt5RenewSignalIdFromExisting(baseId, existingIds) {
  const base = mt5RenewSignalIdBase(baseId);
  let max = 0;
  const ids = Array.isArray(existingIds) ? existingIds : [];
  for (const idRaw of ids) {
    const id = String(idRaw || "");
    if (id === base) {
      max = Math.max(max, 0);
      continue;
    }
    const match = id.match(
      new RegExp(`^${base.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\.(\\d+)$`),
    );
    if (!match) continue;
    const n = Number(match[1]);
    if (Number.isFinite(n) && n > max) max = n;
  }
  return `${base}.${max + 1}`;
}

let MT5_BACKEND = null;
let USER_ACCOUNT_OBJECT_STORE = null;
const LEGACY_USER_ACCOUNT_MIGRATIONS = new Set();
const LEGACY_USER_ACCOUNT_FILE_MIGRATIONS = new Set();
const LEGACY_USER_TEMPLATE_MIGRATIONS = new Set();
const LEGACY_USER_SETTINGS_TABLE_MIGRATIONS = new Set();

function getUserAccountObjectStore() {
  if (!USER_ACCOUNT_OBJECT_STORE) {
    USER_ACCOUNT_OBJECT_STORE = createUserObjectStore({
      redisEnabled: CFG.redisEnabled,
      getRedisClient,
      logger: console,
    });
  }
  return USER_ACCOUNT_OBJECT_STORE;
}

const BROKER_SYMBOL_METADATA_OBJECT_TYPE = "broker_symbol_metadata";
const CTRADER_DOWNSTREAM_URL = String(
  process.env.CTRADER_DOWNSTREAM_URL ||
    (process.env.CTRADER_EXECUTOR_URL || "").replace(/\/execute\/?$/, ""),
).trim();
const CTRADER_DOWNSTREAM_API_KEY = String(
  process.env.CTRADER_DOWNSTREAM_API_KEY ||
    process.env.CTRADER_EXECUTOR_API_KEY ||
    "",
).trim();
const CTRADER_DOWNSTREAM_ACCOUNT_ID = String(
  process.env.CTRADER_ACCOUNT_ID || "",
).trim();
const CTRADER_DEFAULT_MIN_STOP_PIPS = asNum(
  process.env.CTRADER_MIN_STOP_PIPS ||
    process.env.BROKER_MIN_STOP_PIPS ||
    process.env.MIN_STOP_PIPS,
  null,
);

function normalizeBrokerSymbolMetadataId({
  provider = "",
  accountId = "",
  symbol = "",
} = {}) {
  const providerKey = String(provider || "broker").trim().toLowerCase() || "broker";
  const accountKey = String(accountId || "default").trim() || "default";
  const symbolKey = String(symbol || "").trim().toUpperCase();
  if (!symbolKey) return "";
  return safeObjectPathPart(`${providerKey}__${accountKey}__${symbolKey}`);
}

function normalizeBrokerSymbolMetadata(input = {}, fallback = {}) {
  const symbol = String(input.symbol || fallback.symbol || "").trim().toUpperCase();
  if (!symbol) return null;
  const provider = String(
    input.provider ||
      input.provider_code ||
      fallback.provider ||
      fallback.provider_code ||
      "broker",
  )
    .trim()
    .toLowerCase();
  const accountId = String(input.account_id || fallback.account_id || "").trim();
  const pipSize = asNum(input.pip_size ?? input.pipSize, null);
  const minStopPips = asNum(input.min_stop_pips ?? input.minStopPips, null);
  const bid = asNum(input.bid ?? input.b, null);
  const ask = asNum(input.ask ?? input.a, null);
  const lastPrice = asNum(
    input.last_price ??
      input.lastPrice ??
      input.mid ??
      (bid != null && ask != null ? (bid + ask) / 2 : null),
    null,
  );
  return {
    provider,
    account_id: accountId || null,
    symbol,
    broker_symbol: String(input.broker_symbol || input.symbol_name || input.symbol || symbol)
      .trim()
      .toUpperCase(),
    digits: asNum(input.digits, null),
    pip_position: asNum(input.pip_position ?? input.pipPosition, null),
    pip_size: pipSize,
    tick_size: asNum(input.tick_size ?? input.tickSize, null),
    pip_value: asNum(input.pip_value ?? input.pipValue, null),
    min_volume_units: asNum(input.min_volume_units ?? input.min_vol ?? input.minVolume, null),
    step_volume_units: asNum(input.step_volume_units ?? input.step_vol ?? input.volumeStep, null),
    min_stop_pips: minStopPips,
    min_stop_price_distance: asNum(
      input.min_stop_price_distance ??
        input.minStopPriceDistance ??
        (pipSize != null && minStopPips != null ? pipSize * minStopPips : null),
      null,
    ),
    spread_pips: asNum(input.spread_pips ?? input.spread, null),
    bid,
    ask,
    last_price: lastPrice,
    last_price_at: input.last_price_at || input.price_at || null,
    calibrated_at: input.calibrated_at || null,
    source: String(input.source || fallback.source || "broker_sync").trim(),
  };
}

function brokerSymbolMetadataPublic(row = null) {
  if (!row) return null;
  const metadata = row.metadata && typeof row.metadata === "object" ? row.metadata : {};
  return {
    ...metadata,
    object_id: row.object_id || metadata.object_id || "",
    updated_at: row.updated_at || metadata.updated_at || null,
    created_at: row.created_at || metadata.created_at || null,
  };
}

function brokerSymbolMetadataKey(item = {}) {
  return `${String(item.provider || "broker").toLowerCase()}:${String(
    item.account_id || "default",
  )}:${String(item.symbol || "").toUpperCase()}`;
}

function applyBrokerSymbolMetadataRuntimePrice(item = null) {
  if (!item?.symbol) return item;
  const symbol = String(item.symbol || "").trim().toUpperCase();
  const price = brokerPriceCache[symbol];
  if (!price) return item;
  const bid = asNum(price.bid, null);
  const ask = asNum(price.ask, null);
  const lastPrice = bid != null && ask != null ? (bid + ask) / 2 : asNum(item.last_price, null);
  const ts = Number(price.ts);
  return {
    ...item,
    bid: bid ?? item.bid ?? null,
    ask: ask ?? item.ask ?? null,
    last_price: lastPrice ?? item.last_price ?? null,
    last_price_at:
      Number.isFinite(ts) && ts > 0
        ? new Date(ts).toISOString()
        : item.last_price_at || null,
  };
}

function brokerSymbolMetadataMatchesFilters(item = {}, filters = {}) {
  const symbolFilter = String(filters.symbol || "").trim().toUpperCase();
  const accountFilter = String(filters.account_id || filters.accountId || "").trim();
  const providerFilter = String(filters.provider || "").trim().toLowerCase();
  return (
    (!symbolFilter || String(item.symbol || "").toUpperCase() === symbolFilter) &&
    (!accountFilter || String(item.account_id || "") === accountFilter) &&
    (!providerFilter || String(item.provider || "").toLowerCase() === providerFilter)
  );
}

async function listBrokerSymbolMetadataFromAccounts(userId) {
  const uid = String(userId || CFG.mt5DefaultUserId).trim() || CFG.mt5DefaultUserId;
  const accounts = await getUserAccountObjectStore()
    .listUnifiedObjects(uid, "user_accounts")
    .catch(() => []);
  const items = [];
  for (const account of accounts || []) {
    if (String(account?.status || "").toUpperCase() === "ARCHIVED") continue;
    const accountMeta = mt5ParseAccountMetadata(account?.metadata);
    const metrics = Array.isArray(accountMeta?.symbol_metrics)
      ? accountMeta.symbol_metrics
      : Array.isArray(account?.symbol_metrics)
        ? account.symbol_metrics
        : [];
    if (!metrics.length) continue;
    const provider =
      account?.provider_code ||
      accountMeta?.provider_code ||
      resolveProviderCode(account?.broker_name || accountMeta?.broker_name) ||
      "broker";
    const accountId = String(account?.account_id || account?.object_id || "").trim();
    for (const metric of metrics) {
      const normalized = normalizeBrokerSymbolMetadata(metric, {
        provider,
        account_id: accountId,
        source: "account_symbol_metrics",
      });
      if (!normalized) continue;
      const objectId = normalizeBrokerSymbolMetadataId({
        provider: normalized.provider,
        accountId: normalized.account_id || "default",
        symbol: normalized.symbol,
      });
      items.push({
        ...normalized,
        object_id: objectId,
        updated_at:
          metric?.updated_at ||
          metric?.calibrated_at ||
          account?.updated_at ||
          accountMeta?.updated_at ||
          null,
        created_at: account?.created_at || null,
      });
    }
  }
  return items;
}

async function upsertBrokerSymbolMetadata(userId, input = {}, fallback = {}) {
  const metadata = normalizeBrokerSymbolMetadata(input, fallback);
  if (!metadata) return null;
  const uid = String(userId || CFG.mt5DefaultUserId).trim() || CFG.mt5DefaultUserId;
  const objectId = normalizeBrokerSymbolMetadataId({
    provider: metadata.provider,
    accountId: metadata.account_id || fallback.account_id || "default",
    symbol: metadata.symbol,
  });
  if (!objectId) return null;
  const store = getUserAccountObjectStore();
  const existing = await store
    .getDynamicObject(uid, BROKER_SYMBOL_METADATA_OBJECT_TYPE, objectId)
    .catch(() => null);
  const existingMeta =
    existing?.metadata && typeof existing.metadata === "object" ? existing.metadata : {};
  const now = new Date().toISOString();
  const next = {
    ...existingMeta,
    ...Object.fromEntries(
      Object.entries(metadata).filter(([, value]) => value !== undefined && value !== null && value !== ""),
    ),
    object_id: objectId,
    updated_at: now,
  };
  if (metadata.pip_size && metadata.min_stop_pips) {
    next.min_stop_price_distance = metadata.pip_size * metadata.min_stop_pips;
  }
  if (metadata.pip_size && metadata.last_price) {
    next.last_price_pips_unit = metadata.pip_size;
  }
  return store.upsertDynamicObject(
    uid,
    BROKER_SYMBOL_METADATA_OBJECT_TYPE,
    objectId,
    next,
    "ACTIVE",
    {
      created_at: existing?.created_at || now,
      updated_at: now,
    },
  );
}

async function listBrokerSymbolMetadata(userId, filters = {}) {
  const uid = String(userId || CFG.mt5DefaultUserId).trim() || CFG.mt5DefaultUserId;
  const rows = await getUserAccountObjectStore().listDynamicObjects(
    uid,
    BROKER_SYMBOL_METADATA_OBJECT_TYPE,
  );
  const persistedItems = rows
    .map(brokerSymbolMetadataPublic)
    .filter(Boolean)
    .map(applyBrokerSymbolMetadataRuntimePrice);
  const accountItems = (await listBrokerSymbolMetadataFromAccounts(uid)).map(
    applyBrokerSymbolMetadataRuntimePrice,
  );
  const byKey = new Map();
  for (const item of accountItems) {
    if (!item?.symbol) continue;
    byKey.set(brokerSymbolMetadataKey(item), item);
  }
  for (const item of persistedItems) {
    if (!item?.symbol) continue;
    const key = brokerSymbolMetadataKey(item);
    byKey.set(key, { ...(byKey.get(key) || {}), ...item });
  }
  return Array.from(byKey.values())
    .filter((item) => brokerSymbolMetadataMatchesFilters(item, filters))
    .sort((a, b) =>
      `${a.provider || ""}:${a.account_id || ""}:${a.symbol || ""}`.localeCompare(
        `${b.provider || ""}:${b.account_id || ""}:${b.symbol || ""}`,
      ),
    );
}

async function fetchBrokerSymbolCalibration(symbol, options = {}) {
  const safeSymbol = String(symbol || "").trim().toUpperCase();
  if (!safeSymbol || !CTRADER_DOWNSTREAM_URL || !CTRADER_DOWNSTREAM_ACCOUNT_ID) {
    return null;
  }
  const accountId = String(options.account_id || CTRADER_DOWNSTREAM_ACCOUNT_ID).trim();
  if (!accountId) return null;
  const response = await fetch(
    `${CTRADER_DOWNSTREAM_URL.replace(/\/+$/, "")}/symbol-calibration`,
    {
      method: "POST",
      headers: {
        "content-type": "application/json",
        ...(CTRADER_DOWNSTREAM_API_KEY
          ? { "x-api-key": CTRADER_DOWNSTREAM_API_KEY }
          : {}),
      },
      body: JSON.stringify({
        account_id: accountId,
        symbol: safeSymbol,
      }),
      signal: AbortSignal.timeout(5000),
    },
  );
  if (!response.ok) return null;
  const body = await response.json().catch(() => null);
  return body?.ok && body?.calibration ? body.calibration : null;
}

