  GER30: "DAX",
  DAX: "DAX",
  DAX40: "GER40",
  HK33: "HSI",
  HSI: "HSI",
  HKG33: "HSI",
  HK50: "HSI",
  JPN225: "NI225",
  JP225: "NI225",
