function normalizeSymbolForTwelve(rawSymbol) {
  const base = String(rawSymbol || "")
    .trim()
    .toUpperCase();
  if (!base) return "";
  const noProvider = base.includes(":")
    ? base.split(":").slice(1).join(":")
    : base;
  const compact = noProvider.replace(/[^A-Z0-9]/g, "");
  if (!compact) return "";

  if (TWELVE_SYMBOL_MAP[compact]) return TWELVE_SYMBOL_MAP[compact];

  if (compact.endsWith("USDT") && compact.length > 4) {
    const left = compact.slice(0, -4);
    return `${left}/USD`;
  }
  if (/^[A-Z]{6}$/.test(compact)) {
    return `${compact.slice(0, 3)}/${compact.slice(3)}`;
  }
  if (/^[A-Z]{3,5}USD$/.test(compact)) {
    return `${compact.slice(0, -3)}/USD`;
  }
  return compact;
}

async function resolveTwelveSymbol(rawSymbol, apiKey = "") {
  const base = String(rawSymbol || "")
    .trim()
    .toUpperCase();
  if (!base) return [];
  const noProvider = base.includes(":")
    ? base.split(":").slice(1).join(":").trim().toUpperCase()
    : base;
  const normalized = normalizeSymbolForTwelve(noProvider);
  const compact = noProvider.replace(/[^A-Z0-9]/g, "");
  const candidates = [];
  const add = (v) => {
    const s = String(v || "")
      .trim()
      .toUpperCase();
    if (!s) return;
    if (!candidates.includes(s)) candidates.push(s);
  };
  add(normalized);
  add(compact);
  if (/^[A-Z]{6}$/.test(compact))
    add(`${compact.slice(0, 3)}/${compact.slice(3)}`);
  if (/^[A-Z]{3,5}USD$/.test(compact)) add(`${compact.slice(0, -3)}/USD`);

  // Try Twelve symbol search to pick a provider-accepted symbol variant.
  try {
    const searchUrl = `https://api.twelvedata.com/symbol_search?symbol=${encodeURIComponent(noProvider)}${apiKey ? `&apikey=${encodeURIComponent(apiKey)}` : ""}`;
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 8000);
    const res = await fetch(searchUrl, { signal: ctrl.signal });
    clearTimeout(timer);
    const out = await res.json().catch(() => ({}));
    const arr = Array.isArray(out?.data) ? out.data : [];
    for (const row of arr) {
      add(row?.symbol);
      if (row?.symbol && row?.exchange) {
        add(`${row.symbol}:${row.exchange}`);
      }
    }
  } catch {
    // ignore and fallback to static candidates
  }

  return candidates;
}

function timeframeToTwelve(tfRaw) {
  const s = String(tfRaw || "")
    .trim()
    .toLowerCase();
  if (!s || s === "manual") return "15min";
  if (s === "d") return "1day";
  if (s === "w") return "1week";
  if (s === "mn" || s === "mo" || s === "month") return "1month";
  if (/^\d+$/.test(s)) {
    const n = Number(s);
    if (!Number.isFinite(n) || n <= 0) return "15min";
    if (n < 60) return `${n}min`;
    if (n % 60 === 0 && n < 1440) return `${n / 60}h`;
    if (n === 1440) return "1day";
    if (n === 10080) return "1week";
    if (n === 43200) return "1month";
    return `${Math.max(1, Math.round(n / 60))}h`;
  }
  const m = s.match(/^(\d+)(m|min|h|d|w)$/);
  if (m) {
    const n = Math.max(1, Number(m[1] || 1));
    const unit = m[2];
    if (unit === "m" || unit === "min") return `${n}min`;
    if (unit === "h") return `${n}h`;
    if (unit === "d") return `${n}day`;
    if (unit === "w") return `${n}week`;
  }
  return s;
}

function parseSnapshotPdArrays(payload = {}) {
  const fromTradePlan = payload?.market_analysis?.pd_arrays;
  const direct = payload?.pd_arrays || payload?.pdArrays;
  const arr = Array.isArray(fromTradePlan)
    ? fromTradePlan
    : Array.isArray(direct)
      ? direct
      : [];
  return arr
    .map((x) => (x && typeof x === "object" ? x : null))
    .filter(Boolean)
    .map((x) => ({
      id: Number.isFinite(Number(x.id)) ? Number(x.id) : null,
      type: String(x.type || "").trim(),
      direction: String(x.direction || "").trim(),
      strength: String(x.strength || "").trim(),
      timeframe: String(x.timeframe || x.tf || "").trim(),
      zone: x.zone,
      low: x.low ?? x.bottom ?? x.price_bottom ?? null,
      high: x.high ?? x.top ?? x.price_top ?? null,
      bar_start: Number.isFinite(Number(x.bar_start_unix ?? x.bar_start))
        ? Number(x.bar_start_unix ?? x.bar_start)
        : null,
      status: String(x.status || "").trim(),
      touched: Number.isFinite(Number(x.touched)) ? Number(x.touched) : null,
      mitigation_type: String(x.mitigation_type || "").trim(),
      note: String(x.note || "").trim(),
    }));
}

function parseSnapshotKeyLevels(payload = {}) {
  const out = [];
  const pushLevel = (item) => {
    if (!item) return;
    if (typeof item === "number") {
      if (Number.isFinite(item))
        out.push({ name: "Key Level", price: item, kind: "generic" });
      return;
    }
    if (typeof item === "string") {
      const nums = item.match(/-?\d+(?:\.\d+)?/g);
      if (nums && nums[0] && Number.isFinite(Number(nums[0]))) {
        out.push({
          name: item.slice(0, 30),
          price: Number(nums[0]),
          kind: "generic",
        });
      }
      return;
    }
    if (typeof item === "object") {
      const name = String(
        item.name || item.label || item.type || "Key Level",
      ).slice(0, 40);
      const p = Number(item.price ?? item.level ?? item.value);
      const barStart = Number(item.bar_start_unix ?? item.bar_start);
      if (Number.isFinite(p))
        out.push({
          name,
          price: p,
          kind: String(item.kind || item.type || "generic"),
          type: String(item.type || "").trim(),
          zone_type: String(item.zone_type || "").trim(),
          swept: Boolean(item.swept),
          bar_start: Number.isFinite(barStart) ? barStart : null,
        });
    }
  };
  const keyLevels = Array.isArray(payload?.market_analysis?.key_levels)
    ? payload.market_analysis.key_levels
    : payload?.key_levels || payload?.keyLevels;
  if (Array.isArray(keyLevels)) keyLevels.forEach(pushLevel);
  if (payload?.key_level) pushLevel(payload.key_level);
  if (Array.isArray(payload?.risk_management?.key_levels))
    payload.risk_management.key_levels.forEach(pushLevel);
  const pd = parseSnapshotPdArrays(payload);
  pd.forEach((x) => {
    const low = Number(x.low);
    const high = Number(x.high);
    if (Number.isFinite(low))
      out.push({ name: `${x.type || "PD"} low`, price: low, kind: "pd" });
    if (Number.isFinite(high))
      out.push({ name: `${x.type || "PD"} high`, price: high, kind: "pd" });
  });
  const dedup = new Map();
  out.forEach((x) => {
    if (!Number.isFinite(Number(x.price))) return;
    const k = `${x.name}|${Number(x.price).toFixed(6)}`;
    if (!dedup.has(k)) dedup.set(k, { ...x, price: Number(x.price) });
  });
  return [...dedup.values()].slice(0, 40);
}

function parseSnapshotChecklist(payload = {}) {
  const raw =
    payload?.market_analysis?.confluence_checklist ??
    payload?.confluence_checklist ??
    payload?.market_analysis?.checklist ??
    payload?.checklist;
  const arr = Array.isArray(raw)
    ? raw
    : [
        ...(Array.isArray(raw?.buy)
          ? raw.buy.map((x) => ({ side: "buy", ...x }))
          : []),
        ...(Array.isArray(raw?.buy?.items)
          ? raw.buy.items.map((x) => ({ side: "buy", ...x }))
          : []),
        ...(Array.isArray(raw?.sell)
          ? raw.sell.map((x) => ({ side: "sell", ...x }))
          : []),
        ...(Array.isArray(raw?.sell?.items)
          ? raw.sell.items.map((x) => ({ side: "sell", ...x }))
          : []),
      ];
  return arr
    .map((x) => ({
      side: String(x?.side || "").trim(),
      strategy: String(x?.strategy || "").trim(),
      condition: String(x?.condition || x?.item || "").trim(),
      weight: String(x?.weight || "").trim(),
      checked: Boolean(x?.checked ?? x?.passed),
      pd_array_ref: Number.isFinite(Number(x?.pd_array_ref ?? x?.pdRef))
        ? Number(x.pd_array_ref ?? x.pdRef)
        : null,
      note: String(x?.note || "").trim(),
    }))
    .filter((x) => x.strategy || x.condition || x.note);
}

function confidenceLevelToPct(level) {
  const v = String(level || "")
    .trim()
    .toLowerCase();
  if (v === "high") return 80;
  if (v === "normal") return 60;
  if (v === "low") return 40;
  return null;
}

function planTakeProfitsRaw(plan = {}) {
  const list = Array.isArray(plan?.take_profits) ? [...plan.take_profits] : [];
  if (!list.length) {
    const mx = plan?.multiple_exits || {};
    if (mx?.tp2) list.push(mx.tp2);
    if (mx?.full_tp) list.push(mx.full_tp);
  }
  return list;
}

function planTakeProfitValue(tpLike) {
  if (tpLike && typeof tpLike === "object") return tpLike.price ?? null;
  return tpLike ?? null;
}

function planPartialTps(plan = {}) {
  const fromTakeProfits = planTakeProfitsRaw(plan).map((t) => ({
    price: t?.price ?? null,
    size_pct: t?.close_position_pct ?? null,
    rr: t?.reward_to_risk ?? null,
  }));
  if (fromTakeProfits.length) return fromTakeProfits;
  const mx = plan?.multiple_exits || {};
  return ["break_even", "tp2", "full_tp"]
    .filter((k) => mx && typeof mx[k] === "object")
    .map((k) => ({
      price: mx[k]?.price ?? null,
      size_pct: mx[k]?.position_pct ?? null,
      rr: mx[k]?.risk_reward ?? null,
    }));
}

function planDecisionText(plan = {}) {
  const decision =
    plan?.risk_management?.skip_decision ||
    plan?.trade_decision ||
    plan?.position_management?.trade_decision ||
    "";
  return decision === "Proceed" ? "" : String(decision || "");
}

function planSkipReasons(plan = {}) {
  const normalizeReasons = (value) => {
    if (Array.isArray(value)) {
      return value.map((r) => ({
        reason: r?.reason || String(r || ""),
        severity: r?.severity || "",
      }));
    }
    const text = String(value || "").trim();
    return text ? [{ reason: text, severity: "" }] : [];
  };
  const rmReasons = normalizeReasons(plan?.risk_management?.skip_reasons);
  if (rmReasons.length) return rmReasons;
  if (Array.isArray(plan?.skip_reasons)) {
    return plan.skip_reasons.map((r) => ({
      reason: r?.reason || "",
      severity: r?.severity || "",
    }));
  }
  const text = String(
    plan?.position_management?.skips_reasons ||
      plan?.position_management?.skip_reasons ||
      "",
  ).trim();
  return text ? [{ reason: text, severity: "" }] : [];
}

function mt5NormalizeSkipDecisionText(rawValue) {
  return String(rawValue || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function mt5IsSkipTradeDecision(rawValue) {
  const normalized = mt5NormalizeSkipDecisionText(rawValue);
  return (
    normalized === "skip" ||
    normalized === "skip trade" ||
    normalized === "do not trade" ||
    normalized === "dont trade" ||
    normalized === "no trade" ||
    normalized === "notrade"
  );
}

function mt5IsNoTradeOrderType(rawValue) {
  const normalized = mt5NormalizeSkipDecisionText(rawValue);
  return (
    normalized === "no trade" ||
    normalized === "notrade" ||
    normalized.startsWith("no trade ") ||
    normalized.startsWith("notrade ")
  );
}

function mt5IsAbortSuggestedAction(rawValue) {
  const normalized = mt5NormalizeSkipDecisionText(rawValue);
  return (
    normalized === "no trade abort" ||
    normalized === "notrade abort" ||
    normalized === "abort" ||
    normalized === "abort trade" ||
    normalized === "do not trade abort"
  );
}

function mt5CollectTradeIntentNodes(root) {
  const out = [];
  const queue = [root];
  const seen = new Set();
  while (queue.length) {
    const node = queue.shift();
    if (!node || typeof node !== "object") continue;
    if (seen.has(node)) continue;
    seen.add(node);
    out.push(node);
    if (Array.isArray(node)) {
      for (const item of node) queue.push(item);
      continue;
    }
    queue.push(node.metadata);
    queue.push(node.raw_json);
    queue.push(node.trade_plan);
    queue.push(node.position_management);
    queue.push(node.risk_management);
    queue.push(node.execution_verdict);
    queue.push(node.analysis_result);
    queue.push(node.analysis_snapshot);
    queue.push(node.final_verdict);
  }
  return out;
}

function mt5ResolveSkipTradeDirective(root = {}) {
  for (const node of mt5CollectTradeIntentNodes(root)) {
    if (mt5IsSkipTradeDecision(node?.trade_decision)) {
      return { cancelled: true, reason: "SKIP" };
    }
    if (mt5IsSkipTradeDecision(node?.skip_recommendation)) {
      return { cancelled: true, reason: "SKIP" };
    }
    if (mt5IsSkipTradeDecision(node?.skip_decision)) {
      return { cancelled: true, reason: "SKIP" };
    }
    if (mt5IsAbortSuggestedAction(node?.suggested_action)) {
      return { cancelled: true, reason: "NO_TRADE_ABORT" };
    }
    if (mt5IsNoTradeOrderType(node?.order_type)) {
      return { cancelled: true, reason: "NO_TRADE" };
    }
    if (mt5IsNoTradeOrderType(node?.orderType)) {
      return { cancelled: true, reason: "NO_TRADE" };
    }
    if (mt5IsNoTradeOrderType(node?.trade_type)) {
      return { cancelled: true, reason: "NO_TRADE" };
    }
    if (mt5IsNoTradeOrderType(node?.type)) {
      return { cancelled: true, reason: "NO_TRADE" };
    }
  }
  return { cancelled: false, reason: null };
}

const RESPONSE_MAPPING_PATH = path.join(
  __dirname,
  "..",
  "config",
  "response_mapping.json",
);

function loadResponseMappingRules() {
  try {
    if (!fs.existsSync(RESPONSE_MAPPING_PATH)) return {};
    const parsed = JSON.parse(fs.readFileSync(RESPONSE_MAPPING_PATH, "utf8"));
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch {
    return {};
  }
}

const RESPONSE_MAPPING_RULES = loadResponseMappingRules();
const DEFAULT_TRADE_PLAN_PATHS = ["trade_plan", "analysis_data[].trade_plan"];

function extractByRulePath(root, rulePath) {
  const pathText = String(rulePath || "").trim();
  if (!pathText) return [];
  const steps = pathText
    .split(".")
    .map((s) => s.trim())
    .filter(Boolean);
  let current = [root];
  for (const step of steps) {
    const isArrayStep = step.endsWith("[]");
    const key = isArrayStep ? step.slice(0, -2) : step;
    const next = [];
    for (const node of current) {
      if (!node || typeof node !== "object") continue;
      const value = node[key];
      if (isArrayStep) {
        if (Array.isArray(value)) next.push(...value);
      } else {
        if (value !== undefined && value !== null) next.push(value);
      }
    }
    current = next;
    if (!current.length) break;
  }
  return current;
}

function collectTradePlansByRules(root) {
  const paths = Array.isArray(RESPONSE_MAPPING_RULES?.trade_plan_paths)
    ? RESPONSE_MAPPING_RULES.trade_plan_paths
    : DEFAULT_TRADE_PLAN_PATHS;
  const out = [];
  for (const p of paths) {
    const hits = extractByRulePath(root, p);
    for (const item of hits) {
      if (Array.isArray(item)) {
        for (const x of item) if (x && typeof x === "object") out.push(x);
      } else if (item && typeof item === "object") {
        out.push(item);
      }
    }
  }
  return out;
}

function dedupeTradePlans(plans = []) {
  const list = Array.isArray(plans) ? plans : [];
  const seen = new Set();
  const out = [];
  for (const p of list) {
    if (!p || typeof p !== "object") continue;
    const key = [
      String(p.symbol || "")
        .trim()
        .toUpperCase(),
      String(p.direction || p.dir || "")
        .trim()
        .toUpperCase(),
      Number(p.entry ?? p.entry_price ?? NaN),
      Number(p.sl ?? p.stop_loss ?? NaN),
      Number(
        p.tp ?? p.take_profit ?? p.tp3 ?? p.multiple_exits?.tp3?.price ?? NaN,
      ),
      String(p.entry_model || "")
        .trim()
        .toUpperCase(),
      String(p.strategy || "")
        .trim()
        .toUpperCase(),
    ].join("|");
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(p);
  }
  return out;
}

function resolvePlanTakeProfit(plan = {}) {
  const candidates = [
    plan?.tp,
    plan?.take_profit,
    plan?.breakeven_trigger,
    plan?.tp3,
    plan?.tp2,
    plan?.tp1,
    plan?.multiple_exits?.full_tp?.price,
    plan?.multiple_exits?.tp3?.price,
    plan?.multiple_exits?.tp2?.price,
    plan?.multiple_exits?.tp1?.price,
  ];
  for (const value of candidates) {
    const n = Number(value);
    if (Number.isFinite(n) && n > 0) return n;
  }
  return null;
}

function planPrimaryTpNumber(plan = {}) {
  return Number(resolvePlanTakeProfit(plan) ?? NaN);
}

function hasNumericEntrySlTp(plan = {}) {
  const entry = Number(plan?.entry ?? plan?.entry_price ?? NaN);
  const sl = Number(plan?.sl ?? plan?.stop_loss ?? NaN);
  const tp = planPrimaryTpNumber(plan);
  return Number.isFinite(entry) && Number.isFinite(sl) && Number.isFinite(tp);
}

function enforceActionableTradePlans(payload = {}) {
  if (!payload || typeof payload !== "object" || Array.isArray(payload))
    return payload;
  const out = { ...payload };
  if (!Array.isArray(out.trade_plan)) return out;
  out.trade_plan = dedupeTradePlans(out.trade_plan).map((plan) => {
    if (!plan || typeof plan !== "object") return plan;
    const hasPrices = hasNumericEntrySlTp(plan);
    const decisionRaw = String(
      plan?.skip_recommendation ||
        plan?.trade_decision ||
        plan?.risk_management?.skip_decision ||
        "",
    )
      .trim()
      .toLowerCase();
    const proceeding =
      !decisionRaw ||
      decisionRaw === "proceed" ||
      decisionRaw === "trade" ||
      decisionRaw === "enter";
    if (hasPrices || !proceeding) return plan;
    const reasonText =
      "Missing entry/stop-loss/take-profit in AI response. Auto-marked as Skip.";
    const reasons = Array.isArray(plan?.reasons_to_skip)
      ? [...plan.reasons_to_skip]
      : [];
    if (
      !reasons.some((r) => String(r?.reason || "").includes("Missing entry"))
    ) {
      reasons.push({ reason: reasonText, severity: "warning" });
    }
    return {
      ...plan,
      skip_recommendation: "Skip",
      trade_decision: "Skip",
      reasons_to_skip: reasons,
      risk_management:
        plan?.risk_management && typeof plan.risk_management === "object"
          ? {
              ...plan.risk_management,
              skip_decision: "Skip",
              skip_reasons: plan.risk_management.skip_reasons || reasonText,
            }
          : {
              skip_decision: "Skip",
              skip_reasons: reasonText,
            },
      note: String(plan?.note || "").trim() || reasonText,
    };
  });
  return out;
}

function normalizeAiAnalysisContract(input = {}) {
  return input;
  if (!input || typeof input !== "object" || Array.isArray(input)) return input;
  const out = { ...input };
  const indexedRootPlans = Object.keys(out)
    .filter((k) => /^\d+$/.test(String(k)))
    .map((k) => out[k])
    .filter((x) => x && typeof x === "object" && !Array.isArray(x))
    .filter(
      (x) =>
        x.execution_plan ||
        x.risk_management ||
        x.entry != null ||
        x.entry_price != null ||
        x.stop_loss != null ||
        x.sl != null,
    )
    .map((x) => ({ ...(x || {}) }));
  const mappedPlans = collectTradePlansByRules(out).map((p) => ({
    ...(p || {}),
  }));
  const mergedMappedPlans = [...mappedPlans, ...indexedRootPlans];
  if (
    mergedMappedPlans.length &&
    (!Array.isArray(out.trade_plan) || out.trade_plan.length === 0)
  ) {
    out.trade_plan = mergedMappedPlans;
  }
  // Alternate schema variant: analyses[] with per-symbol trade_plan
  if (Array.isArray(out.analyses) && out.analyses.length > 0) {
    const entries = out.analyses.filter((x) => x && typeof x === "object");
    const analysisPlans = entries.flatMap((e) =>
      Array.isArray(e.trade_plan)
        ? e.trade_plan.map((p) => ({
            ...(p || {}),
            symbol: String(p?.symbol || e?.symbol || "").trim(),
          }))
        : [],
    );
    if (analysisPlans.length) {
      const rootPlans = Array.isArray(out.trade_plan)
        ? out.trade_plan
            .filter((p) => p && typeof p === "object")
            .map((p) => ({ ...(p || {}) }))
        : [];
      out.trade_plan = [...rootPlans, ...analysisPlans];
    }
    if (!out.ai_full_analysis) {
      const first = entries[0] || {};
      out.symbol = String(first?.symbol || out?.symbol || "").trim();
      out.ai_full_analysis = {
        htf_context: Array.isArray(first?.htf_context) ? first.htf_context : [],
        ltf_analysis: Array.isArray(first?.ltf_analysis)
          ? first.ltf_analysis
          : [],
        confluence_checklist:
          first?.confluence_checklist &&
          typeof first.confluence_checklist === "object"
            ? first.confluence_checklist
            : {},
      };
    }
  }
  // Alternate schema variant: symbols[] with per-symbol trade_plan
  if (Array.isArray(out.symbols) && out.symbols.length > 0) {
    const entries = out.symbols.filter((x) => x && typeof x === "object");
    const symbolPlans = entries.flatMap((e) =>
      Array.isArray(e.trade_plan)
        ? e.trade_plan.map((p) => ({
            ...(p || {}),
            symbol: String(p?.symbol || e?.symbol || "").trim(),
          }))
        : [],
    );
    if (symbolPlans.length) {
      const rootPlans = Array.isArray(out.trade_plan)
        ? out.trade_plan
            .filter((p) => p && typeof p === "object")
            .map((p) => ({ ...(p || {}) }))
        : [];
      out.trade_plan = [...rootPlans, ...symbolPlans];
    }
    if (!out.ai_full_analysis) {
      const first = entries[0] || {};
      out.symbol = String(first?.symbol || out?.symbol || "").trim();
      out.ai_full_analysis = {
        htf_context: Array.isArray(first?.htf_context) ? first.htf_context : [],
        ltf_analysis: Array.isArray(first?.ltf_analysis)
          ? first.ltf_analysis
          : [],
        confluence_checklist:
          first?.confluence_checklist &&
          typeof first.confluence_checklist === "object"
            ? first.confluence_checklist
            : {},
      };
    }
  }
  // NEW schema (v2.6): analysis_data[] root
  if (Array.isArray(out.analysis_data) && out.analysis_data.length > 0) {
    const entries = out.analysis_data.filter((x) => x && typeof x === "object");
    const nestedPlans = entries.flatMap((e) =>
      Array.isArray(e.trade_plan)
        ? e.trade_plan.map((p) => ({
            ...(p || {}),
            symbol: String(p?.symbol || e?.symbol || "").trim(),
          }))
        : [],
    );
    const rootPlans = Array.isArray(out.trade_plan)
      ? out.trade_plan
          .filter((p) => p && typeof p === "object")
          .map((p) => ({ ...(p || {}) }))
      : [];
    const first = entries[0] || {};
    const mtf =
      first?.multi_timeframes_analysis &&
      typeof first.multi_timeframes_analysis === "object"
        ? first.multi_timeframes_analysis
        : {};
    out.symbol = String(first?.symbol || out?.symbol || "").trim();
    out.ai_full_analysis = mtf;
    // Keep root trade_plan too. Some providers put plans at root, not per analysis_data item.
    out.trade_plan = [...rootPlans, ...nestedPlans];
  }

  // BARE trade_plan: AI returned trade_plan directly (no ai_full_analysis wrapper)
  // Normalize old field names → legacy market_analysis format
  if (
    !out.ai_full_analysis &&
    Array.isArray(out.trade_plan) &&
    !out.market_analysis
  ) {
    out.trade_plan = out.trade_plan.map((x) => ({
      symbol: String(x?.symbol || out?.symbol || "").trim(),
      direction: x?.direction || x?.dir || "",
      profile: x?.profile || "",
      type: x?.order_type || x?.type || "",
      session_entry: x?.session || "",
      strategy: x?.strategy || "",
      entry_model: x?.entry_model || "",
      entry: x?.entry_price ?? x?.entry ?? null,
      sl: x?.stop_loss ?? x?.sl ?? null,
      be_trigger: x?.breakeven_trigger ?? x?.be ?? null,
      tp: resolvePlanTakeProfit(x),
      tp2:
        planTakeProfitValue(planTakeProfitsRaw(x)[1]) ??
        x?.multiple_exits?.tp2?.price ??
        x?.tp2 ??
        null,
      tp3:
        planTakeProfitValue(planTakeProfitsRaw(x)[2]) ??
        x?.multiple_exits?.full_tp?.price ??
        x?.tp3 ??
        null,
      estimated_bars: x?.estimated_candles_to_tp1 ?? x?.estimated_bars ?? null,
      rr: x?.risk_reward ?? x?.rr ?? null,
      risk_pct: x?.risk_percent ?? x?.risk_pct ?? null,
      partial_tps: planPartialTps(x),
      confidence_pct:
        x?.confidence_pct ?? confidenceLevelToPct(x?.confidence_level),
      skip_recommendation: planDecisionText(x),
      reasons_to_skip: planSkipReasons(x),
      entry_condition:
        x?.entry_trigger || x?.position_management?.entry_trigger || "",
      exit_condition:
        x?.mid_trade_invalidation ||
        x?.position_management?.mid_trade_invalidation ||
        "",
      invalidation:
        x?.pre_entry_invalidation ||
        x?.position_management?.pre_entry_invalidation ||
        "",
      note: x?.note || "",
    }));
    return enforceActionableTradePlans(out);
  }

  // NEW schema (v2.2): ai_full_analysis wrapper
  if (out.ai_full_analysis && typeof out.ai_full_analysis === "object") {
    const a = out.ai_full_analysis;
    // Flatten HTF + LTF timeframes
    const htfTfs = Array.isArray(a.htf_context) ? a.htf_context : [];
    const ltfTfs = Array.isArray(a.ltf_analysis) ? a.ltf_analysis : [];
    const allTfs = [...htfTfs, ...ltfTfs];
    // Merge PD arrays and key levels from LTF only
    const pdArrays = ltfTfs.flatMap((t) =>
      Array.isArray(t.pd_arrays)
        ? t.pd_arrays.map((p) => ({ ...p, timeframe: t.timeframe }))
        : [],
    );
    const keyLevels = ltfTfs.flatMap((t) =>
      Array.isArray(t.key_levels) ? t.key_levels : [],
    );
    // HTF reference zones → key levels with type prefix
    const htfZones = htfTfs.flatMap((t) =>
      Array.isArray(t.reference_zones)
        ? t.reference_zones.map((z) => ({
            ...z,
            name: `HTF_${z.type}_${z.id || ""}`,
            zone_type: z.type,
          }))
        : [],
    );
    const allKeyLevels = [...keyLevels, ...htfZones];
    // First HTF DOL
    const dol =
      htfTfs.find((t) => t.draw_on_liquidity?.target_price)
        ?.draw_on_liquidity || null;

    out.market_analysis = {
      timeframes: allTfs.map((t) => ({
        tf: t.timeframe || "",
        trend: t.trend || "",
        structure: t.structure || "",
        market_phase: t.phase || "",
        bias: t.bias || "",
        poi_alignment: Boolean(t.poi_aligned),
        price_action_summary: {
          recent_move: t.what_price_just_did || "",
          key_breaks: (Array.isArray(t.key_events) ? t.key_events : []).map(
            (e) => ({
              event: e.event || "",
              price_level: e.price,
              direction:
                e.direction === "Bull"
                  ? "Bullish"
                  : e.direction === "Bear"
                    ? "Bearish"
                    : e.direction || "",
            }),
          ),
        },
        price_prediction: {
          narrative: t.what_price_likely_does_next || "",
          expected_path: (Array.isArray(t.expected_path)
            ? t.expected_path
            : []
          ).map((p) => ({
            step: p.step,
            action: p.action || "",
            target_price: p.target_price,
            condition: p.required_condition || "",
          })),
        },
      })),
      pd_arrays: pdArrays.map((p) => ({
        id: p.id,
        type: p.type || "",
        direction:
          p.direction === "Bull"
            ? "Bullish"
            : p.direction === "Bear"
              ? "Bearish"
              : p.direction || "",
        strength: p.strength || "",
        price_top: p.zone_top,
        price_bottom: p.zone_bottom,
        status: p.status || "",
        touched: p.times_touched || 0,
        timeframe: p.timeframe || "",
        note: p.note || "",
      })),
      key_levels: allKeyLevels.map((k) => ({
        name: k.name || "",
        price: k.price,
        type: k.zone_type || k.type || "",
        swept: Boolean(k.already_swept),
      })),
      institutional_filters: {
        draw_on_liquidity: {
          target: dol?.narrative || "",
          price: dol?.target_price,
          type: dol?.target_type || "",
        },
      },
      confluence_checklist: {
        buy: {
          items: (Array.isArray(a.confluence_checklist?.buy?.passed_items)
            ? a.confluence_checklist.buy.passed_items
            : []
          ).map((c) => ({
            category: c.category || "",
            item: c.description || "",
            weight: c.weight || "",
            checked: true,
            pd_array_ref: c.linked_array_id || null,
          })),
          score: a.confluence_checklist?.buy?.weighted_score ?? 0,
          total: 100,
          high_weight_passed:
            a.confluence_checklist?.buy?.high_weight_passed ?? 0,
          high_weight_total:
            a.confluence_checklist?.buy?.high_weight_total ?? 0,
        },
        sell: {
          items: (Array.isArray(a.confluence_checklist?.sell?.passed_items)
            ? a.confluence_checklist.sell.passed_items
            : []
          ).map((c) => ({
            category: c.category || "",
            item: c.description || "",
            weight: c.weight || "",
            checked: true,
            pd_array_ref: c.linked_array_id || null,
          })),
          score: a.confluence_checklist?.sell?.weighted_score ?? 0,
          total: 100,
          high_weight_passed:
            a.confluence_checklist?.sell?.high_weight_passed ?? 0,
          high_weight_total:
            a.confluence_checklist?.sell?.high_weight_total ?? 0,
        },
      },
    };

    // Normalize trade_plan
    if (!out.trade_plan && Array.isArray(out.tradePlan)) {
      out.trade_plan = out.tradePlan;
    }
    if (Array.isArray(out.trade_plan)) {
      out.trade_plan = out.trade_plan.map((x) => ({
        symbol: String(x?.symbol || out?.symbol || "").trim(),
        direction: x?.direction || x?.dir || "",
        profile: x?.profile || "",
        type: x?.order_type || x?.type || "",
        session_entry: x?.session || "",
        strategy: x?.strategy || "",
        entry_model: x?.entry_model || "",
        entry: x?.entry_price ?? x?.entry ?? null,
        sl: x?.stop_loss ?? x?.sl ?? null,
        be_trigger: x?.breakeven_trigger ?? x?.be ?? null,
        tp: resolvePlanTakeProfit(x),
        tp2:
          planTakeProfitValue(planTakeProfitsRaw(x)[1]) ??
          x?.multiple_exits?.tp2?.price ??
          x?.tp2 ??
          null,
        tp3:
          planTakeProfitValue(planTakeProfitsRaw(x)[2]) ??
          x?.multiple_exits?.full_tp?.price ??
          x?.tp3 ??
          null,
        estimated_bars:
          x?.estimated_candles_to_tp1 ?? x?.estimated_bars ?? null,
        risk_pct: x?.risk_percent ?? x?.risk_pct ?? null,
        rr: x?.risk_reward ?? x?.rr ?? null,
        partial_tps: planPartialTps(x),
        confluence_checklist: Array.isArray(x?.confluence_checklist)
          ? x.confluence_checklist
          : [],
        reasons_to_skip: planSkipReasons(x),
        skip_recommendation: planDecisionText(x),
        entry_condition:
          x?.entry_trigger || x?.position_management?.entry_trigger || "",
        exit_condition:
          x?.mid_trade_invalidation ||
          x?.position_management?.mid_trade_invalidation ||
          "",
        risk_management:
          x?.grade === "A" ? "normal" : x?.grade === "B" ? "low" : "high",
        invalidation:
          x?.pre_entry_invalidation ||
          x?.position_management?.pre_entry_invalidation ||
          "",
        confidence_pct:
          x?.confidence_pct ??
          x?.confluence_score ??
          confidenceLevelToPct(x?.confidence_level),
        note: x?.note || "",
      }));
    }

    // Remove raw wrapper to avoid duplication
    delete out.ai_full_analysis;
    return enforceActionableTradePlans(out);
  }

  // OLD schema (flat format)
  if (
    !out.market_analysis &&
    (Array.isArray(out.timeframes) ||
      Array.isArray(out.pdArrays) ||
      Array.isArray(out.keyLevels) ||
      out.checklist ||
      out.dol)
  ) {
    out.market_analysis = {
      timeframes: (Array.isArray(out.timeframes) ? out.timeframes : []).map(
        (x) => ({
          tf: x?.tf ?? "",
          trend: x?.trend ?? "",
          structure: x?.structure ?? "",
          market_phase: x?.phase ?? x?.market_phase ?? "",
          bias: x?.bias ?? "",
          poi_alignment: Boolean(x?.poiAlign ?? x?.poi_alignment),
          price_action_summary: {
            recent_move: String(
              x?.did ?? x?.price_action_summary?.recent_move ?? "",
            ),
            key_breaks: (Array.isArray(x?.keyBreaks)
              ? x.keyBreaks
              : x?.price_action_summary?.key_breaks || []
            ).map((b) => ({
              event: b?.event ?? "",
              price_level: b?.price ?? b?.price_level ?? null,
              direction:
                b?.direction === "Bull"
                  ? "Bullish"
                  : b?.direction === "Bear"
                    ? "Bearish"
                    : (b?.direction ?? ""),
              bar_ref: b?.bar_ref ?? null,
            })),
          },
          price_prediction: {
            narrative: String(x?.next ?? x?.price_prediction?.narrative ?? ""),
            expected_path: (Array.isArray(x?.path)
              ? x.path
              : x?.price_prediction?.expected_path || []
            ).map((p) => ({
              step: p?.step ?? null,
              action: p?.action ?? "",
              target_price: p?.target ?? p?.target_price ?? null,
              condition: p?.condition ?? "",
            })),
          },
          note: x?.note ?? "",
        }),
      ),
      pd_arrays: (Array.isArray(out.pdArrays) ? out.pdArrays : []).map((x) => ({
        id: x?.id ?? null,
        type: x?.type ?? "",
        direction:
          x?.dir === "Bull"
            ? "Bullish"
            : x?.dir === "Bear"
              ? "Bearish"
              : (x?.direction ?? ""),
        strength: x?.strength ?? "",
        bar_start: x?.bar_start ?? null,
        price_top: x?.top ?? x?.price_top ?? null,
        price_bottom: x?.bot ?? x?.price_bottom ?? null,
        status: x?.status ?? "",
        touched: x?.touched ?? 0,
        mitigation_type: x?.mitigation_type ?? "",
        timeframe: x?.tf ?? x?.timeframe ?? "",
        note: x?.note ?? "",
      })),
      key_levels: (Array.isArray(out.keyLevels) ? out.keyLevels : []).map(
        (x) => ({
          name: x?.name ?? "",
          price: x?.price ?? null,
          type: x?.type ?? "",
          zone_type: x?.zone_type ?? "",
          swept: Boolean(x?.swept),
          bar_start: x?.bar_start ?? null,
        }),
      ),
      institutional_filters: {
        draw_on_liquidity: {
          target: out.dol?.target ?? "",
          price: out.dol?.price ?? null,
          type: out.dol?.type ?? "",
          timeframe: out.dol?.tf ?? "",
        },
      },
      confluence_checklist: {
        buy: (Array.isArray(out.checklist?.buy?.items)
          ? out.checklist.buy.items
          : []
        ).map((x) => ({
          category: x?.category ?? "",
          item: x?.item ?? "",
          weight: x?.weight ?? "",
          checked: Boolean(x?.passed ?? x?.checked),
          pd_array_ref: x?.pdRef ?? x?.pd_array_ref ?? null,
          note: x?.note ?? "",
        })),
        sell: (Array.isArray(out.checklist?.sell?.items)
          ? out.checklist.sell.items
          : []
        ).map((x) => ({
          category: x?.category ?? "",
          item: x?.item ?? "",
          weight: x?.weight ?? "",
          checked: Boolean(x?.passed ?? x?.checked),
          pd_array_ref: x?.pdRef ?? x?.pd_array_ref ?? null,
          note: x?.note ?? "",
        })),
        buy_score: {
          checked: out.checklist?.buy?.score ?? 0,
          total: 100,
          high_weight_passed: out.checklist?.buy?.highPassed ?? 0,
          high_weight_total: out.checklist?.buy?.highTotal ?? 0,
        },
        sell_score: {
          checked: out.checklist?.sell?.score ?? 0,
          total: 100,
          high_weight_passed: out.checklist?.sell?.highPassed ?? 0,
          high_weight_total: out.checklist?.sell?.highTotal ?? 0,
        },
      },
    };
  }

  // Catch-all: normalize raw trade_plan if it still has schema-native field names
  // (e.g. Claude 3.5 Sonnet returns entry_price/stop_loss/take_profits from schema)
  if (Array.isArray(out.trade_plan) && out.trade_plan.length > 0) {
    const first = out.trade_plan[0];
    if (
      first?.entry_price !== undefined ||
      first?.stop_loss !== undefined ||
      first?.take_profits !== undefined ||
      first?.take_profit !== undefined ||
      first?.multiple_exits !== undefined
    ) {
      out.trade_plan = out.trade_plan.map((x) => ({
        symbol: String(x?.symbol || out?.symbol || "").trim(),
        direction: x?.direction || x?.dir || "",
        profile: x?.profile || "",
        type: x?.order_type || x?.type || "limit",
        session_entry: x?.session || "",
        strategy: x?.strategy || "",
        entry_model: x?.entry_model || "",
        entry: x?.entry_price ?? x?.entry ?? null,
        sl: x?.stop_loss ?? x?.sl ?? null,
        tp: resolvePlanTakeProfit(x),
        tp2:
          planTakeProfitValue(planTakeProfitsRaw(x)[1]) ??
          x?.multiple_exits?.tp2?.price ??
          x?.tp2 ??
          null,
        tp3:
          planTakeProfitValue(planTakeProfitsRaw(x)[2]) ??
          x?.multiple_exits?.full_tp?.price ??
          x?.tp3 ??
          null,
        estimated_bars:
          x?.estimated_candles_to_tp1 ?? x?.estimated_bars ?? null,
        rr: x?.risk_reward ?? x?.rr ?? null,
        risk_pct: x?.risk_percent ?? x?.risk_pct ?? null,
        partial_tps: planPartialTps(x),
        confidence_pct:
          x?.confidence_pct ?? confidenceLevelToPct(x?.confidence_level),
        skip_recommendation: planDecisionText(x),
        reasons_to_skip: planSkipReasons(x),
        entry_condition:
          x?.entry_trigger || x?.position_management?.entry_trigger || "",
        exit_condition:
          x?.mid_trade_invalidation ||
          x?.position_management?.mid_trade_invalidation ||
          "",
        invalidation:
          x?.pre_entry_invalidation ||
          x?.position_management?.pre_entry_invalidation ||
          "",
        note: x?.note || "",
        risk_management: x?.risk_management || "",
      }));
    }
  }

  if (!out.trade_plan && out.tradePlan) {
    const tradePlans = Array.isArray(out.tradePlan)
      ? out.tradePlan
      : out.tradePlan && typeof out.tradePlan === "object"
        ? [out.tradePlan]
        : [];
    out.trade_plan = tradePlans.map((x) => ({
      symbol: String(x?.symbol || out?.symbol || "").trim(),
      direction: x?.direction ?? x?.dir ?? "",
      profile: x?.profile ?? "",
      type: x?.type ?? "",
      session_entry: x?.session ?? "",
      strategy: x?.strategy ?? "",
      entry_model: x?.entry_model ?? x?.model ?? "",
      entry: x?.entry ?? null,
      sl: x?.sl ?? null,
      be_trigger: x?.be ?? null,
      tp:
        resolvePlanTakeProfit(x) ??
        (Array.isArray(x?.tps) && x.tps[2]
          ? (x.tps[2].price ?? null)
          : Array.isArray(x?.tps) && x.tps.length
            ? (x.tps[x.tps.length - 1]?.price ?? null)
            : null),
      tp2:
        x?.tp2 ??
        (Array.isArray(x?.tps) && x.tps[1] ? (x.tps[1].price ?? null) : null),
      tp3:
        x?.tp3 ??
        (Array.isArray(x?.tps) && x.tps[2] ? (x.tps[2].price ?? null) : null),
      estimated_bars: x?.estimated_bars ?? null,
      risk_pct: x?.riskPct ?? x?.risk_pct ?? null,
      rr: x?.rr ?? null,
      partial_tps: (Array.isArray(x?.tps) ? x.tps : []).map((t) => ({
        price: t?.price ?? null,
        size_pct: t?.pct ?? null,
        rr: t?.rr ?? null,
      })),
      confluence_checklist: Array.isArray(x?.confluence_checklist)
        ? x.confluence_checklist
        : [],
      reasons_to_skip: (Array.isArray(x?.skipReasons)
        ? x.skipReasons
        : Array.isArray(x?.reasons_to_skip)
          ? x.reasons_to_skip
          : []
      ).map((r) => ({ reason: r?.reason ?? "", severity: r?.severity ?? "" })),
      skip_recommendation:
        x?.skip_recommendation ?? x?.skip ?? x?.action?.recommendation ?? "",
      entry_condition: x?.action?.entry_condition ?? "",
      exit_condition: x?.action?.exit_condition ?? "",
      risk_management: x?.action?.risk_management ?? "",
      invalidation: x?.invalidation ?? out.verdict?.invalidation ?? "",
      confidence_pct: x?.confidence_pct ?? x?.confidence ?? null,
      note: x?.note ?? "",
    }));
  }

  if (!out.final_verdict && out.verdict && typeof out.verdict === "object") {
    out.final_verdict = {
      action: out.verdict.action ?? "",
      risk_tier: out.verdict.tier ?? "",
      confidence: out.verdict.confidence ?? 0,
      bias_shift_invalidation: out.verdict.invalidation ?? "",
      next_poi: {
        price: out.verdict.nextPoi?.price ?? null,
        timeframe: out.verdict.nextPoi?.tf ?? "",
        type: out.verdict.nextPoi?.type ?? "",
      },
      note: out.verdict.note ?? "",
    };
  }
  if (Array.isArray(out.trade_plan)) {
    out.trade_plan = dedupeTradePlans(out.trade_plan);
  }
  return enforceActionableTradePlans(out);
}

function parseSnapshotBarsLimit(payload = {}) {
  const n = Number(
    payload.lookbackBars ?? payload.lookback_bars ?? payload.bars ?? 1000,
  );
  if (!Number.isFinite(n)) return 1000;
  return Math.max(50, Math.min(CHART_HISTORY_MAX_BARS, Math.round(n)));
}

async function loadUserApiKeysMap(userId) {
  const out = {};
  const rows = await settingsStore.listUserSettingsByType(userId, "api_key");
  for (const row of rows || []) {
    const name = normalizeAiApiKeyName(row?.name);
    const dec = decryptObject(
      row?.data && typeof row.data === "object" ? row.data : {},
    );
    if (ALLOWED_AI_API_KEY_NAMES.has(name)) {
      const normalized = buildApiKeySettingPayload(dec);
      out[name] = sanitizeRuntimeApiKey(normalized.api_key || "");
    }
    if (dec && typeof dec === "object") {
      Object.assign(out, dec);
    }
  }
  return out;
}

const API_KEY_ROTATION_CURSOR = new Map();

async function loadApiKeySettingRecord(userId, settingName) {
  const uid =
    String(userId || CFG.mt5DefaultUserId).trim() || CFG.mt5DefaultUserId;
  const normalizedName = normalizeAiApiKeyName(settingName);
  const row = await settingsStore.getUserSetting(uid, "api_key", normalizedName);
  const enc = row?.data && typeof row.data === "object" ? row.data : {};
  const dec = decryptObject(enc);
  const normalized = buildApiKeySettingPayload(dec);
  return {
    userId: uid,
    settingName: normalizedName,
    row,
    encryptedData: enc,
    decryptedData: dec,
    normalizedData: normalized,
    entries: normalizeApiKeyEntries(normalized),
  };
}

function envApiKeyCandidates(settingName = "") {
  const normalizedName = normalizeAiApiKeyName(settingName);
  const envNames = [normalizedName];
  if (normalizedName === "CLAUDE_API_KEY") envNames.unshift("ANTHROPIC_API_KEY");
  if (normalizedName === "ANTHROPIC_API_KEY") envNames.unshift("CLAUDE_API_KEY");
  const out = [];
  const seen = new Set();
  for (const envName of envNames) {
    const raw = sanitizeRuntimeApiKey(envStr(process.env[envName] || ""));
    if (!raw) continue;
    const fingerprint = apiKeyFingerprint(raw);
    if (!fingerprint || seen.has(fingerprint)) continue;
    seen.add(fingerprint);
    out.push({
      id: `env_${envName.toLowerCase()}`,
      api_key: raw,
      status: "active",
      invalid: false,
      invalid_reason: null,
      invalid_at: null,
      last_checked_at: null,
      last_error: null,
      last_success_at: null,
      fingerprint,
      source: "env",
    });
  }
  return out;
}

async function resolveApiKeyPool(userId, settingName) {
  const record = await loadApiKeySettingRecord(userId, settingName);
  const envEntries = envApiKeyCandidates(record.settingName);
  const entryMap = new Map();
  for (const entry of [...record.entries, ...envEntries]) {
    const fingerprint = String(entry?.fingerprint || apiKeyFingerprint(entry?.api_key || ""));
    if (!fingerprint || entryMap.has(fingerprint)) continue;
    entryMap.set(fingerprint, entry);
  }
  const entries = [...entryMap.values()];
  return {
    ...record,
    entries,
    availableEntries: entries.filter((entry) => entry.status === "active"),
  };
}

function rotateApiKeyEntries(pool = {}) {
  const available = Array.isArray(pool?.availableEntries) ? pool.availableEntries : [];
  if (!available.length) return [];
  const rotationKey = `${pool.userId || CFG.mt5DefaultUserId}:${pool.settingName || "API_KEY"}`;
  const cursor = Number(API_KEY_ROTATION_CURSOR.get(rotationKey) || 0);
  const start = cursor % available.length;
  API_KEY_ROTATION_CURSOR.set(rotationKey, cursor + 1);
  return [...available.slice(start), ...available.slice(0, start)];
}

async function persistApiKeyEntryState(
  userId,
  settingName,
  fingerprint,
  update = {},
) {
  const record = await loadApiKeySettingRecord(userId, settingName);
  if (!record.row) return false;
  let changed = false;
  const nextEntries = record.entries.map((entry) => {
    if (entry.fingerprint !== fingerprint) return entry;
    changed = true;
    return {
      ...entry,
      ...update,
    };
  });
  if (!changed) return false;
  const nextData = buildApiKeySettingPayload(
    {
      ...(record.decryptedData && typeof record.decryptedData === "object"
        ? record.decryptedData
        : {}),
      key_entries: nextEntries,
    },
    { fallbackEntries: nextEntries },
  );
  await settingsStore.upsertUserSetting(
    record.userId,
    "api_key",
    record.settingName,
    encryptObject(nextData),
    record.row?.status || "ACTIVE",
  );
  return true;
}

async function markApiKeyEntryInvalid(userId, settingName, entry = {}, reason = "") {
  const fingerprint = String(entry?.fingerprint || apiKeyFingerprint(entry?.api_key || "")).trim();
  if (!fingerprint) return false;
  const nowIso = new Date().toISOString();
  return persistApiKeyEntryState(userId, settingName, fingerprint, {
    status: "invalid",
    invalid: true,
    invalid_reason: String(reason || "invalid_api_key").trim() || "invalid_api_key",
    invalid_at: nowIso,
    last_checked_at: nowIso,
    last_error: String(reason || "invalid_api_key").trim() || "invalid_api_key",
  });
}

async function markApiKeyEntrySuccess(userId, settingName, entry = {}) {
  const fingerprint = String(entry?.fingerprint || apiKeyFingerprint(entry?.api_key || "")).trim();
  if (!fingerprint || entry?.source === "env") return false;
  const nowIso = new Date().toISOString();
  return persistApiKeyEntryState(userId, settingName, fingerprint, {
    status: "active",
    invalid: false,
    invalid_reason: null,
    invalid_at: null,
    last_checked_at: nowIso,
    last_error: null,
    last_success_at: nowIso,
  });
}

async function withRotatingApiKeys(userId, settingName, task) {
  const pool = await resolveApiKeyPool(userId, settingName);
  const orderedEntries = rotateApiKeyEntries(pool);
  if (!orderedEntries.length) {
    throw new Error(`${normalizeAiApiKeyName(settingName)} is missing in Settings.`);
  }
  const errors = [];
  for (const entry of orderedEntries) {
    try {
      const result = await task(entry);
      await markApiKeyEntrySuccess(userId, settingName, entry).catch(() => {});
      return result;
    } catch (error) {
      const reason = String(error?.message || error || "provider request failed").trim();
      if (isLikelyInvalidProviderKeyError(error)) {
        await markApiKeyEntryInvalid(userId, settingName, entry, reason).catch(() => {});
      }
      errors.push(reason);
      if (!isLikelyInvalidProviderKeyError(error)) {
        throw error;
      }
    }
  }
  throw new Error(errors.filter(Boolean).join(" | ") || `${normalizeAiApiKeyName(settingName)} failed`);
}

// ── Provider schema migration ──
async function migrateProviderSchema() {
  try {
    const rows = await settingsStore.listUserSettingsByType(null, "api_key");
    const filtered = (rows || []).filter((r) => {
      const d = settingsStore.parseJsonField(r.data) || {};
      return !d.api_key;
    });
    let migrated = 0;
    for (const row of filtered) {
      const parsed = settingsStore.parseJsonField(row.data) || {};
      const dec = decryptObject(parsed);
      const oldKey = String(dec?.value || dec?.api_key || "").trim();
      const newData = {
        models: Array.isArray(dec?.models) ? dec.models : [],
        ...buildApiKeySettingPayload({ api_key: oldKey }),
        remain_credits: Number.isFinite(Number(dec?.remain_credits))
          ? Number(dec.remain_credits)
          : 0,
      };
      const enc = encryptObject(newData);
      await settingsStore.upsertUserSetting(
        row.user_id || row.userId || CFG.mt5DefaultUserId,
        "api_key",
        row.name,
        enc,
        row.status || "ACTIVE",
      );
      migrated++;
    }
    if (migrated > 0) {
      console.log(
        `[Migration] Provider schema: migrated ${migrated} api_key settings to new format`,
      );
    }
  } catch (err) {
    console.warn("[Migration] Provider schema migration failed:", err.message);
  }
}

function isCryptoPair(symbol) {
  const s = String(symbol || "")
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, "");
  // Common crypto base assets
  const cryptoBases = [
    "BTC",
    "ETH",
    "SOL",
    "BNB",
    "XRP",
    "ADA",
    "DOGE",
    "DOT",
    "MATIC",
    "LTC",
    "LINK",
    "UNI",
    "AVAX",
    "ATOM",
    "ETC",
    "FIL",
    "APT",
    "ARB",
    "OP",
    "NEAR",
    "PEPE",
    "SUI",
    "SEI",
    "TIA",
    "WIF",
    "BONK",
  ];
  for (const base of cryptoBases) {
    if (s.startsWith(base) && (s.endsWith("USD") || s.endsWith("USDT"))) {
      return { base: base, quote: s.slice(base.length) };
    }
  }
  return null;
}

function timeframeToBinance(tf) {
  const t = String(tf || "")
    .trim()
    .toLowerCase();
  const map = {
    "1": "1m",
    "5": "5m",
    "15": "15m",
    "30": "30m",
    "60": "1h",
    "240": "4h",
    "1440": "1d",
    "10080": "1w",
    "1m": "1m",
    "5m": "5m",
    "15m": "15m",
    "30m": "30m",
    "1h": "1h",
    "4h": "4h",
    "1d": "1d",
    "1w": "1w",
    "1month": "1M",
    "1mo": "1M",
    "1min": "1m",
    "5min": "5m",
    "15min": "15m",
    "30min": "30m",
    "1day": "1d",
    "1week": "1w",
  };
  return map[t] || "15m";
}

function binanceKlineToBar(k) {
  return {
    time: Math.floor(Number(k[0]) / 1000),
    open: Number(k[1]),
    high: Number(k[2]),
    low: Number(k[3]),
    close: Number(k[4]),
    volume: Number(k[5]),
  };
}

async function fetchBinanceBars(symbolNorm, tfNorm, bars) {
  const pair = isCryptoPair(symbolNorm);
  if (!pair) return null;
  const binanceSymbol =
    pair.base + (pair.quote === "USD" ? "USDT" : pair.quote);
  const interval = timeframeToBinance(tfNorm);
  const limit = Math.max(50, Math.min(bars || 300, 1000));
  const url = `https://api.binance.com/api/v3/klines?symbol=${binanceSymbol}&interval=${interval}&limit=${limit}`;
  console.log(
    `[binance] FETCH sym=${binanceSymbol} interval=${interval} limit=${limit}`,
  );
  try {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 10000);
    const res = await fetch(url, { signal: ctrl.signal });
    clearTimeout(timer);
    if (!res.ok) throw new Error(`Binance HTTP ${res.status}`);
    const raw = await res.json();
    if (!Array.isArray(raw) || !raw.length)
      throw new Error("Binance empty response");
    const bars = raw
      .map(binanceKlineToBar)
      .filter((b) => Number.isFinite(b.time));
    console.log(`[binance] OK sym=${binanceSymbol} bars=${bars.length}`);
    trackSourceActivity("binance", true);
    return {
      provider: "binance",
      status: "ok",
      symbol: symbolNorm,
      symbol_norm: symbolNorm,
      timeframe: tfNorm,
      tf_norm: tfNorm,
      bars,
      bar_start: bars[0]?.time || null,
      bar_end: bars[bars.length - 1]?.time || null,
      last_price: bars[bars.length - 1]?.close || null,
      cache_source: "binance",
      api_url: url,
      api_interval: interval,
    };
  } catch (e) {
    console.warn(`[binance] FAIL sym=${binanceSymbol}: ${e.message}`);
    trackSourceActivity("binance", false);
    return null;
  }
}

const CHART_HISTORY_MAX_BARS = 20_000;
const CHART_HISTORY_DERIVED_SOURCE_MAX_BARS = CHART_HISTORY_MAX_BARS * 3;
const TWELVE_MAX_BARS_PER_CALL = 5000;
const BINANCE_MAX_BARS_PER_CALL = 1000;

function normalizeBarsDownloadDirection(value = "") {
  const raw = String(value || "").trim().toLowerCase();
  return raw === "history" ? "history" : "latest";
}

function marketDataRefreshJobKey(symbolNorm = "", tfNorm = "", direction = "latest") {
  const symbolKey = String(symbolNorm || "").trim().toUpperCase();
  const tfKey = normalizeMarketDataTf(tfNorm || "1min");
  const directionKey = normalizeBarsDownloadDirection(direction);
  return `${symbolKey}:${tfKey}:${directionKey}`;
}

function providerMaxBarsPerCall(provider = "") {
  return String(provider || "").trim().toLowerCase() === "binance"
    ? BINANCE_MAX_BARS_PER_CALL
    : TWELVE_MAX_BARS_PER_CALL;
}

function listHigherTimeframes(tfNorm = "") {
  const chain = ["1min", "5min", "15min", "1h", "4h", "1day"];
  const normalized = normalizeMarketDataTf(tfNorm || "1min");
  const startIndex = chain.indexOf(normalized);
  if (startIndex < 0) return chain.slice(1);
  return chain.slice(startIndex + 1);
}

async function fetchBinanceBarsPaged(symbolNorm, tfNorm, barsNeeded, options = {}) {
  const pair = isCryptoPair(symbolNorm);
  if (!pair) return [];
  const binanceSymbol =
    pair.base + (pair.quote === "USD" ? "USDT" : pair.quote);
  const interval = timeframeToBinance(tfNorm);
  const target = Math.max(
    50,
    Math.min(Number(barsNeeded) || 1000, CHART_HISTORY_DERIVED_SOURCE_MAX_BARS),
  );
  const dedup = new Map();
  let endTimeMs = Number(options.endTimeMs);
  if (!Number.isFinite(endTimeMs) || endTimeMs <= 0) endTimeMs = null;
  while (dedup.size < target) {
    const remaining = target - dedup.size;
    const limit = Math.max(1, Math.min(1000, remaining));
    const url = new URL("https://api.binance.com/api/v3/klines");
    url.searchParams.set("symbol", binanceSymbol);
    url.searchParams.set("interval", interval);
    url.searchParams.set("limit", String(limit));
    if (Number.isFinite(endTimeMs) && endTimeMs > 0) {
      url.searchParams.set("endTime", String(endTimeMs));
    }
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 10000);
    let raw = [];
    try {
      const res = await fetch(String(url), { signal: ctrl.signal });
      if (!res.ok) throw new Error(`Binance HTTP ${res.status}`);
      raw = await res.json();
    } catch (error) {
      if (error?.name === "AbortError") {
        if (dedup.size > 0) break;
        throw new Error("Binance request timed out after 10s");
      }
      throw error;
    } finally {
      clearTimeout(timer);
    }
    if (!Array.isArray(raw) || !raw.length) break;
    const bars = raw
      .map(binanceKlineToBar)
      .filter((bar) => Number.isFinite(bar.time))
      .sort((a, b) => a.time - b.time);
    for (const bar of bars) dedup.set(bar.time, bar);
    const earliest = bars[0]?.time;
    if (!Number.isFinite(earliest) || bars.length < limit) break;
    endTimeMs = earliest * 1000 - 1;
  }
  return [...dedup.values()].sort((a, b) => a.time - b.time).slice(-target);
}

async function resolveTwelveFetchCandidate(symbol, twelveKey) {
  const tvCandidates = await resolveTwelveSymbol(symbol, twelveKey);
  if (!tvCandidates || !tvCandidates.length) return [];
  const primaryCandidates = [...tvCandidates];
  const rawNoProvider = String(symbol || "")
    .trim()
    .toUpperCase()
    .includes(":")
    ? String(symbol || "")
        .trim()
        .toUpperCase()
        .split(":")
        .slice(1)
        .join(":")
        .trim()
        .toUpperCase()
    : String(symbol || "")
        .trim()
        .toUpperCase();
  const normalizedFallback = normalizeSymbolForTwelve(rawNoProvider);
  if (normalizedFallback && !primaryCandidates.includes(normalizedFallback)) {
    primaryCandidates.push(normalizedFallback);
  }
  const compactFallback = rawNoProvider.replace(/[^A-Z0-9]/g, "");
  if (compactFallback && !primaryCandidates.includes(compactFallback)) {
    primaryCandidates.push(compactFallback);
  }
  return primaryCandidates;
}

async function fetchTwelveBarsPaged(
  symbol,
  interval,
  barsNeeded,
  twelveKey,
  options = {},
) {
  const target = Math.max(
    50,
    Math.min(Number(barsNeeded) || 1000, CHART_HISTORY_DERIVED_SOURCE_MAX_BARS),
  );
  const candidates = await resolveTwelveFetchCandidate(symbol, twelveKey);
  if (!candidates.length) {
    return { bars: [], usedSymbol: symbol, triedCandidates: [], lastError: "invalid symbol" };
  }
  const dedup = new Map();
  let usedSymbol = symbol;
  let lastError = "";
  let endDate = String(options.endDate || "").trim();
  while (dedup.size < target) {
    const remaining = target - dedup.size;
    const outputsize = Math.max(1, Math.min(5000, remaining));
    let pageBars = [];
    let pageSymbol = usedSymbol;
    for (const candidate of candidates) {
      const url = new URL("https://api.twelvedata.com/time_series");
      url.searchParams.set("symbol", candidate);
      url.searchParams.set("interval", interval);
      url.searchParams.set("outputsize", String(outputsize));
      url.searchParams.set("timezone", "UTC");
      url.searchParams.set("order", "ASC");
      url.searchParams.set("apikey", twelveKey);
      if (endDate) url.searchParams.set("end_date", endDate);
      const ctrl = new AbortController();
      const timer = setTimeout(() => ctrl.abort(), 14000);
      let parsed = {};
      try {
        const res = await fetch(String(url), { signal: ctrl.signal });
        const txt = await res.text();
        try {
          parsed = JSON.parse(txt);
        } catch {}
        if (!res.ok) {
          lastError = `http_${res.status}: ${txt.slice(0, 100)}`;
          continue;
        }
      } catch (error) {
        lastError =
          error?.name === "AbortError"
            ? `timeout:${candidate}:${interval}`
            : String(error?.message || error || "request failed");
        if (error?.name === "AbortError") break;
        continue;
      } finally {
        clearTimeout(timer);
      }
      if (String(parsed?.status || "").toLowerCase() === "error") {
        lastError = String(parsed?.message || "provider error");
        continue;
      }
      const vals = Array.isArray(parsed?.values) ? parsed.values : [];
      if (!vals.length) {
        lastError = "empty values";
        continue;
      }
      pageBars = vals
        .map((value) => {
          const t = parseTimeToUnixSec(value?.datetime);
          const o = Number(value?.open);
          const h = Number(value?.high);
          const l = Number(value?.low);
          const c = Number(value?.close);
          const volume = Number(value?.volume);
          if (
            !Number.isFinite(t) ||
            !Number.isFinite(o) ||
            !Number.isFinite(h) ||
            !Number.isFinite(l) ||
            !Number.isFinite(c)
          ) {
            return null;
          }
          return {
            time: t,
            open: o,
            high: h,
            low: l,
            close: c,
            volume: Number.isFinite(volume) ? volume : 0,
          };
        })
        .filter(Boolean)
        .sort((a, b) => a.time - b.time);
      pageSymbol = candidate;
      usedSymbol = candidate;
      lastError = "";
      break;
    }
    if (!pageBars.length) break;
    for (const bar of pageBars) dedup.set(bar.time, bar);
    const earliest = pageBars[0]?.time;
    if (!Number.isFinite(earliest) || pageBars.length < outputsize) break;
    endDate = formatUnixSecForProvider(earliest - 1);
  }
  return {
    bars: [...dedup.values()].sort((a, b) => a.time - b.time).slice(-target),
    usedSymbol,
    triedCandidates: candidates,
    lastError,
  };
}

function deriveBarsFromOneMinute(sourceBars = [], tfNorm = "5m", limit = 0) {
  const targetSec = Math.max(60, parseTfTokenToSeconds(tfNorm));
  if (targetSec <= 60) {
    const normalized = normalizeMarketDataBars(sourceBars);
    if (!limit || limit <= 0) return normalized;
    return normalized.slice(-limit);
  }
  return barsStorage.aggregateBarsFromLowerTimeframe(
    sourceBars,
    targetSec,
    60,
    limit > 0 ? limit : 5000,
  );
}

function compareBarSeries(expected = [], actual = [], tfNorm = "5m") {
  const expectedMap = new Map(
    (Array.isArray(expected) ? expected : []).map((bar) => [Number(bar.time), bar]),
  );
  const actualMap = new Map(
    (Array.isArray(actual) ? actual : []).map((bar) => [Number(bar.time), bar]),
  );
  const timestamps = [...new Set([...expectedMap.keys(), ...actualMap.keys()])]
    .filter(Number.isFinite)
    .sort((a, b) => a - b);
  const mismatches = [];
  for (const time of timestamps) {
    const left = expectedMap.get(time);
    const right = actualMap.get(time);
    if (!left || !right) {
      mismatches.push({ time, reason: left ? "missing_actual" : "missing_expected" });
      continue;
    }
    const fields = ["open", "high", "low", "close", "volume"];
    const diff = {};
    for (const field of fields) {
      const a = Number(left[field] || 0);
      const b = Number(right[field] || 0);
      if (Math.abs(a - b) > 1e-9) diff[field] = { expected: a, actual: b };
    }
    if (Object.keys(diff).length) mismatches.push({ time, diff });
  }
  return {
    timeframe: tfNorm,
    expected_bars: expected.length,
    actual_bars: actual.length,
    mismatch_count: mismatches.length,
    mismatches: mismatches.slice(0, 20),
  };
}

async function refreshSelectedTimeframeBars({
  userId,
  symbol,
  requestedTfNorm,
  requestedBars,
  direction = "latest",
  endTimeSec = null,
}) {
  const symbolNorm = normalizeMarketDataSymbol(symbol);
  if (!symbolNorm) {
    return { ok: false, reason: "invalid symbol" };
  }
  const selectedTfNorm = normalizeMarketDataTf(requestedTfNorm || "1min");
  const refreshDirection = normalizeBarsDownloadDirection(direction);
  const refreshJobKey = marketDataRefreshJobKey(
    symbolNorm,
    selectedTfNorm,
    refreshDirection,
  );
  const existingJob = MARKET_DATA_REFRESH_JOBS.get(refreshJobKey);
  if (existingJob) return existingJob;

  const job = (async () => {
    const historyLoadTraceId =
      refreshDirection === "history" ? genTraceId("mdhist_") : "";
    const requestedSourceBars = Math.max(50, Number(requestedBars) || 1000);
    const emitHistoryStep = (subType, message, payload = {}, ok = true) => {
      if (refreshDirection !== "history") return;
      notifyMutationResult({
        eventType: "MARKET_DATA_HISTORY_LOAD",
        subType,
        ok,
        message,
        sourceType: "market_data",
        sourceId: `${symbolNorm}:${selectedTfNorm}`,
        userId,
        payload: {
          symbol: symbolNorm,
          timeframe: selectedTfNorm,
          direction: refreshDirection,
          notification: true,
          trace_id: historyLoadTraceId,
          ...payload,
        },
      });
    };
    let sourceBars = [];
    let provider = "twelvedata";
    let providerMeta = {};
    const existingSourceBars = await barsStorage.readBrokerBarsFromFileAsync(
      symbolNorm,
      selectedTfNorm,
      0,
      {
        dataRoot: GLOBAL_DATA_DIR,
        duckdbPath: process.env.BARS_DUCKDB_PATH,
        fullFile: true,
      },
    );
    const existingStoredBarsList = Array.isArray(existingSourceBars)
      ? existingSourceBars
      : [];
    const earliestStoredBarTime = Number(existingStoredBarsList?.[0]?.time || 0);
    const requestedHistoryEndSec =
      refreshDirection === "history" &&
      Number.isFinite(Number(endTimeSec)) &&
      Number(endTimeSec) > 0
        ? Math.floor(Number(endTimeSec))
        : null;
    const remoteHistoryCursorSec =
      refreshDirection === "history"
        ? requestedHistoryEndSec > 0
          ? requestedHistoryEndSec
          : earliestStoredBarTime > 0
            ? earliestStoredBarTime
            : null
        : null;
    emitHistoryStep(
      "storage_scan",
      `Load history storage scan: ${symbolNorm} ${selectedTfNorm} (${existingStoredBarsList.length} bars in file)`,
      {
        step: "storage_scan",
        existing_bars: existingStoredBarsList.length,
        earliest_stored_bar_time: earliestStoredBarTime || null,
      },
    );

    if (isCryptoPair(symbolNorm)) {
      provider = "binance";
      const barsToFetch = Math.max(
        50,
        Math.min(requestedSourceBars, CHART_HISTORY_DERIVED_SOURCE_MAX_BARS),
      );
      emitHistoryStep(
        "remote_fetch_started",
        `Load history remote fetch: ${symbolNorm} ${selectedTfNorm} via Binance (${barsToFetch} requested)`,
        {
          step: "remote_fetch_started",
          provider,
          requested_source_bars: requestedSourceBars,
          remote_request_bars: barsToFetch,
          remote_end_time_ms:
            Number.isFinite(remoteHistoryCursorSec) && remoteHistoryCursorSec > 0
              ? remoteHistoryCursorSec * 1000 - 1
              : null,
        },
      );
      sourceBars = await fetchBinanceBarsPaged(
        symbolNorm,
        selectedTfNorm,
        barsToFetch,
        {
          endTimeMs:
            Number.isFinite(remoteHistoryCursorSec) && remoteHistoryCursorSec > 0
              ? remoteHistoryCursorSec * 1000 - 1
              : null,
        },
      );
        providerMeta = {
          provider_max_bars_per_call: providerMaxBarsPerCall(provider),
        };
    } else {
      const twelvePool = await resolveApiKeyPool(userId, "TWELVE_DATA_API_KEY").catch(
        () => ({ availableEntries: [] }),
      );
      if (!twelvePool.availableEntries?.length) {
        return { ok: false, reason: "TWELVE_DATA_API_KEY missing" };
      }
      const barsToFetch = Math.max(
        50,
        Math.min(requestedSourceBars, CHART_HISTORY_DERIVED_SOURCE_MAX_BARS),
      );
      emitHistoryStep(
        "remote_fetch_started",
        `Load history remote fetch: ${symbolNorm} ${selectedTfNorm} via Twelve Data (${barsToFetch} requested)`,
        {
          step: "remote_fetch_started",
          provider,
          requested_source_bars: requestedSourceBars,
          remote_request_bars: barsToFetch,
          remote_end_time:
            Number.isFinite(remoteHistoryCursorSec) && remoteHistoryCursorSec > 0
              ? formatUnixSecForProvider(remoteHistoryCursorSec - 1)
              : "",
        },
      );
      const fetched = await withRotatingApiKeys(
        userId,
        "TWELVE_DATA_API_KEY",
        async (entry) => {
          const response = await fetchTwelveBarsPaged(
            symbol,
            timeframeToTwelve(selectedTfNorm),
            barsToFetch,
            entry.api_key,
            {
              endDate:
                Number.isFinite(remoteHistoryCursorSec) && remoteHistoryCursorSec > 0
                  ? formatUnixSecForProvider(remoteHistoryCursorSec - 1)
                  : "",
            },
          );
          if (
            !Array.isArray(response?.bars) ||
            !response.bars.length
          ) {
            const lastError = String(response?.lastError || "").trim();
            if (isLikelyInvalidProviderKeyError(lastError)) {
              const invalidError = new Error(lastError);
              invalidError.status = 401;
              throw invalidError;
            }
          }
          return response;
        },
      );
      sourceBars = fetched.bars;
      providerMeta = {
        normalized_symbol: fetched.usedSymbol,
        tried_candidates: fetched.triedCandidates,
        last_error: fetched.lastError || null,
        provider_max_bars_per_call: providerMaxBarsPerCall(provider),
      };
    }

    if (!Array.isArray(sourceBars) || !sourceBars.length) {
      emitHistoryStep(
        "remote_fetch_empty",
        `Load history remote fetch returned no bars: ${symbolNorm} ${selectedTfNorm} (${provider})`,
        {
          step: "remote_fetch_empty",
          provider,
          reason: `${provider}_empty`,
          ...providerMeta,
        },
        false,
      );
      return {
        ok: false,
        provider,
        fetch_tf: selectedTfNorm,
        direction: refreshDirection,
        requested_tf: requestedTfNorm,
        requested_bars: requestedBars,
        requested_source_bars: requestedSourceBars,
        fetched_source_bars: 0,
        stored_source_bars: existingStoredBarsList.length,
        reason: `${provider}_empty`,
        remote_reason:
          String(providerMeta.last_error || `${provider}_empty`).trim() || `${provider}_empty`,
        ...providerMeta,
      };
    }
    emitHistoryStep(
      "remote_fetch_completed",
      `Load history remote fetch completed: ${symbolNorm} ${selectedTfNorm} (${sourceBars.length} bars from ${provider})`,
      {
        step: "remote_fetch_completed",
        provider,
        fetched_source_bars: sourceBars.length,
        ...providerMeta,
      },
    );

    const mergeResult = await mergeBarsIntoStorageAsync(
      symbolNorm,
      selectedTfNorm,
      sourceBars,
    );
    const fullSourceBars = Array.isArray(mergeResult?.mergedBars)
      ? mergeResult.mergedBars
      : [];
    if (!fullSourceBars.length) {
      emitHistoryStep(
        "merge_failed",
        `Load history merge failed: ${symbolNorm} ${selectedTfNorm} (file unavailable after merge)`,
        {
          step: "merge_failed",
          provider,
          reason: "selected_tf_unavailable_after_merge",
        },
        false,
      );
      return { ok: false, reason: "selected_tf_unavailable_after_merge" };
    }
    emitHistoryStep(
      "merge_completed",
      `Load history merge completed: ${symbolNorm} ${selectedTfNorm} (${fullSourceBars.length} bars stored)`,
      {
        step: "merge_completed",
        provider,
        stored_source_bars: fullSourceBars.length,
        fetched_source_bars: sourceBars.length,
        inserted_or_updated: Number(mergeResult?.added || 0),
      },
    );

    const rebuildTargets = listHigherTimeframes(selectedTfNorm);
    const sourceTfSeconds = Math.max(60, parseTfTokenToSeconds(selectedTfNorm));
    const rebuiltEntries = await Promise.all(
      rebuildTargets.map(async (tf) => {
        const targetTfSeconds = Math.max(60, parseTfTokenToSeconds(tf));
        const derived = barsStorage.aggregateBarsFromLowerTimeframe(
          fullSourceBars,
          targetTfSeconds,
          sourceTfSeconds,
          0,
        );
        if (!derived.length) return null;
        const storedCount = await barsStorage.overwriteBrokerBarsFileAsync(
          symbolNorm,
          tf,
          derived,
          {
            dataRoot: GLOBAL_DATA_DIR,
            duckdbPath: process.env.BARS_DUCKDB_PATH,
          },
        );
        return [
          tf,
          {
            merged_bars: derived.length,
            inserted_or_updated: derived.length,
            stored_bars: storedCount,
          },
        ];
      }),
    );
    const rebuilt = Object.fromEntries(rebuiltEntries.filter(Boolean));

    let comparison = null;
    if (!isCryptoPair(symbolNorm) && selectedTfNorm === "1min") {
      const twelvePool = await resolveApiKeyPool(userId, "TWELVE_DATA_API_KEY").catch(
        () => ({ availableEntries: [] }),
      );
      if (twelvePool.availableEntries?.length) {
        const direct5m = await withRotatingApiKeys(
          userId,
          "TWELVE_DATA_API_KEY",
          async (entry) =>
            fetchTwelveBarsPaged(
              symbol,
              timeframeToTwelve("5m"),
              Math.min(1000, Math.ceil(fullSourceBars.length / 5)),
              entry.api_key,
            ),
        );
        const derived5m = deriveBarsFromOneMinute(fullSourceBars, "5m", 0);
        comparison = compareBarSeries(
          direct5m.bars,
          derived5m.slice(-direct5m.bars.length),
          "5m",
        );
      }
    }

    return {
      ok: true,
      provider,
      fetch_tf: selectedTfNorm,
      direction: refreshDirection,
      requested_tf: requestedTfNorm,
      requested_bars: requestedBars,
      requested_source_bars: requestedSourceBars,
      fetched_source_bars: sourceBars.length,
      stored_source_bars: fullSourceBars.length,
      rebuilt,
      comparison,
      ...providerMeta,
    };
  })();

  MARKET_DATA_REFRESH_JOBS.set(refreshJobKey, job);
  try {
    const result = await job;
    notifyMutationResult({
      eventType: "CHART_REFRESH",
      subType: result?.ok ? "completed" : "failed",
      ok: Boolean(result?.ok),
      message: result?.ok
        ? `+${result?.fetched_source_bars || result?.requested_source_bars || result?.requested_bars || 0} bars from ${result?.provider || "source"} ${result?.fetch_tf || requestedTfNorm || ""}, ${result?.stored_source_bars || result?.fetched_source_bars || result?.requested_source_bars || result?.requested_bars || 0} stored.`
        : `${result?.remote_reason || result?.last_error || result?.reason || "refresh failed"}`,
      sourceType: "market_data",
      sourceId: `${symbolNorm}:${result?.fetch_tf || requestedTfNorm || ""}`,
      userId,
      payload: {
        symbol: symbolNorm,
        timeframe: result?.fetch_tf || requestedTfNorm || null,
        direction,
        notification: true,
        reason: result?.reason || null,
        remote_reason: result?.remote_reason || result?.last_error || null,
      },
      data: result,
    });
    return result;
  } finally {
    MARKET_DATA_REFRESH_JOBS.delete(refreshJobKey);
  }
}

const REFRESH_FIX_CHAIN_TFS = ["1", "5", "15", "60", "240", "1440", "1w"];

function listRefreshFixChainTimeframes(targetTf = "1440", baseTf = "1") {
  const targetKey = normalizeCsvTfKey(targetTf);
  const baseKey = normalizeCsvTfKey(baseTf || "1");
  const startIndex = Math.max(0, REFRESH_FIX_CHAIN_TFS.indexOf(baseKey));
  const endIndex = REFRESH_FIX_CHAIN_TFS.indexOf(targetKey);
  if (endIndex < 0) return REFRESH_FIX_CHAIN_TFS.slice(startIndex);
  if (endIndex < startIndex) {
    return REFRESH_FIX_CHAIN_TFS.slice(startIndex, startIndex + 1);
  }
  return REFRESH_FIX_CHAIN_TFS.slice(startIndex, endIndex + 1);
}

function describeRefreshFixChainFailure(result = {}) {
  const tfSteps = Array.isArray(result?.timeframes) ? result.timeframes : [];
  const failedTf =
    String(result?.stopped_at || "").trim() ||
    String(tfSteps[tfSteps.length - 1]?.tf || "").trim() ||
    String(result?.target_tf || "").trim() ||
    "";
  const failedStep =
    tfSteps.find((step) => String(step?.tf || "").trim() === failedTf) ||
    tfSteps[tfSteps.length - 1] ||
    null;
  const actions = Array.isArray(failedStep?.actions) ? failedStep.actions : [];
  const remoteActionWithError = [...actions]
    .reverse()
    .find((action) => {
      const remote = action?.remote && typeof action.remote === "object" ? action.remote : null;
      return Boolean(String(remote?.last_error || remote?.error || "").trim());
    });
  const lastRemoteAction = remoteActionWithError || [...actions]
    .reverse()
    .find((action) => action && typeof action === "object" && action.remote);
  const remoteError = String(
    lastRemoteAction?.remote?.last_error ||
      lastRemoteAction?.remote?.error ||
      "",
  ).trim();
  const provider = String(
    lastRemoteAction?.provider || failedStep?.provider || "",
  ).trim();
  const afterReasons = Array.isArray(failedStep?.after?.reasons)
    ? failedStep.after.reasons.filter(Boolean)
    : [];
  const beforeReasons = Array.isArray(failedStep?.before?.reasons)
    ? failedStep.before.reasons.filter(Boolean)
    : [];
  const topReason = String(
    remoteError ||
      afterReasons[0] ||
      beforeReasons[0] ||
      result?.reason ||
      "",
  ).trim();
  const gapCount = Number(failedStep?.after?.gap_count || 0) || 0;
  const returnedBars = Number(lastRemoteAction?.returned_bars || 0) || 0;
  const barCount = Number(failedStep?.after?.bar_count || 0) || 0;
  const lastBarAt = String(failedStep?.after?.last_bar_at || "").trim();
  const detailParts = [];

  if (topReason) {
    detailParts.push(provider ? `${provider}: ${topReason}` : topReason);
  } else if (provider && returnedBars === 0) {
    detailParts.push(`${provider}: no bars returned`);
  } else if (failedTf) {
    detailParts.push(`unable to repair ${failedTf} bars from remote source`);
  }

  if (gapCount > 0) {
    detailParts.push(`${gapCount} gap${gapCount === 1 ? "" : "s"} remain`);
  } else if (barCount <= 0) {
    detailParts.push("no stored bars");
  } else if (lastBarAt) {
    detailParts.push(`last bar ${lastBarAt}`);
  }

  return String(detailParts.join(" · "))
    .replace(/\s+/g, " ")
    .trim();
}

function parseAuditIsoToUnixSec(value) {
  const ms = Date.parse(String(value || "").trim());
  if (!Number.isFinite(ms) || ms <= 0) return null;
  return Math.floor(ms / 1000);
}

function latestCompletedBarTimeSec(
  tfKey,
  nowSec = Math.floor(Date.now() / 1000),
) {
  const tfSec = Math.max(60, parseTfTokenToSeconds(tfKey));
  const current = Number(nowSec);
  if (!Number.isFinite(current) || current <= 1) return null;
  return Math.floor((current - 1) / tfSec) * tfSec;
}

function auditGapWindows(audit = {}) {
  const windows = audit?.issue_report?.suspicious_places?.gap_windows;
  return Array.isArray(windows) ? windows : [];
}

function auditGapCount(audit = {}) {
  return Number(audit?.issue_report?.metrics?.gap_count || 0);
}

function auditBarCount(audit = {}) {
  return Number(audit?.summary?.bar_count || 0);
}

function auditCoverageResolved(audit = {}) {
  return auditBarCount(audit) > 0 && auditGapCount(audit) === 0;
}

function summarizeAuditState(audit = {}) {
  return {
    bar_count: auditBarCount(audit),
    first_bar_at: audit?.summary?.first_bar_at || null,
    last_bar_at: audit?.summary?.last_bar_at || null,
    suspicious: Boolean(audit?.issue_report?.suspicious),
    reasons: Array.isArray(audit?.issue_report?.reasons)
      ? audit.issue_report.reasons.slice(0, 12)
      : [],
    gap_count: auditGapCount(audit),
    coverage_resolved: auditCoverageResolved(audit),
  };
}

function auditTailFresh(audit = {}, tfKey = "", toleranceBars = 1) {
  const tfSec = Math.max(60, parseTfTokenToSeconds(tfKey));
  const latestCompletedSec = latestCompletedBarTimeSec(tfKey);
  const lastStoredSec = parseAuditIsoToUnixSec(audit?.summary?.last_bar_at);
  if (!Number.isFinite(latestCompletedSec) || latestCompletedSec <= 0) {
    return true;
  }
  if (!Number.isFinite(lastStoredSec) || lastStoredSec <= 0) return false;
  const toleranceSec =
    Math.max(0, Math.round(Number(toleranceBars) || 0)) * tfSec;
  return lastStoredSec >= latestCompletedSec - toleranceSec;
}

function isStepSatisfiedForRefreshMode(
  audit = {},
  tfKey = "",
  repairHistoryGaps = true,
) {
  if (repairHistoryGaps) {
    return auditCoverageResolved(audit);
  }
  return auditBarCount(audit) > 0 && auditTailFresh(audit, tfKey, 1);
}

async function readFullBrokerBarsForTf(symbolNorm, tfKey) {
  return barsStorage.readBrokerBarsFromFileAsync(symbolNorm, tfKey, 0, {
    dataRoot: GLOBAL_DATA_DIR,
    duckdbPath: process.env.BARS_DUCKDB_PATH,
    fullFile: true,
  });
}

async function mergeBarsDirectToStorage(symbolNorm, tfKey, bars = []) {
  const normalizedBars = Array.isArray(bars) ? bars.filter(Boolean) : [];
  if (!normalizedBars.length) {
    return { inserted_or_updated: 0, stored_bars: 0 };
  }
  const insertedOrUpdated = await barsStorage.mergeBrokerBarsIntoFileAsync(
    symbolNorm,
    tfKey,
    normalizedBars,
    {
      dataRoot: GLOBAL_DATA_DIR,
      duckdbPath: process.env.BARS_DUCKDB_PATH,
    },
  );
  const storedBars = await readFullBrokerBarsForTf(symbolNorm, tfKey);
  return {
    inserted_or_updated: Number(insertedOrUpdated || 0),
    stored_bars: Array.isArray(storedBars) ? storedBars.length : 0,
  };
}

function buildRemoteBarsRequestSize(provider, requestedBars) {
  return Math.max(
    50,
    Math.min(
      CHART_HISTORY_DERIVED_SOURCE_MAX_BARS,
      Math.round(Number(requestedBars) || 0) || 300,
    ),
  );
}

async function fetchRemoteBarsForTimeframe({
  userId,
  symbol,
  symbolNorm,
  tfKey,
  requestedBars,
  endTimeSec = null,
}) {
  const pair = isCryptoPair(symbolNorm);
  if (pair) {
    const provider = "binance";
    const request = {
      requested_bars: buildRemoteBarsRequestSize(provider, requestedBars),
      end_time_sec:
        Number.isFinite(Number(endTimeSec)) && Number(endTimeSec) > 0
          ? Math.floor(Number(endTimeSec))
          : null,
      end_time_iso:
        Number.isFinite(Number(endTimeSec)) && Number(endTimeSec) > 0
          ? new Date(Math.floor(Number(endTimeSec)) * 1000).toISOString()
          : null,
    };
    let bars = [];
    let lastError = null;
    try {
      bars = await fetchBinanceBarsPaged(symbolNorm, tfKey, request.requested_bars, {
        endTimeMs:
          Number.isFinite(Number(endTimeSec)) && Number(endTimeSec) > 0
            ? Math.floor(Number(endTimeSec) * 1000) - 1
            : null,
      });
    } catch (error) {
      lastError = error instanceof Error ? error.message : String(error || "binance fetch failed");
    }
    if (!lastError && (!Array.isArray(bars) || bars.length === 0)) {
      lastError = "No bars returned from Binance";
    }
    return {
      provider,
      bars,
      request,
      meta: {
        provider_max_bars_per_call: providerMaxBarsPerCall(provider),
        last_error: lastError,
      },
    };
  }

  const twelvePool = await resolveApiKeyPool(userId, "TWELVE_DATA_API_KEY").catch(
    () => ({ availableEntries: [] }),
  );
  if (!twelvePool.availableEntries?.length) {
    return {
      provider: "twelvedata",
      bars: [],
      request: {
        requested_bars: buildRemoteBarsRequestSize("twelvedata", requestedBars),
        end_time_sec:
          Number.isFinite(Number(endTimeSec)) && Number(endTimeSec) > 0
            ? Math.floor(Number(endTimeSec))
            : null,
        end_time_iso:
          Number.isFinite(Number(endTimeSec)) && Number(endTimeSec) > 0
            ? new Date(Math.floor(Number(endTimeSec)) * 1000).toISOString()
            : null,
      },
      meta: {
        missing_api_key: true,
        provider_max_bars_per_call: providerMaxBarsPerCall("twelvedata"),
        last_error: "TWELVE_DATA_API_KEY missing",
      },
    };
  }

  const requested = buildRemoteBarsRequestSize("twelvedata", requestedBars);
  let fetched = null;
  let lastError = null;
  try {
    fetched = await withRotatingApiKeys(userId, "TWELVE_DATA_API_KEY", async (entry) => {
      const response = await fetchTwelveBarsPaged(
        symbol,
        timeframeToTwelve(tfKey),
        requested,
        entry.api_key,
          {
            endDate:
              Number.isFinite(Number(endTimeSec)) && Number(endTimeSec) > 0
              ? formatUnixSecForProvider(Math.floor(Number(endTimeSec) - 1))
              : "",
          },
        );
      if ((!Array.isArray(response?.bars) || !response.bars.length) && isLikelyInvalidProviderKeyError(response?.lastError || "")) {
        const invalidError = new Error(String(response?.lastError || "invalid api key"));
        invalidError.status = 401;
        throw invalidError;
      }
      return response;
    });
  } catch (error) {
    lastError =
      error instanceof Error
        ? error.message
        : String(error || "twelvedata fetch failed");
  }
  return {
    provider: "twelvedata",
    bars: Array.isArray(fetched?.bars) ? fetched.bars : [],
    request: {
      requested_bars: requested,
      end_time_sec:
        Number.isFinite(Number(endTimeSec)) && Number(endTimeSec) > 0
          ? Math.floor(Number(endTimeSec))
          : null,
      end_time_iso:
        Number.isFinite(Number(endTimeSec)) && Number(endTimeSec) > 0
          ? new Date(Math.floor(Number(endTimeSec)) * 1000).toISOString()
          : null,
    },
    meta: {
      normalized_symbol: fetched?.usedSymbol || symbolNorm,
      tried_candidates: Array.isArray(fetched?.triedCandidates)
        ? fetched.triedCandidates
        : [],
      last_error: fetched?.lastError || lastError || null,
      provider_max_bars_per_call: providerMaxBarsPerCall("twelvedata"),
    },
  };
}

function estimateLatestBarsForRepair(
  tfKey,
  audit = {},
  preferredBars = 1000,
  repairHistoryGaps = true,
) {
  const baseline = Math.max(50, Math.round(Number(preferredBars) || 1000));
  const tfSec = Math.max(60, parseTfTokenToSeconds(tfKey));
  const latestCompletedSec = latestCompletedBarTimeSec(tfKey);
  const lastStoredSec = parseAuditIsoToUnixSec(audit?.summary?.last_bar_at);
  if (!Number.isFinite(latestCompletedSec) || latestCompletedSec <= 0) {
    return baseline;
  }
  if (!Number.isFinite(lastStoredSec) || lastStoredSec <= 0) return baseline;
  const tailBars = Math.max(
    0,
    Math.ceil((latestCompletedSec - lastStoredSec) / tfSec) + 8,
  );
  if (repairHistoryGaps !== true) {
    return Math.max(50, Math.min(300, tailBars || 50));
  }
  return Math.max(baseline, tailBars);
}

async function repairCoverageGapsFromRemote({
  userId,
  symbol,
  symbolNorm,
  tfKey,
  startAudit,
  gapBufferBars = 50,
  maxGapWindowsPerTf = 12,
}) {
  let currentAudit = startAudit;
  const actions = [];
  const tfSec = Math.max(60, parseTfTokenToSeconds(tfKey));
  const windows = auditGapWindows(currentAudit).slice(
    0,
    Math.max(1, maxGapWindowsPerTf),
  );
  for (const gap of windows) {
    const requestEndSec = Number(gap?.before_time) - tfSec;
    const requestedBars = Math.max(
      50,
      Number(gap?.missing_bars || 0) +
        Math.max(10, Number(gapBufferBars) || 0) * 2,
    );
    const fetched = await fetchRemoteBarsForTimeframe({
      userId,
      symbol,
      symbolNorm,
      tfKey,
      requestedBars,
      endTimeSec: requestEndSec,
    });
    const remoteAction = {
      type: "remote_gap_fetch",
      gap_after_time: Number(gap?.after_time || 0) || null,
      gap_before_time: Number(gap?.before_time || 0) || null,
      gap_after_at: gap?.after_at || null,
      gap_before_at: gap?.before_at || null,
      missing_bars: Number(gap?.missing_bars || 0) || 0,
      provider: fetched.provider,
      request: fetched.request,
      returned_bars: Array.isArray(fetched.bars) ? fetched.bars.length : 0,
      remote: fetched.meta,
    };
    if (Array.isArray(fetched.bars) && fetched.bars.length) {
      remoteAction.merge = await mergeBarsDirectToStorage(
        symbolNorm,
        tfKey,
        fetched.bars,
      );
      currentAudit = marketDataAuditService.auditMarketData(symbolNorm, tfKey, {
        dataRoot: GLOBAL_DATA_DIR,
        duckdbPath: process.env.BARS_DUCKDB_PATH,
      });
      remoteAction.after = summarizeAuditState(currentAudit);
    }
    actions.push(remoteAction);
    if (auditCoverageResolved(currentAudit)) break;
  }
  return {
    audit: currentAudit,
    actions,
  };
}

async function rebuildAndMergeTimeframeFromLower(symbolNorm, lowerTfKey, targetTfKey) {
  const lowerBars = await readFullBrokerBarsForTf(symbolNorm, lowerTfKey);
  const lowerTfSeconds = Math.max(60, parseTfTokenToSeconds(lowerTfKey));
  const targetTfSeconds = Math.max(60, parseTfTokenToSeconds(targetTfKey));
  const derivedBars = barsStorage.aggregateBarsFromLowerTimeframe(
    lowerBars,
    targetTfSeconds,
    lowerTfSeconds,
    0,
  );
  const merge = await mergeBarsDirectToStorage(symbolNorm, targetTfKey, derivedBars);
  return {
    lower_tf: lowerTfKey,
    target_tf: targetTfKey,
    source_bars: Array.isArray(lowerBars) ? lowerBars.length : 0,
    derived_bars: Array.isArray(derivedBars) ? derivedBars.length : 0,
    merge,
  };
}

async function refreshFixMarketDataChain({
  userId,
  symbol,
  targetTf,
  baseTf = "1",
  latestBars = 1000,
  gapBufferBars = 50,
  maxGapWindowsPerTf = 12,
  stopOnUnresolved = true,
  repairHistoryGaps = false,
}) {
  const symbolNorm = normalizeMarketDataSymbol(symbol);
  const targetTfKey = normalizeCsvTfKey(targetTf);
  const baseTfKey = normalizeCsvTfKey(baseTf || "1");
  if (!symbolNorm || !targetTfKey) {
    return { ok: false, reason: "symbol and target_tf are required" };
  }
  const chain = listRefreshFixChainTimeframes(targetTfKey, baseTfKey);
  const auditMarketDataForRefresh = (tfKey) =>
    marketDataAuditService.auditMarketDataAsync(symbolNorm, tfKey, {
      dataRoot: GLOBAL_DATA_DIR,
      duckdbPath: process.env.BARS_DUCKDB_PATH,
    });
  const out = {
    ok: true,
    symbol: symbolNorm,
    base_tf: baseTfKey,
    target_tf: targetTfKey,
    latest_bars: Math.max(50, Math.round(Number(latestBars) || 1000)),
    gap_buffer_bars: Math.max(10, Math.round(Number(gapBufferBars) || 50)),
    max_gap_windows_per_tf: Math.max(
      1,
      Math.round(Number(maxGapWindowsPerTf) || 12),
    ),
    stop_on_unresolved: stopOnUnresolved !== false,
    repair_history_gaps: repairHistoryGaps === true,
    timeframes: [],
    stopped_at: null,
  };

  let previousTfKey = null;
  for (const tfKey of chain) {
    const beforeAudit = await auditMarketDataForRefresh(tfKey);
    const step = {
      tf: tfKey,
      before: summarizeAuditState(beforeAudit),
      actions: [],
      after: null,
      coverage_resolved: false,
    };

    if (tfKey === baseTfKey) {
      const fetchedLatest = await fetchRemoteBarsForTimeframe({
        userId,
        symbol,
        symbolNorm,
        tfKey,
        requestedBars: estimateLatestBarsForRepair(
          tfKey,
          beforeAudit,
          out.latest_bars,
          repairHistoryGaps,
        ),
      });
      const latestAction = {
        type: "remote_latest_fetch",
        provider: fetchedLatest.provider,
        request: fetchedLatest.request,
        returned_bars: Array.isArray(fetchedLatest.bars)
          ? fetchedLatest.bars.length
          : 0,
        remote: fetchedLatest.meta,
      };
      if (Array.isArray(fetchedLatest.bars) && fetchedLatest.bars.length) {
        latestAction.merge = await mergeBarsDirectToStorage(
          symbolNorm,
          tfKey,
          fetchedLatest.bars,
        );
      }
      step.actions.push(latestAction);

      let currentAudit = await auditMarketDataForRefresh(tfKey);
      if (
        repairHistoryGaps === true &&
        !auditCoverageResolved(currentAudit) &&
        auditGapCount(currentAudit) > 0
      ) {
        const gapRepair = await repairCoverageGapsFromRemote({
          userId,
          symbol,
          symbolNorm,
          tfKey,
          startAudit: currentAudit,
          gapBufferBars: out.gap_buffer_bars,
          maxGapWindowsPerTf: out.max_gap_windows_per_tf,
        });
        step.actions.push(...gapRepair.actions);
        currentAudit = gapRepair.audit;
      } else if (
        repairHistoryGaps !== true &&
        auditGapCount(currentAudit) > 0
      ) {
        step.actions.push({
          type: "skip_historical_gap_repair",
          reason: "fast_refresh_mode",
          remaining_gap_count: auditGapCount(currentAudit),
        });
      }
      step.after = summarizeAuditState(currentAudit);
      step.coverage_resolved = auditCoverageResolved(currentAudit);
      step.refresh_ok = isStepSatisfiedForRefreshMode(
        currentAudit,
        tfKey,
        repairHistoryGaps,
      );
      previousTfKey = tfKey;
      out.timeframes.push(step);
      if (!step.refresh_ok && out.stop_on_unresolved && tfKey !== targetTfKey) {
        out.ok = false;
        out.stopped_at = tfKey;
        break;
      }
      continue;
    }

    if (!previousTfKey) {
      step.actions.push({
        type: "skip",
        reason: "missing_previous_timeframe",
      });
      step.after = summarizeAuditState(beforeAudit);
      out.timeframes.push(step);
      out.ok = false;
      out.stopped_at = tfKey;
      break;
    }

    const rebuildAction = await rebuildAndMergeTimeframeFromLower(
      symbolNorm,
      previousTfKey,
      tfKey,
    );
    step.actions.push({
      type: "rebuild_from_lower_tf",
      ...rebuildAction,
    });

    let currentAudit = await auditMarketDataForRefresh(tfKey);
    if (
      !auditCoverageResolved(currentAudit) &&
      auditBarCount(currentAudit) === 0
    ) {
      const fetchedLatest = await fetchRemoteBarsForTimeframe({
        userId,
        symbol,
        symbolNorm,
        tfKey,
        requestedBars: estimateLatestBarsForRepair(
          tfKey,
          currentAudit,
          out.latest_bars,
          repairHistoryGaps,
        ),
      });
      const latestAction = {
        type: "remote_latest_fetch",
        provider: fetchedLatest.provider,
        request: fetchedLatest.request,
        returned_bars: Array.isArray(fetchedLatest.bars)
          ? fetchedLatest.bars.length
          : 0,
        remote: fetchedLatest.meta,
      };
      if (Array.isArray(fetchedLatest.bars) && fetchedLatest.bars.length) {
        latestAction.merge = await mergeBarsDirectToStorage(
          symbolNorm,
          tfKey,
          fetchedLatest.bars,
        );
      }
      step.actions.push(latestAction);
      currentAudit = await auditMarketDataForRefresh(tfKey);
    }
    if (
      repairHistoryGaps === true &&
      !auditCoverageResolved(currentAudit) &&
      auditGapCount(currentAudit) > 0
    ) {
      const gapRepair = await repairCoverageGapsFromRemote({
        userId,
        symbol,
        symbolNorm,
        tfKey,
        startAudit: currentAudit,
        gapBufferBars: out.gap_buffer_bars,
        maxGapWindowsPerTf: out.max_gap_windows_per_tf,
      });
      step.actions.push(...gapRepair.actions);
      currentAudit = gapRepair.audit;
    } else if (
      repairHistoryGaps !== true &&
      auditGapCount(currentAudit) > 0
    ) {
      step.actions.push({
        type: "skip_historical_gap_repair",
        reason: "fast_refresh_mode",
        remaining_gap_count: auditGapCount(currentAudit),
      });
    }
    step.after = summarizeAuditState(currentAudit);
    step.coverage_resolved = auditCoverageResolved(currentAudit);
    step.refresh_ok = isStepSatisfiedForRefreshMode(
      currentAudit,
      tfKey,
      repairHistoryGaps,
    );
    out.timeframes.push(step);
    previousTfKey = tfKey;
    if (!step.refresh_ok && out.stop_on_unresolved && tfKey !== targetTfKey) {
      out.ok = false;
      out.stopped_at = tfKey;
      break;
    }
  }

  const finalStep =
    out.timeframes.length > 0 ? out.timeframes[out.timeframes.length - 1] : null;
  if (!finalStep?.refresh_ok) {
    out.ok = false;
  }
  return out;
}

// Merge live last_price into last bar's close for TV chart real-time display
function mergeLastPriceIntoBars(result) {
  if (!result || !Array.isArray(result.bars) || !result.bars.length)
    return result;
  const lp = Number(result.last_price);
  if (!Number.isFinite(lp) || lp <= 0) return result;
  const lastBar = result.bars[result.bars.length - 1];
  if (!lastBar || typeof lastBar !== "object") return result;
  const barTime = Number(lastBar.time);
  const lpTime = result.last_price_at
    ? Math.floor(new Date(result.last_price_at).getTime() / 1000)
    : 0;
  if (lpTime > 0 && lpTime < barTime) return result;
  const updated = { ...lastBar, close: lp };
  if (lp > (Number(lastBar.high) || 0)) updated.high = lp;
  if (lp < (Number(lastBar.low) || Infinity)) updated.low = lp;
  return { ...result, bars: [...result.bars.slice(0, -1), updated] };
}

async function upsertBrokerSymbolMetadataFromSnapshot({
  userId,
  symbol,
  snapshot,
  source = "chart_tf_api",
} = {}) {
  const symbolKey = normalizeMarketDataSymbol(symbol || snapshot?.symbol || snapshot?.symbol_norm);
  const lastPrice = asNum(snapshot?.last_price, null);
  if (!symbolKey || lastPrice == null || lastPrice <= 0) return null;
  const lastPriceAt =
    snapshot?.last_price_at ||
    snapshot?.fetched_at ||
    snapshot?.cached_at ||
    new Date().toISOString();
  const provider = String(
    snapshot?.metadata?.provider_code ||
      snapshot?.provider ||
      snapshot?.cache_source ||
      source ||
      "chart_tf_api",
  )
    .trim()
    .toLowerCase();
  const uid = String(userId || CFG.mt5DefaultUserId).trim() || CFG.mt5DefaultUserId;
  const row = await upsertBrokerSymbolMetadata(uid, {
    symbol: symbolKey,
    provider,
    account_id: "market_data",
    last_price: lastPrice,
    last_price_at: lastPriceAt,
    source,
  }, {
    account_id: "market_data",
    provider,
  }).catch(() => null);
  if (row) {
    emitBrokerSymbolMetadataRealtime({
      user_id: uid,
      account_id: "market_data",
      provider,
      source,
      symbols: [symbolKey],
    });
  }
  return row;
}

function tfNormToRefreshStatsKey(tfNorm = "") {
  const raw = String(tfNorm || "").trim().toLowerCase();
  if (raw === "1m" || raw === "1min") return "1m";
  if (raw === "5m" || raw === "5min") return "5m";
  if (raw === "15m" || raw === "15min") return "15m";
  if (raw === "1h" || raw === "60" || raw === "60m") return "1h";
  if (raw === "4h" || raw === "240" || raw === "240m") return "4h";
  if (raw === "1d" || raw === "1440" || raw === "day") return "1d";
  return raw;
}

function buildRefreshDisplayMetadata(tfNorm, canonicalRefresh, barsLength = 0) {
  const refresh = canonicalRefresh && typeof canonicalRefresh === "object"
    ? canonicalRefresh
    : {};
  const provider = String(refresh.provider || "").trim().toLowerCase();
  const fetchedSourceBars = Math.max(0, Number(refresh.fetched_source_bars || 0) || 0);
  const refreshReason = String(
    refresh.remote_reason ||
      refresh.last_error ||
      refresh.reason ||
      "",
  ).trim();
  const historyMetadata = {
    remote_reason: refreshReason || null,
    remote_attempted:
      String(refresh.direction || "").trim().toLowerCase() === "history"
        ? true
        : null,
    remote_refreshed: refresh.ok === true,
    remote_returned_bars: fetchedSourceBars,
    history_status:
      String(refresh.direction || "").trim().toLowerCase() === "history"
        ? refresh.ok === true && fetchedSourceBars > 0
          ? "merged"
          : "exhausted"
        : null,
  };
  const key = tfNormToRefreshStatsKey(tfNorm);
  const fetchTfKey = tfNormToRefreshStatsKey(refresh.fetch_tf || refresh.requested_tf);
  const rebuilt =
    refresh?.rebuilt && typeof refresh.rebuilt === "object"
      ? refresh.rebuilt[key]
      : null;
  if (key === fetchTfKey) {
    return {
      source_kind: provider === "binance" ? "binance" : "twelve",
      updated_bars: fetchedSourceBars || null,
      stored_bars: Number(refresh.stored_source_bars || 0) || null,
      ...historyMetadata,
    };
  }
  return {
    source_kind: provider === "binance" ? "binance" : "twelve",
    updated_bars: Number(rebuilt?.inserted_or_updated || 0) || null,
    stored_bars: Number(rebuilt?.stored_bars || 0) || null,
    merged_bars: Number(rebuilt?.merged_bars || 0) || null,
    ...historyMetadata,
  };
}

async function buildAnalysisSnapshotFromTwelve({
  userId,
  payload = {},
  symbol,
  timeframe,
  traceId,
}) {
  const outputsize = parseSnapshotBarsLimit(payload);
  const requestedEndTimeSec =
    Number(payload?.end_time_sec ?? payload?.endTimeSec ?? payload?.end_time_unix) || 0;
  const forceRefresh = asBool(
    payload?.force_refresh ?? payload?.forceRefresh ?? false,
    false,
  );
  const refreshDirection = normalizeBarsDownloadDirection(payload?.direction);
  const symbolNorm = normalizeMarketDataSymbol(symbol);
  const tfNorm = normalizeMarketDataTf(timeframe);
  const realtimeSnapshotTfs = forceRefresh
    ? [tfNorm, ...listHigherTimeframes(tfNorm)]
    : [];
  const realtimeSnapshotsBefore = realtimeSnapshotTfs.length
    ? captureChartRealtimeSnapshots(symbolNorm, realtimeSnapshotTfs)
    : null;
  const reqRange = estimateRequestedBarsRange({
    tfNorm,
    bars: outputsize,
    endTimeSec: requestedEndTimeSec,
  });
  const tradeSid = String(payload?.trade_sid ?? payload?.tradeSid ?? "").trim();

  const scopedTradeBars = (() => {
    if (!tradeSid) return [];
    const rawBars = readTradeBars(tradeSid, timeframe, symbolNorm, {
      limit: outputsize,
      endTimeSec: requestedEndTimeSec,
    });
    if (!Array.isArray(rawBars) || !rawBars.length) return [];
    const filteredBars = rawBars
      .filter((bar) => {
        const time = Number(bar?.time || 0);
        if (!Number.isFinite(time) || time <= 0) return false;
        if (Number.isFinite(requestedEndTimeSec) && requestedEndTimeSec > 0) {
          return time <= requestedEndTimeSec;
        }
        return true;
      })
      .sort((a, b) => Number(a?.time || 0) - Number(b?.time || 0));
    if (!filteredBars.length) return [];
    return outputsize > 0 ? filteredBars.slice(-outputsize) : filteredBars;
  })();

  if (scopedTradeBars.length) {
    return mergeLastPriceIntoBars(
      buildBrokerSnapshotFromBars(symbol, timeframe, tfNorm, scopedTradeBars, {
        metadata: {
          source_kind: "trade_bars",
          trade_sid: tradeSid,
          scoped_to_trade: true,
        },
      }),
    );
  }

  // Prefer locally persisted broker bars whenever available.
  // Even on "refresh", broker-fed local bars remain the source of truth for
  // intraday chart rendering; refresh should bypass remote caches, not bypass
  // trustworthy local broker data and replace it with a worse provider.
  const brokerBars = readBrokerBarsFromCsv(
    symbolNorm,
    tfNorm,
    outputsize,
    requestedEndTimeSec,
  );
  const brokerGapCandidates = detectMarketDataGapCandidates(brokerBars, tfNorm);
  const brokerBarsSynthetic = brokerBarsLookSynthetic(brokerBars, tfNorm);
  const brokerSnapshotForRequest =
    brokerBars.length && !brokerBarsSynthetic
      ? buildBrokerSnapshotFromBars(symbol, timeframe, tfNorm, brokerBars)
      : null;
  const hasAnchoredHistoricalRequest = Number.isFinite(requestedEndTimeSec) && requestedEndTimeSec > 0;
  if (hasAnchoredHistoricalRequest && brokerSnapshotForRequest) {
    tfCacheSet(symbolNorm, tfNorm, brokerSnapshotForRequest);
    await marketDataFileUpsert(symbolNorm, tfNorm, brokerSnapshotForRequest).catch(
      () => {},
    );
    return mergeLastPriceIntoBars(brokerSnapshotForRequest);
  }
  if (!forceRefresh && brokerBars.length && !brokerBarsSynthetic) {
    tfCacheSet(symbolNorm, tfNorm, brokerSnapshotForRequest);
    await marketDataFileUpsert(symbolNorm, tfNorm, brokerSnapshotForRequest).catch(
      () => {},
    );
    return mergeLastPriceIntoBars(brokerSnapshotForRequest);
  }
  if (brokerBars.length && brokerBarsSynthetic) {
    console.warn(
      `[twelve] IGNORE_SYNTHETIC_LOCAL_BARS sym=${symbolNorm} tf=${tfNorm} bars=${brokerBars.length}`,
    );
  }

  const tid = traceId || genTraceId("twelve_");
  console.log(
    `[twelve] START sym=${symbolNorm} tf=${tfNorm} force=${forceRefresh}`,
  );
  if (!symbolNorm)
    return {
      provider: "twelvedata",
      status: "skipped",
      reason: "invalid symbol",
    };

  if (forceRefresh) {
    const canonicalRefresh = await refreshSelectedTimeframeBars({
      userId,
      symbol,
      requestedTfNorm: tfNorm,
      requestedBars: outputsize,
      direction: refreshDirection,
      endTimeSec: requestedEndTimeSec,
    }).catch((error) => ({
      ok: false,
      reason: String(error?.message || error || "canonical_refresh_failed"),
    }));
    const refreshedBrokerBars = readBrokerBarsFromCsv(
      symbolNorm,
      tfNorm,
      outputsize,
      requestedEndTimeSec,
    );
    if (
      refreshedBrokerBars.length &&
      !brokerBarsLookSynthetic(refreshedBrokerBars, tfNorm)
    ) {
      const refreshDisplayMeta = buildRefreshDisplayMetadata(
        tfNorm,
        canonicalRefresh,
        refreshedBrokerBars.length,
      );
      const brokerSnapshot = buildBrokerSnapshotFromBars(
        symbol,
        timeframe,
        tfNorm,
        refreshedBrokerBars,
        {
          metadata: {
            refresh_mode: "canonical_1m",
            refresh_direction: refreshDirection,
            canonical_refresh: canonicalRefresh,
            ...refreshDisplayMeta,
          },
        },
      );
      tfCacheSet(symbolNorm, tfNorm, brokerSnapshot);
      await marketDataFileUpsert(symbolNorm, tfNorm, brokerSnapshot).catch(
        () => {},
      );
      if (realtimeSnapshotsBefore) {
        emitChartRealtimeDiffs(
          symbolNorm,
          realtimeSnapshotsBefore,
          realtimeSnapshotTfs,
        );
      }
      return mergeLastPriceIntoBars(brokerSnapshot);
    }
  }

  if (!forceRefresh) {
    // Check per-TF memory cache (TTL = TF duration)
    const cached = await tfCacheGet(symbolNorm, tfNorm);
    if (cached && cached.bars && cached.bars.length) {
      const s = Number(cached.bar_start || cached.bars[0].time);
      const e = Number(
        cached.bar_end || cached.bars[cached.bars.length - 1].time,
      );
      if (s <= reqRange.start && e >= reqRange.end) {
        return mergeLastPriceIntoBars(
          attachIndicatorDataToMarketSnapshot({
            ...cached,
            symbol: symbolNorm,
            symbol_norm: symbolNorm,
            timeframe: tfNorm,
            tf_norm: tfNorm,
            bar_start: s,
            bar_end: e,
            status: "ok",
            cache_source: "memory",
          }),
        );
      }
    }
    // Fallback to CSV files
    console.log(`[twelve] FILE_READ sym=${symbolNorm} tf=${tfNorm}`);
    let dbHit = null;
    try {
      dbHit = await marketDataFileRead(
        symbolNorm,
        tfNorm,
        reqRange.start,
        reqRange.end,
      );
    } catch (e) {
      console.error(`[twelve] FILE_ERROR: ${e.message}`);
      dbHit = null;
    }

    if (dbHit && Array.isArray(dbHit.bars) && dbHit.bars.length) {
      const enrichedDbHit = attachIndicatorDataToMarketSnapshot(dbHit);
      tfCacheSet(symbolNorm, tfNorm, enrichedDbHit);
      return mergeLastPriceIntoBars({
        ...enrichedDbHit,
        status: "ok",
        cache_source: "db",
        provider: enrichedDbHit.provider || brokerBarsCacheSourceLabel(),
        symbol_norm: symbolNorm,
        tf_norm: tfNorm,
      });
    }
  }

  // Crypto symbols: use Binance free API instead of Twelve Data
  const binanceResult = await fetchBinanceBars(symbolNorm, tfNorm, outputsize);
  if (binanceResult) {
    const enrichedBinanceResult =
      attachIndicatorDataToMarketSnapshot({
        ...binanceResult,
        metadata: {
          source_kind: "binance",
          file_type: "db",
          loaded_bars: Array.isArray(binanceResult?.bars)
            ? binanceResult.bars.length
            : 0,
          updated_bars: Array.isArray(binanceResult?.bars)
            ? binanceResult.bars.length
            : 0,
        },
      });
    if (notificationManager) {
      notificationManager.handle("REMOTE_API_CALL", "binance_success", {
        message: `Binance OK ${symbolNorm} ${tfNorm} ${enrichedBinanceResult.bars.length} bars`,
        api: "Binance",
        symbol: symbolNorm,
        tf: tfNorm,
        bars_count: enrichedBinanceResult.bars.length,
      });
    }
    tfCacheSet(symbolNorm, tfNorm, enrichedBinanceResult);
    await marketDataFileUpsert(symbolNorm, tfNorm, enrichedBinanceResult).catch(
      () => {},
    );
    return mergeLastPriceIntoBars(enrichedBinanceResult);
  }

  const twelvePool = await resolveApiKeyPool(userId, "TWELVE_DATA_API_KEY").catch(
    () => ({ availableEntries: [] }),
  );
  if (!twelvePool.availableEntries?.length)
    return {
      provider: "twelvedata",
      status: "skipped",
      reason: "TWELVE_DATA_API_KEY missing",
    };

  trackApiCall("TwelveData");

  const fetchTfNorm = tfNorm === "15m" ? "5m" : tfNorm;
  const fetchTimeframe = tfNorm === "15m" ? "5m" : timeframe;
  const fetchOutputsize =
    fetchTfNorm === "5m" && tfNorm === "15m"
      ? Math.min(
          CHART_HISTORY_DERIVED_SOURCE_MAX_BARS,
          Math.max(outputsize * 3, 300),
        )
      : outputsize;
  const interval = timeframeToTwelve(fetchTimeframe);
  const rawNoProvider = String(symbol || "")
    .trim()
    .toUpperCase()
    .includes(":")
    ? String(symbol || "")
        .trim()
        .toUpperCase()
        .split(":")
        .slice(1)
        .join(":")
        .trim()
        .toUpperCase()
    : String(symbol || "")
        .trim()
        .toUpperCase();
  const normalizedFallback = normalizeSymbolForTwelve(rawNoProvider);
  const compactFallback = rawNoProvider.replace(/[^A-Z0-9]/g, "");
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 14000);
  try {
    const t0 = Date.now();
    const { data, usedSymbol, lastError, primaryCandidates } =
      await withRotatingApiKeys(userId, "TWELVE_DATA_API_KEY", async (entry) => {
        const tvCandidates = await resolveTwelveSymbol(symbol, entry.api_key);
        if (!tvCandidates || !tvCandidates.length) {
          return {
            data: {},
            usedSymbol: symbol,
            lastError: "invalid symbol",
            primaryCandidates: [],
          };
        }
        const primaryCandidates = [...tvCandidates];
        if (normalizedFallback && !primaryCandidates.includes(normalizedFallback)) {
          primaryCandidates.push(normalizedFallback);
        }
        if (compactFallback && !primaryCandidates.includes(compactFallback)) {
          primaryCandidates.push(compactFallback);
        }
        console.log(
          `[twelve-fetch] symbol=${symbol} candidates=${primaryCandidates.join(",")} interval=${interval} bars=${fetchOutputsize} requested_tf=${tfNorm} fetch_tf=${fetchTfNorm}`,
        );

        let data = {};
        let usedSymbol = symbol;
        let lastError = "";
        for (const candidate of primaryCandidates) {
          const endpoint = `https://api.twelvedata.com/time_series?symbol=${encodeURIComponent(candidate)}&interval=${encodeURIComponent(interval)}&outputsize=${fetchOutputsize}&timezone=UTC&order=ASC&apikey=${encodeURIComponent(entry.api_key)}`;
          const res = await fetch(endpoint, { signal: ctrl.signal });
          const txt = await res.text();
          let parsed = {};
          try {
            parsed = JSON.parse(txt);
          } catch {}

          if (!res.ok) {
            lastError = `http_${res.status}: ${txt.slice(0, 100)}`;
            console.warn(
              `[twelve-candidate-fail] candidate=${candidate} error=${lastError}`,
            );
            if (isLikelyInvalidProviderKeyError({ status: res.status, message: txt })) {
              const invalidError = new Error(lastError);
              invalidError.status = res.status;
              throw invalidError;
            }
            continue;
          }
          if (String(parsed?.status || "").toLowerCase() === "error") {
            lastError = String(parsed?.message || "provider error");
            console.warn(
              `[twelve-candidate-error] candidate=${candidate} msg=${lastError}`,
            );
            if (isLikelyInvalidProviderKeyError(lastError)) {
              const invalidError = new Error(lastError);
              invalidError.status = 401;
              throw invalidError;
            }
            continue;
          }
          const vals = Array.isArray(parsed?.values) ? parsed.values : [];
          if (!vals.length) {
            lastError = "empty values";
            console.warn(`[twelve-candidate-empty] candidate=${candidate}`);
            continue;
          }
          data = parsed;
          usedSymbol = candidate;
          lastError = "";
          console.log(`[twelve-success] candidate=${candidate}`);
          if (notificationManager) {
            notificationManager.handle("REMOTE_API_CALL", "twelve_success", {
              message: `TwelveData OK ${symbolNorm} ${tfNorm} ${vals.length} bars`,
              api: "TwelveData",
              symbol: symbolNorm,
              tf: tfNorm,
              bars_count: vals.length,
            });
          }
          break;
        }
        return { data, usedSymbol, lastError, primaryCandidates };
      });
    if (!data || !Array.isArray(data?.values) || !data.values.length) {
      if (notificationManager) {
        notificationManager.handle("REMOTE_API_CALL", "twelve_error", {
          message: `TwelveData FAIL ${symbolNorm} ${tfNorm} ${lastError || "provider error"}`,
          api: "TwelveData",
          symbol: symbolNorm,
          tf: tfNorm,
          error: lastError,
        });
      }
      if (brokerBars.length && !brokerBarsSynthetic) {
        return mergeLastPriceIntoBars(
          buildBrokerSnapshotFromBars(symbol, timeframe, tfNorm, brokerBars, {
            metadata: {
              backfill_failed: true,
              backfill_failed_reason: lastError || "provider error",
              source_kind: "broker",
            },
          }),
        );
      }
      return {
        provider: "twelvedata",
        status: "error",
        reason: lastError || "provider error",
        tried_candidates: primaryCandidates,
      };
    }
    const values = Array.isArray(data?.values) ? data.values : [];
    const dedup = new Map();
    values
      .map((v) => {
        const t = parseTimeToUnixSec(v?.datetime);
        const o = Number(v?.open);
        const h = Number(v?.high);
        const l = Number(v?.low);
        const c = Number(v?.close);
        const volume = Number(v?.volume);
        if (
          !Number.isFinite(t) ||
          !Number.isFinite(o) ||
          !Number.isFinite(h) ||
          !Number.isFinite(l) ||
          !Number.isFinite(c)
        )
          return null;
        if (t > reqRange.end + reqRange.sec * 2) return null;
        const bar = { time: t, open: o, high: h, low: l, close: c };
        if (Number.isFinite(volume)) bar.volume = volume;
        return bar;
      })
      .filter(Boolean)
      .forEach((bar) => {
        dedup.set(bar.time, bar);
      });
    const bars = [...dedup.values()].sort((a, b) => a.time - b.time);
    const barStart = bars.length ? bars[0].time : null;
    const barEnd = bars.length
      ? bars[bars.length - 1].time + reqRange.sec
      : null;
    const snapshot = attachIndicatorDataToMarketSnapshot({
      provider: "twelvedata",
      status: "ok",
      timezone: "UTC",
      display_timezone: normalizeMarketDataTimezone(
        payload?.timezone || payload?.display_timezone,
      ),
      user_id: userId,
      setting_name: String(
        payload?.setting_name || payload?.settingName || "default",
      ),
      symbol: String(symbol || "").toUpperCase(),
      symbol_norm: symbolNorm,
      normalized_symbol: usedSymbol,
      timeframe: String(timeframe || ""),
      tf_norm: fetchTfNorm,
      interval,
      fetched_at: new Date().toISOString(),
      bar_start: barStart,
      bar_end: barEnd,
      last_price: bars.length ? bars[bars.length - 1].close : null,
      last_price_at: bars.length
        ? new Date(Number(bars[bars.length - 1].time) * 1000).toISOString()
        : null,
      bars,
      gap_candidates: detectMarketDataGapCandidates(bars, fetchTfNorm).slice(
        0,
        20,
      ),
      entry: Number.isFinite(Number(payload?.entry ?? payload?.price))
        ? Number(payload?.entry ?? payload?.price)
        : null,
      sl: Number.isFinite(Number(payload?.sl)) ? Number(payload?.sl) : null,
      tp: Number.isFinite(Number(payload?.tp)) ? Number(payload?.tp) : null,
      pd_arrays: parseSnapshotPdArrays(payload),
      key_levels: parseSnapshotKeyLevels(payload),
      summary: {
        profile: String(payload?.profile || "").trim(),
        bias: String(payload?.market_analysis?.bias || "").trim(),
        trend: String(payload?.market_analysis?.trend || "").trim(),
        confidence_pct: Number.isFinite(Number(payload?.confidence_pct))
          ? Number(payload.confidence_pct)
          : null,
        invalidation: String(payload?.invalidation || "").trim(),
        note: String(payload?.trade_plan?.note || payload?.note || "").trim(),
      },
      checklist: parseSnapshotChecklist(payload),
      metadata: {
        source_kind: "twelve",
        file_type: "db",
        loaded_bars: bars.length,
        updated_bars: bars.length,
      },
    });

    // Update Unified Cache
    tfCacheSet(symbolNorm, fetchTfNorm, snapshot);
    await marketDataFileUpsert(symbolNorm, fetchTfNorm, snapshot).catch(
      () => {},
    );

    const refreshedBrokerBars = readBrokerBarsFromCsv(
      symbolNorm,
      tfNorm,
      outputsize,
    );
    if (
      refreshedBrokerBars.length &&
      !brokerBarsLookSynthetic(refreshedBrokerBars, tfNorm)
    ) {
      const brokerSnapshot = buildBrokerSnapshotFromBars(
        symbol,
        timeframe,
        tfNorm,
        refreshedBrokerBars,
        {
          metadata: {
            backfilled_from: "twelvedata",
            backfill_fetch_tf: fetchTfNorm,
            backfill_fetch_bars: fetchOutputsize,
            backfill_requested_bars: outputsize,
            backfill_refreshed_at: new Date().toISOString(),
            source_kind: "twelve",
            updated_bars: fetchOutputsize,
          },
        },
      );
      tfCacheSet(symbolNorm, tfNorm, brokerSnapshot);
      await marketDataFileUpsert(symbolNorm, tfNorm, brokerSnapshot).catch(
        () => {},
      );
      return mergeLastPriceIntoBars(brokerSnapshot);
    }

    return mergeLastPriceIntoBars(snapshot);
  } catch (error) {
    const reason =
      error?.name === "AbortError"
        ? "timeout"
        : String(error?.message || error || "fetch_failed");
    if (brokerBars.length && !brokerBarsSynthetic) {
      return mergeLastPriceIntoBars(
        buildBrokerSnapshotFromBars(symbol, timeframe, tfNorm, brokerBars, {
          metadata: {
            backfill_failed: true,
            backfill_failed_reason: reason,
          },
        }),
      );
    }
    return { provider: "twelvedata", status: "error", reason };
  } finally {
    clearTimeout(timer);
  }
}

async function mt5EnqueueSignalFromPayload(payload, opts = {}) {
  const source = String(payload.source || opts.source || "tradingview");
  const eventType = String(opts.eventType || "QUEUED");
  const sourceId = mt5SlugId(source, "tradingview");

  const action = mt5NormalizeAction(payload);
  const symbol = mt5NormalizeSymbol(payload);
  const volume = mt5NormalizeVolume(payload);
  const orderType = mt5NormalizeOrderType(payload);
  const userId = envStr(
    payload.user_id ?? payload.userId ?? payload.user ?? CFG.mt5DefaultUserId,
    CFG.mt5DefaultUserId,
  );
  const rrPlanned = asNum(payload.rr ?? payload.risk_reward, null);
  const riskMoneyPlanned = asNum(
    payload.risk_money ?? payload.money_risk ?? payload.riskMoney,
    null,
  );
  const riskPctPlanned = asNum(
    payload.risk_pct ??
      payload.riskPct ??
      payload.risk_percent ??
      payload.riskPercent ??
      payload.vol ??
      payload.volume ??
      payload.lots ??
      payload.volume_pct ??
      payload.volumePct,
    null,
  );
  const signalTf = mt5TfToMinutes(
    payload.trade_tf ??
      payload.signalTf ??
      payload.sourceTf ??
      payload.timeframe ??
      payload.tf,
  );
  const chartTf = mt5TfToMinutes(
    payload.chart_tf ??
      payload.chartTf ??
      payload.chartTimeframe ??
      payload.chart_tf_period,
  );
  const rawJson = payload.raw_json || payload;
  const strategy =
    String(
      payload.strategy || rawJson?.strategy || opts.strategy || "",
    ).trim() || null;
  const derived = mt5DeriveEntryModelAndNote(payload, {
    fallbackModel: strategy || source || "MANUAL",
  });
  const entryModel = derived.entryModel;
  const note = derived.note;
  const onlySignal = Boolean(
    payload.only_signal ??
    payload.onlySignal ??
    payload.raw_json?.only_signal ??
    payload.raw_json?.onlySignal,
  );

  const plannedEntry = asNum(payload.entry ?? payload.price, NaN);
  const plannedSl = asNum(payload.sl, NaN);
  const tpNorm = mt5NormalizeTpFields(payload, mt5MapActionToSide(action));
  const plannedTp = asNum(tpNorm.tp ?? payload.tp, NaN);
  const duplicate = await mt5FindDuplicateSignal({
    user_id: userId,
    symbol,
    entry: plannedEntry,
    sl: plannedSl,
    tp: plannedTp,
  });
  if (duplicate?.sid) {
    throw new Error("Already added");
  }
  const sessionPrefix = sanitizeSessionPrefix(
    payload.session_prefix ||
      payload.sessionPrefix ||
      rawJson?.session_prefix ||
      rawJson?.sessionPrefix ||
      "",
  );
  const sidBaseFromPayload = String(
    payload.sid ||
      payload.trade_id ||
      payload.signal_id ||
      rawJson?.sid ||
      rawJson?.trade_id ||
      rawJson?.signal_id ||
      "",
  ).trim();
  const tradeSid = sidBaseFromPayload
    ? normalizePublicSidBase(sidBaseFromPayload, "TRD")
    : mt5GenerateTimeSid();
  let rawJsonNormalized = {
    ...rawJson,
    session_prefix: sessionPrefix || undefined,
    order_type: orderType,
    entry_model:
      entryModel ||
      mt5NormalizeEntryModel(rawJson.entry_model ?? rawJson.entryModel ?? "", {
        fallback: source,
      }),
    entry_model_raw:
      derived.entryModelRaw ||
      mt5CollapseWhitespace(rawJson.entry_model ?? rawJson.entryModel ?? "") ||
      null,
  };

  const hasRisk =
    rawJsonNormalized.riskPct != null ||
    rawJsonNormalized.risk_pct != null ||
    rawJsonNormalized.volumePct != null ||
    rawJsonNormalized.volume_pct != null;
  if (!hasRisk) {
    rawJsonNormalized.riskPct = 1.0;
  }
  // Strip sensitive credentials before persisting to DB.
  delete rawJsonNormalized.apiKey;
  delete rawJsonNormalized.api_key;
  delete rawJsonNormalized.password;
  delete rawJsonNormalized.token;
  await mt5UpsertSourceV2({
    source_id: sourceId,
    name: source,
    kind: sourceId.includes("tv") ? "tv" : "api",
    auth_mode: "token",
    is_active: true,
    metadata: {
      migrated_from: "signal_trade_cutover",
      signal_source: source,
    },
  }).catch(() => null);

  const fanout = await mt5FanoutSignalTradeV2({
    trade_id: tradeSid,
    source_id: sourceId,
    user_id: userId,
    strategy: strategy || null,
    entry_model: entryModel || null,
    trade_tf: signalTf || null,
    chart_tf: chartTf || null,
    symbol,
    action: mt5MapActionToSide(action),
    order_type: orderType,
    entry:
      Number.isFinite(plannedEntry) && plannedEntry > 0 ? plannedEntry : null,
    sl: payload.sl ?? null,
    tp: Number.isFinite(tpNorm.tp) ? tpNorm.tp : payload.tp ?? null,
    tp1: Number.isFinite(tpNorm.tp1) ? tpNorm.tp1 : null,
    tp2: Number.isFinite(tpNorm.tp2) ? tpNorm.tp2 : null,
    tp3: Number.isFinite(tpNorm.tp3) ? tpNorm.tp3 : null,
    tp_targets: Array.isArray(tpNorm.tp_targets) ? tpNorm.tp_targets : [],
    volume: volume ?? null,
    rr_planned: Number.isFinite(rrPlanned) ? rrPlanned : null,
    risk_money_planned: Number.isFinite(riskMoneyPlanned)
      ? riskMoneyPlanned
      : null,
    risk_pct_planned: Number.isFinite(riskPctPlanned) ? riskPctPlanned : null,
    note: note || null,
    sid: tradeSid,
    session_prefix: sessionPrefix || null,
    metadata: {
      event_type: eventType,
      order_type: orderType,
      trade_tf: signalTf || null,
      chart_tf: chartTf || null,
      provider: payload.provider || null,
      entry_model_raw: derived.entryModelRaw || null,
      session_prefix: sessionPrefix || null,
      only_signal_requested: onlySignal,
      analysis_snapshot:
        rawJsonNormalized?.analysis_snapshot &&
        typeof rawJsonNormalized.analysis_snapshot === "object"
          ? rawJsonNormalized.analysis_snapshot
          : null,
      raw_json: rawJsonNormalized,
    },
  });

  for (const sid of fanout?.sids || []) {
    await mt5Log(
      sid,
      "trades",
      {
        event_type: eventType,
        source,
        trade_id: tradeSid,
        only_signal_requested: onlySignal,
      },
      userId,
    ).catch(() => {});
  }

  await StateRepo.del("SIGNALS_PENDING", "all");
  if (userId) await StateRepo.del("SIGNALS_PENDING", userId);

  return {
    trade_id: tradeSid,
    signal_id: tradeSid,
    sid: fanout?.sids?.[0] || tradeSid,
    action,
    symbol,
    created: fanout?.created || 0,
    sids: fanout?.sids || [],
    status: (fanout?.created || 0) > 0 ? "NEW" : "SKIPPED",
  };
}

function mt5NormalizeUiSource(rawSource, fallback = "ui_manual") {
  const input = String(rawSource || "")
    .trim()
    .toLowerCase();
  if (!input) return fallback;
  if (input === "ai") return "ai_claude";
  if (input.startsWith("ai_")) return input;
  if (input === "ui" || input === "manual" || input === "ui_manual")
    return "ui_manual";
  return (
    input
      .replace(/[^a-z0-9_/-]+/g, "_")
      .replace(/_+/g, "_")
      .replace(/^_+|_+$/g, "") || fallback
  );
}

function mt5NormalizeAckStatus(value) {
  const s = String(value || "")
    .trim()
    .toUpperCase();
  if (!s) throw new Error("status is required");
  const legacyToCurrent = {
    DONE: "PLACED",
    FAILED: "FAIL",
    PENDING: "PLACED",
    STARTED: "START",
    CANCELED: "CANCEL",
    CANCELLED: "CANCEL",
    CLOSED_TP: "TP",
    CLOSED_SL: "SL",
    CLOSED_MANUAL: "CANCEL",
    CLOSED: "PLACED",
  };
  const normalized = legacyToCurrent[s] || s;
  const allowed = [
    "FAIL",
    "START",
    "TP",
    "SL",
    "CANCEL",
    "EXPIRED",
    "PLACED",
    "SL_CHANGED",
    "PARTIAL_CLOSE",
  ];
  if (!allowed.includes(normalized)) {
    throw new Error(
      "status must be one of: FAIL, START, TP, SL, CANCEL, EXPIRED, PLACED, SL_CHANGED, PARTIAL_CLOSE",
    );
  }
  return normalized;
}

function mt5StatusToInternal(status) {
  return mt5NormalizeAckStatus(status);
}

function mt5CanonicalStoredStatus(value) {
  const s = String(value || "")
    .trim()
    .toUpperCase();
  if (!s) return "";
  const legacyToCurrent = {
    DONE: "PLACED",
    FAILED: "FAIL",
    CANCELED: "CANCEL",
    CANCELLED: "CANCEL",
    CLOSED_TP: "TP",
    CLOSED_SL: "SL",
    CLOSED_MANUAL: "CANCEL",
    OK: "PLACED",
  };
  return legacyToCurrent[s] || s;
}

function mt5TicketCandidates(raw = {}) {
  const out = [];
  const push = (value) => {
    const v = String(value ?? "").trim();
    if (v && !out.includes(v)) out.push(v);
  };
  push(raw.ticket);
  push(raw.ticket_number);
  push(raw.broker_trade_id);
  push(raw.position_ticket);
  push(raw.position_id);
  push(raw.broker_position_id);
  push(raw.deal_ticket);
  push(raw.deal_id);
  push(raw.broker_deal_id);
  push(raw.order_ticket);
  push(raw.order_id);
  push(raw.broker_order_id);
  return out;
}

function mt5CloseReasonFromSync(raw = {}) {
  const status = String(raw.status || raw.execution_status || "")
    .trim()
    .toUpperCase();
  // When status is generic CLOSED, use close_reason/reason for specificity (e.g. cTrader bridge sends close_reason=TP|SL|MANUAL_CLOSE)
  const s =
    status === "CLOSED" || !status
      ? String(raw.close_reason || raw.reason || status || "")
          .trim()
          .toUpperCase()
      : status;
  if (s === "TP" || s === "DEAL_REASON_TP") return "TP";
  if (
    s === "SL" ||
    s === "SO" ||
    s === "DEAL_REASON_SL" ||
    s === "DEAL_REASON_SO"
  )
    return "SL";
  if (
    [
      "CANCEL",
      "CANCELLED",
      "CLIENT",
      "MOBILE",
      "EXPERT",
      "MANUAL",
      "MANUAL_CLOSE",
      "DEAL_REASON_CLIENT",
      "DEAL_REASON_MOBILE",
      "DEAL_REASON_EXPERT",
    ].includes(s)
  )
    return "MANUAL";
  if (s === "EXPIRED") return "EXPIRED";
  if (s === "FAIL" || s === "FAILED") return "FAIL";
  return null;
}

function mt5SyncTime(value) {
  if (value === null || value === undefined || value === "") return null;
  if (typeof value === "number" && Number.isFinite(value))
    return new Date(value * 1000).toISOString();
  const s = String(value).trim();
  if (/^\d+$/.test(s)) return new Date(Number(s) * 1000).toISOString();
  const t = Date.parse(s);
  return Number.isFinite(t) ? new Date(t).toISOString() : null;
}

function mt5SyncPrice(...values) {
  for (const value of values) {
    const n = Number(value);
    if (Number.isFinite(n) && n > 0) return n;
  }
  return null;
}

function mt5ResolveOpenedAtFromPayload(raw = {}) {
  return mt5SyncTime(
    raw.opened_at ??
      raw.openedAt ??
      raw.open_time ??
      raw.openTime ??
      raw.opened_time ??
      raw.time_open ??
      raw.exec_ts ??
      raw.execTs ??
      null,
  );
}

function mt5ResolveClosedAtFromPayload(raw = {}) {
  return mt5SyncTime(
    raw.closed_at ??
      raw.closedAt ??
      raw.close_time ??
      raw.closeTime ??
      raw.closed_time ??
      raw.time_close ??
      raw.time ??
      null,
  );
}

function mt5ResolveExitPriceFromPayload(raw = {}, options = {}) {
  const allowGenericPrice = options.allowGenericPrice === true;
  return mt5SyncPrice(
    raw.exit_price,
    raw.exitPrice,
    raw.close_price,
    raw.closePrice,
    raw.price_close,
    raw.close_exec,
    raw.deal_price,
    raw.fill_price,
    raw.execution_price,
    allowGenericPrice ? raw.price_current : null,
    allowGenericPrice ? raw.price : null,
  );
}

function mt5BuildBrokerSyncItems(payload = {}) {
  const merged = new Map();
  const seenTickets = new Set();
  const statusRank = (s) => {
    if (s === "CLOSED") return 3;
    if (s === "FILLED") return 2;
    return 1;
  };
  const pushItems = (arr = []) => {
    for (const item of Array.isArray(arr) ? arr : []) {
      const raw =
        item && typeof item === "string"
          ? (() => {
              try {
                return JSON.parse(item);
              } catch {
                return null;
              }
            })()
          : item;
      if (!raw || typeof raw !== "object") continue;
      const signalId = String(raw.sid || raw.trade_id || raw.signal_id || "").trim();
      const ticketCandidates = mt5TicketCandidates(raw);
      const ticket = ticketCandidates[0] || null;
      if (!signalId && !ticketCandidates.length) continue;
      for (const candidate of ticketCandidates) seenTickets.add(candidate);
      const pnlRaw = Number(raw.pnl);
      const pnl = Number.isFinite(pnlRaw) ? pnlRaw : null;
      const volumeRaw = Number(raw.volume || raw.lots);
      const volume = Number.isFinite(volumeRaw) ? volumeRaw : null;
      const entryRaw = Number(
        raw.entry ??
          raw.entry_price ??
          raw.target_price ??
          raw.price ??
          raw.entry_exec,
      );
      const entry = Number.isFinite(entryRaw) && entryRaw > 0 ? entryRaw : null;
      const slRaw = Number(raw.sl ?? raw.stop_loss ?? raw.sl_price);
      const sl = Number.isFinite(slRaw) && slRaw > 0 ? slRaw : null;
      const tpRaw = Number(
        raw.tp ?? raw.take_profit ?? raw.tp_price ?? raw.target_tp,
      );
      const tp = Number.isFinite(tpRaw) && tpRaw > 0 ? tpRaw : null;
      const symbol = String(raw.symbol || "").trim().toUpperCase();
      const action = String(raw.action || raw.side || "").trim().toUpperCase();
      const orderTypeRaw = String(raw.order_type || raw.type || "")
        .trim()
        .toUpperCase();
      const closeReason = mt5CloseReasonFromSync(raw);
      const openedAt = mt5ResolveOpenedAtFromPayload(raw);
      const closedAt = mt5ResolveClosedAtFromPayload(raw);
      let statusRaw = String(raw.status || "").trim().toUpperCase();
      if (!statusRaw) {
        if (closedAt || raw.close_reason) statusRaw = "CLOSED";
        else statusRaw = "FILLED";
      }
      let executionStatus = "PENDING";
      const s = String(statusRaw || "").toUpperCase();
      const remainingVolume = Number(
        raw.remaining_volume ?? raw.volume_remaining ?? NaN,
      );
      const closedVolumePartial = Number(
        raw.closed_volume_partial ?? raw.partial_closed_volume ?? NaN,
      );
      const hasPartial =
        Number.isFinite(remainingVolume) ||
        Number.isFinite(closedVolumePartial) ||
        Number.isFinite(Number(raw.realized_pnl_partial ?? NaN)) ||
        Number.isFinite(Number(raw.realized_pnl_total ?? NaN));

      if (["START", "ACTIVE", "OPEN", "FILLED", "EXECUTED"].includes(s)) {
        executionStatus = TRADE_STATUS.LIVE;
      } else if (
        ["PLACED", "NEW", "PENDING", "SUBMITTED", "PARTIAL"].includes(s)
      ) {
        executionStatus = "PENDING";
      } else if (
        [
          "TP",
          "SL",
          "CANCEL",
          "FAIL",
          "CLOSED",
          "EXPIRED",
          "REJECTED",
          "DELETED",
        ].includes(s)
      ) {
        executionStatus = "CLOSED";
      }
      if (
        executionStatus === "CLOSED" &&
        Number.isFinite(remainingVolume) &&
        remainingVolume > 0
      ) {
        executionStatus = TRADE_STATUS.LIVE;
      }
      const exitPrice = mt5ResolveExitPriceFromPayload(raw, {
        allowGenericPrice:
          executionStatus === "CLOSED" ||
          Boolean(closedAt) ||
          Boolean(closeReason),
      });
      const channel = String(
        raw.source_id ??
          raw.source ??
          raw.channel ??
          raw.Channel ??
          raw.channel_name ??
          raw.channelName ??
          "",
      ).trim();
      const label = String(raw.label ?? raw.Label ?? "").trim();
      const comment = String(raw.comment ?? raw.Comment ?? "").trim();
      const commentSid = mt5ExtractBrokerCommentSid(comment);
      const note = comment || label;
      const strategy =
        String(raw.strategy ?? raw.Strategy ?? "").trim() ||
        (mt5LooksLikeBrokerStrategyLabel(label, signalId, comment) ? label : "") ||
        "manual";
      const sidText = String(signalId || commentSid || "");
      const brokerSidCandidate = sidText
        .replace(/[^a-zA-Z0-9]/g, "")
        .toUpperCase();
      const effectiveSignalId =
        brokerSidCandidate.length === 9 ? brokerSidCandidate : "";
      const key = ticket ? `tk:${ticket}` : `sig:${effectiveSignalId}`;
      const next = {
        sid: effectiveSignalId || null,
        trade_id: effectiveSignalId || null,
        signal_id: effectiveSignalId || null,
        ticket,
        ticket_candidates: ticketCandidates,
        pnl: Number(raw.realized_pnl_total ?? raw.pnl ?? raw.net_pnl ?? 0),
        net_pnl: Number(raw.realized_pnl_total ?? raw.pnl ?? raw.net_pnl ?? 0),
        pnl_realized: raw.status === "CLOSED" ? Number(raw.pnl ?? 0) : null,
        commission: Number(raw.commission ?? 0),
        swap: Number(raw.swap ?? 0),
        pips: Number(raw.pips ?? 0),
        lots:
          Number(raw.lots) ||
          (Number(raw.volume || 0) > 0 ? Number(raw.volume || 0) / 100000 : 0),
        volume:
          Number(raw.lots) ||
          (Number(raw.volume || 0) > 0 ? Number(raw.volume || 0) / 100000 : 0),
        broker_volume: Number(raw.volume || 0),
        symbol,
        action,
        order_type: orderTypeRaw || null,
        entry,
        sl,
        tp,
        tp1:
          tp !== null && !Number.isFinite(Number(raw.tp1))
            ? tp
            : Number.isFinite(Number(raw.tp1))
              ? Number(raw.tp1)
              : null,
        tp2: Number.isFinite(Number(raw.tp2)) ? Number(raw.tp2) : null,
        tp3: Number.isFinite(Number(raw.tp3)) ? Number(raw.tp3) : null,
        note,
        comment: comment || null,
        label: label || null,
        channel: channel || null,
        source_id: channel || null,
        source: channel || null,
        strategy,
        status_raw: statusRaw || "UNKNOWN",
        execution_status: executionStatus,
        close_reason: closeReason,
        opened_at: openedAt,
        closed_at: closedAt,
        exit_price: exitPrice,
        has_partial: hasPartial,
        margin: Number(raw.margin) || 0,
        tp_pnl: Number.isFinite(Number(raw.tp_pnl ?? raw.pnl_tp))
          ? Number(raw.tp_pnl ?? raw.pnl_tp)
          : null,
        sl_pnl: Number.isFinite(Number(raw.sl_pnl ?? raw.pnl_sl))
          ? Number(raw.sl_pnl ?? raw.pnl_sl)
          : null,
      };
      const prev = merged.get(key);
      if (!prev) {
        merged.set(key, next);
      } else {
        Object.assign(prev, next);
        if (
          statusRank(next.execution_status) > statusRank(prev.execution_status)
        ) {
          prev.execution_status = next.execution_status;
          prev.status_raw = next.status_raw;
        }
        prev.ticket_candidates = Array.from(
          new Set([...(prev.ticket_candidates || []), ...ticketCandidates]),
        );
      }
    }
  };

  pushItems(payload.positions);
  pushItems(payload.orders);
  pushItems(payload.closed);
  pushItems(payload.closed_positions);
  pushItems(payload.deals);
  return {
    items: Array.from(merged.values()),
    seenTickets,
    snapshotComplete:
      Array.isArray(payload?.positions) && Array.isArray(payload?.orders),
  };
}

function mt5IsRetryableConnectivityFail(status, errorText) {
  const st = mt5CanonicalStoredStatus(status);
  if (st !== "FAIL") return false;
  const msg = String(errorText || "").toLowerCase();
  return (
    msg.includes("retcode=10031") ||
    msg.includes("no connection") ||
    msg.includes("trade server") ||
    msg.includes("off quotes")
  );
}

function mt5PublicState(row) {
  const status = mt5CanonicalStoredStatus(row.status);
  const ackStatus = row.ack_status
    ? mt5CanonicalStoredStatus(row.ack_status)
    : null;
  const updatedAt = [
    row.closed_at,
    row.opened_at,
    row.ack_at,
    row.locked_at,
    row.created_at,
  ]
    .map((v) => {
      const t = Date.parse(String(v || ""));
      return Number.isFinite(t) ? t : NaN;
    })
    .filter((t) => Number.isFinite(t))
    .sort((a, b) => b - a)[0];
  let stage = "unknown";
  if (status === "NEW") stage = "queued";
  else if (status === "LOCKED") stage = "pulled_by_mt5";
  else if (status === "START") stage = "position_active";
  else if (status === "PLACED") stage = "ack_placed";
  else if (status === "FAIL") stage = "execute_failed";
  else if (status === "TP") stage = "take_profit_hit";
  else if (status === "SL") stage = "stop_loss_hit";
  else if (status === "CANCEL") stage = "manually_cancelled";
  else if (status === "EXPIRED") stage = "expired_ignored";

  return {
    ...row,
    status,
    ack_status: ackStatus,
    updated_at: Number.isFinite(updatedAt)
      ? new Date(updatedAt).toISOString()
      : null,
    stage,
    is_open_candidate:
      status === "NEW" ||
      status === "LOCKED" ||
      status === "START" ||
      status === "PLACED",
    dedupe_safe: status !== "NEW",
  };
}

function mt5TerminalStatuses() {
  return ["FAIL", "TP", "SL", "CANCEL", "EXPIRED"];
}

function mt5LegacySignalStatusFromTrade(row = {}) {
  const execStatus = String(
    row.executionStatus || row.execution_status || "",
  )
    .trim()
    .toUpperCase();
  const dispatchStatus = String(
    row.dispatchStatus || row.dispatch_status || "",
  )
    .trim()
    .toUpperCase();
  const closeReason = String(row.closeReason || row.close_reason || "")
    .trim()
    .toUpperCase();
  if (execStatus === "REJECTED") return "FAIL";
  if (execStatus === "CANCELLED") return closeReason === "EXPIRED" ? "EXPIRED" : "CANCEL";
  if (execStatus === "CLOSED") {
    if (closeReason === "TP") return "TP";
    if (closeReason === "SL") return "SL";
    if (closeReason === "EXPIRED") return "EXPIRED";
    return "CANCEL";
  }
  if (execStatus === "FILLED") return "START";
  if (dispatchStatus === "LEASED") return "LOCKED";
  if (String(row.brokerTradeId || row.broker_trade_id || "").trim()) return "PLACED";
  return "NEW";
}

function mt5LegacySignalRowFromTrade(row = {}) {
  const rawJson = dbQueries.parseJsonField(row.rawJson || row.raw_json) || {};
  const metadata = dbQueries.parseJsonField(row.metadata) || {};
  const status = mt5LegacySignalStatusFromTrade(row);
  const tradeId = row.tradeId || row.trade_id || row.signalId || row.signal_id || row.sid;
  const tradeTf = row.tradeTf || row.trade_tf || row.signalTf || row.trade_tf || null;
  return {
    ...row,
    sid: row.sid,
    trade_id: tradeId,
    signal_id: tradeId,
    status,
    ack_status: status === "START" ? "PLACED" : status,
    ack_ticket: row.brokerTradeId || row.broker_trade_id || "",
    pnl_money_realized: row.pnlRealized ?? row.pnl_realized ?? null,
    action: row.action || row.side || "",
    side: row.action || row.side || "",
    order_type: row.orderType || row.order_type || rawJson.order_type || null,
    trade_tf: tradeTf,
    trade_tf: tradeTf,
    chart_tf: row.chartTf || row.chart_tf || null,
    rr_planned: row.rrPlanned || row.rr_planned || null,
    risk_pct_planned: row.riskPctPlanned || row.risk_pct_planned || null,
    created_at: row.createdAt || row.created_at || null,
    opened_at: row.openedAt || row.opened_at || null,
    closed_at: row.closedAt || row.closed_at || null,
    exit_price:
      row.exitPrice ??
      row.exit_price ??
      metadata.exit_price ??
      metadata.broker_data?.exit_price ??
      metadata.close_price ??
      metadata.broker_data?.close_price ??
      null,
    raw_json: rawJson,
    metadata,
  };
}

