async function mt5AckTrade(tradeId, status, ticket, error, extra = {}) {
  const s = String(status || "").trim().toUpperCase();
  let executionStatus = "PENDING";
  let closeReason = null;
  if (["PLACED", "NEW", "LOCKED"].includes(s)) executionStatus = "PENDING";
  else if (["START", "PARTIAL_CLOSE", "SL_CHANGED"].includes(s))
    executionStatus = "FILLED";
  else if (["TP", "SL"].includes(s)) {
    executionStatus = "CLOSED";
    closeReason = s;
  } else if (["CANCEL", "CANCELLED", "EXPIRED"].includes(s)) {
    executionStatus = "CANCELLED";
    closeReason = s === "CANCELLED" ? "CANCEL" : s;
  } else if (s === "FAIL") {
    executionStatus = "REJECTED";
    closeReason = "FAIL";
  }
  const out = await mt5ApplySignalAckGlobal(tradeId, null, {
    execution_status: executionStatus,
    broker_trade_id: ticket || "",
    pnl_realized: extra.pnl_money_realized ?? extra.pnl ?? null,
    is_closed: ["CLOSED", "CANCELLED", "REJECTED"].includes(executionStatus),
    order_type: extra.order_type || null,
    opened_at: extra.opened_at || null,
    closed_at: extra.closed_at || null,
    exit_price: extra.exit_price ?? null,
    entry_price_exec: extra.entry_price_exec ?? null,
    entry_exec: extra.entry_price_exec ?? null,
    sl_exec: extra.sl_exec ?? extra.used_sl ?? null,
    tp_exec: extra.tp_exec ?? extra.used_tp ?? null,
    requested_sl: extra.requested_sl ?? null,
    requested_tp: extra.requested_tp ?? null,
    used_sl: extra.used_sl ?? extra.sl_exec ?? null,
    used_tp: extra.used_tp ?? extra.tp_exec ?? null,
    sl_pips: extra.sl_pips ?? null,
    tp_pips: extra.tp_pips ?? null,
    pip_value_per_lot: extra.pip_value_per_lot ?? null,
    risk_money_actual: extra.risk_money_actual ?? null,
    reward_money_planned: extra.reward_money_planned ?? null,
    metadata: {
      sl_pips: extra.sl_pips ?? null,
      tp_pips: extra.tp_pips ?? null,
      pip_value_per_lot: extra.pip_value_per_lot ?? null,
      risk_money_actual: extra.risk_money_actual ?? null,
      reward_money_planned: extra.reward_money_planned ?? null,
      entry_price_exec: extra.entry_price_exec ?? null,
      exit_price: extra.exit_price ?? null,
      sl_exec: extra.sl_exec ?? extra.used_sl ?? null,
      tp_exec: extra.tp_exec ?? extra.used_tp ?? null,
      requested_sl: extra.requested_sl ?? null,
      requested_tp: extra.requested_tp ?? null,
      used_sl: extra.used_sl ?? extra.sl_exec ?? null,
      used_tp: extra.used_tp ?? extra.tp_exec ?? null,
      ack_error: error || null,
      last_ack_telemetry_at: new Date().toISOString(),
    },
  });
  if (out?.ok && out?.item) {
    await mt5AppendTradeEvent(tradeId, "TRADE_EA_ACK", {
      status: s,
      ticket,
      error,
      user_id: out.item.userId || out.item.user_id || CFG.mt5DefaultUserId,
    });
  }
  return { ok: Boolean(out?.ok) };
}

const mt5AckSignal = mt5AckTrade;

async function mt5ListSignals(limit, statusFilter, userId = null) {
  const safeLimit = Math.max(1, Number(limit) || 200);
  const filterObj =
    typeof statusFilter === "string"
      ? { status: statusFilter }
      : statusFilter && typeof statusFilter === "object"
        ? statusFilter
        : {};
  const rows = await mt5ListTradesGlobal(
    {
      user_id: userId || filterObj.user_id || undefined,
      symbol: filterObj.symbol || undefined,
      q: filterObj.q || undefined,
    },
    userId || filterObj.user_id || null,
  );
  const wantedStatuses =
    typeof statusFilter === "string"
      ? [statusFilter]
      : String(filterObj.status || "")
          .split(",")
          .map((value) => mt5CanonicalStoredStatus(value))
          .filter(Boolean);
  let filteredRows = rows;
  if (wantedStatuses.length) {
    const allowed = new Set(wantedStatuses);
    filteredRows = rows.filter((row) =>
      allowed.has(
        mt5CanonicalStoredStatus(
          row.executionStatus || row.execution_status || row.status,
        ),
      ),
    );
  }
  let items = filteredRows.map(mt5LegacySignalRowFromTrade);
  items.sort((a, b) =>
    String(b.updated_at || b.closed_at || b.created_at || "").localeCompare(
      String(a.updated_at || a.closed_at || a.created_at || ""),
    ),
  );
  return items.slice(0, safeLimit);
}

async function mt5CleanupSignalTradeArtifacts({
  signalRows = [],
  tradeRows = [],
  signalIds = [],
  tradeIds = [],
} = {}) {
  const sigIdSet = new Set(
    (Array.isArray(signalIds) ? signalIds : [])
      .map((x) => String(x || "").trim())
      .filter(Boolean),
  );
  const trdIdSet = new Set(
    (Array.isArray(tradeIds) ? tradeIds : [])
      .map((x) => String(x || "").trim())
      .filter(Boolean),
  );
  const signalRowsArr = Array.isArray(signalRows) ? signalRows : [];
  const tradeRowsArr = Array.isArray(tradeRows) ? tradeRows : [];

  for (const row of signalRowsArr) {
    const sid = String(row?.sid || "").trim();
    if (sid) sigIdSet.add(sid);
  }
  for (const row of tradeRowsArr) {
    const tid = String(row?.sid || "").trim();
    const sid = String(row?.sid || "").trim();
    if (tid) trdIdSet.add(tid);
    if (sid) sigIdSet.add(sid);
  }

  const signalIdList = [...sigIdSet];
  const tradeIdList = [...trdIdSet];

  const fileSet = new Set();
  for (const row of signalRowsArr) {
    collectSnapshotFilesFromValue(row?.raw_json, fileSet);
  }
  for (const row of tradeRowsArr) {
    collectSnapshotFilesFromValue(row?.metadata, fileSet);
  }

  const b = await mt5Backend().catch(() => null);
  if (b?.db) {
    if (signalIdList.length > 0) {
      try {
        const { inArray } = require("drizzle-orm");
        const schema = b.schema || require("../../db/schema");
        const res = await b.db
          .select({ sid: schema.trades.sid })
          .from(schema.trades)
          .where(inArray(schema.trades.sid, signalIdList));
        for (const row of res || []) {
          const tid = String(row?.sid || "").trim();
          if (tid) trdIdSet.add(tid);
        }
      } catch {
        // ignore fetch failure
      }
    }

    const knownTradeIds = [...trdIdSet];
    if (knownTradeIds.length > 0) {
      try {
        const { inArray } = require("drizzle-orm");
        const schema = b.schema || require("../../db/schema");
        const res = await b.db
          .select({ metadata: schema.trades.metadata })
          .from(schema.trades)
          .where(inArray(schema.trades.sid, knownTradeIds));
        for (const row of res || [])
          collectSnapshotFilesFromValue(row?.metadata, fileSet);
      } catch {
        // ignore fetch failure
      }
    }
  }

  const allTradeIds = [...trdIdSet];
  const snapshotFilesDeleted = deleteSnapshotFilesByName([...fileSet]);
  const tradeFoldersDeleted = deleteTradeArtifactFoldersBySid(allTradeIds);

  return {
    logs_deleted: 0,
    files_deleted: snapshotFilesDeleted + tradeFoldersDeleted,
    snapshot_files_deleted: snapshotFilesDeleted,
    trade_folders_deleted: tradeFoldersDeleted,
  };
}

