function runBrokerSyncSideEffectQueue(tasks = [], label = "broker-sync") {
  const queue = Array.isArray(tasks)
    ? tasks.filter((task) => typeof task === "function")
    : [];
  if (!queue.length) return;
  const runNext = (index = 0) => {
    if (index >= queue.length) return;
    setImmediate(async () => {
      try {
        await queue[index]();
      } catch (error) {
        console.warn(`[${label}] side effect failed`, {
          index,
          message: error instanceof Error ? error.message : String(error),
        });
      }
      runNext(index + 1);
    });
  };
  runNext(0);
}

async function mt5BrokerSyncSqlite(accountId, payload = {}) {
  const syncStartedAtMs = Date.now();
  const rawAid = String(accountId || "").trim();
  if (!rawAid) return { ok: false, error: "account_id is required" };
  const store = getUserAccountObjectStore();
  const existingAccount = await resolveCanonicalUserAccount(
    payload.user_id || CFG.mt5DefaultUserId,
    rawAid,
    payload,
  );
  const aid = String(existingAccount?.account_id || rawAid).trim();
  const uid = String(
    existingAccount?.user_id || payload.user_id || CFG.mt5DefaultUserId,
  ).trim() || CFG.mt5DefaultUserId;
  const currentDynamic = existingAccount
    ? await getDynamicUserAccountRecord(uid, aid)
    : null;
  const nextMeta = {
    ...(currentDynamic?.metadata || {}),
    balance: asNum(payload.balance, currentDynamic?.metadata?.balance ?? 0),
    equity: asNum(payload.equity, currentDynamic?.metadata?.equity ?? 0),
    margin: asNum(payload.margin, currentDynamic?.metadata?.margin ?? 0),
    free_margin: asNum(
      payload.free_margin,
      currentDynamic?.metadata?.free_margin ?? 0,
    ),
    leverage: asNum(payload.leverage, currentDynamic?.metadata?.leverage ?? 0),
    provider_code: String(
      payload.provider_code ||
        currentDynamic?.metadata?.provider_code ||
        resolveProviderCode(payload.broker_name) ||
        "",
    ),
    source_ids_cache:
      payload.source_ids_cache !== undefined
        ? normalizeAccountSourceIdsCache(payload.source_ids_cache)
        : normalizeAccountSourceIdsCache(
            currentDynamic?.metadata?.source_ids_cache,
          ),
    symbol_metrics: (() => {
      const incoming = Array.isArray(payload.symbol_metrics)
        ? payload.symbol_metrics
        : [];
      const existing = Array.isArray(currentDynamic?.metadata?.symbol_metrics)
        ? currentDynamic.metadata.symbol_metrics
        : [];
      const map = new Map();
      existing.forEach((m) => {
        if (m?.symbol) map.set(String(m.symbol).toUpperCase(), m);
      });
      incoming.forEach((m) => {
        if (m?.symbol) {
          map.set(String(m.symbol).toUpperCase(), {
            ...map.get(String(m.symbol).toUpperCase()),
            ...m,
            updated_at: new Date().toISOString(),
          });
        }
      });
      return Array.from(map.values());
    })(),
    health_updated_at: new Date().toISOString(),
  };
  if (existingAccount) {
    await store.upsertDynamicObject(
      uid,
      "user_accounts",
      aid,
      nextMeta,
      currentDynamic?.status || existingAccount.status || "ACTIVE",
      {
        created_at: currentDynamic?.created_at || existingAccount.created_at || mt5NowIso(),
        updated_at: mt5NowIso(),
      },
    );
    await StateRepo.del("USER_ACCOUNTS", uid);
  }
  await Promise.all(
    (Array.isArray(nextMeta.symbol_metrics) ? nextMeta.symbol_metrics : []).map((metric) =>
      upsertBrokerSymbolMetadata(uid, metric, {
        account_id: aid,
        provider: nextMeta.provider_code || resolveProviderCode(payload.broker_name) || "broker",
        source: "broker_sync",
      }).catch(() => null),
    ),
  );
  const syncedMetricSymbols = (Array.isArray(nextMeta.symbol_metrics) ? nextMeta.symbol_metrics : [])
    .map((metric) => String(metric?.symbol || "").trim().toUpperCase())
    .filter(Boolean);
  if (syncedMetricSymbols.length) {
    emitBrokerSymbolMetadataRealtime({
      user_id: uid,
      account_id: aid,
      provider: nextMeta.provider_code || resolveProviderCode(payload.broker_name) || "broker",
      source: "broker_sync",
      symbols: syncedMetricSymbols,
    });
  }

  const syncPositions = Array.isArray(payload.positions) ? payload.positions : [];
  const syncOrders = Array.isArray(payload.orders) ? payload.orders : [];
  const syncClosed = Array.isArray(payload.closed) ? payload.closed : [];
  const priceTicks = Array.isArray(payload.prices)
    ? payload.prices
    : Array.isArray(payload.p)
      ? payload.p
      : [];
  const requestSymbolSet = new Set();
  for (const item of [...syncPositions, ...syncOrders, ...syncClosed]) {
    const sym = String(item?.symbol || "").trim().toUpperCase();
    if (sym) requestSymbolSet.add(sym);
  }
  let priceStored = 0;
  const priceStoredSymbols = [];
  for (const t of priceTicks) {
    const sym = String(t?.s || t?.symbol || "").trim().toUpperCase();
    const bid = Number(t?.b ?? t?.bid);
    const ask = Number(t?.a ?? t?.ask);
    if (!sym || !Number.isFinite(bid) || !Number.isFinite(ask)) continue;
    brokerPriceCache[sym] = { bid, ask, ts: Date.now() };
    await upsertBrokerSymbolMetadata(uid, {
      symbol: sym,
      bid,
      ask,
      last_price: (bid + ask) / 2,
      last_price_at: new Date().toISOString(),
      source: "broker_price_push",
    }, {
      account_id: aid,
      provider: nextMeta.provider_code || resolveProviderCode(payload.broker_name) || "broker",
    }).catch(() => null);
    if (!priceStoredSymbols.includes(sym)) priceStoredSymbols.push(sym);
    requestSymbolSet.add(sym);
    priceStored++;
  }
  if (priceStored > 0) lastBrokerPricePush = Date.now();
  if (priceStored > 0) {
    emitBrokerSymbolMetadataRealtime({
      user_id: uid,
      account_id: aid,
      provider: nextMeta.provider_code || resolveProviderCode(payload.broker_name) || "broker",
      source: "broker_sync_prices",
      symbols: priceStoredSymbols,
    });
  }

  const { items, seenTickets, snapshotComplete } = mt5BuildBrokerSyncItems(
    payload,
  );
  const symbolMetricsMap = new Map(
    (Array.isArray(nextMeta.symbol_metrics) ? nextMeta.symbol_metrics : [])
      .filter((m) => m && m.symbol)
      .map((m) => [String(m.symbol).trim().toUpperCase(), m]),
  );
  const repo = await mt5TradeRepo(uid);
  const out = await repo.brokerSyncTrades(uid, aid, items, {
    now: mt5NowIso(),
    snapshotComplete,
    brokerName: payload.broker_name || "",
    providerCode: nextMeta.provider_code || "",
    sourceId:
      (payload.broker_name || "BROKER").toUpperCase().replace(/\s+/g, "_"),
    generateSid: mt5GenerateTimeSid,
    resolvePlannedTpPnl: (item) => {
      const fallback = mt5ComputePlannedPnlFromMetrics(
        item,
        symbolMetricsMap.get(String(item.symbol || "").toUpperCase()) || null,
      );
      return mt5ResolveStoredPlannedPnlValue(null, fallback.tpPnl);
    },
    resolvePlannedSlPnl: (item) => {
      const fallback = mt5ComputePlannedPnlFromMetrics(
        item,
        symbolMetricsMap.get(String(item.symbol || "").toUpperCase()) || null,
      );
      return mt5ResolveStoredPlannedPnlValue(null, fallback.slPnl);
    },
  });
  const repoCompletedAtMs = Date.now();

  for (const update of out.tradeUpdates || []) {
    await mt5Log(
      update.sid,
      "trades",
      {
        event: "TRADE_SYNC_UPDATE",
        execution_status: update.execution_status,
        pnl: update.broker_pnl,
        pips: update.broker_pips,
        sl_before: update.sl_before,
        sl_after: update.sl,
        tp_before: update.tp_before,
        tp_after: update.tp,
        has_partial: update.has_partial,
      },
      uid,
    ).catch(() => {});
    emitTradeRealtimeEvent(update);
  }

  for (const row of out.closedRows || []) {
    await mt5Log(
      row.sid,
      "trades",
      {
        event: "TRADE_SYNC_CLOSE",
        ticket: row.brokerTradeId || null,
        execution_status: row.executionStatus || null,
        close_reason: row.closeReason || null,
        pnl_inferred: Number.isFinite(Number(row.pnlRealized))
          ? Number(row.pnlRealized)
          : null,
      },
      uid,
    ).catch(() => {});
    try {
      archiveTradeStats(row.sid, row.symbol);
    } catch {}
    try {
      moveTradeFolder(row.sid, "active", "closed", row.symbol || "");
    } catch {}
    emitTradeRealtimeEvent({
      sid: row.sid,
      symbol: row.symbol,
      execution_status: row.executionStatus || "CLOSED",
      pnl_realized: row.pnlRealized ?? null,
      close_reason: row.closeReason || null,
      closed_at: row.closedAt || null,
    });
  }

  for (const it of items) {
    const sid = String(it.sid || "").trim();
    const st = String(it.execution_status || "").toUpperCase();
    const sym = String(it.symbol || "").trim();
    if (sid && ["PENDING", "FILLED"].includes(st)) {
      moveTradeFolder(sid, "draft", "active", sym);
    }
  }

  if ((out.tradeUpdates || []).length > 0) {
    notificationManager.handle("BROKER_SYNC", "sync", {
      user_id: uid,
      page_id: "trades",
      event: "broker_sync",
      data: out.tradeUpdates,
      message: `BROKER SYNC: ${[...new Set((out.tradeUpdates || []).map((u) => u.symbol).filter(Boolean))].slice(0, 3).join(", ") || "none"} (${out.matched} updated)`,
      type: "info",
      need_refresh: false,
      comp_refresh: out.matched > 0,
    });
  }

  const resultSummary = {
    read: Array.isArray(out.results) ? out.results.length : 0,
    unchanged: 0,
    created: 0,
    changed: 0,
    closed: 0,
    errors: 0,
    skipped: 0,
  };
  for (const row of Array.isArray(out.results) ? out.results : []) {
    const status = String(row?.status || "").trim().toUpperCase();
    if (status === "NOCHANGE") resultSummary.unchanged += 1;
    else if (status === "ADDED") resultSummary.created += 1;
    else if (status === "ERROR") resultSummary.errors += 1;
    else if (status === "SKIP") resultSummary.skipped += 1;
  }
  for (const update of Array.isArray(out.tradeUpdates) ? out.tradeUpdates : []) {
    const exec = String(update?.execution_status || "").trim().toUpperCase();
    if (exec === "CLOSED" || exec === "CANCELLED") resultSummary.closed += 1;
    else resultSummary.changed += 1;
  }

  const totalDurationMs = Date.now() - syncStartedAtMs;
  const repoDurationMs = repoCompletedAtMs - syncStartedAtMs;
  if (totalDurationMs >= 4000) {
    console.warn("[v2/broker/sync] slow sync", {
      account_id: aid,
      user_id: uid,
      duration_ms: totalDurationMs,
      repo_duration_ms: repoDurationMs,
      items: items.length,
      positions: syncPositions.length,
      orders: syncOrders.length,
      closed: syncClosed.length,
      price_symbols: priceStoredSymbols.length,
      snapshot_complete: Boolean(snapshotComplete),
      matched: out.matched,
      synced: out.synced,
      closed_by_snapshot: out.closedRows?.length || 0,
    });
  }

  return {
    ok: true,
    synced: out.synced,
    matched: out.matched,
    received: out.received,
    closed_by_snapshot: out.closed_by_snapshot,
    results: out.results,
    tradeUpdates: out.tradeUpdates,
    closedRows: out.closedRows || [],
    request_summary: {
      positions: syncPositions.length,
      orders: syncOrders.length,
      closed: syncClosed.length,
      price_symbols: priceStoredSymbols.length,
      symbols: requestSymbolSet.size,
    },
    price_summary: {
      stored: priceStored,
      symbols: priceStoredSymbols,
    },
    result_summary: resultSummary,
  };
}

async function mt5TradesBrokerSync(accountId, payload = {}, userId = null) {
  const resolvedUserId = await mt5ResolveBrokerUserId(
    accountId,
    userId || payload?.user_id || null,
  );
  const { items, seenTickets, snapshotComplete } = mt5BuildBrokerSyncItems(
    payload,
  );
  const result = await tradesService().brokerSyncTrades(
    resolvedUserId,
    accountId,
    items,
    {
      now: mt5NowIso(),
      snapshotComplete,
      brokerName: payload.broker_name || "",
      providerCode: String(payload.provider_code || "").trim(),
      sourceId:
        String(payload.broker_name || "BROKER")
          .trim()
          .toUpperCase()
          .replace(/\s+/g, "_") || "BROKER",
      generateSid: mt5GenerateTimeSid,
    },
  );
  return {
    ok: true,
    matched: result.matched || 0,
    synced: result.synced || 0,
    received: items.length,
    seen_tickets: [...seenTickets],
    snapshot_complete: Boolean(snapshotComplete),
    results: result.results || [],
    tradeUpdates: result.tradeUpdates || [],
    closedRows: result.closedRows || [],
  };
}

