const mt5TradeUserIdsForScope = tradeUserIdsForScope;

async function getTradesBySidsGlobal(sids = [], userId = null) {
  const refs = Array.isArray(sids)
    ? sids.map((sid) => String(sid || "").trim()).filter(Boolean)
    : [];
  if (!refs.length) return [];
  const out = [];
  for (const uid of await tradeUserIdsForScope(userId)) {
    const repo = await tradeRepo(uid);
    const rows = await repo.getTradesBySids(uid || CFG.mt5DefaultUserId, refs);
    out.push(...(rows || []));
  }
  return out;
}
const mt5GetTradesBySidsGlobal = getTradesBySidsGlobal;

async function deleteTradesBySidsGlobal(sids = [], userId = null) {
  const refs = Array.isArray(sids)
    ? sids.map((sid) => String(sid || "").trim()).filter(Boolean)
    : [];
  if (!refs.length) return 0;
  let deleted = 0;
  for (const uid of await tradeUserIdsForScope(userId)) {
    const repo = await tradeRepo(uid);
    const out = await repo.deleteTradesBySids(uid || null, refs);
    deleted += Number(out?.deleted || 0);
  }
  return deleted;
}
const mt5DeleteTradesBySidsGlobal = deleteTradesBySidsGlobal;

async function mt5DeleteTradesOlderThanGlobal(days, userId = null) {
  const cutoff = new Date(Date.now() - Number(days || 0) * 24 * 60 * 60 * 1000)
    .toISOString();
  let deleted = 0;
  for (const uid of await mt5TradeUserIdsForScope(userId)) {
    const repo = await mt5TradeRepo(uid);
    const out = await repo.deleteTradesOlderThan(uid || null, cutoff);
    deleted += Number(out?.deleted || 0);
  }
  return deleted;
}

async function mt5CountTradesMatchingGlobal(filters = {}, userId = null) {
  let total = 0;
  for (const uid of await mt5TradeUserIdsForScope(userId || filters.user_id || null)) {
    const repo = await mt5TradeRepo(uid);
    const batch = await repo.listTradesV2(uid || CFG.mt5DefaultUserId, {
      ...filters,
      user_id: uid || filters.user_id || undefined,
    }, 1, 1);
    total += Number(batch?.total || 0);
  }
  return total;
}

async function mt5ListTradesGlobal(filters = {}, userId = null) {
  const out = [];
  for (const uid of await mt5TradeUserIdsForScope(userId || filters.user_id || null)) {
    const repo = await mt5TradeRepo(uid);
    let page = 1;
    let total = 0;
    do {
      const batch = await repo.listTradesV2(
        uid || CFG.mt5DefaultUserId,
        {
          ...filters,
          user_id: uid || filters.user_id || undefined,
        },
        page,
        5000,
      );
      total = Number(batch?.total || 0);
      out.push(...(batch?.items || []));
      page += 1;
    } while (out.length < total);
  }
  return out;
}

async function mt5ApplySignalAckGlobal(signalId, userId, patch = {}) {
  const targetUser = String(userId || "").trim();
  const candidateUserIds = targetUser
    ? [targetUser]
    : await mt5TradeUserIdsForScope(null);
  for (const uid of candidateUserIds) {
    const repo = await mt5TradeRepo(uid);
    const out = await repo.applySignalAck(uid || null, signalId, patch);
    if (out?.ok && out?.item) return out;
  }
  return { ok: false, error: "trade not found" };
}

