async function mt5CreateTradeFanoutViaRepo(payload = {}) {
  const tradeIdRaw = String(
    payload.sid || payload.trade_id || payload.tradeId || "",
  ).trim();
  const tradeId = tradeIdRaw || null;
  const sourceId = String(payload.source_id || "").trim();
  const userId = String(payload.user_id || CFG.mt5DefaultUserId).trim();
  const skipDirective = mt5ResolveSkipTradeDirective(payload);
  const forcedExecutionStatus = skipDirective.cancelled
    ? "CANCELLED"
    : String(payload.execution_status || "PENDING")
        .trim()
        .toUpperCase() || "PENDING";
  const forcedDispatchStatus = skipDirective.cancelled
    ? "CANCEL"
    : String(
        payload.dispatch_status ||
          (forcedExecutionStatus === "DRAFT" ? "NEW" : "OPEN"),
      )
        .trim()
        .toUpperCase() ||
      (forcedExecutionStatus === "DRAFT" ? "NEW" : "OPEN");
  const forcedClosedAt = skipDirective.cancelled ? mt5NowIso() : null;
  if (!sourceId || !userId) return { created: 0, account_ids: [], sids: [] };
  const levelValidationError = mt5ValidateTradeLevels({
    side: payload.action,
    entry: payload.entry,
    sl: payload.sl,
    tp1: payload.tp1 ?? payload.tp,
    tp2: payload.tp2,
    tp3: payload.tp3,
  });
  if (levelValidationError) {
    throw new Error(`Invalid trade levels: ${levelValidationError}`);
  }
  const resolvedStrategy = (() => {
    const direct = nullLikeEmpty(payload.strategy);
    if (direct) return direct;
    const planCandidates = [
      ...(Array.isArray(payload.trade_plan) ? payload.trade_plan : []),
      ...(Array.isArray(payload.trade_plans) ? payload.trade_plans : []),
      ...(Array.isArray(payload?.metadata?.trade_plan)
        ? payload.metadata.trade_plan
        : []),
      ...(Array.isArray(payload?.metadata?.trade_plans)
        ? payload.metadata.trade_plans
        : []),
    ];
    for (const plan of planCandidates) {
      const value = nullLikeEmpty(
        plan?.strategy_name || plan?.strategy || plan?.strategy_id,
      );
      if (value) return value;
    }
    const metadataValue = nullLikeEmpty(
      payload?.metadata?.strategy_name ||
        payload?.metadata?.strategy ||
        payload?.metadata?.strategy_id ||
        payload?.raw_json?.strategy_name ||
        payload?.raw_json?.strategy ||
        payload?.raw_json?.strategy_id ||
        payload?.metadata?.raw_json?.strategy_name ||
        payload?.metadata?.raw_json?.strategy ||
        payload?.metadata?.raw_json?.strategy_id,
    );
    return metadataValue || null;
  })();
  const store = getUserAccountObjectStore();
  const accounts = (await store.listUnifiedObjects(userId, "user_accounts"))
    .filter((row) => String(row?.status || "").toUpperCase() !== "ARCHIVED")
    .map((row) => ({
      account_id: row?.account_id || row?.object_id || "",
      metadata: row?.metadata || {},
    }));
  const repo = await mt5TradeRepo(userId);
  const rows = [];
  const accountIds = [];
  const sids = [];
  for (const row of accounts || []) {
    const aid = String(row.account_id || "").trim();
    if (!aid) continue;
    const accountMeta = mt5ParseAccountMetadata(row.metadata);
    const symbolMetric = mt5FindSymbolMetric(accountMeta, payload.symbol);
    const plannedPnlFallback = mt5ComputePlannedPnlFromMetrics(
      payload,
      symbolMetric,
    );
    const plannedTpPnl = mt5ResolveStoredPlannedPnlValue(
      payload.planned_tp_pnl,
      plannedPnlFallback.tpPnl,
    );
    const plannedSlPnl = mt5ResolveStoredPlannedPnlValue(
      payload.planned_sl_pnl,
      plannedPnlFallback.slPnl,
    );
    const tradeSid = tradeId || mt5GenerateTimeSid();
    const metadata = (() => {
      const m = { ...(payload.metadata || {}) };
      m.tp_targets = mt5NormalizeTpTargets(
        payload.tp_targets || [payload.tp1, payload.tp2, payload.tp3, payload.tp],
        payload.action,
      );
      delete m.raw_json;
      if (tradeId && !m.trade_sid) m.trade_sid = tradeId;
      return m;
    })();
    const rawJson = (() => {
      const rj = payload.metadata?.raw_json || payload.raw_json || {};
      if (rj && typeof rj === "object" && rj.prompt) {
        const { prompt: _prompt, ...rest } = rj;
        return rest;
      }
      return rj;
    })();
    rows.push({
      sid: tradeSid,
      account_id: aid,
      user_id: userId,
      trade_id: tradeId || tradeSid,
      source_id: sourceId,
      strategy: resolvedStrategy,
      entry_model: payload.entry_model || null,
      trade_tf:
        payload.trade_tf ??
        payload.tradeTf ??
        payload.signal_tf ??
        payload.signalTf ??
        null,
      chart_tf: payload.chart_tf || null,
      symbol: payload.symbol,
      action: payload.action,
      order_type: payload.order_type || "limit",
      entry: payload.entry,
      sl: payload.sl,
      tp: payload.tp,
      tp1: payload.tp1,
      tp2: payload.tp2,
      tp3: payload.tp3,
      volume: payload.volume,
      note: payload.note,
      dispatch_status: forcedDispatchStatus,
      execution_status: forcedExecutionStatus,
      close_reason: skipDirective.reason,
      closed_at: forcedClosedAt,
      metadata,
      raw_json: rawJson,
      profile: payload.profile || null,
      confidence_pct: payload.confidence_pct || null,
      estimated_bars: payload.estimated_bars || null,
      be_trigger: payload.be_trigger || null,
      rr_planned: payload.rr_planned || null,
      risk_money_planned: payload.risk_money_planned || null,
      risk_pct_planned: payload.risk_pct_planned || null,
      planned_tp_pnl: Number.isFinite(plannedTpPnl) ? plannedTpPnl : null,
      planned_sl_pnl: Number.isFinite(plannedSlPnl) ? plannedSlPnl : null,
    });
    accountIds.push(aid);
    sids.push(tradeSid);
  }
  await repo.createTrades(userId, rows);
  for (const sid of sids) {
    await mt5Log(
      sid,
      "trades",
      tradeId
        ? { event: "TRADE_FANOUT", trade_id: tradeId }
        : { event: "DIRECT_TRADE_CREATE" },
      userId,
    ).catch(() => {});
    if (forcedExecutionStatus === "DRAFT") {
      ensureTradeDir(sid, payload.symbol || "", "draft");
    } else if (
      ["CANCELLED", "REJECTED", "CLOSED"].includes(forcedExecutionStatus)
    ) {
      moveTradeFolder(sid, "draft", "closed", payload.symbol || "");
    } else {
      moveTradeFolder(sid, "draft", "active", payload.symbol || "");
    }
  }
  bumpPulse(userId);
  return { created: rows.length, account_ids: accountIds, sids };
}

async function mt5ResolveBrokerUserId(accountId, fallbackUserId = null) {
  const fallback =
    String(fallbackUserId || CFG.mt5DefaultUserId).trim() ||
    CFG.mt5DefaultUserId;
  const account = await findUnifiedUserAccountById(accountId, fallback).catch(
    () => null,
  );
  return String(account?.user_id || account?.userId || fallback).trim() || fallback;
}

