async function resolvePreferredTrades2AccountId(userId, sourceId = null) {
  const uid =
    String(userId || CFG.mt5DefaultUserId).trim() || CFG.mt5DefaultUserId;
  const activeProfile = await mt5GetActiveExecutionProfileV2(uid).catch(
    () => null,
  );
  const profileAccountId = String(activeProfile?.account_id || "").trim();
  if (profileAccountId) return profileAccountId;

  const store = getUserAccountObjectStore();
  const wantedSourceId = String(sourceId || "").trim();
  const accounts = (await store.listUnifiedObjects(uid, "user_accounts"))
    .filter((row) => String(row?.status || "").toUpperCase() !== "ARCHIVED")
    .map((row) => ({
      account_id: String(row?.account_id || row?.object_id || "").trim(),
      source_ids: normalizeAccountSourceIdsCache(
        row?.source_ids_cache ?? row?.metadata?.source_ids_cache ?? [],
      ),
    }))
    .filter((row) => row.account_id);

  if (wantedSourceId) {
    const matching = accounts.filter((row) => row.source_ids.includes(wantedSourceId));
    if (matching.length) return matching[0].account_id;
  }

  if (accounts.length === 1) return accounts[0].account_id;
  return accounts[0]?.account_id || null;
}

function mt5NormalizeExecutionProfileRow(row = {}) {
  const data = dbQueries.parseJsonField(row?.data) || {};
  return {
    profile_id:
      String(row?.name || row?.profile_id || "default").trim() || "default",
    user_id: String(row?.userId || row?.user_id || "").trim(),
    profile_name:
      String(
        data?.profile_name || row?.profile_name || row?.name || "default",
      ).trim() || "default",
    route:
      String(data?.route || row?.route || "ea")
        .trim()
        .toLowerCase() || "ea",
    account_id: String(data?.account_id || row?.account_id || "").trim(),
    source_ids: Array.isArray(data?.source_ids)
      ? data.source_ids.map((v) => String(v || "").trim()).filter(Boolean)
      : [],
    ctrader_mode:
      String(data?.ctrader_mode || row?.ctrader_mode || "")
        .trim()
        .toLowerCase() || "",
    ctrader_account_id: String(
      data?.ctrader_account_id || row?.ctrader_account_id || "",
    ).trim(),
    is_active:
      data?.is_active === undefined
        ? Boolean(row?.is_active)
        : Boolean(data.is_active),
    metadata:
      data?.metadata && typeof data.metadata === "object" ? data.metadata : {},
    raw: row,
    created_at: row?.createdAt || row?.created_at || null,
    updated_at: row?.updatedAt || row?.updated_at || null,
  };
}

async function mt5SaveExecutionProfileV2(payload = {}) {
  const profileId = String(payload.profile_id || "default").trim() || "default";
  const userId =
    String(payload.user_id || CFG.mt5DefaultUserId).trim() ||
    CFG.mt5DefaultUserId;
  const profileName =
    String(payload.profile_name || profileId).trim() || profileId;
  const routeRaw = String(payload.route || "")
    .trim()
    .toLowerCase();
  const route = ["ea", "v2026.05.09 19:31 - 728f356", "ctrader", "ctrader2"].includes(
    routeRaw,
  )
    ? routeRaw
    : "ea";
  const accountId = String(payload.account_id || "").trim() || null;
  const sourceIds = (
    Array.isArray(payload.source_ids) ? payload.source_ids : []
  )
    .map((v) => String(v || "").trim())
    .filter(Boolean);
  const ctraderModeRaw = String(payload.ctrader_mode || "")
    .trim()
    .toLowerCase();
  const ctraderMode = ["demo", "live"].includes(ctraderModeRaw)
    ? ctraderModeRaw
    : null;
  const ctraderAccountId =
    String(payload.ctrader_account_id || "").trim() || null;
  const isActive =
    payload.is_active === undefined ? true : Boolean(payload.is_active);
  const metadata =
    payload.metadata && typeof payload.metadata === "object"
      ? payload.metadata
      : {};

  if (isActive) {
    // Set all other execution_profiles for this user to inactive
    const existingRows = await settingsStore.listUserSettingsByType(
      userId,
      "execution_profile",
    );
    for (const row of existingRows || []) {
      const d = settingsStore.parseJsonField(row.data) || {};
      if (d.is_active) {
        const updated = { ...d, is_active: false };
        await settingsStore.upsertUserSetting(
          userId,
          "execution_profile",
          row.name,
          updated,
          row.status || "ACTIVE",
        );
      }
    }
  }

  const data = {
    profile_name: profileName,
    route,
    account_id: accountId,
    source_ids: sourceIds,
    ctrader_mode: ctraderMode,
    ctrader_account_id: ctraderAccountId,
    is_active: isActive,
    metadata,
  };

  await settingsStore.upsertUserSetting(
    userId,
    "execution_profile",
    profileId,
    data,
    "ACTIVE",
  );

  return {
    ok: true,
    item: mt5NormalizeExecutionProfileRow({
      userId: userId,
      name: profileId,
      data: data,
    }),
  };
}

