    const t0a = Date.now();
    const sess = getUiSessionFromReq(req);
    const isAdmin =
      (req.headers["x-api-key"] || url.searchParams.get("key")) ===
      CFG.adminKey;
    if (!sess.ok && !isAdmin)
      return json(res, 401, { ok: false, error: "AUTH_REQUIRED" });
    let isLocalAnalyzeProvider = false;
