async function mt5RunSnapshotsCronInline() {
  const rows = await settingsStore.listUserSettingsByType(null, "cron");
  const configs = (rows || []).filter((r) => {
    const d = settingsStore.parseJsonField(r.data) || {};
    return (
      ["SNAPSHOTS_CRON", "SNAPSHOT_CRON"].includes(d.cron_type) &&
      String(r.status || "").toUpperCase() === "ACTIVE"
    );
  });
  if (!configs.length) return null;
  const now = Date.now();
  const summary = {
    configs: 0,
    captured: 0,
    skipped: 0,
    symbols: [],
    errors: [],
  };
  for (const conf of configs) {
    const userId = conf.userId || conf.user_id;
    let data = settingsStore.parseJsonField(conf.data) || {};
    if (!asBool(data.enabled ?? true, true)) continue;
    summary.configs++;
    const decision = await cronConfigShouldRunNow(
      data,
      now,
      CRON_STATE.lastSnapshotsRun[`${userId}_${conf.name}`] || 0,
      60,
    );
    data = decision.normalized;
    const symbols = await resolveCronSymbols(data, userId);
    const excludeSymbols = new Set(
      (Array.isArray(data.exclude_symbols) ? data.exclude_symbols : [])
        .map((s) => String(s).toUpperCase().trim())
        .filter(Boolean),
    );
    const filteredSymbols = symbols.filter(
      (s) => !excludeSymbols.has(String(s).toUpperCase().trim()),
    );
    const tfs = Array.isArray(data.timeframes) ? data.timeframes : [];
    if (!filteredSymbols.length || !tfs.length) continue;
    const rawBatchSize = Number(data.symbols_per_tick);
    const batchSize =
      Number.isFinite(rawBatchSize) && rawBatchSize > 0
        ? Math.max(1, Math.floor(rawBatchSize))
        : filteredSymbols.length;
    const stateKey = `${userId}_${conf.name}`;

    if (!decision.shouldRun) {
      summary.skipped++;
      continue;
    }
    // Default behavior is "all symbols each tick". A positive symbols_per_tick
    // enables round-robin batching.
    let tickSymbols = filteredSymbols;
    let batchLabel = "all";
    if (batchSize < filteredSymbols.length) {
      const rrKey = `${userId}_${conf.name}_rr`;
      let rrIdx = CRON_STATE.lastSnapshotsRun[rrKey] || 0;
      if (rrIdx >= filteredSymbols.length) rrIdx = 0;
      tickSymbols = filteredSymbols.slice(rrIdx, rrIdx + batchSize);
      CRON_STATE.lastSnapshotsRun[rrKey] =
        (rrIdx + batchSize) % filteredSymbols.length;
      batchLabel = String(Math.floor(rrIdx / batchSize) + 1);
    }
    console.log(
      `[Cron][Snapshots] Running userId=${userId} name=${conf.name} symbols=${tickSymbols.length}/${filteredSymbols.length} (batch ${batchLabel})`,
    );
    CRON_STATE.lastSnapshotsRun[stateKey] = now;
    try {
      const startedAt = Date.now();
      const broker = String(data.broker || "");
      const results = await captureTradingViewSnapshotsBatch({
        symbols: tickSymbols,
        timeframes: tfs,
        provider: broker,
        lookbackBars: Number(data.lookback_bars || 200),
        format: String(data.format || "png"),
        quality: Number(data.quality || 90),
        theme: String(data.theme || "dark"),
        width: Number(data.width || 1200),
        height: Number(data.height || 800),
        maxConcurrent: Math.min(
          tickSymbols.length,
          Math.max(
            1,
            Math.floor(asNum(process.env.SNAPSHOTS_CRON_SYMBOL_CONCURRENCY, 4)),
          ),
        ),
        userId,
      });
      const created = [];
      if (Array.isArray(results)) {
        for (const r of results) {
          if (r && r.status === "ok") {
            summary.captured++;
            summary.symbols.push(`${r.symbol || "?"}:${r.timeframe || "?"}`);
            created.push({
              symbol: r.symbol || "",
              timeframe: r.timeframe || "",
              file_name: r.file_name || "",
              url: r.url || "",
            });
            await updateHealthActivity("SNAPSHOT", String(r.symbol || ""), {
              status: "ok",
              message: `${r.symbol || "?"} ${r.timeframe || ""}`,
              timeframe: r.timeframe || "",
              file_name: r.file_name || "",
              url: r.url || "",
              cron_name: conf.name,
            });
            await upsertSymbolActivity(String(r.symbol || ""), {
              snapshot: {
                last_time: new Date().toISOString(),
                timeframe: r.timeframe || "",
                file_name: r.file_name || "",
                url: r.url || "",
                cron_name: conf.name,
              },
            });
          }
        }
      }
      const createdSymbols = created
        .map((x) =>
          String(x.symbol || "")
            .trim()
            .toUpperCase(),
        )
        .filter(Boolean);
      const failedResults = Array.isArray(results)
        ? results.filter((r) => r && r.status !== "ok")
        : [];
      const failedSymbols = failedResults
        .map((r) => {
          const sym = String(r?.symbol || "")
            .trim()
            .toUpperCase();
          const err = String(r?.error || "").trim();
          if (sym && err) return `${sym}: ${err}`;
          return sym || err;
        })
        .filter(Boolean);
      const captureErrorMessage = failedSymbols.length
        ? `Snapshot capture failed: ${failedSymbols.join("; ")}`
        : "Snapshot capture failed: no images were created";
      await updateHealthActivity(
        "CRON",
        String(conf.name || "SNAPSHOTS_CRON"),
        {
          status: created.length === 0 ? "error" : "ok",
          message:
            created.length === 0
              ? captureErrorMessage
              : `completed ${createdSymbols.join(", ") || "0 symbols"}`,
          user_id: userId,
          cron_type: String(data.cron_type || "SNAPSHOTS_CRON"),
          broker: broker || null,
          tick_symbols: tickSymbols,
          all_symbols_count: filteredSymbols.length,
          timeframes: Array.isArray(tfs) ? tfs : [],
          created_count: created.length,
          created,
          errors: failedSymbols,
          duration_ms: Date.now() - startedAt,
        },
      );
      if (created.length === 0) {
        notificationManager.handle("CRON_SNAPSHOT", "failed", {
          user_id: userId,
          event: "cron_snapshot",
          message: captureErrorMessage,
          type: "error",
          notification: true,
          cron_name: String(conf.name || "SNAPSHOTS_CRON"),
          created_count: created.length,
          errors: failedSymbols,
        });
      } else {
        notificationManager.handle("CRON_SNAPSHOT", "completed", {
          user_id: userId,
          event: "cron_snapshot",
          message: createdSymbols.join(", ") || `${created.length} created`,
          type: "info",
          notification: true,
          symbols: createdSymbols,
          cron_name: String(conf.name || "SNAPSHOTS_CRON"),
          created_count: created.length,
        });
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      summary.errors.push(msg);
      await updateHealthActivity(
        "CRON",
        String(conf.name || "SNAPSHOTS_CRON"),
        {
          status: "error",
          message: msg,
          user_id: userId,
          cron_type: String(data.cron_type || "SNAPSHOTS_CRON"),
          broker: String(data.broker || "") || null,
          tick_symbols: tickSymbols,
          all_symbols_count: filteredSymbols.length,
          timeframes: Array.isArray(tfs) ? tfs : [],
          created_count: 0,
          created: [],
          errors: [msg],
        },
      );
      notificationManager.handle("CRON_SNAPSHOT", "failed", {
        user_id: userId,
        event: "cron_snapshot",
        message: `Snapshots FAILED (${String(conf.name || "SNAPSHOTS_CRON")}): ${msg}`,
        type: "error",
        notification: true,
        cron_name: String(conf.name || "SNAPSHOTS_CRON"),
        error: msg,
      });
      console.error(`[Cron][Snapshots] Failed userId=${userId}:`, msg);
    }
  }
  return summary;
}

async function runSnapshotsCronConfigNow(conf) {
  const userId = conf.userId || conf.user_id;
  const data = settingsStore.parseJsonField(conf.data) || {};
  const cronName = String(conf.name || "SNAPSHOTS_CRON");
  const summary = {
    cron_name: cronName,
    cron_type: String(data.cron_type || "SNAPSHOTS_CRON"),
    captured: 0,
    skipped: 0,
    symbols: [],
    errors: [],
  };
  if (!asBool(data.enabled ?? true, true)) return summary;
  const symbols = await resolveCronSymbols(data, userId);
  const excludeSymbols = new Set(
    (Array.isArray(data.exclude_symbols) ? data.exclude_symbols : [])
      .map((s) => String(s).toUpperCase().trim())
      .filter(Boolean),
  );
  const filteredSymbols = symbols.filter(
    (s) => !excludeSymbols.has(String(s).toUpperCase().trim()),
  );
  const tfs = Array.isArray(data.timeframes) ? data.timeframes : [];
  if (!filteredSymbols.length || !tfs.length) return summary;
  const rawBatchSize = Number(data.symbols_per_tick);
  const batchSize =
    Number.isFinite(rawBatchSize) && rawBatchSize > 0
      ? Math.max(1, Math.floor(rawBatchSize))
      : filteredSymbols.length;
  const tickSymbols =
    batchSize < filteredSymbols.length
      ? filteredSymbols.slice(0, batchSize)
      : filteredSymbols;
  console.log(
    `[Cron][Snapshots][Manual] Running userId=${userId} name=${conf.name} symbols=${tickSymbols.length}/${filteredSymbols.length}`,
  );
  await writeObjectLog(userId, "cron", cronName, {
    event: "CRON_SNAPSHOT",
    level: "INFO",
    message: `Manual execute started (${tickSymbols.length}/${filteredSymbols.length} symbols)`,
    cron_name: cronName,
    cron_type: String(data.cron_type || "SNAPSHOTS_CRON"),
    manual_run: true,
    symbols: tickSymbols,
    timeframes: tfs,
  }).catch(() => {});
  try {
    const startedAt = Date.now();
    const broker = String(data.broker || "");
    const results = await captureTradingViewSnapshotsBatch({
      symbols: tickSymbols,
      timeframes: tfs,
      provider: broker,
      lookbackBars: Number(data.lookback_bars || 200),
      format: String(data.format || "png"),
      quality: Number(data.quality || 90),
      theme: String(data.theme || "dark"),
      width: Number(data.width || 1200),
      height: Number(data.height || 800),
      maxConcurrent: Math.min(
        tickSymbols.length,
        Math.max(
          1,
          Math.floor(asNum(process.env.SNAPSHOTS_CRON_SYMBOL_CONCURRENCY, 4)),
        ),
      ),
      userId,
    });
    const created = [];
    if (Array.isArray(results)) {
      for (const r of results) {
        if (r && r.status === "ok") {
          summary.captured++;
          summary.symbols.push(`${r.symbol || "?"}:${r.timeframe || "?"}`);
          created.push({
            symbol: r.symbol || "",
            timeframe: r.timeframe || "",
            file_name: r.file_name || "",
            url: r.url || "",
          });
        }
      }
    }
    const failedResults = Array.isArray(results)
      ? results.filter((r) => r && r.status !== "ok")
      : [];
    const failedSymbols = failedResults
      .map((r) => {
        const sym = String(r?.symbol || "")
          .trim()
          .toUpperCase();
        const err = String(r?.error || "").trim();
        if (sym && err) return `${sym}: ${err}`;
        return sym || err;
      })
      .filter(Boolean);
    summary.errors = failedSymbols;
    await writeObjectLog(userId, "cron", cronName, {
      event: "CRON_SNAPSHOT",
      level: created.length === 0 ? "ERROR" : "INFO",
      message:
        created.length === 0
          ? failedSymbols.join("; ") || "Manual snapshot execute failed"
          : `Manual execute completed: ${created.map((x) => x.symbol).join(", ") || "0 symbols"}`,
      cron_name: cronName,
      cron_type: String(data.cron_type || "SNAPSHOTS_CRON"),
      manual_run: true,
      created_count: created.length,
      symbols: created.map((x) => x.symbol).filter(Boolean),
      errors: failedSymbols,
    }).catch(() => {});
    if (created.length === 0) {
      notificationManager.handle("CRON_SNAPSHOT", "failed", {
        user_id: userId,
        event: "cron_snapshot",
        message: failedSymbols.join("; ") || "Manual snapshot execute failed",
        type: "error",
        notification: true,
        cron_name: cronName,
        created_count: created.length,
        errors: failedSymbols,
        manual_run: true,
      });
    } else {
      notificationManager.handle("CRON_SNAPSHOT", "completed", {
        user_id: userId,
        event: "cron_snapshot",
        message:
          created
            .map((x) => x.symbol)
            .filter(Boolean)
            .join(", ") || `${created.length} created`,
        type: "info",
        notification: true,
        symbols: created.map((x) => x.symbol).filter(Boolean),
        cron_name: cronName,
        created_count: created.length,
        manual_run: true,
      });
    }
    await updateHealthActivity("CRON", String(conf.name || "SNAPSHOTS_CRON"), {
      status: created.length === 0 ? "error" : "ok",
      message:
        created.length === 0
          ? failedSymbols.join("; ") || "Snapshot capture failed"
          : `manual run completed ${created.map((x) => x.symbol).join(", ") || "0 symbols"}`,
      user_id: userId,
      cron_type: String(data.cron_type || "SNAPSHOTS_CRON"),
      broker: broker || null,
      tick_symbols: tickSymbols,
      all_symbols_count: filteredSymbols.length,
      timeframes: Array.isArray(tfs) ? tfs : [],
      created_count: created.length,
      created,
      errors: failedSymbols,
      duration_ms: Date.now() - startedAt,
      manual_run: true,
    });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    summary.errors.push(msg);
    await writeObjectLog(userId, "cron", cronName, {
      event: "CRON_SNAPSHOT",
      level: "ERROR",
      message: `Manual execute failed: ${msg}`,
      cron_name: cronName,
      cron_type: String(data.cron_type || "SNAPSHOTS_CRON"),
      manual_run: true,
      errors: [msg],
    }).catch(() => {});
    notificationManager.handle("CRON_SNAPSHOT", "failed", {
      user_id: userId,
      event: "cron_snapshot",
      message: `Snapshots FAILED (${cronName}): ${msg}`,
      type: "error",
      notification: true,
      cron_name: cronName,
      error: msg,
      manual_run: true,
    });
    await updateHealthActivity("CRON", String(conf.name || "SNAPSHOTS_CRON"), {
      status: "error",
      message: msg,
      user_id: userId,
      cron_type: String(data.cron_type || "SNAPSHOTS_CRON"),
      broker: String(data.broker || "") || null,
      tick_symbols: tickSymbols,
      all_symbols_count: filteredSymbols.length,
      timeframes: Array.isArray(tfs) ? tfs : [],
      created_count: 0,
      created: [],
      errors: [msg],
      manual_run: true,
    });
  }
  return summary;
}
async function mt5RunSnapshotsCron() {
  const queueReady = Boolean(SNAPSHOTS_CRON_QUEUE && SNAPSHOTS_CRON_WORKER);
  if (!queueReady) return mt5RunSnapshotsCronInline();
  try {
    const bucket = Math.floor(Date.now() / 60000);
    await SNAPSHOTS_CRON_QUEUE.add(
      "run-snapshots-cron",
      { bucket },
      { jobId: `snapshots_cron_${bucket}` },
    );
    return { queued: 1 };
  } catch (err) {
    console.error(
      `[Cron][Snapshots] BullMQ enqueue failed, fallback inline: ${err?.message || err}`,
    );
    return mt5RunSnapshotsCronInline();
  }
}
async function mt5CronLoop(runtime) {
  console.log("[Cron] Initializing master loop (1min cadence)");
  const intervalMs = 60 * 1000;
  global._cronStatus = "running";

  const run = async () => {
    if (!CRON_STATE.masterActive) {
      global._cronStatus = "paused";
      return;
    }
    if (CRON_STATE.isRunning) return;
    CRON_STATE.isRunning = true;
    const startMs = Date.now();
    const events = [];
    global._cronDetails = global._cronDetails || {};

    // Run each cron independently — one hanging won't block others
    const runOne = async (name, fn, okLabel) => {
      const t0 = Date.now();
      try {
        const res = await Promise.race([
          fn(),
          new Promise((_, reject) =>
            setTimeout(() => reject(new Error("timeout")), 300000),
          ),
        ]);
        const elapsed = Math.round((Date.now() - t0) / 1000);
        if (res) {
          global._cronDetails[name] = `ok (${elapsed}s, ${okLabel(res)})`;
          events.push(`${name}: done`);
        } else {
          global._cronDetails[name] = "no configs";
          events.push(`${name}: skipped`);
        }
      } catch (e) {
        global._cronDetails[name] = `error: ${e.message}`;
        events.push(`${name}: ERROR`);
        console.error(`[Cron] ${name} error:`, e.message);
      }
    };

    const cronTasks = [
      runOne(
        "marketData",
        mt5RunMarketDataCron,
        (r) => `${r.queued || 0} jobs`,
      ),
      runOne(
        "downloadBars",
        mt5RunDownloadBarsCron,
        (r) => `${r.queued || 0} jobs`,
      ),
      runOne(
        "aiAnalysis",
        mt5RunAiAnalysisCron,
        (r) => `${r.triggered || 0} trig`,
      ),
      runOne(
        "strategyScan",
        mt5RunStrategyScanCron,
        (r) => `${r.created || 0} created`,
      ),
      runOne(
        "tradesBulkAction",
        mt5RunTradesBulkActionCron,
        (r) => `${r.updated || 0} updated`,
      ),
    ];
    if (CFG.snapshotsCronEnabled) {
      cronTasks.push(
        runOne(
          "snapshots",
          mt5RunSnapshotsCron,
          (r) => `${r.captured || 0} img`,
        ),
      );
    } else {
      global._cronDetails.snapshots = "disabled";
      events.push("snapshots: disabled");
    }
    await Promise.all(cronTasks);

    const elapsed = Math.round((Date.now() - startMs) / 1000);
    global._cronStatus = `ok (${elapsed}s)`;
    global._cronEvents = global._cronEvents || [];
    global._cronEvents.unshift({
      time: new Date().toISOString(),
      elapsed,
      events,
      status: "ok",
    });
    if (global._cronEvents.length > 20) global._cronEvents.length = 20;
    if (notificationManager) {
      notificationManager.handle("SYSTEM_EVENT", "cron_tick", {
        message: `Cron OK (${elapsed}s): ${events.join("; ")}`,
        user_id: "*",
        ticker: true,
        console_log: true,
        notification: false,
        _force_ticker: true,
        metadata: {
          elapsed_sec: elapsed,
          events,
          details: global._cronDetails,
        },
      });
    }
    CRON_STATE.isRunning = false;
  };

  await runtime.automation.scheduleRecurring("mt5-master-cron", {
    intervalMs,
    handler: run,
    payload: { source: "mt5CronLoop" },
  });
  await runtime.automation.enqueueNow("mt5-master-cron", {
    source: "startup",
  });
}

async function mt5RunMarketDataCron() {
  if (!CFG.marketDataCronEnabled) return;
  const rows = await settingsStore.listUserSettingsByType(null, "cron");
  const configs = (rows || []).filter((r) => {
    const d = settingsStore.parseJsonField(r.data) || {};
    return (
      d.cron_type === "MARKET_DATA_CRON" &&
      String(r.status || "").toUpperCase() === "ACTIVE"
    );
  });
  if (!configs.length) return { triggered: 0 };

  const now = Date.now();

  for (const conf of configs) {
    const userId = conf.userId || conf.user_id;
    let data = settingsStore.parseJsonField(conf.data) || {};
    if (!marketDataCronSettingEnabled(data)) continue;
    const defaultCadence =
      Array.isArray(data.timeframes) && data.timeframes.length
        ? parseTfTokenToSeconds(data.timeframes[0])
        : 60;
    const stateKey = `${userId}_${conf.name}`;
    const decision = await cronConfigShouldRunNow(
      data,
      now,
      CRON_STATE.lastMarketDataRun[stateKey] || 0,
      defaultCadence,
    );
    data = decision.normalized;
    const symbols = await resolveCronSymbols(data, userId);
    const excludeSymbols = new Set(
      (Array.isArray(data.exclude_symbols) ? data.exclude_symbols : [])
        .map((s) => String(s).toUpperCase().trim())
        .filter(Boolean),
    );
    const filteredSymbols = symbols.filter(
      (s) => !excludeSymbols.has(String(s).toUpperCase().trim()),
    );
    const tfs = Array.isArray(data.timeframes) ? data.timeframes : [];
    if (!filteredSymbols.length || !tfs.length) continue;
    const timezone = marketDataCronTimezone(data);

    if (!decision.shouldRun) continue;

    CRON_STATE.lastMarketDataRun[stateKey] = now;

    for (const tf of tfs) {
      const tfSec = parseTfTokenToSeconds(tf);

      console.log(
        `[Cron][MarketData] Running userId=${userId} name=${conf.name} tf=${tf} symbols=${filteredSymbols.length}`,
      );

      // Batch symbols to avoid hitting Twelve Data limits
      const batchSize =
        Number(data.batch_size || CFG.marketDataCronBatchSize) || 8;
      for (let i = 0; i < filteredSymbols.length; i += batchSize) {
        const batch = filteredSymbols.slice(i, i + batchSize);
        if (MARKET_DATA_QUEUE) {
          const bucket = Math.floor(now / (tfSec * 1000));
          const results = await Promise.allSettled(
            batch.map((symbol) => {
              const symbolNorm = normalizeMarketDataSymbol(symbol);
              const tfNorm = normalizeMarketDataTf(tf);
              const jobId = `market_${sanitizeBullJobIdPart(userId)}_${sanitizeBullJobIdPart(conf.name || "default")}_${sanitizeBullJobIdPart(symbolNorm)}_${sanitizeBullJobIdPart(tfNorm)}_${sanitizeBullJobIdPart(bucket)}`;
              return MARKET_DATA_QUEUE.add(
                "fetch-bars",
                {
                  userId,
                  settingName: conf.name || "default",
                  symbol,
                  tf,
                  timezone,
                },
                { jobId },
              );
            }),
          );
          const failed = results.filter((r) => r.status === "rejected");
          if (failed.length) {
            console.error(
              `[Cron][MarketData] BullMQ add failed for ${failed.length} symbols: ${failed.map((f) => f.reason?.message || String(f.reason)).join("; ")}`,
            );
          }
        } else {
          await Promise.all(
            batch.map(async (symbol) => {
              try {
                await marketDataFetchJob({
                  userId,
                  settingName: conf.name || "default",
                  symbol,
                  tf,
                  timezone,
                });
              } catch (err) {
                console.error(
                  `[Cron][MarketData] Failed symbol=${symbol} tf=${tf}:`,
                  err.message,
                );
              }
            }),
          );
        }
      }
      await marketDataUpdateCronState({
        userId,
        settingName: conf.name || "default",
        symbol: "_cron",
        tf,
        patch: {
          timezone,
          queued_at: new Date().toISOString(),
          symbols_count: filteredSymbols.length,
          batch_size: batchSize,
          queue: MARKET_DATA_QUEUE ? "bullmq" : "inline",
        },
      }).catch(() => {});
    }
  }
  return { queued: 1 };
}

