function normalizeStrategyScanAutoSave(value) {
  const normalized = String(value || "trades")
    .trim()
    .toLowerCase();
  if (
    normalized === "none" ||
    normalized === "signals" ||
    normalized === "trades" ||
    normalized === "trades"
  ) {
    return normalized;
  }
  return "trades";
}

function normalizeAnalyzeAutoSave(value, options = {}) {
  const defaultToTrades = options.defaultToTrades === true;
  if (value === undefined) return defaultToTrades ? "trades" : null;
  if (value === null) return null;
  const normalized = String(value || "")
    .trim()
    .toLowerCase();
  if (normalized === "signals" || normalized === "trades") return normalized;
  if (normalized === "" || normalized === "none" || normalized === "null") {
    return null;
  }
  return defaultToTrades ? "trades" : null;
}

async function createTrades2PendingTrade(input = {}, options = {}) {
  const nowIso = new Date().toISOString();
  const sid = String(
    input.sid || input.trade_id || input.signal_id || mt5GenerateTimeSid(),
  ).trim();
  if (!sid) throw new Error("sid is required");
  const metadataInput =
    input.metadata && typeof input.metadata === "object" ? { ...input.metadata } : {};
  const rawJsonInput =
    input.raw_json && typeof input.raw_json === "object" ? { ...input.raw_json } : {};
  const planInput = firstTradePlanItem(
    metadataInput.trade_plan || rawJsonInput.trade_plan || input.trade_plan,
  );
  const resolvedUserId =
    String(input.user_id || CFG.mt5DefaultUserId || "default").trim() || "default";
  const resolvedAccountId =
    String(input.account_id || "").trim() ||
    (await resolvePreferredTrades2AccountId(resolvedUserId, input.source_id || null));
  const derivedLots = asNum(
    input.lots ??
      input.volume_basis_lots ??
      metadataInput.volume_basis_lots ??
      planInput.lots ??
      planInput.volume_basis_lots ??
      rawJsonInput.lots ??
      rawJsonInput.volume_basis_lots,
    null,
  );
  const directVolume = asNum(input.volume, null);
  const fallbackVolume = asNum(
    planInput.volume ?? rawJsonInput.volume,
    null,
  );
  const resolvedVolume =
    Number.isFinite(directVolume) && directVolume > 0
      ? directVolume
      : Number.isFinite(fallbackVolume) && fallbackVolume > 0
        ? fallbackVolume
        : null;
  const payloadMetadata = {
    ...metadataInput,
    ...(Number.isFinite(derivedLots) ? { volume_basis_lots: derivedLots } : {}),
  };
  const payload = {
    sid,
    user_id: resolvedUserId,
    account_id: resolvedAccountId || null,
    source_id: String(input.source_id || "").trim() || null,
    strategy: String(input.strategy || "").trim() || null,
    entry_model: String(input.entry_model || "").trim() || null,
    trade_tf: input.trade_tf ?? null,
    chart_tf: input.chart_tf ?? null,
    symbol: String(input.symbol || "").trim().toUpperCase(),
    action: String(input.action || input.side || "").trim().toUpperCase(),
    order_type: mt5NormalizeOrderTypeValue(input.order_type, "limit"),
    volume: resolvedVolume,
    entry: asNum(input.entry, null),
    sl: asNum(input.sl, null),
    tp: asNum(input.tp, null),
    tp1: asNum(input.tp1, null),
    tp2: asNum(input.tp2, null),
    tp3: asNum(input.tp3, null),
    rr_planned: asNum(input.rr_planned, null),
    risk_pct_planned: asNum(input.risk_pct_planned, null),
    confidence_pct: asNum(input.confidence_pct, null),
    estimated_bars: asNum(input.estimated_bars, null),
    be_trigger: asNum(input.be_trigger, null),
    profile: input.profile ?? null,
    note: String(input.note || "").trim() || null,
    dispatch_status: String(input.dispatch_status || "NEW").trim().toUpperCase(),
    execution_status: String(input.execution_status || "PENDING").trim().toUpperCase(),
    close_reason: String(input.close_reason || "").trim() || null,
    rejection_reason: String(input.rejection_reason || "").trim() || null,
    broker_trade_id: String(input.broker_trade_id || "").trim() || null,
    opened_at: input.opened_at || null,
    closed_at: input.closed_at || null,
    metadata: payloadMetadata,
    raw_json: Object.keys(rawJsonInput).length ? rawJsonInput : null,
    created_at: input.created_at || nowIso,
    updated_at: input.updated_at || nowIso,
  };
  const result = await tradesService().upsertTrade(payload, {
    entryType: options.entryType || "trade.ai_create",
    reason: options.reason || "manual_analysis",
  });
  return result?.trade || payload;
}

function normalizeStrategyPlanDirectionToAction(value) {
  const normalized = String(value || "")
    .trim()
    .toLowerCase();
  if (["buy", "bull", "bullish", "long"].includes(normalized)) return "buy";
  if (["sell", "bear", "bearish", "short"].includes(normalized)) return "sell";
  return normalized;
}

function resolveStrategyScanCronIds(data = {}) {
  return [
    ...new Set(
      (Array.isArray(data?.strategy_ids)
        ? data.strategy_ids
        : Array.isArray(data?.strategies)
          ? data.strategies
          : []
      )
        .map((item) => String(item || "").trim())
        .filter(Boolean),
    ),
  ];
}

async function resolveStrategyScanCronStrategies(userId, data = {}) {
  const selectedIds = resolveStrategyScanCronIds(data);
  if (!selectedIds.length) return [];
  const available = await backtestService.listAvailableStrategies(userId).catch(() => []);
  const byId = new Map(
    (Array.isArray(available) ? available : []).map((strategy) => [
      String(strategy?.id || strategy?.key || "").trim(),
      strategy,
    ]),
  );
  return selectedIds.map((strategyId) => byId.get(strategyId)).filter(Boolean);
}

async function loadStrategyScanBarsByTf({
  userId,
  symbol,
  timeframes = [],
  barsCount = 300,
}) {
  const barsByTf = {};
  const errors = [];
  for (const timeframe of Array.isArray(timeframes) ? timeframes : []) {
    const tf = String(timeframe || "").trim();
    if (!tf) continue;
    try {
      const snapshot = await buildAnalysisSnapshotFromTwelve({
        userId,
        payload: {
          bars: Math.max(50, Math.min(Number(barsCount || 300) || 300, CHART_HISTORY_MAX_BARS)),
          force_refresh: false,
          direction: "latest",
        },
        symbol,
        timeframe: tf,
      });
      if (String(snapshot?.status || "").toLowerCase() !== "ok") {
        errors.push({
          timeframe: tf,
          error: snapshot?.reason || "market_data_failed",
        });
        continue;
      }
      const bars = normalizeMarketDataBars(snapshot?.bars);
      if (bars.length < 2) {
        errors.push({
          timeframe: tf,
          error: "not_enough_bars",
        });
        continue;
      }
      barsByTf[tf] = bars;
    } catch (error) {
      errors.push({
        timeframe: tf,
        error: error instanceof Error ? error.message : String(error || "market_data_failed"),
      });
    }
  }
  return { barsByTf, errors };
}

async function executeStrategyScanCronConfig(conf, options = {}) {
  const userId = conf.userId || conf.user_id || CFG.mt5DefaultUserId;
  const data = settingsStore.parseJsonField(conf.data) || {};
  const cronName = String(conf.name || "STRATEGY_SCAN_CRON").trim() || "STRATEGY_SCAN_CRON";
  const summary = {
    cron_name: cronName,
    cron_type: "STRATEGY_SCAN_CRON",
    triggered: 0,
    created: 0,
    matched: 0,
    symbols: [],
    results: [],
  };
  const symbols = await resolveCronSymbols(data, userId);
  const strategyRows = await resolveStrategyScanCronStrategies(userId, data);
  const timeframes = Array.isArray(data?.timeframes)
    ? [...new Set(data.timeframes.map((item) => String(item || "").trim()).filter(Boolean))]
    : [];
  const barsCount = Math.max(50, Math.min(Number(data?.bars_count || 300) || 300, CHART_HISTORY_MAX_BARS));
  const autoSave = normalizeStrategyScanAutoSave(data?.auto_save);

  function buildStrategyScanSummaryMessage() {
    if (summary.error) {
      return `Strategy scan cron failed: ${summary.error}`;
    }
    const symbolResults = Array.isArray(summary.results) ? summary.results : [];
    for (const item of symbolResults) {
      const skipReasons = Array.isArray(item?.skip_reasons) ? item.skip_reasons : [];
      for (const reason of skipReasons) {
        const detail = String(reason?.detail || "").trim();
        if (!detail) continue;
        const timeframe = String(reason?.timeframe || "").trim();
        const symbol = String(item?.symbol || "").trim();
        const scope = [symbol, timeframe].filter(Boolean).join(" ");
        return scope
          ? `Strategy scan skipped: ${scope} - ${detail}`
          : `Strategy scan skipped: ${detail}`;
      }
      const itemErrors = Array.isArray(item?.errors) ? item.errors : [];
      for (const errorItem of itemErrors) {
        const detail = String(errorItem?.detail || errorItem?.error || errorItem?.message || "").trim();
        if (!detail) continue;
        const timeframe = String(errorItem?.timeframe || "").trim();
        const symbol = String(item?.symbol || "").trim();
        const scope = [symbol, timeframe].filter(Boolean).join(" ");
        return scope
          ? `Strategy scan error: ${scope} - ${detail}`
          : `Strategy scan error: ${detail}`;
      }
    }
    return `Strategy scan cron completed: ${summary.created} trades from ${summary.matched} matches`;
  }

  async function finalizeSummary(level = null, message = "") {
    const finalLevel =
      level ||
      (summary.error ? "ERROR" : summary.results.some((item) => item?.ok === false) ? "WARN" : "INFO");
    const finalMessage = message || buildStrategyScanSummaryMessage();
    await writeObjectLog(userId, "cron", cronName, {
      event: "CRON_STRATEGY_SCAN",
      level: finalLevel,
      message: finalMessage,
      cron_name: cronName,
      cron_type: "STRATEGY_SCAN_CRON",
      manual_run: options.manualRun === true,
      auto_save: autoSave,
      bars_count: barsCount,
      timeframes,
      strategy_ids: strategyRows.map((item) => String(item?.id || item?.key || "").trim()).filter(Boolean),
      symbols: summary.symbols,
      created: summary.created,
      matched: summary.matched,
      triggered: summary.triggered,
      results: summary.results,
      error: summary.error || null,
    }).catch(() => {});
    notificationManager.handle("SYSTEM_EVENT", "cron_strategy_scan", {
      message: finalMessage,
      type: summary.error ? "error" : summary.created > 0 ? "success" : "info",
      notification: true,
      cron_name: cronName,
      cron_type: "STRATEGY_SCAN_CRON",
      manual_run: options.manualRun === true,
      created: summary.created,
      matched: summary.matched,
      triggered: summary.triggered,
      results: summary.results,
    });
    return summary;
  }

  if (!symbols.length) {
    summary.error = "No symbols selected";
    return finalizeSummary("WARN", "Strategy scan skipped: no symbols selected");
  }
  if (!timeframes.length) {
    summary.error = "No timeframes selected";
    return finalizeSummary("WARN", "Strategy scan skipped: no timeframes selected");
  }
  if (!strategyRows.length) {
    summary.error = "No strategies selected";
    return finalizeSummary("WARN", "Strategy scan skipped: no strategies selected");
  }

  const pickupMode = String(data.pickup_mode || "all").trim().toLowerCase();
  const runSymbols =
    pickupMode === "random"
      ? [symbols[Math.floor(Math.random() * symbols.length)]]
      : symbols;
  const sourceName = mt5NormalizeUiSource(`strategy_scan_${cronName}`, "strategy_scan_cron");
  const sourceId = mt5SlugId(sourceName, "scan");
  await mt5UpsertSourceV2({
    source_id: sourceId,
    name: sourceName,
    kind: "api",
    auth_mode: "token",
    is_active: true,
    metadata: {
      signal_source: sourceName,
      cron_name: cronName,
      cron_type: "STRATEGY_SCAN_CRON",
    },
  }).catch(() => null);

  for (const symbolRaw of runSymbols) {
    const symbol = normalizeMarketDataSymbol(symbolRaw);
    const symbolResult = {
      symbol,
      ok: true,
      created: 0,
      matched: 0,
      timeframes: [],
      skip_reasons: [],
      errors: [],
    };
    try {
      const newsEvents =
        data?.avoid_news === true
          ? await StateRepo.get("NEWS_CALENDAR", "week").catch(() => [])
          : [];
      const { barsByTf, errors } = await loadStrategyScanBarsByTf({
        userId,
        symbol,
        timeframes,
        barsCount,
      });
      if (errors.length) {
        symbolResult.errors.push(...errors);
      }
      const plansToCreate = [];
      for (const timeframe of timeframes) {
        const tf = String(timeframe || "").trim();
        const bars = Array.isArray(barsByTf?.[tf]) ? barsByTf[tf] : [];
        if (bars.length < 2) {
          symbolResult.skip_reasons.push({
            timeframe: tf,
            code: "not_enough_bars",
            detail: `Need at least 2 bars, got ${bars.length}`,
          });
          continue;
        }
        const evaluation = evaluateChartStrategies({
          bars,
          strategies: strategyRows,
          lookbackBars: 1,
          symbol,
          tf,
          multiTfBars: barsByTf,
          scanMode: "live",
          skipConditions: true,
          newsEvents,
        });
        const matches = Array.isArray(evaluation?.latestMatches)
          ? evaluation.latestMatches
          : [];
        const latestBarTimeUnix = Number(bars[bars.length - 1]?.time || 0);
        const currentBarMatches = matches.filter(
          (hit) => Number(hit?.barTimeUnix || 0) === latestBarTimeUnix,
        );
        if (!currentBarMatches.length) {
          symbolResult.skip_reasons.push({
            timeframe: tf,
            code: "no_latest_bar_match",
            detail: "No strategy match on the latest closed bar",
          });
          continue;
        }
        const tfPlans = currentBarMatches.flatMap((hit) =>
          (Array.isArray(hit?.tradePlans) ? hit.tradePlans : []).map((plan) => ({
            hit,
            plan,
          })),
        );
        if (!tfPlans.length) {
          symbolResult.skip_reasons.push({
            timeframe: tf,
            code: "no_trade_plans",
            detail: "Latest-bar match existed but produced no trade plans",
            strategies: currentBarMatches.map((hit) => hit?.strategyId).filter(Boolean),
          });
          continue;
        }
        symbolResult.timeframes.push({
          timeframe: tf,
          matched: tfPlans.length,
          strategies: currentBarMatches.map((hit) => hit?.strategyId).filter(Boolean),
        });
        plansToCreate.push(...tfPlans);
      }

      symbolResult.matched = plansToCreate.length;
      summary.matched += plansToCreate.length;
      summary.triggered += 1;
      summary.symbols.push(symbol);

      if (autoSave === "none" || !plansToCreate.length) {
        if (autoSave === "none" && plansToCreate.length) {
          symbolResult.skip_reasons.push({
            code: "auto_save_disabled",
            detail: "Matches found, but auto_save is none so no trades were created",
          });
        } else if (!plansToCreate.length && symbolResult.skip_reasons.length === 0) {
          symbolResult.skip_reasons.push({
            code: "no_tradeable_matches",
            detail: "Scan completed but produced no tradeable matches",
          });
        }
        summary.results.push(symbolResult);
        continue;
      }

      for (const [index, item] of plansToCreate.entries()) {
        const plan = item?.plan || {};
        const hit = item?.hit || {};
        const action = normalizeStrategyPlanDirectionToAction(plan?.direction);
        if (action !== "buy" && action !== "sell") {
          symbolResult.skip_reasons.push({
            timeframe: String(hit?.tf || plan?.tf || "").trim() || null,
            code: "unsupported_direction",
            detail: `Plan direction "${String(plan?.direction || "").trim() || "-"}" is not buy/sell`,
            strategy_id: String(hit?.strategyId || "").trim() || null,
            event_id: String(hit?.eventId || "").trim() || null,
          });
          continue;
        }
        const skipDirective = mt5ResolveSkipTradeDirective({
          symbol,
          raw_json: plan && typeof plan === "object" ? { ...plan } : {},
          trade_plan: [plan],
        });
        if (skipDirective.cancelled) {
          symbolResult.skip_reasons.push({
            timeframe: String(hit?.tf || plan?.tf || "").trim() || null,
            code: "skip_directive_cancelled",
            detail: String(skipDirective.reason || skipDirective.message || "Trade cancelled by skip directive"),
            strategy_id: String(hit?.strategyId || "").trim() || null,
            event_id: String(hit?.eventId || "").trim() || null,
          });
        }
        if (autoSave === "trades") {
          const tradeSid = normalizePublicSidBase(
            `${mt5GenerateTimeSid()}_${cronName}_${symbol}_${hit?.strategyId || index + 1}`,
            "TRD",
          );
          const savedTrade = await createTrades2PendingTrade(
            {
              sid: tradeSid,
              user_id: userId,
              account_id: null,
              source_id: sourceId,
              strategy:
                String(plan?.strategy || hit?.strategyName || hit?.strategyId || "").trim() ||
                null,
              entry_model: String(plan?.entry_model || "").trim() || null,
              trade_tf: mt5TfToMinutes(plan?.tf || hit?.sourceTf || hit?.tf || "") || null,
              chart_tf: mt5TfToMinutes(hit?.tf || plan?.tf || "") || null,
              symbol,
              action,
              order_type: mt5NormalizeOrderTypeValue(plan?.type, "limit"),
              volume: asNum(plan?.volume ?? plan?.lots, null),
              entry: asNum(plan?.entry, null),
              sl: asNum(plan?.sl, null),
              tp: asNum(plan?.tp, null),
              tp1: asNum(plan?.tp1, null),
              tp2: asNum(plan?.tp2, null),
              tp3: asNum(plan?.tp3, null),
              rr_planned: asNum(plan?.rr, null),
              risk_pct_planned: asNum(plan?.risk_pct, null),
              confidence_pct: asNum(plan?.confidence_pct, null),
              estimated_bars: asNum(plan?.estimated_bars, null),
              be_trigger: asNum(plan?.be_trigger, null),
              note: String(plan?.note || hit?.displayText || "").trim(),
              dispatch_status: skipDirective.cancelled ? "CONSUMED" : "NEW",
              execution_status: skipDirective.cancelled ? "CANCELLED" : "PENDING",
              close_reason: skipDirective.cancelled ? "SKIP" : null,
              metadata: {
                event_type: skipDirective.cancelled
                  ? "STRATEGY_SCAN_CRON_CANCELLED"
                  : "STRATEGY_SCAN_CRON_TRADE2",
                cron_name: cronName,
                cron_type: "STRATEGY_SCAN_CRON",
                strategy_id: String(hit?.strategyId || "").trim() || null,
                strategy_name: String(hit?.strategyName || "").trim() || null,
                event_id: String(hit?.eventId || "").trim() || null,
                event_name: String(hit?.eventName || "").trim() || null,
                hit_time_unix: Number(hit?.barTimeUnix || 0) || null,
                hit_time_iso:
                  Number(hit?.barTimeUnix || 0) > 0
                    ? new Date(Number(hit.barTimeUnix) * 1000).toISOString()
                    : null,
                volume_basis_lots: asNum(
                  plan?.lots ?? plan?.volume_basis_lots,
                  null,
                ),
                raw_json: plan && typeof plan === "object" ? { ...plan } : {},
                trade_plan: [plan],
                strategy_hit: hit,
              },
              raw_json: plan && typeof plan === "object" ? { ...plan } : {},
            },
            {
              entryType: "trade.strategy_scan_trades",
              reason: "strategy_scan_cron",
            },
          );
          symbolResult.created += savedTrade?.sid ? 1 : 0;
          summary.created += savedTrade?.sid ? 1 : 0;
          continue;
        }
        const fanout = await mt5FanoutSignalTradeV2({
          signal_id: null,
          source_id: sourceId,
          user_id: userId,
          strategy:
            String(plan?.strategy || hit?.strategyName || hit?.strategyId || "").trim() || null,
          entry_model: String(plan?.entry_model || "").trim() || null,
          trade_tf: mt5TfToMinutes(plan?.tf || hit?.sourceTf || hit?.tf || "") || null,
          chart_tf: mt5TfToMinutes(hit?.tf || plan?.tf || "") || null,
          symbol,
          action,
          order_type: mt5NormalizeOrderTypeValue(plan?.type, "limit"),
          entry: asNum(plan?.entry, null),
          sl: asNum(plan?.sl, null),
          tp: asNum(plan?.tp, null),
          tp2: asNum(plan?.tp2, null),
          tp3: asNum(plan?.tp3, null),
          rr_planned: asNum(plan?.rr, null),
          risk_pct_planned: asNum(plan?.risk_pct, null),
          confidence_pct: asNum(plan?.confidence_pct, null),
          estimated_bars: asNum(plan?.estimated_bars, null),
          be_trigger: asNum(plan?.be_trigger, null),
          note: String(plan?.note || hit?.displayText || "").trim(),
          sid: normalizePublicSidBase(
            `${mt5GenerateTimeSid()}_${cronName}_${symbol}_${hit?.strategyId || index + 1}`,
            "TRD",
          ),
          execution_status:
            autoSave === "signals"
              ? "DRAFT"
              : skipDirective.cancelled
                ? "CANCELLED"
                : "PENDING",
          metadata: {
            event_type:
              autoSave === "signals"
                ? "STRATEGY_SCAN_CRON_DRAFT"
                : skipDirective.cancelled
                  ? "STRATEGY_SCAN_CRON_CANCELLED"
                  : "STRATEGY_SCAN_CRON_TRADE",
            cron_name: cronName,
            cron_type: "STRATEGY_SCAN_CRON",
            strategy_id: String(hit?.strategyId || "").trim() || null,
            strategy_name: String(hit?.strategyName || "").trim() || null,
            event_id: String(hit?.eventId || "").trim() || null,
            event_name: String(hit?.eventName || "").trim() || null,
            hit_time_unix: Number(hit?.barTimeUnix || 0) || null,
            hit_time_iso:
              Number(hit?.barTimeUnix || 0) > 0
                ? new Date(Number(hit.barTimeUnix) * 1000).toISOString()
                : null,
            raw_json: plan && typeof plan === "object" ? { ...plan } : {},
            trade_plan: [plan],
            strategy_hit: hit,
          },
        });
        symbolResult.created += Number(fanout?.created || 0);
        summary.created += Number(fanout?.created || 0);
      }
      summary.results.push(symbolResult);
      fileLog(
        symbol,
        "cron",
        {
          event: "CRON_STRATEGY_SCAN",
          level: symbolResult.errors.length || symbolResult.skip_reasons.length ? "WARN" : "INFO",
          message: `${symbol}: ${symbolResult.created} trades from ${symbolResult.matched} matches`,
          cron_name: cronName,
          symbol,
          created_trades: symbolResult.created,
          matched_trades: symbolResult.matched,
          skip_reasons: symbolResult.skip_reasons,
          errors: symbolResult.errors,
        },
        userId,
      );
    } catch (error) {
      symbolResult.ok = false;
      symbolResult.errors.push({
        error: error instanceof Error ? error.message : String(error || "strategy_scan_failed"),
      });
      summary.results.push(symbolResult);
      fileLog(
        symbol,
        "cron",
        {
          event: "CRON_STRATEGY_SCAN",
          level: "ERROR",
          message: `${symbol} ERROR: ${symbolResult.errors[0]?.error || "strategy_scan_failed"}`,
          cron_name: cronName,
          symbol,
          error: symbolResult.errors[0]?.error || "strategy_scan_failed",
        },
        userId,
      );
    }
  }

  return finalizeSummary();
}

async function mt5RunStrategyScanCron() {
  const rows = await settingsStore.listUserSettingsByType(null, "cron");
  const configs = (rows || []).filter((r) => {
    const d = settingsStore.parseJsonField(r.data) || {};
    return (
      d.cron_type === "STRATEGY_SCAN_CRON" &&
      String(r.status || "").toUpperCase() === "ACTIVE"
    );
  });
  if (!configs.length) return { triggered: 0, created: 0, matched: 0 };

  const now = Date.now();
  let triggered = 0;
  let created = 0;
  let matched = 0;
  for (const conf of configs) {
    const userId = conf.userId || conf.user_id || CFG.mt5DefaultUserId;
    let data = settingsStore.parseJsonField(conf.data) || {};
    const confName = String(conf.name || "STRATEGY_SCAN_CRON");
    const stateKey = `${userId}_${conf.name}`;
    const hydratedLastRunMs = readCronObjectLogTimestampMs(
      userId,
      confName,
      "strategy_scan",
    );
    const lastRunMs = Math.max(
      Number(CRON_STATE.lastStrategyScanRun[stateKey] || 0),
      Number(hydratedLastRunMs || 0),
    );
    if (!CRON_STATE.lastStrategyScanRun[stateKey] && hydratedLastRunMs > 0) {
      CRON_STATE.lastStrategyScanRun[stateKey] = hydratedLastRunMs;
    }
    const defaultCadence =
      Array.isArray(data.timeframes) && data.timeframes.length
        ? parseTfTokenToSeconds(data.timeframes[0])
        : 60;
    const decision = await cronConfigShouldRunNow(data, now, lastRunMs, defaultCadence);
    data = decision.normalized;
    if (!decision.shouldRun) continue;
    CRON_STATE.lastStrategyScanRun[stateKey] = now;
    const out = await executeStrategyScanCronConfig({ ...conf, data }, {
      manualRun: false,
    });
    triggered += Number(out?.triggered || 0);
    created += Number(out?.created || 0);
    matched += Number(out?.matched || 0);
  }
  return { triggered, created, matched };
}

async function runStrategyScanCronConfigNow(conf) {
  return executeStrategyScanCronConfig(conf, {
    manualRun: true,
  });
}

async function mt5RunAiAnalysisCronInline() {
  const rows = await settingsStore.listUserSettingsByType(null, "cron");
  const configs = (rows || []).filter((r) => {
    const d = settingsStore.parseJsonField(r.data) || {};
    return (
      d.cron_type === "ANALYSIS_CRON" &&
      String(r.status || "").toUpperCase() === "ACTIVE"
    );
  });
  if (!configs.length) return { triggered: 0 };

  const now = Date.now();
  let triggered = 0;
  for (const conf of configs) {
    const userId = conf.userId || conf.user_id;
    let data = settingsStore.parseJsonField(conf.data) || {};
    const confName = String(conf.name || "ANALYSIS_CRON");
    const stateKey = `${userId}_${conf.name}`;
    const hydratedLastRunMs = readCronObjectLogTimestampMs(
      userId,
      confName,
      "ai_analysis",
    );
    const lastRunMs = Math.max(
      Number(CRON_STATE.lastAiAnalysisRun[stateKey] || 0),
      Number(hydratedLastRunMs || 0),
    );
    if (!CRON_STATE.lastAiAnalysisRun[stateKey] && hydratedLastRunMs > 0) {
      CRON_STATE.lastAiAnalysisRun[stateKey] = hydratedLastRunMs;
    }
    const decision = await cronConfigShouldRunNow(data, now, lastRunMs, 3600);
    data = decision.normalized;
    const symbols = await resolveCronSymbols(data, userId);
    const tfs = Array.isArray(data.timeframes) ? data.timeframes : [];

    if (decision.shouldRun) {
      console.log(
        `[Cron][AiAnalysis] Running userId=${userId} name=${conf.name} symbols=${symbols.length}`,
      );
      CRON_STATE.lastAiAnalysisRun[stateKey] = now;

      // Pickup mode: "random" picks 1 random symbol, "all" (default) runs all
      const pickupMode = String(data.pickup_mode || "all").toLowerCase();
      const runSymbols =
        pickupMode === "random"
          ? [symbols[Math.floor(Math.random() * symbols.length)]]
          : symbols;
      if (pickupMode === "random") {
        console.log(
          `[Cron][AiAnalysis] Random pickup: selected ${runSymbols[0]} from ${symbols.length} symbols`,
        );
      }

      for (const symbol of runSymbols) {
        // Call the same manual AI analyze endpoint — no code duplication.
        // When no custom prompt is in cron config, the endpoint will use
        // the rich system.md guide as default (same as manual UI).
        try {
          const runTimeframes = tfs.length ? tfs : ["D", "4H", "15m", "5m"];
          const forceRefreshSnapshots =
            data.refresh_snapshot === true || data.snapshot_refresh === true;
          let shouldRefreshSnapshots = forceRefreshSnapshots;
          if (!shouldRefreshSnapshots) {
            const recent = findRecentChartSnapshots({
              symbol,
              provider: String(data.broker || "ICMARKETS"),
              timeframes: runTimeframes,
              maxAgeMs: 5 * 60 * 1000,
            });
            shouldRefreshSnapshots =
              !Array.isArray(recent.items) ||
              recent.items.length < recent.target_timeframes.length;
          }
          if (shouldRefreshSnapshots) {
            await captureTradingViewSnapshotsBatch({
              symbol,
              provider: String(data.broker || "ICMARKETS"),
              timeframes: runTimeframes,
              lookbackBars: Number(data.lookback_bars || 300),
              format: "png",
              quality: 70,
              theme: "dark",
            });
          }
          const analyzePayload = JSON.stringify({
            symbol,
            timeframes: runTimeframes,
            model: data.model || "claude-sonnet-4-0",
            auto_save: normalizeAnalyzeAutoSave(data.auto_save, {
              defaultToTrades: true,
            }),
            prompt: data.prompt || "",
            profile: data.profile || "",
            provider: data.broker || "ICMARKETS",
            snapshot_refresh: shouldRefreshSnapshots,
          });
          const http = require("http");
          const { statusCode, body } = await new Promise((resolve, reject) => {
            const req = http.request(
              {
                hostname: "127.0.0.1",
                port: 3001,
                path: "/api/chart/snapshots/analyze",
                method: "POST",
                headers: {
                  "Content-Type": "application/json",
                  "x-api-key": CFG.signalApiKey || "",
                  "Content-Length": Buffer.byteLength(analyzePayload),
                },
                timeout: 180000,
              },
              (res) => {
                let b = "";
                res.on("data", (chunk) => (b += chunk));
                res.on("end", () =>
                  resolve({ statusCode: res.statusCode, body: b }),
                );
              },
            );
            req.on("error", (e) => reject(e));
            req.on("timeout", () => {
              req.destroy();
              reject(new Error("timeout"));
            });
            req.write(analyzePayload);
            req.end();
          });
          let created = 0;
          let createdTradeSid = "";
          let parsedBody = null;
          try {
            parsedBody = JSON.parse(body);
            created = Number(
              parsedBody?.auto_save_result?.created ||
                parsedBody?.auto_save?.created ||
                0,
            );
            createdTradeSid = String(
              parsedBody?.auto_save_result?.trade_sid ||
                parsedBody?.auto_save_result?.sid ||
                parsedBody?.auto_save?.trade_sid ||
                parsedBody?.auto_save?.sid ||
                parsedBody?.trade_sid ||
                parsedBody?.sid ||
                "",
            ).trim();
            if (!createdTradeSid) {
              const ids = parsedBody?.auto_save_result?.created_ids;
              if (Array.isArray(ids) && ids.length > 0) {
                createdTradeSid = String(ids[0] || "").trim();
              }
            }
          } catch (_) {}
          triggered++;
          const ok = statusCode >= 200 && statusCode < 300;
          const failureDetail = ok
            ? ""
            : extractCronAiFailureDetail(body) ||
              String(parsedBody?.error || parsedBody?.message || "").trim();
          console.log(
            `[Cron][AiAnalysis] ${symbol}: ${ok ? "OK" : "FAIL"} (${statusCode}) created=${created}${failureDetail ? ` detail=${failureDetail}` : ""}`,
          );
          const successMessage = `${createdTradeSid || "NO_SID"}-${symbol}, ${created} created`;
          const errorMessage = `${symbol} ERROR${failureDetail ? `: ${failureDetail}` : ` (${statusCode})`}`;
          // Per-symbol log
          fileLog(
            symbol,
            "cron",
            {
              event: "CRON_AI_ANALYSIS",
              level: ok ? "INFO" : "ERROR",
              message: ok ? successMessage : errorMessage,
              cron_name: confName,
              symbol,
              status: ok ? "ok" : "error",
              created_trades: created,
              trade_sid: createdTradeSid || undefined,
              status_code: statusCode,
              error: ok ? undefined : failureDetail || `HTTP ${statusCode}`,
              error_detail: ok ? undefined : failureDetail || undefined,
            },
            userId,
          );
          // Notify hub
          if (notificationManager) {
            notificationManager.handle("SYSTEM_EVENT", "cron_ai", {
              message: ok ? successMessage : errorMessage,
              symbol,
            });
          }
        } catch (err) {
          console.error(`[Cron][AiAnalysis] Failed ${symbol}: ${err.message}`);
          fileLog(
            symbol,
            "cron",
            {
              event: "CRON_AI_ANALYSIS",
              message: `${symbol} ERROR: ${err.message}`,
              level: "ERROR",
              error: err.message,
              error_detail: err.message,
              cron_name: confName,
              symbol,
            },
            userId,
          );
        }
      }
    }
  }
  return { triggered };
}

async function runAiAnalysisCronConfigNow(conf) {
  const userId = conf.userId || conf.user_id;
  const data = settingsStore.parseJsonField(conf.data) || {};
  const confName = String(conf.name || "ANALYSIS_CRON");
  const summary = {
    cron_name: confName,
    cron_type: String(data.cron_type || "ANALYSIS_CRON"),
    triggered: 0,
    results: [],
  };
  const symbols = await resolveCronSymbols(data, userId);
  const tfs = Array.isArray(data.timeframes) ? data.timeframes : [];
  if (!symbols.length) return summary;
  console.log(
    `[Cron][AiAnalysis][Manual] Running userId=${userId} name=${conf.name} symbols=${symbols.length}`,
  );
  const pickupMode = String(data.pickup_mode || "all").toLowerCase();
  const runSymbols =
    pickupMode === "random"
      ? [symbols[Math.floor(Math.random() * symbols.length)]]
      : symbols;
  await writeObjectLog(userId, "cron", confName, {
    event: "CRON_AI_ANALYSIS",
    level: "INFO",
    message: `Manual execute started (${runSymbols.length} symbols)`,
    cron_name: confName,
    cron_type: String(data.cron_type || "ANALYSIS_CRON"),
    manual_run: true,
    symbols: runSymbols,
    timeframes: tfs,
  }).catch(() => {});
  for (const symbol of runSymbols) {
    try {
      const runTimeframes = tfs.length ? tfs : ["D", "4H", "15m", "5m"];
      const forceRefreshSnapshots =
        data.refresh_snapshot === true || data.snapshot_refresh === true;
      let shouldRefreshSnapshots = forceRefreshSnapshots;
      if (!shouldRefreshSnapshots) {
        const recent = findRecentChartSnapshots({
          symbol,
          provider: String(data.broker || "ICMARKETS"),
          timeframes: runTimeframes,
          maxAgeMs: 5 * 60 * 1000,
        });
        shouldRefreshSnapshots =
          !Array.isArray(recent.items) ||
          recent.items.length < recent.target_timeframes.length;
      }
      if (shouldRefreshSnapshots) {
        await captureTradingViewSnapshotsBatch({
          symbol,
          provider: String(data.broker || "ICMARKETS"),
          timeframes: runTimeframes,
          lookbackBars: Number(data.lookback_bars || 300),
          format: "png",
          quality: 70,
          theme: "dark",
        });
      }
      const analyzePayload = JSON.stringify({
        symbol,
        timeframes: runTimeframes,
        model: data.model || "claude-sonnet-4-0",
        auto_save: normalizeAnalyzeAutoSave(data.auto_save, {
          defaultToTrades: true,
        }),
        prompt: data.prompt || "",
        profile: data.profile || "",
        provider: data.broker || "ICMARKETS",
        snapshot_refresh: shouldRefreshSnapshots,
      });
      const { statusCode, body } = await new Promise((resolve, reject) => {
        const req = http.request(
          {
            hostname: "127.0.0.1",
            port: 3001,
            path: "/api/chart/snapshots/analyze",
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "x-api-key": CFG.signalApiKey || "",
              "Content-Length": Buffer.byteLength(analyzePayload),
            },
            timeout: 180000,
          },
          (res) => {
            let b = "";
            res.on("data", (chunk) => (b += chunk));
            res.on("end", () =>
              resolve({ statusCode: res.statusCode, body: b }),
            );
          },
        );
        req.on("error", (e) => reject(e));
        req.on("timeout", () => {
          req.destroy();
          reject(new Error("timeout"));
        });
        req.write(analyzePayload);
        req.end();
      });
      let parsedBody = null;
      try {
        parsedBody = JSON.parse(body);
      } catch {}
      const ok = statusCode >= 200 && statusCode < 300;
      const failureDetail = ok
        ? ""
        : extractCronAiFailureDetail(body) ||
          String(parsedBody?.error || parsedBody?.message || "").trim();
      summary.triggered++;
      summary.results.push({
        symbol,
        ok,
        statusCode,
        error: failureDetail || null,
      });
      fileLog(symbol, "cron", {
        event: "CRON_AI_ANALYSIS",
        level: ok ? "INFO" : "ERROR",
        message: ok
          ? `${symbol} manual run completed`
          : `${symbol} ERROR${failureDetail ? `: ${failureDetail}` : ` (${statusCode})`}`,
        cron_name: confName,
        symbol,
        status: ok ? "ok" : "error",
        manual_run: true,
      });
    } catch (err) {
      summary.results.push({
        symbol,
        ok: false,
        statusCode: 500,
        error: err.message,
      });
    }
  }
  const failed = summary.results.filter((x) => !x.ok);
  await writeObjectLog(userId, "cron", confName, {
    event: "CRON_AI_ANALYSIS",
    level: failed.length ? "ERROR" : "INFO",
    message: failed.length
      ? `Manual execute finished with ${failed.length} failure(s)`
      : `Manual execute completed for ${summary.results.length} symbol(s)`,
    cron_name: confName,
    cron_type: String(data.cron_type || "ANALYSIS_CRON"),
    manual_run: true,
    results: summary.results,
  }).catch(() => {});
  notificationManager.handle("SYSTEM_EVENT", "cron_ai_manual", {
    message: failed.length
      ? `AI cron manual run ${confName}: ${failed.length} failed`
      : `AI cron manual run ${confName}: ${summary.results.length} completed`,
    type: failed.length ? "warning" : "info",
    notification: true,
    cron_name: confName,
    results: summary.results,
    manual_run: true,
  });
  return summary;
}

async function executeTradesBulkActionCronConfig(conf, options = {}) {
  const userId = conf.userId || conf.user_id || CFG.mt5DefaultUserId;
  const data = settingsStore.parseJsonField(conf.data) || {};
  const cronName = String(conf.name || "TRADES_BULK_ACTION").trim();
  const action = String(data.bulk_action || "").trim().toLowerCase();
  const filters = buildTradeBulkActionFilters(data, userId);
  const summary = {
    cron_name: cronName,
    cron_type: "TRADES_BULK_ACTION",
    action: action || "",
    updated: 0,
    skipped: false,
    reason: "",
  };

  async function finalizeSummary() {
    if (options.writeLog !== false) {
      await writeObjectLog(userId, "cron", cronName, {
        event: "CRON_TRADES_BULK_ACTION",
        level: summary.error ? "ERROR" : summary.skipped ? "WARN" : "INFO",
        message: summary.error
          ? `Trades bulk action failed: ${summary.error}`
          : summary.skipped
            ? `Trades bulk action skipped: ${summary.reason || "no-op"}`
            : `Trades bulk action ${action}: ${summary.updated} updated`,
        cron_name: cronName,
        cron_type: "TRADES_BULK_ACTION",
        manual_run: options.manualRun === true,
        action,
        filters,
        updated: summary.updated,
        legacy_deleted: summary.legacy_deleted || 0,
        service_deleted: summary.service_deleted || 0,
        files_deleted: summary.files_deleted || 0,
        trade_folders_deleted: summary.trade_folders_deleted || 0,
        skipped: summary.skipped,
        reason: summary.reason || null,
        error: summary.error || null,
      }).catch(() => {});
    }
    notificationManager.handle("SYSTEM_EVENT", "cron_trade_bulk_action", {
      message: summary.error
        ? `Trade bulk cron ${cronName} failed: ${summary.error}`
        : summary.skipped
          ? `Trade bulk cron ${cronName} skipped: ${summary.reason || "no-op"}`
          : `Trade bulk cron ${cronName}: ${summary.updated} updated`,
      type: summary.error ? "error" : summary.skipped ? "warning" : "info",
      notification: true,
      cron_name: cronName,
      cron_type: "TRADES_BULK_ACTION",
      manual_run: options.manualRun === true,
      action,
      updated: summary.updated,
      legacy_deleted: summary.legacy_deleted || 0,
      service_deleted: summary.service_deleted || 0,
      files_deleted: summary.files_deleted || 0,
      trade_folders_deleted: summary.trade_folders_deleted || 0,
      skipped: summary.skipped,
      reason: summary.reason || null,
      error: summary.error || null,
    });
    return summary;
  }

  if (!action) {
    summary.skipped = true;
    summary.reason = "Bulk action is not configured";
    return finalizeSummary();
  }
  if (!hasTradeBulkActionCriteria(filters)) {
    summary.skipped = true;
    summary.reason = "No trade filters selected";
    return finalizeSummary();
  }
  try {
    const out = await mt5BulkActionTradesV2(action, filters);
    summary.updated = Number(out?.updated || 0);
    summary.skipped = out?.skipped === true;
    summary.reason = String(out?.reason || "").trim();
    summary.sids = Array.isArray(out?.sids) ? out.sids : [];
    summary.trade_ids = Array.isArray(out?.trade_ids) ? out.trade_ids : [];
    summary.legacy_deleted = Number(out?.legacy_deleted || 0);
    summary.service_deleted = Number(out?.service_deleted || 0);
    if (action === "delete_all" && summary.sids.length) {
      const cleanup = await mt5CleanupSignalTradeArtifacts({
        tradeIds: summary.sids,
        tradeRows: summary.sids.map((sid) => ({ sid })),
      });
      summary.logs_deleted = Number(cleanup?.logs_deleted || 0);
      summary.files_deleted = Number(cleanup?.files_deleted || 0);
      summary.snapshot_files_deleted = Number(cleanup?.snapshot_files_deleted || 0);
      summary.trade_folders_deleted = Number(cleanup?.trade_folders_deleted || 0);
    }
    return finalizeSummary();
  } catch (error) {
    const errorMessage =
      error instanceof Error ? error.message : String(error || "Unknown error");
    console.error(
      `[Cron][TradesBulkAction] ${cronName} failed:`,
      error?.stack || errorMessage,
    );
    summary.skipped = true;
    summary.reason = errorMessage;
    summary.error = errorMessage;
    return finalizeSummary();
  }
}

async function mt5RunTradesBulkActionCron() {
  const rows = await settingsStore.listUserSettingsByType(null, "cron");
  const configs = (rows || []).filter((r) => {
    const d = settingsStore.parseJsonField(r.data) || {};
    return (
      d.cron_type === "TRADES_BULK_ACTION" &&
      String(r.status || "").toUpperCase() === "ACTIVE"
    );
  });
  if (!configs.length) return { updated: 0 };

  const now = Date.now();
  let totalUpdated = 0;
  for (const conf of configs) {
    const userId = conf.userId || conf.user_id || CFG.mt5DefaultUserId;
    let data = settingsStore.parseJsonField(conf.data) || {};
    const confName = String(conf.name || "TRADES_BULK_ACTION");
    const stateKey = `${userId}_${conf.name}`;
    const hydratedLastRunMs = readCronObjectLogTimestampMs(
      userId,
      confName,
      "trades_bulk_action",
    );
    const lastRunMs = Math.max(
      Number(CRON_STATE.lastTradesBulkActionRun[stateKey] || 0),
      Number(hydratedLastRunMs || 0),
    );
    const decision = await cronConfigShouldRunNow(data, now, lastRunMs, 60);
    data = decision.normalized;
    if (!decision.shouldRun) continue;
    CRON_STATE.lastTradesBulkActionRun[stateKey] = now;
    const nextConf = { ...conf, data };
    const out = await executeTradesBulkActionCronConfig(nextConf, {
      manualRun: false,
    });
    totalUpdated += Number(out?.updated || 0);
  }
  return { updated: totalUpdated };
}

async function runTradesBulkActionCronConfigNow(conf) {
  return executeTradesBulkActionCronConfig(conf, {
    manualRun: true,
  });
}

async function runCronSettingNow(conf) {
  const data = settingsStore.parseJsonField(conf?.data) || {};
  const cronType = String(data.cron_type || "").toUpperCase();
  if (cronType === "MARKET_DATA_CRON") {
    return runMarketDataCronConfigNow(conf);
  }
  if (cronType === "DOWNLOAD_BARS_CRON") {
    return runDownloadBarsCronConfigNow(conf);
  }
  if (cronType === "ANALYSIS_CRON") {
    return runAiAnalysisCronConfigNow(conf);
  }
  if (cronType === "STRATEGY_SCAN_CRON") {
    return runStrategyScanCronConfigNow(conf);
  }
  if (cronType === "SNAPSHOT_CRON" || cronType === "SNAPSHOTS_CRON") {
    return runSnapshotsCronConfigNow(conf);
  }
  if (cronType === "TRADES_BULK_ACTION") {
    return runTradesBulkActionCronConfigNow(conf);
  }
  throw new Error(`Unsupported cron type: ${cronType || "unknown"}`);
}
async function mt5RunAiAnalysisCron() {
  const queueReady = Boolean(AI_ANALYSIS_CRON_QUEUE && AI_ANALYSIS_CRON_WORKER);
  if (!queueReady) return mt5RunAiAnalysisCronInline();
  try {
    const bucket = Math.floor(Date.now() / 60000);
    await AI_ANALYSIS_CRON_QUEUE.add(
      "run-ai-analysis-cron",
      { bucket },
      { jobId: `ai_analysis_cron_${bucket}` },
    );
    return { queued: 1 };
  } catch (err) {
    console.error(
      `[Cron][AiAnalysis] BullMQ enqueue failed, fallback inline: ${err?.message || err}`,
    );
    return mt5RunAiAnalysisCronInline();
  }
}

start().catch((err) => {
  const message = err instanceof Error ? err.stack || err.message : String(err);
  console.error(`Failed to start server: ${message}`);
  process.exit(1);
});

async function handleShutdownSignal(signal) {
  try {
    await gracefulShutdown(signal);
    process.exit(0);
  } catch (error) {
    const message =
      error instanceof Error ? error.stack || error.message : String(error);
    console.error(`[shutdown] failed during ${signal}: ${message}`);
    process.exit(1);
  }
}

process.on("SIGINT", () => {
  void handleShutdownSignal("SIGINT");
});

process.on("SIGTERM", () => {
  void handleShutdownSignal("SIGTERM");
});
